import hashlib
from urllib.request import urlopen

def calculate_file_hash(filepath, checksum=None):
    """
    Calculates the SHA-256 hash of a file given its path.

    Args:
        filepath (str): Path to the file.
        checksum (str, optional): Checksum value to verify against. Defaults to None.

    Returns:
        str: Hash of the file if successful, otherwise an error message.
    """
    try:
        with open(filepath, 'rb') as f:
            hash_obj = hashlib.sha256()
            chunk_size = 1024 * 1024
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hash_obj.update(data)
        file_hash = hash_obj.hexdigest()
        if checksum and checksum != file_hash:
            return "Hash mismatch. Expected: {}. Actual: {}".format(checksum, file_hash)
        else:
            return "Success. Hash of the file is {}.".format(file_hash)
    except IOError as e:
        return "Unable to access file at {}.".format(filepath)
    except ValueError as e:
        return "Checksum value is invalid."
