using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Generic;

namespace MyCustomDataStructure
{
    public class DataLoader
    {
        private const int MAX_BINARY_SIZE = 1024 * 1024 * 5; // 5MB

        public static List<MyCustomObject> LoadData(string filePath)
        {
            BinaryFormatter formatter = new BinaryFormatter();
            using (FileStream stream = new FileStream(filePath, FileMode.Open))
            {
                if (stream.Length > MAX_BINARY_SIZE)
                {
                    throw new Exception("File size exceeds maximum allowed size.");
                }

                List<MyCustomObject> data;
                try
                {
                    data = formatter.Deserialize(stream) as List<MyCustomObject>;
                }
                catch (Exception ex)
                {
                    throw new Exception("Error deserializing data.", ex);
                }

                if (data == null)
                {
                    throw new Exception("Data is empty or null.");
                }

                // Integrate with external API to validate data against remote schema.
                ValidateData(data);

                return data;
            }
        }

        private static void ValidateData(List<MyCustomObject> data)
        {
            try
            {
                using (var client = new HttpClient())
                {
                    var jsonSchema = JsonConvert.SerializeObject(data);
                    var schemaUrl = "https://example.com/schema";
                    var response = await client.PostAsync(schemaUrl, new StringContent(jsonSchema));

                    if (!response.IsSuccessStatusCode)
                    {
                        throw new Exception("Validation failed.");
                    }
                }
            }
            catch (Exception ex)
            {
                throw new Exception("Error validating data.", ex);
            }
        }

        public static void Dispose()
        {
            if (_fileStream != null)
            {
                _fileStream.Dispose();
            }

            if (_binaryFormatter != null)
            {
                _binaryFormatter.Dispose();
            }
        }
    }
}
