class SandeshClient {
 public:
  SandeshClient(boost::asio::io_context& io_context, const string& hostname) :
      resolver_(io_context), socket_(io_context) {
    // Resolve the hostname to an IP address
    tcp::resolver::query query(hostname, "80");
    resolver_.async_resolve(query, boost::bind(&SandeshClient::onResolve, this, _1, _2));
  }

  void onResolve(const boost::system::error_code& err, tcp::resolver::results_type results) {
    if (err) {
      cerr << "Error resolving hostname: " << err.message() << endl;
      return;
    }
    // Make a connection to the server
    socket_.async_connect(results, boost::bind(&SandeshClient::onConnect, this, _1));
  }

  void onConnect(const boost::system::error_code& err) {
    if (err) {
      cerr << "Error connecting to server: " << err.message() << endl;
      return;
    }
    // Send a GET request to the server
    string request = "GET / HTTP/1.1\r\nHost: " + socket_.remote_endpoint().address().to_string() + "\r\n";
    boost::asio::async_write(socket_, boost::asio::buffer(request), boost::bind(&SandeshClient::onWrite, this, _1));
  }

  void onWrite(const boost::system::error_code& err) {
    if (err) {
      cerr << "Error writing to server: " << err.message() << endl;
      return;
    }
    // Read the response from the server
    boost::asio::async_read(socket_, boost::asio::buffer(response), boost::bind(&SandeshClient::onRead, this, _1));
  }

  void onRead(const boost::system::error_code& err) {
    if (err) {
      cerr << "Error reading from server: " << err.message() << endl;
      return;
    }
    // Parse the response and verify that it matches the expected value
    string response_string(response.begin(), response.end());
    cout << "Response from server: " << response_string << endl;
    if (response_string == "Hello, world!") {
      cerr << "Response verification passed" << endl;
    } else {
      cerr << "Response verification failed" << endl;
    }
  }

 private:
  tcp::resolver resolver_;
  tcp::socket socket_;
  boost::asio::streambuf response;
};

int main() {
  // Initialize the Boost ASIO io_context and start the client
  boost::asio::io_context io_context;
  SandeshClient* client = new SandeshClient(io_context, "localhost");
  io_context.run();
  return 0;
}
