public class DisjointPairFinder {
    private UnionFind unionFind;

    public DisjointPairFinder() {
        this.unionFind = new UnionFind();
    }

    public void addElement(int element) {
        this.unionFind.addElement(element);
    }

    public boolean areDisjoint(int element1, int element2) {
        return this.unionFind.areDisjoint(element1, element2);
    }

    public void trackTimeTaken() {
        long startTime = System.currentTimeMillis();
        // Perform disjoint check operation
        boolean areDisjoint = this.unionFind.areDisjoint(element1, element2);
        long endTime = System.currentTimeMillis();
        long timeTaken = endTime - startTime;
        System.out.println("Time taken to perform disjoint check: " + timeTaken + " ms");
    }
}

class UnionFind {
    private List<Integer> elements;
    private int[] parents;

    public UnionFind() {
        this.elements = new ArrayList<>();
        this.parents = new int[0];
    }

    public void addElement(int element) {
        this.elements.add(element);
        this.parents = Arrays.copyOf(this.parents, this.parents.length + 1);
        this.parents[this.parents.length - 1] = this.parents.length;
    }

    public boolean areDisjoint(int element1, int element2) {
        return findSet(element1) != findSet(element2);
    }

    private int findSet(int element) {
        if (this.parents[element] == element) {
            return element;
        } else {
            this.parents[element] = findSet(this.parents[element]);
            return this.parents[element];
        }
    }
}

