const reduceAsync = async (arr, initialValue, callback) => {
  // Split the array into smaller chunks for parallel processing
  const chunkSize = 100;
  const chunks = [];
  for (let i = 0; i < Math.ceil(arr.length / chunkSize); i++) {
    chunks.push(arr.slice(i * chunkSize, (i + 1) * chunkSize));
  }

  // Create a promise chain to process the chunks concurrently
  const promises = [];
  for (const chunk of chunks) {
    promises.push(reduceChunkAsync(chunk, initialValue, callback));
  }
  const results = await Promise.all(promises);

  // Combine the results from each chunk and return the final value
  let reducedValue = initialValue;
  for (const result of results) {
    reducedValue += result;
  }
  return reducedValue;
};

const reduceChunkAsync = async (chunk, initialValue, callback) => {
  // Fetch the current number from the external service and update the chunk
  const currentNumber = await fetchCurrentNumber();
  if (currentNumber !== undefined) {
    chunk.push(currentNumber);
  } else {
    console.error("Error fetching current number");
  }

  // Reduce the chunk using the callback function and return the result
  const reducedValue = await reduceChunk(chunk, initialValue, callback);
  return reducedValue;
};

const fetchCurrentNumber = async () => {
  // Simulate an external service that returns a random number or fails with a timeout
  const currentNumber = Math.random() > 0.5 ? Math.floor(Math.random() * 100) : undefined;
  if (currentNumber === undefined) {
    console.error("Error fetching current number from external service");
  }
  return currentNumber;
};

const reduceChunk = async (chunk, initialValue, callback) => {
  // Reduce the chunk using the callback function and return the result
  let reducedValue = initialValue;
  for (const element of chunk) {
    try {
      reducedValue = await callback(reducedValue, element);
    } catch (error) {
      console.error(`Error reducing value: ${element}`);
    }
  }
  return reducedValue;
};

// Test the function with a sample array and simulate different network conditions
