using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace UserProfileUpdater
{
    public class ProfileUpdateManager
    {
        private const string FILE_PATH = "user-profiles.bin";
        private const int MAX_VERSIONS = 2;

        public void UpdateProfiles(string apiUrl, string apiKey)
        {
            try
            {
                // Load data from the binary file
                BinaryFormatter formatter = new BinaryFormatter();
                using (FileStream fs = File.Open(FILE_PATH, FileMode.Open))
                {
                    UserProfile[] profiles = (UserProfile[])formatter.Deserialize(fs);
                    Console.WriteLine($"Loaded {profiles.Length} user profiles from file");

                    // Validate the deserialized data against the remote schema
                    foreach (UserProfile profile in profiles)
                    {
                        if (!ValidateProfile(profile))
                        {
                            Console.WriteLine($"Invalid profile: {profile}");
                            continue;
                        }
                    }

                    // Send the validated data to the external API for profile updates
                    foreach (UserProfile profile in profiles)
                    {
                        UpdateProfile(apiUrl, apiKey, profile);
                    }
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error updating profiles: {e.Message}");
            }
        }

        private bool ValidateProfile(UserProfile profile)
        {
            // Validate the user information against a remote schema
            try
            {
                HttpClient client = new HttpClient();
                client.BaseAddress = new Uri(apiUrl);
                client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

                UserProfileSchema schema = JsonConvert.DeserializeObject<UserProfileSchema>(await client.GetStringAsync("/schema"));
                if (profile != null && profile.Email != null)
                {
                    return ValidateEmail(profile.Email, schema);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error validating profile: {e.Message}");
            }
            return false;
        }

        private bool ValidateEmail(string email, UserProfileSchema schema)
        {
            // Implement a custom email validation using the remote schema
            try
            {
                Regex regex = new Regex(schema.emailRegex);
                if (regex.IsMatch(email))
                {
                    return true;
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error validating email: {e.Message}");
            }
            return false;
        }

        private void UpdateProfile(string apiUrl, string apiKey, UserProfile profile)
        {
            // Send the user information to the external API for profile updates
            try
            {
                HttpClient client = new HttpClient();
                client.BaseAddress = new Uri(apiUrl);
                client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

                UserProfileUpdate update = new UserProfileUpdate()
                {
                    Email = profile.Email,
                    PhoneNumber = profile.PhoneNumber
                };

                HttpResponseMessage response = await client.PostAsync("/profiles/" + profile.Id, update);
                if (response.IsSuccessStatusCode)
                {
                    Console.WriteLine($"Updated profile: {profile}");
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error updating profile: {e.Message}");
            }
        }

        public class UserProfile
        {
            public int Id { get; set; }
            public string Email { get; set; }
            public string PhoneNumber { get; set; }
        }

        public class UserProfileUpdate
        {
            public string Email { get; set; }
            public string PhoneNumber { get; set; }
        }

        public class UserProfileSchema
        {
            public string emailRegex { get; set; }
        }
    }
}
