#include <iostream>
#include <fstream>
#include <string>
#include <chrono>
#include <thread>

using namespace std;

// Function to randomly select an attack for the character and wait for its cooldown period
void selectAttack(Character& char) {
    // Vector of available attacks
    vector<string> attacks = {"Slash", "Fireball", "Poison Dart"};

    // Current time in seconds
    int currentTime = (int)chrono::system_clock::now().time_since_epoch().count();

    // Previous attack type and its cooldown period
    string previousAttack;
    int previousCooldown = 0;

    // Check if the character has used the same attack consecutively
    if (previousAttack == char.getLastAttack()) {
        // Wait until the next available cooldown period before allowing another attack of the same type
        while (currentTime - previousCooldown < 6) {
            this_thread::sleep_for(chrono::seconds(1));
            currentTime = (int)chrono::system_clock::now().time_since_epoch().count();
        }
    }

    // Randomly select an attack from the vector of available attacks
    int randomAttackIndex = rand() % attacks.size();
    string selectedAttack = attacks[randomAttackIndex];

    // Set the previous attack type and cooldown period based on the selected attack
    if (selectedAttack == "Slash") {
        previousAttack = "Slash";
        previousCooldown = currentTime + 6;
    } else if (selectedAttack == "Fireball") {
        previousAttack = "Fireball";
        previousCooldown = currentTime + 12;
    } else {
        previousAttack = "Poison Dart";
        previousCooldown = currentTime + 3;
    }

    // Set the character's last attack to the selected attack
    char.setLastAttack(selectedAttack);

    // Log each attack used to a file
    ofstream logFile("attacks.log", ios::app);
    if (!logFile) {
        cerr << "Error opening attacks.log" << endl;
        return;
    }
    logFile << currentTime << ": " << selectedAttack << endl;
    logFile.close();
}
