const express = require('express');
const app = express();
const axios = require('axios');
const cheerio = require('cheerio');
const moment = require('moment');
const { Cache } = require('cache-manager');
const cacheManager = new Cache();

app.get('/weather/:location', (req, res) => {
  const location = req.params.location;
  const apiKey = 'YOUR_API_KEY'; // Replace with your OpenWeatherMap API key
  let currentWeather;
  let forecast;
  let monthlyStatistics;
  let historicalEvents;

  // Get current weather conditions from OpenWeatherMap API
  axios.get(`http://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${apiKey}`)
    .then(response => {
      currentWeather = response.data;
      return axios.get(`http://api.openweathermap.org/data/2.5/forecast?q=${location}&appid=${apiKey}`);
    })
    .then(response => {
      forecast = response.data;
      // Get average temperature statistics for each month over the past year from Climate API
      axios.get(`http://api.climacell.com/v3/weather/time-series?location=${location}&start=1year&end=today&unit=imperial`)
        .then(response => {
          monthlyStatistics = response.data;
          return axios.get(`http://api.climacell.com/v3/weather/historical?location=${location}&start=1year&end=today&unit=imperial`);
        })
        .then(response => {
          historicalEvents = response.data;
          const weatherData = {
            current_weather: currentWeather,
            forecast: forecast,
            monthly_statistics: monthlyStatistics,
            historical_events: historicalEvents
          };
          res.json(weatherData);
        })
        .catch(error => {
          console.log(`Error getting weather data for ${location}:`, error);
        });
    })
    .catch(error => {
      console.log(`Error getting weather forecast for ${location}:`, error);
    });
});

app.listen(3000, () => {
  console.log('Weather microservice listening on port 3000');
});
