#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

// Function to read integers from a file and store them in an array
int* readIntegers(const char* filename, int* numInts) {
  // Open the file for reading
  FILE *file = fopen(filename, "r");
  if (file == NULL) {
    printf("Error: Could not open file %s\n", filename);
    return NULL;
  }

  // Initialize an array to hold the integers
  int* arr = malloc(sizeof(int) * 100);
  if (arr == NULL) {
    printf("Error: Could not allocate memory for array\n");
    fclose(file);
    return NULL;
  }

  // Read the integers from the file and store them in the array
  int i = 0;
  while (!feof(file) && !ferror(file)) {
    if (fscanf(file, "%d", &arr[i]) != 1) {
      printf("Error: Could not read integer from file %s\n", filename);
      fclose(file);
      return NULL;
    }
    i++;
  }

  // Close the file
  fclose(file);

  // Check if there were any errors during reading
  if (ferror(file)) {
    printf("Error: Reading from file %s failed\n", filename);
    free(arr);
    return NULL;
  }

  // Sort the array in ascending order
  qsort(arr, i, sizeof(int), compareInts);

  *numInts = i;
  return arr;
}

// Function to sort an integer array in ascending order using quicksort
void quickSort(int* arr, int left, int right) {
  if (left < right) {
    int partitionIndex = partition(arr, left, right);
    quickSort(arr, left, partitionIndex - 1);
    quickSort(arr, partitionIndex + 1, right);
  }
}

// Function to partition an integer array around a pivot element
int partition(int* arr, int left, int right) {
  int pivot = arr[right];
  int i = left - 1;

  for (int j = left; j < right; j++) {
    if (arr[j] <= pivot) {
      i++;
      swap(&arr[i], &arr[j]);
    }
  }

  swap(&arr[i + 1], &arr[right]);
  return i + 1;
}

// Function to swap two integers in an array
void swap(int* a, int* b) {
  int temp = *a;
  *a = *b;
  *b = temp;
}

// Function to compare two integers for sorting
int compareInts(const void* a, const void* b) {
  return (*(int*)a - *(int*)b);
}

// Function to find the largest integer in an array
int getMax(int* arr, int size) {
  int max = INT_MIN;
  for (int i = 0; i < size; i++) {
    if (arr[i] > max) {
      max = arr[i];
    }
  }
  return max;
}

// Main function to test the functions above
int main() {
  int* nums;
  int numInts;

  // Read integers from a file and store them in an array
  nums = readIntegers("integers.txt", &numInts);
  if (nums == NULL) {
    printf("Error: Could not read integers from file\n");
    return -1;
  }

  // Print the largest integer in the array
  int max = getMax(nums, numInts);
  printf("The largest integer in the array is %d\n", max);

  // Free the memory allocated for the array
  free(nums);

  return 0;
}
