using System;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Generic;
using Newtonsoft.Json;

// Define the custom data structure for deserializing the binary file
[Serializable]
public class UserProfile
{
    public string Email { get; set; }
    public string PhoneNumber { get; set; }
    public Address Address { get; set; }
}

// Define the external RESTful API client
public class ExternalApiClient
{
    private readonly HttpClient _httpClient = new HttpClient();

    public Task<bool> UpdateUserProfileAsync(UserProfile profile)
    {
        var jsonPayload = JsonConvert.SerializeObject(profile);
        var content = new StringContent(jsonPayload, Encoding.UTF8, "application/json");
        return _httpClient.PostAsync("https://example.com/api/update-user-profile", content);
    }
}

// Define the function to load and deserialize the binary file
public static async Task<List<UserProfile>> LoadAndDeserializeAsync(string filePath, string encryptionKey)
{
    List<UserProfile> userProfiles = new List<UserProfile>();

    // Load the compressed binary file using a file stream
    using (var fs = File.OpenRead(filePath))
    {
        // Decompress the file stream using gzip decompression
        using var ds = new GZipStream(fs, CompressionMode.Decompress);

        // Deserialize the decompressed data using BinaryFormatter and a custom serialization binder
        var formatter = new BinaryFormatter();
        formatter.Binder = new CustomSerializationBinder();
        while (ds.Position < ds.Length)
        {
            try
            {
                // Deserialize the user profile from the binary data
                UserProfile profile = (UserProfile)formatter.Deserialize(ds);
                userProfiles.Add(profile);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to deserialize user profile at position {ds.Position}: {ex.Message}");
            }
        }
    }

    return userProfiles;
}

// Define a custom serialization binder for the BinaryFormatter
public class CustomSerializationBinder : SerializationBinder
{
    public override Type BindToType(string assemblyName, string typeName)
    {
        if (typeName == typeof(UserProfile).FullName)
        {
            return typeof(UserProfile);
        }

        throw new Exception($"Unknown type '{typeName}'");
    }
}

// Define a function to update user profiles on the external API
public static async Task UpdateProfilesAsync(List<UserProfile> profiles)
{
    using var client = new ExternalApiClient();
    foreach (var profile in profiles)
    {
        try
        {
            await client.UpdateUserProfileAsync(profile);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to update user profile '{profile.Email}': {ex.Message}");
        }
    }
}
