import json
import requests
import logging
from pathlib import Path
from contextlib import closing

class CustomConfig:
    def __init__(self, config_file):
        self.config = {}
        self.load(config_file)

    def load(self, config_file):
        try:
            with open(config_file, 'r') as f:
                self.config = json.load(f)
        except Exception as e:
            logging.error("Error loading configuration file: {}".format(e))

    def get(self, key):
        return self.config.get(key)

    def set(self, key, value):
        self.config[key] = value

class ConfigLoader:
    def __init__(self, config_file, api_url=None):
        self.config = CustomConfig(config_file)
        self.api_url = api_url

    def load_remote_config(self):
        try:
            with closing(requests.get(self.api_url)) as r:
                remote_config = r.json()
                self.merge_configs(remote_config)
        except Exception as e:
            logging.error("Error fetching remote configuration: {}".format(e))

    def merge_configs(self, new_config):
        for key, value in new_config.items():
            self.config.set(key, value)

    def update_config(self):
        self.load_remote_config()
        logging.info("Updated configuration: {}".format(self.config))

class ConfigError(Exception):
    pass

def main():
    config_file = Path("/path/to/config.json")
    api_url = "https://example.com/api/config"
    loader = ConfigLoader(config_file, api_url)
    while True:
        try:
            loader.update_config()
        except ConfigError as e:
            logging.error("Error updating configuration: {}".format(e))
        else:
            logging.info("Configuration updated successfully.")
```
