using System;
using System.IO;
using ThirdPartyLoggingLibrary;

public class BinaryFileCacheLoader {
    private const string CacheFileName = "user-preferences.bin";

    public UserPreferences LoadUserPreferences(string userId) {
        try {
            // Try to load the cache file
            using (var fileStream = new FileStream(CacheFileName, FileMode.OpenOrCreate)) {
                if (!fileStream.CanRead) {
                    throw new IOException("Cache file is not readable");
                }

                // Deserialize the user preferences from the cache file
                using (var reader = new BinaryReader(fileStream)) {
                    return UserPreferences.FromBinary(reader);
                }
            }
        } catch (IOException ex) {
            LoggingLibrary.LogError($"Failed to read cache file: {ex}");
            // Fallback mechanism - load user preferences from database if the cache is unavailable
            return LoadUserPreferencesFromDatabase(userId);
        }
    }

    private UserPreferences LoadUserPreferencesFromDatabase(string userId) {
        try {
            // Load user preferences from database
            var dbQuery = "SELECT * FROM user_preferences WHERE user_id = @userId";
            var dbResults = DatabaseConnection.Instance.ExecuteQuery<UserPreferences>(dbQuery, new { userId });
            return UserPreferences.FromDatabase(dbResults);
        } catch (Exception ex) {
            LoggingLibrary.LogError($"Failed to load user preferences from database: {ex}");
            // Fallback mechanism - return empty user preferences if the database query fails
            return new UserPreferences();
        }
    }
}
