public class ReportGenerator {
    private static final Logger logger = Logger.getLogger(ReportGenerator.class.getName());

    public CompletableFuture<byte[]> generateReportAsync(HttpServletRequest request) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                // Get report parameters from the request
                String reportName = request.getParameter("report");
                List<String> databaseNames = Arrays.asList(request.getParameter("databases").split(","));
                String query = request.getParameter("query");

                // Connect to databases
                MongoClient mongoClient = new MongoClient("mongodb://localhost:27017/");
                Connection mysqlConnection = new com.mysql.jdbc.Connection(null, null);
                Connection postgresqlConnection = new org.postgresql.Driver().connect("jdbc:postgresql://localhost:5432/", null);

                // Fetch data from databases
                List<String> databaseResults = new ArrayList<>();
                for (String databaseName : databaseNames) {
                    switch (databaseName) {
                        case "mongodb":
                            DBCursor cursor = mongoClient.getDatabase(reportName).getCollection("data").find(query);
                            while (cursor.hasNext()) {
                                databaseResults.add(cursor.next().toJson());
                            }
                            break;
                        case "mysql":
                            Statement statement = mysqlConnection.createStatement();
                            ResultSet resultSet = statement.executeQuery(query);
                            while (resultSet.next()) {
                                databaseResults.add(resultSet.getString("data"));
                            }
                            break;
                        case "postgresql":
                            statement = postgresqlConnection.createStatement();
                            resultSet = statement.executeQuery(query);
                            while (resultSet.next()) {
                                databaseResults.add(resultSet.getString("data"));
                            }
                            break;
                    }
                }

                // Perform complex data aggregation and transformation tasks
                // ...

                // Format results into a customizable PDF report
                Gson gson = new Gson();
                String jsonData = gson.toJson(databaseResults);
                byte[] pdfBytes = generatePDFReport(jsonData, reportName);

                return pdfBytes;
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Error generating report", e);
            } finally {
                mongoClient.close();
                mysqlConnection.close();
                postgresqlConnection.close();
            }
            return null;
        });
    }

    public static byte[] generatePDFReport(String jsonData, String reportName) {
