using System;
using System.Threading;
using System.IO;
using System.Net.Http;
using Newtonsoft.Json;

namespace WebServerManagementAPI
{
    public static class AddAndStartWebsite
    {
        private static readonly HttpClient _httpClient = new HttpClient();
        private static readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

        public static async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName)
        {
            if (!Directory.Exists(directoryPath))
                return "The specified directory path does not exist.";

            if (File.Exists($"{directoryPath}/web.config"))
                return "A web.config file already exists in the directory.";

            var request = new HttpRequestMessage(HttpMethod.Post, $"/api/v1/sites?directoryPath={directoryPath}&siteName={siteName}");
            using (var response = await _httpClient.SendAsync(request))
            {
                if (!response.IsSuccessStatusCode)
                    return $"Failed to add the website: {response.ReasonPhrase}";

                var result = JsonConvert.DeserializeObject<AddWebsiteResult>(await response.Content.ReadAsStringAsync());
                if (result.Error != null)
                    return $"Failed to start the website: {result.Error}";

                request = new HttpRequestMessage(HttpMethod.Post, $"/api/v1/sites/{siteName}/start");
                using (var response = await _httpClient.SendAsync(request))
                {
                    if (!response.IsSuccessStatusCode)
                        return $"Failed to start the website: {response.ReasonPhrase}";

                    return "Website successfully added and started.";
                }
            }
        }

        public class AddWebsiteResult
        {
            public string Error { get; set; }
        }
    }
}
