#include <semaphore.h>

// Function to create a semaphore with a specified initial value
sem_t *createSemaphore(int initialValue) {
    sem_t *sem = malloc(sizeof(sem_t));
    if (sem == NULL) {
        perror("Error creating semaphore");
        exit(1);
    }
    if (sem_init(sem, 0, initialValue) != 0) {
        perror("Error initializing semaphore");
        exit(1);
    }
    return sem;
}

// Function to delete a semaphore
void deleteSemaphore(sem_t *sem) {
    if (sem == NULL) {
        fprintf(stderr, "Error deleting semaphore: semaphore is null\n");
        exit(1);
    }
    if (sem_destroy(sem) != 0) {
        perror("Error destroying semaphore");
        exit(1);
    }
    free(sem);
}

// Function to find and print the largest integer in an array of integers
int findLargestInteger(int *arr, int size) {
    if (arr == NULL || size <= 0) {
        return -1;
    }
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

// Main function to read a list of integers from standard input, store them in an array, and find and print the largest integer
int main() {
    // Create a semaphore with initial value 0
    sem_t *sem = createSemaphore(0);

    // Read the list of integers from standard input and store them in an array
    int arr[10];
    for (int i = 0; i < 10; i++) {
        scanf("%d", &arr[i]);
        sem_wait(sem);
    }

    // Find the largest integer in the array and print it
    int largest = findLargestInteger(arr, 10);
    printf("The largest integer is %d\n", largest);

    // Delete the semaphore
    deleteSemaphore(sem);

    return 0;
}
