using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public static class FileHasher
{
    public static async Task<string> GetSecureHashAsync(string filePath)
    {
        try
        {
            using (var fs = new FileStream(filePath, FileMode.Open))
            {
                using (var md5 = MD5.Create())
                {
                    var hash = await ComputeHashInChunksAsync(fs, md5);
                    return hash;
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine("Error occurred while computing the hash: " + e.Message);
            return null;
        }
    }

    private static async Task<string> ComputeHashInChunksAsync(Stream stream, MD5 md5)
    {
        var buffer = new byte[1024];
        int readBytes;
        while ((readBytes = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            md5.TransformBlock(buffer, 0, readBytes, null, 0);
        }
        md5.TransformFinalBlock(buffer, 0, readBytes);
        return Convert.ToBase64String(md5.Hash);
    }
}
