use std::time::Instant;
use std::sync::Once;
use std::io::Error;
use std::process::Command;

fn send_to_database(data: &[u8]) -> Result<DataTableReader, String> {
    let start = Instant::now();
    let mut cmd = Command::new("my_command");
    cmd.arg("--input").arg(data);
    let output = cmd.output().unwrap();
    let time_taken = start.elapsed().as_secs();

    if output.status.success() {
        // Convert the output to a string
        let output_string = String::from_utf8(output.stdout).unwrap();

        // Use the string to run another command to send the data to the database
        let mut cmd2 = Command::new("my_other_command");
        cmd2.arg("--input").arg(&output_string);
        let _ = cmd2.spawn().unwrap();

        // Catch any errors that occur during the execution of the command
        if let Err(err) = cmd2.wait() {
            early_error!("Error executing my_other_command: {}", err);
        }

        // Return the result of the query as a DataTableReader object wrapped in a Result type
        Ok(DataTableReader::new(output_string))
    } else {
        // Return an error message if the database operation is unsuccessful
        Err(format!("Error executing my_command: {}", output.status))
    }
}
