#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SESSIONS 100
#define MONTH_DAYS 30

typedef struct {
    int userId;
    int sessionId;
    TrafficStats trafficStats;
} UserSession;

void populateUserSessionList(int n) {
    // Allocate memory for the list
    UserSession* sessions = (UserSession*) malloc(sizeof(UserSession) * n);
    if (!sessions) {
        return;
    }

    // Initialize the list with randomly generated byte counts for the current month
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        sessions[i].userId = rand() % 10000;
        sessions[i].sessionId = rand() % 10000;
        sessions[i].trafficStats.incomingBytes = rand() % MONTH_DAYS * 1024;
        sessions[i].trafficStats.outgoingBytes = rand() % MONTH_DAYS * 1024;
    }

    // Ensure that the list does not exceed a specified maximum size
    int sessionCount = 0;
    while (sessionCount < n) {
        UserSession* newSession = sessions + sessionCount;
        if (sessionCount == MAX_SESSIONS - 1) {
            break;
        }
        ++sessionCount;
        memcpy(newSession, &sessions[rand() % (n - sessionCount)], sizeof(UserSession));
    }

    // Deallocate memory for the list
    free(sessions);
}
