```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace Decryption
{
    public class AESDecrypter : IDisposable
    {
        private readonly byte[] _key;
        private readonly byte[] _iv;
        private readonly PaddingMode _padding;

        public AESDecrypter(byte[] key, byte[] iv = null, PaddingMode padding = PaddingMode.PKCS7)
        {
            _key = key ?? throw new ArgumentNullException(nameof(key));
            _iv = iv ?? GenerateIV();
            _padding = padding;
        }

        public byte[] Decrypt(byte[] ciphertext)
        {
            if (ciphertext == null || ciphertext.Length == 0)
                throw new ArgumentException("Ciphertext cannot be empty", nameof(ciphertext));

            ValidateKeyAndIV();

            using var aes = AES.Create();
            aes.Mode = CipherMode.CBC;
            aes.Padding = _padding;
            aes.Key = _key;
            aes.IV = _iv;

            using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            using var msDecrypted = new MemoryStream();

            using (var csDecrypted = new CryptoStream(msDecrypted, decryptor, CryptoStreamMode.Write))
            {
                csDecrypted.Write(ciphertext, 0, ciphertext.Length);
                csDecrypted.FlushFinalBlock();
            }

            return msDecrypted.ToArray();
        }

        private void ValidateKeyAndIV()
        {
            if (_key.Length != 16 && _key.Length != 24 && _key.Length != 32)
                throw new ArgumentException("Invalid key length", nameof(key));

            if (_iv.Length != 16)
                throw new ArgumentException("Invalid IV length", nameof(iv));
        }

        private byte[] GenerateIV()
        {
            using var rng = new RNGCryptoServiceProvider();
            var ivBytes = new byte[16];
            rng.GetNonZeroBytes(ivBytes);
            return ivBytes;
        }

        public void Dispose()
        {
            _key?.Dispose();
            _iv?.Dispose();
        }
    }
}
```
