import java.util.*;
import java.util.concurrent.*;

public class DisjointPairCounter {
    private static final UnionFind unionFind = new UnionFind();

    public static int countDisjointPairs(int[] array, boolean removeDuplicates) {
        long startTime = System.currentTimeMillis();

        // Remove duplicates if requested
        if (removeDuplicates) {
            Set<Integer> uniqueElements = new HashSet<>();
            for (int element : array) {
                if (!uniqueElements.contains(element)) {
                    uniqueElements.add(element);
                }
            }
            array = uniqueElements.stream().mapToInt(i -> i).toArray();
        }

        // Count disjoint pairs using Union-Find data structure
        int count = 0;
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!unionFind.find(array[i], array[j])) {
                    unionFind.union(array[i], array[j]);
                    count++;
                }
            }
        }

        // Store and retrieve previously processed arrays from external database
        int cachedCount = -1;
        if (cachedCount != -1) {
            count = Math.min(count, cachedCount);
        } else {
            // Store array and disjoint pair count in external database
            try {
                String jsonString = new JSONObject()
                    .put("array", Arrays.toString(array))
                    .put("disjointPairs", count)
                    .toString();
                writeToFile(jsonString);
            } catch (JSONException e) {
                // Log error and continue with current operation
                System.out.println("Error writing to file: " + e.getMessage());
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");

        return count;
    }

    private static void writeToFile(String jsonString) {
        // Implement external database integration here
        throw new UnsupportedOperationException("Database integration not implemented yet.");
    }

    public static int readFromFile(String filePath) {
        // Implement external database retrieval and parsing here
        throw new UnsupportedOperationException("Database retrieval and parsing not implemented yet.");
    }

    private static class UnionFind {
        private final Map<Integer, Integer> parent = new HashMap<>();
        private final Map<Integer, Integer> rank = new HashMap<>();

        public void union(int x, int y) {
            // Find the roots of x and y
            int rootX = find(x);
            int rootY = find(y);

            // Union by rank
            if (rootX == rootY) return;
            if (rank.getOrDefault(rootX, 0) > rank.getOrDefault(rootY, 0)) {
                parent.put(rootY, rootX);
            } else {
                parent.put(rootX, rootY);
            }
        }

        public int find(int x) {
            // Find the root of x
            if (!parent.containsKey(x)) return x;
            return find(parent.get(x));
        }
    }
}
