```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <mysql.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
    char **tags;
} Record;

void populate_records(int num_servers, char **server_addresses) {
    // Initialize variables
    int i, j;
    Record *records = NULL;
    MYSQL *mysql[num_servers];
    MYSQL_RES *result[num_servers];
    MYSQL_ROW row[num_servers];
    pthread_mutex_t mutex;
    pthread_cond_t cond;

    // Allocate memory for the arrays
    records = (Record *)malloc(sizeof(Record) * num_servers);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }
    mysql = (MYSQL **)malloc(num_servers * sizeof(MYSQL *));
    if (!mysql) {
        fprintf(stderr, "Failed to allocate memory for MySQL connections\n");
        free(records);
        return;
    }
    result = (MYSQL_RES **)malloc(num_servers * sizeof(MYSQL_RES *));
    if (!result) {
        fprintf(stderr, "Failed to allocate memory for MySQL results\n");
        free(records);
        free(mysql);
        return;
    }
    row = (MYSQL_ROW *)malloc(num_servers * sizeof(MYSQL_ROW));
    if (!row) {
        fprintf(stderr, "Failed to allocate memory for MySQL rows\n");
        free(records);
        free(mysql);
        free(result);
        return;
    }

    // Initialize mutex and condition variable
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Connect to all servers in parallel
    for (i = 0; i < num_servers; ++i) {
        mysql[i] = mysql_init(NULL);
        if (!mysql[i]) {
            fprintf(stderr, "Failed to initialize MySQL connection\n");
            free(records);
            free(mysql);
            free(result);
            free(row);
            return;
        }
        mysql_options(mysql[i], MYSQL_READ_DEFAULT_FILE, "/etc/my.cnf");
        if (mysql_real_connect(mysql[i], server_addresses[i], "user", "password", "dbname", 0, NULL, 0) == NULL) {
            fprintf(stderr, "Failed to connect to MySQL\n");
            free(records);
            free(mysql);
            free(result);
            free(row);
            return;
        }
    }

    // Start populating records in parallel
    for (i = 0; i < num_servers; ++i) {
        pthread_create(&threads[i], NULL, populate_records_helper, &mysql[i]);
    }

    // Wait for all threads to complete
    for (i = 0; i < num_servers; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free resources
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    for (i = 0; i < num_servers; ++i) {
        mysql_close(mysql[i]);
    }
    free(records);
    free(mysql);
    free(result);
    free(row);
}

void *populate_records_helper(void *arg) {
    MYSQL **mysql = (MYSQL **)arg;
    Record *record = NULL;
    int num_rows = 0;
    char query[1024];

    // Lock mutex before accessing shared resources
    pthread_mutex_lock(&mutex);

    // Query database for records
    sprintf(query, "SELECT * FROM table");
    if (mysql_real_query(*mysql, query, strlen(query)) != 0) {
        fprintf(stderr, "Failed to execute MySQL query\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    result = mysql_store_result(mysql[i]);
    if (!result) {
        fprintf(stderr, "Failed to retrieve MySQL results\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Parse query results and create records
    num_rows = mysql_num_rows(result);
    for (i = 0; i < num_rows; ++i) {
        row = mysql_fetch_row(result);
        record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for Record\n");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        record->offset = atol(row[0]);
        record->key = atoi(row[1]);
        record->timestamp = atof(row[2]);
        // Assign tags using strdup() to allocate memory for each string
        for (j = 3; j < num_rows; ++j) {
            char *tag = strdup(row[j]);
            if (!tag) {
                fprintf(stderr, "Failed to allocate memory for tag\n");
                pthread_mutex_unlock(&mutex);
                return NULL;
            }
            record->tags[j - 3] = tag;
        }
        // Add record to the array of records
        records[num_rows - 1] = record;
    }

    // Unlock mutex after accessing shared resources
    pthread_mutex_unlock(&mutex);

    return NULL;
}
```
Note that this code assumes that you have already defined the `Record` struct and that you have a list of SQL server addresses to connect to. The function `populate_records()` allocates memory for the arrays of records, connects to all servers in parallel using `pthread_create()`, and then starts populating records in parallel using `pthread_join()`. The function also includes error handling for potential SQL server connectivity issues and uses a mutex and condition variable to ensure thread safety.

