using System;
using System.Security.Cryptography;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace AESDecrypter
{
    public class DecryptionService
    {
        private readonly ILogger<DecryptionService> _logger;
        private readonly IDatabaseService _databaseService;

        public DecryptionService(ILogger<DecryptionService> logger, IDatabaseService databaseService)
        {
            _logger = logger;
            _databaseService = databaseService;
        }

        public async Task<string> DecryptFileAsync(string filePath, string ciphertext, int keyLength, PaddingMode paddingMode, string iv)
        {
            var plaintext = string.Empty;

            try
            {
                _logger.LogInformation("Starting decryption process for file {filePath}", filePath);

                using var aes = Aes.Create();
                aes.KeySize = keyLength;
                aes.Padding = paddingMode;
                aes.IV = Encoding.ASCII.GetBytes(iv);
                aes.BlockSize = 128;

                using var memoryStream = new MemoryStream();
                using var cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Write);
                await cryptoStream.WriteAsync(Convert.FromBase64String(ciphertext));
                cryptoStream.FlushFinalBlock();

                plaintext = Encoding.ASCII.GetString(memoryStream.ToArray());
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error occurred during decryption for file {filePath}", filePath);
            }

            return plaintext;
        }
    }
}
