```java
import java.util.List;

public class PokemonService {
  private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/";
  private static final int MAX_RETRIES = 3;
  private static final int RATE_LIMIT_DURATION = 1000; // milliseconds

  public PokemonResponse fetchPokemon(int pokemonId) {
    String apiUrl = API_URL + pokemonId;
    return makeApiCall(apiUrl);
  }

  private PokemonResponse makeApiCall(String apiUrl) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
      try {
        String response = fetchFromApi(apiUrl);
        return parseResponse(response);
      } catch (Exception e) {
        retries++;
        if (retries >= MAX_RETRIES) {
          throw new RuntimeException("Exceeded maximum number of retries", e);
        }
        // Handle temporary failures by sleeping for a duration proportional to the number of retries
        long sleepDuration = RATE_LIMIT_DURATION * (retries + 1);
        try {
          Thread.sleep(sleepDuration);
        } catch (InterruptedException e) {
          // Ignore
        }
      }
    }
    return null;
  }

  private String fetchFromApi(String apiUrl) throws Exception {
    HttpURLConnection connection = (HttpURLConnection) new URL(apiUrl).openConnection();
    connection.setRequestMethod("GET");
    int responseCode = connection.getResponseCode();
    if (responseCode != 200) {
      throw new RuntimeException("API request failed with status code " + responseCode);
    }
    return connection.getInputStream().toString();
  }

  private PokemonResponse parseResponse(String response) throws Exception {
    JsonNode root = new ObjectMapper().readTree(response);
    String name = root.path("name").asText();
    String type = root.path("type").asText();
    List<String> weaknesses = root.path("weaknesses").findValuesAsText("name");
    JsonNode nextEvolution = root.path("next_evolution");
    String nextPokemonName = null;
    Integer nextLevel = null;
    if (nextEvolution != null) {
      nextPokemonName = nextEvolution.path("name").asText();
      nextLevel = nextEvolution.path("level").asInt();
    }
    return new PokemonResponse(name, type, weaknesses, nextPokemonName, nextLevel);
  }
}

class PokemonResponse {
  private final String name;
  private final String type;
  private final List<String> weaknesses;
  private final String nextPokemonName;
  private final Integer nextLevel;

  public PokemonResponse(String name, String type, List<String> weaknesses, String nextPokemonName, Integer nextLevel) {
    this.name = name;
    this.type = type;
    this.weaknesses = weaknesses;
    this.nextPokemonName = nextPokemonName;
    this.nextLevel = nextLevel;
  }

  public String getName() {
    return name;
  }

  public String getType() {
    return type;
  }

  public List<String> getWeaknesses() {
    return weaknesses;
  }

  public String getNextPokemonName() {
    return nextPokemonName;
  }

  public Integer getNextLevel() {
    return nextLevel;
  }
}
