```c
#include <stdio.h>
#include <stdarg.h>
#include <errno.h>
#include <string.h>

void logError(const char* format, ...) {
    va_list args;
    va_start(args, format);
    int rc = vsnprintf(NULL, 0, format, args);
    if (rc > 0) {
        char* buffer = malloc(rc + 1);
        if (buffer != NULL) {
            vsnprintf(buffer, rc + 1, format, args);
            fprintf(stderr, "ERROR: %s\n", buffer);
            free(buffer);
        } else {
            fprintf(stderr, "ERROR: failed to allocate memory for error message\n");
        }
    }
    va_end(args);
}
