public class PokemonService {
    private static final Logger logger = LogManager.getLogger(PokemonService.class);

    // Configure the external API URLs for weaknesses, evolution details, and habitat information
    private static final String WEAKNESSES_API_URL = "https://external-api-for-weaknesses.com/pokemons/{id}";
    private static final String EVOLUTION_DETAILS_API_URL = "https://external-api-for-evolution-details.com/pokemons/{id}";
    private static final String HABITAT_INFO_API_URL = "https://external-api-for-habitat-info.com/pokemons/{id}";

    // Configure the fallback API URL in case the primary APIs are unavailable
    private static final String FALLBACK_API_URL = "https://fallback-api.com/pokemons/{id}";

    // Implement caching mechanisms to reduce redundant API calls and improve response times
    private static Cache<String, JsonNode> weaknessesCache;
    private static Cache<String, JsonNode> evolutionDetailsCache;
    private static Cache<String, JsonNode> habitatInfoCache;

    // Thread pool for handling multiple concurrent requests
    private static ExecutorService executorService = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        weaknessesCache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterWrite(24, TimeUnit.HOURS)
                .build();

        evolutionDetailsCache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterWrite(24, TimeUnit.HOURS)
                .build();

        habitatInfoCache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterWrite(24, TimeUnit.HOURS)
                .build();

        // Start the executor service for handling concurrent requests
        executorService.execute(() -> {
            while (true) {
                try {
                    Thread.sleep(10_000);
                } catch (InterruptedException e) {
                    logger.error("Thread interrupted", e);
                    return;
                }
                weaknessesCache.cleanUp();
                evolutionDetailsCache.cleanUp();
                habitatInfoCache.cleanUp();
            }
        });

        // Start the HTTP server for handling incoming requests
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/pokemons/{id}", new PokemonHandler());
        server.setExecutor(executorService);
        server.start();
    }

    // Handle incoming HTTP requests and delegate to the appropriate handler methods
    private static class PokemonHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            String requestMethod = exchange.getRequestMethod();
            if (!"GET".equalsIgnoreCase(requestMethod)) {
                // Return a 405 Method Not Allowed status code for unsupported methods
                exchange.sendResponseHeaders(405, -1);
                return;
            }

            // Parse the Pokemon ID from the request URL path
            String[] urlPath = exchange.getRequestURI().getPath().split("/");
            if (urlPath.length != 3 || !"pokemons".equals(urlPath[1])) {
                // Return a 404 Not Found status code for invalid Pokemon IDs or non-GET requests
                exchange.sendResponseHeaders(404, -1);
                return;
            }

            String pokemonId = urlPath[2];

            // Fetch data from the external APIs and fallback to a local cache if necessary
            JsonNode weaknessesData = getWeaknessesData(pokemonId);
            JsonNode evolutionDetailsData = getEvolutionDetailsData(pokemonId);
            JsonNode habitatInfoData = getHabitatInfoData(pokemonId);

            // Create a JSON response with the Pokemon's name, type, weaknesses, and habitat information
            Map<String, Object> response = new HashMap<>();
            response.put("name", pokemonId);
            response.put("type", "Pokemon");
            response.put("weaknesses", getWeaknesses(weaknessesData));
            response.put("evolutionDetails", getEvolutionDetails(evolutionDetailsData));
            response.put("habitatInfo", getHabitatInfo(habitatInfoData));

            // Return the JSON response to the client
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, 0);
            OutputStream os = exchange.getResponseBody();
            os.write(new Gson().toJson(response).getBytes());
            os.close();
        }
    }

    // Get weaknesses data from the external API or fallback to a local cache if necessary
    private static JsonNode getWeaknessesData(String pokemonId) {
        try {
            return fetchDataFromApi(WEAKNESSES_API_URL, pokemonId);
        } catch (Exception e) {
            logger.error("Error fetching weaknesses data for Pokemon " + pokemonId, e);
            // Return a local cache value if available
            return getCachedWeaknessesData(pokemonId);
        }
    }

    // Get evolution details from the external API or fallback to a local cache if necessary
    private static JsonNode getEvolutionDetailsData(String pokemonId) {
        try {
            return fetchDataFromApi(EVOLUTION_DETAILS_API, pokemonId);
        } catch (Exception e) {
            logger.error("Error fetching evolution details data for Pokemon " + pokemonId, e);
            // Return a local cache value if available
            return getCachedEvolutionDetailsData(pokemonId);
        }
    }

    // Get habitat information from the external API or fallback to a local cache if necessary
    private static JsonNode getHabitatInfoData(String pokemonId) {
        try {
            return fetchDataFromApi(HABITAT_INFO_API, pokemonId);
        } catch (Exception e) {
            logger.error("Error fetching habitat information data for Pokemon " + pokemonId, e);
            // Return a local cache value if available
            return getCachedHabitatInfoData(pokemonId);
        }
    }

    // Fetch data from the external API and add it to the local cache
    private static JsonNode fetchDataFromApi(String apiUrl, String pokemonId) throws Exception {
        URL url = new URL(apiUrl.replace("{id}", pokemonId));
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.connect();
        if (connection.getResponseCode() != 200) {
            throw new Exception("Invalid response code: " + connection.getResponseCode());
        }
        String jsonString = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8);
        return JsonParser.parseString(jsonString).getAsJsonObject();
    }

    // Get weaknesses data from the local cache or return null if not available
    private static JsonNode getCachedWeaknessesData(String pokemonId) {
        JsonNode cachedValue = weaknessesCache.getIfPresent(pokemonId);
        if (cachedValue == null) {
            logger.info("No local cache value for weaknesses data found for Pokemon " + pokemonId);
        }
        return cachedValue;
    }

    // Get evolution details data from the local cache or return null if not available
    private static JsonNode getCachedEvolutionDetailsData(String pokemonId) {
        JsonNode cachedValue = evolutionDetailsCache.getIfPresent(pokemonId);
        if (cachedValue == null) {
            logger.info("No local cache value for evolution details data found for Pokemon " + pokemonId);
        }
        return cachedValue;
    }

    // Get habitat information data from the local cache or return null if not available
    private static JsonNode getCachedHabitatInfoData(String pokemonId) {
        JsonNode cachedValue = habitatInfoCache.getIfPresent(pokemonId);
        if (cachedValue == null) {
            logger.info("No local cache value for habitat information data found for Pokemon " + pokemonId);
        }
        return cachedValue;
    }

    // Add weaknesses data to the local cache
    private static void addWeaknessesDataToCache(String pokemonId, JsonNode data) {
        weaknessesCache.put(pokemonId, data);
    }

    // Add evolution details data to the local cache
    private static void addEvolutionDetailsDataToCache(String pokemonId, JsonNode data) {
        evolutionDetailsCache.put(pokemonId, data);
    }

    // Add habitat information data to the local cache
    private static void addHabitatInfoDataToCache(String pokemonId, JsonNode data) {
        habitatInfoCache.put(pokemonId, data);
    }

    // Get weaknesses from external API or fallback to a local cache if necessary
    private static List<Object> getWeaknesses(JsonNode weaknessesData) {
        if (weaknessesData == null || weaknessesData.isMissingNode()) {
            logger.info("No weaknesses data found for Pokemon " + pokemonId);
            // Return a local cache value if available
            JsonNode cachedWeaknessesData = getCachedWeaknessesData(pokemonId);
            if (cachedWeaknessesData != null) {
                return Arrays.asList(cachedWeaknessesData.get("weaknesses").iterator().next());
            }
        } else {
            return weaknessesData.get("weaknesses").iterator().next();
        }
        return new ArrayList<>();
    }

    // Get evolution details from external API or fallback to a local cache if necessary
    private static List<Object> getEvolutionDetails(JsonNode evolutionDetailsData) {
        if (evolutionDetailsData == null || evolutionDetailsData.isMissingNode()) {
            logger.info("No evolution details data found for Pokemon " + pokemonId);
            // Return a local cache value if available
            JsonNode cachedEvolutionDetailsData = getCachedEvolutionDetailsData(pokemonId);
            if (cachedEvolutionDetailsData != null) {
                return Arrays.asList(cachedEvolutionDetailsData.get("evolution_details").iterator().next());
            }
        } else {
            return evolutionDetailsData.get("evolution_details").iterator().next();
        }
        return new ArrayList<>();
    }

    // Get habitat information from external API or fallback to a local cache if necessary
    private static List<Object> getHabitatInfo(JsonNode habitatInfoData) {
        if (habitatInfoData == null || habitatInfoData.isMissingNode()) {
            logger.info("No habitat information data found for Pokemon " + pokemonId);
            // Return a local cache value if available
            JsonNode cachedHabitatInfoData = getCachedHabitatInfoData(pokemonId);
            if (cachedHabitatInfoData != null) {
                return Arrays.asList(cachedHabitatInfoData.get("habitat_info").iterator().next());
            }
        } else {
            return habitatInfoData.get("habitat_info").iterator().next();
        }
        return new ArrayList<>();
    }
