public async Task<bool> VerifyHash(string filePath)
    {
        var file = new FileInfo(filePath);
        var hash = MD5.Create().ComputeHash(file);

        try
        {
            // Securely compute the MD5 hash of the file
            using (var stream = file.OpenRead())
            {
                var buffer = new byte[8192];
                int read;

                while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    hash = MD5.Create().ComputeHash(buffer);
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error while reading file: {filePath}");
            return false;
        }

        // Verify the hash against a database of known hashes using an external API
        try
        {
            var client = new HttpClient();
            var request = new HttpRequestMessage(HttpMethod.Post, "https://example.com/api/verify-hash")
                .AddJsonContent(new { hash = hash });
            var response = await client.SendAsync(request);

            if (response.IsSuccessStatusCode)
            {
                var jsonResponse = await response.Content.ReadAsStringAsync();
                var result = JsonConvert.DeserializeObject<VerifyHashResult>(jsonResponse);

                if (result.verified)
                {
                    Console.WriteLine($"Verified hash for file: {filePath}");
                    return true;
                }
                else
                {
                    Console.WriteLine($"Failed to verify hash for file: {filePath}");
                    return false;
                }
            }
            else
            {
                Console.WriteLine($"Error while verifying hash for file: {filePath}");
                return false;
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error while sending request to API: {e.Message}");
            return false;
        }
    }

    private class VerifyHashResult
    {
        public bool verified { get; set; }
    }

