// Python Function to Sort File Lines and Extract Sequence Number from Last Line
import sys

def sort_lines(filepath):
    with open(filepath) as f:
        lines = f.read().splitlines()
        sorted_lines = sorted(lines, key=lambda x: int(x))
        return " ".join(sorted_lines)

def extract_sequence_number(line):
    try:
        return line.split(" ")[-1]
    except IndexError:
        return None

if __name__ == "__main__":
    filepath = sys.argv[1]
    sorted_lines = sort_lines(filepath)
    sequence_number = extract_sequence_number(sorted_lines.splitlines()[-1])
    print(f"{sequence_number} is the last line")
