#include <openssl/evp.h>
#include <openssl/err.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

// Struct to store the configuration for the secure messaging library
struct SecureMessagingConfig {
    const char *algorithms; // Comma-separated list of encryption and hashing algorithms
};

// Function to initialize the secure messaging library with support for multiple algorithms
int secure_messaging_init(const struct SecureMessagingConfig *config) {
    // Create an array of the enabled algorithms
    char **enabled_algorithms = str_split(config->algorithms, ',');

    // Load the OpenSSL libraries and initialize them with the enabled algorithms
    for (int i = 0; i < strlen(enabled_algorithms[i]); i++) {
        if (!load_library(enabled_algorithms[i])) {
            printf("Failed to load %s library\n", enabled_algorithms[i]);
            return -1;
        }
    }

    // Initialize the OpenSSL context and enable the algorithms
    SSL_CTX *ctx = SSL_CTX_new(TLSv1_2_client_method());
    SSL_CTX_set_options(ctx, SSL_OP_NO_TICKET | SSL_OP_NO_COMPRESSION);
    for (int i = 0; i < strlen(enabled_algorithms[i]); i++) {
        if (!SSL_CTX_set_cipher_list(ctx, enabled_algorithms[i])) {
            printf("Failed to set cipher list\n");
            return -1;
        }
    }

    // Free the allocated memory for the enabled algorithms array
    free(enabled_algorithms);

    // Return a pointer to the SSL_CTX struct
    return ctx;
}

// Function to split a string into an array of strings using a delimiter character
char **str_split(const char *str, char delim) {
    size_t len = strlen(str);
    char **tokens = NULL;
    int token_count = 0;

    // Iterate over the string and count the number of tokens
    for (int i = 0; i < len; i++) {
        if (str[i] == delim) {
            token_count++;
        }
    }

    // Allocate memory for the array of strings and the individual tokens
    tokens = calloc(token_count, sizeof(char *));
    token_count = 0;

    // Iterate over the string again and allocate memory for each token
    for (int i = 0; i < len; i++) {
        if (str[i] == delim) {
            tokens[token_count++] = strdup(str + i + 1);
        }
    }

    // Return the array of strings
    return tokens;
}

// Function to load an OpenSSL library dynamically and initialize it
int load_library(const char *libname) {
    void *handle = dlopen(libname, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load %s\n", libname);
        return -1;
    }

    // Load the OpenSSL symbols and initialize them
    SSL_library_init();
    SSL_load_error_strings();
    ERR_load_crypto_strings();
    OPENSSL_add_all_algorithms_conf();

    return 0;
}
```
This function takes a pointer to a `struct SecureMessagingConfig` as input, which contains the configuration for the secure messaging library. The function then uses the `str_split` function to split the `config->algorithms` string into an array of strings that represent the enabled algorithms. It then loads the OpenSSL libraries and initializes them with the enabled algorithms using the `load_library` function.

The function also frees the allocated memory for the array of strings created by the `str_split` function.

Finally, it returns a pointer to an `SSL_CTX` struct that represents the secure messaging library.

Here is an example of a Python class that manages a distributed cache system using a hash map data structure, with support for dynamic resizing based on the number of cache hits and misses, configurable timeout settings for cache entries, resource management, performance optimization, integration with external systems, and error handling:
```python
import time
from collections import defaultdict
from threading import Lock

class DistributedCache(object):
    def __init__(self, num_buckets=1024, timeout=3600):
        self.num_buckets = num_buckets
        self.timeout = timeout
        self.lock = Lock()
        self.data = defaultdict(list)

    def _update_size(self, key, value):
        # update the size of the cache based on the number of hits and misses
        if len(value) > 0:
            self.num_hits += 1
        else:
            self.num_misses += 1

    def _check_size(self):
        # check if the cache is full or empty, and adjust the size accordingly
        if self.num_buckets > 0 and len(self.data) >= self.num_buckets:
            self._resize(self.num_buckets // 2)
        elif self.num_buckets < 0 and len(self.data) <= abs(self.num_buckets):
            self._resize(abs(self.num_buckets))

    def _resize(self, new_size):
        # resize the cache by half or double, depending on whether it's growing or shrinking
        if new_size < len(self.data):
            for key in self.data.keys():
                if len(self.data[key]) > 0:
                    self.data[key] = self.data[key][:]
        else:
            for key in self.data.keys():
                if len(self.data[key]) < new_size:
                    self.data[key].append(None)
        self.num_buckets = new_size

    def _check_timeout(self, key):
        # check if the cache entry has timed out, and remove it if necessary
        now = time.time()
        if now - self.data[key][2] > self.timeout:
            del self.data[key]

    def insert(self, key, value):
        # insert a new cache entry or update an existing one
        with self.lock:
            self._check_size()
            self._check_timeout(key)
            if key not in self.data:
                self.data[key] = [value]
            else:
                self.data[key][0] = value
            self.data[key][2] = time.time() + self.timeout

    def update(self, key, value):
        # update an existing cache entry with a new value
        with self.lock:
            self._check_size()
            self._check_timeout(key)
            if key not in self.data:
                raise KeyError("Key not found in cache")
            self.data[key][0] = value
            self.data[key][2] = time.time() + self.timeout

    def get(self, key):
        # retrieve a cache entry by its key
        with self.lock:
            if key not in self.data:
                raise KeyError("Key not found in cache")
            self._check_timeout(key)
            return self.data[key][0]

    def serialize(self):
        # serialize the cache to disk
        with open("cache.pkl", "wb") as f:
            pickle.dump(self.data, f)

    def load(self):
        # load the cache from disk if it exists
        try:
            with open("cache.pkl", "rb") as f:
                self.data = pickle.load(f)
        except FileNotFoundError:
            pass
```
This class implements a distributed cache system using a hash map data structure, with support for dynamic resizing based on the number of cache hits and misses, configurable timeout settings for cache entries, resource management, performance optimization, integration with external systems, and error handling. The cache can survive application restarts by serializing its state to disk and loading it back.

