function findElements(root, selector, testFunc = null, maxDepth = 0) {
  // Check if root is a valid DOM node
  if (!root || !(root instanceof Node)) {
    throw new Error("Invalid root element");
  }

  // Check if selector is a string
  if (typeof selector !== "string") {
    throw new Error("Selector must be a string");
  }

  // Initialize an empty list to store matching elements
  const matchingElements = [];

  // Traverse the DOM tree starting from root, up to maxDepth levels deep
  traverseDOM(root, maxDepth);

  // Return the list of matching elements
  return matchingElements;

  /**
   * Recursive function to traverse the DOM tree and find elements that match the selector
   * @param {Node} node The current node in the traversal
   * @param {number} depth The current depth of the traversal
   */
  function traverseDOM(node, depth) {
    // Check if the node matches the selector
    if (matchesSelector(node, selector)) {
      // Add the matching element to the list of matching elements
      matchingElements.push(node);
    }

    // Check if the current node has any children
    if (node.hasChildNodes()) {
      // Traverse the children nodes
      for (const childNode of node.childNodes) {
        traverseDOM(childNode, depth + 1);
      }
    }

    // Check if a test function was provided and the current node should be further filtered
    if (testFunc && matchesSelector(node, testFunc)) {
      // Add the matching element to the list of matching elements
      matchingElements.push(node);
    }
  }

  /**
   * Check if a DOM node matches a given CSS selector
   * @param {Node} node The DOM node to check
   * @param {string} selector The CSS selector to match against the node
   */
  function matchesSelector(node, selector) {
    // Check if the node has any matching classes or attributes
    const classList = node.classList;
    for (const className of classList) {
      if (className === selector || className.startsWith(selector)) {
        return true;
      }
    }

    const attributeList = node.attributes;
    for (const attributeName in attributeList) {
      if (attributeName === selector || attributeName.startsWith(selector)) {
        return true;
      }
    }

    // Check if the node has any text content that matches the selector
    const textContent = node.textContent;
    if (textContent && textContent.includes(selector)) {
      return true;
    }

    // No match found
    return false;
  }
}
```
