// Python Function
def get_pokemon_weaknesses(pokemon_id):
    # Read the Pokemon weaknesses file
    with open("pokemon_weaknesses.txt", "r") as f:
        lines = f.readlines()

    # Sort the lines by their sequence number
    sorted_lines = sorted(lines, key=lambda x: int(x.split(",")[0]))

    # Extract the weaknesses for the given Pokemon ID
    pokemon_weaknesses = []
    for line in sorted_lines:
        sequence_number, name, type, weaknesses = line.strip().split(",")
        if int(sequence_number) == pokemon_id:
            pokemon_weaknesses.append(weaknesses)

    return pokemon_weaknesses

// Java Service
@GET
@Path("/pokemons/{pokemonId}/weaknesses")
public Response getPokemonWeaknesses(@PathParam("pokemonId") int pokemonId) {
    // Fetch the Pokemon weaknesses from an external API
    String apiUrl = "https://pokeapi.co/api/v2/pokemon/" + pokemonId;
    RestTemplate restTemplate = new RestTemplate();
    ResponseEntity<String> response = restTemplate.getForEntity(apiUrl, String.class);

    // Parse the API response and extract the Pokemon weaknesses
    JSONObject jsonObject = new JSONObject(response.getBody());
    JSONArray typesJsonArray = jsonObject.getJSONArray("types");
    List<String> pokemonWeaknesses = new ArrayList<>();
    for (int i = 0; i < typesJsonArray.length(); i++) {
        JSONObject typeJsonObject = typesJsonArray.getJSONObject(i);
        String weaknesses = typeJsonObject.getString("damage_relations");
        pokemonWeaknesses.addAll(weaknesses.split(","));
    }

    // Return the Pokemon weaknesses in a JSON response
    ObjectMapper objectMapper = new ObjectMapper();
    Response response = objectMapper.createObjectNode()
            .put("name", jsonObject.getString("name"))
            .put("type", typesJsonArray.getString(0))
            .put("weaknesses", pokemonWeaknesses)
            .toString();
    return Response.ok(response).build();
}

// Unit Tests
@Test
public void testGetPokemonWeaknesses() {
    PokemonService service = new PokemonService();
    int pokemonId = 1;
    List<String> weaknesses = service.getPokemonWeaknesses(pokemonId);
    assertEquals("weaknesses", "fire,water".split(","));
}

@Test
public void testGetPokemonWeaknessesWithInvalidId() {
    PokemonService service = new PokemonService();
    int pokemonId = -1;
    List<String> weaknesses = service.getPokemonWeaknesses(pokemonId);
    assertTrue("weaknesses".isEmpty());
}

@Test
public void testGetPokemonWeaknessesWithNoWeaknesses() {
    PokemonService service = new PokemonService();
    int pokemonId = 2;
    List<String> weaknesses = service.getPokemonWeaknesses(pokemonId);
    assertTrue("weaknesses".isEmpty());
}

