import requests
from flask import Flask, jsonify, request
from flask_restful import Resource, Api
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.orm import sessionmaker
from sqlalchemy.ext.declarative import declarative_base
import logging

# Set up Flask app and API
app = Flask(__name__)
api = Api(app)

# Set up SQLAlchemy
engine = create_engine('postgresql://user:password@host:port/dbname')
Base = declarative_base()
Session = sessionmaker(bind=engine)
session = Session()

# Define models for files and storage nodes
class File(Base):
    __tablename__ = 'files'
    id = Column(Integer, primary_key=True)
    name = Column(String)
    content = Column(Binary)
    created_at = Column(DateTime)

class StorageNode(Base):
    __tablename__ = 'storage_nodes'
    id = Column(Integer, primary_key=True)
    ip_address = Column(String)
    port = Column(Integer)
    status = Column(String)

# Define RESTful API resources
class FileResource(Resource):
    def get(self, file_id):
        # Retrieve file by ID
        file = session.query(File).filter_by(id=file_id).first()
        if not file:
            return jsonify({'error': f'File {file_id} not found'}), 404
        return jsonify({'file': file.to_dict()})

    def put(self, file_id):
        # Update file by ID
        file = session.query(File).filter_by(id=file_id).first()
        if not file:
            return jsonify({'error': f'File {file_id} not found'}), 404
        data = request.get_json()
        file.name = data['name']
        file.content = data['content']
        session.add(file)
        session.commit()
        return jsonify({'success': f'File {file_id} updated successfully'})

    def delete(self, file_id):
        # Delete file by ID
        file = session.query(File).filter_by(id=file_id).first()
        if not file:
            return jsonify({'error': f'File {file_id} not found'}), 404
        session.delete(file)
        session.commit()
        return jsonify({'success': f'File {file_id} deleted successfully'})

class StorageNodeResource(Resource):
    def get(self, node_id):
        # Retrieve storage node by ID
        node = session.query(StorageNode).filter_by(id=node_id).first()
        if not node:
            return jsonify({'error': f'Storage node {node_id} not found'}), 404
        return jsonify({'storage_node': node.to_dict()})

    def put(self, node_id):
        # Update storage node by ID
        node = session.query(StorageNode).filter_by(id=node_id).first()
        if not node:
            return jsonify({'error': f'Storage node {node_id} not found'}), 404
        data = request.get_json()
        node.ip_address = data['ip_address']
        node.port = data['port']
        session.add(node)
        session.commit()
        return jsonify({'success': f'Storage node {node_id} updated successfully'})

    def delete(self, node_id):
        # Delete storage node by ID
        node = session.query(StorageNode).filter_by(id=node_id).first()
        if not node:
            return jsonify({'error': f'Storage node {node_id} not found'}), 404
        session.delete(node)
        session.commit()
        return jsonify({'success': f'Storage node {node_id} deleted successfully'})

# Define file upload and download endpoints
@app.route('/upload', methods=['POST'])
def upload():
    # Upload file to storage
    data = request.files.get('file')
    if not data:
        return jsonify({'error': 'File not found in request'}), 400
    file = File(name=data.filename, content=data.read())
    session.add(file)
    session.commit()
    return jsonify({'success': f'File {file.id} uploaded successfully'})

@app.route('/download/<int:file_id>', methods=['GET'])
def download(file_id):
    # Download file from storage
    file = session.query(File).filter_by(id=file_id).first()
    if not file:
        return jsonify({'error': f'File {file_id} not found'}), 404
    return send_file(file.content, attachment_filename=file.name)

# Define authentication endpoint
@app.route('/authenticate', methods=['POST'])
def authenticate():
    # Authenticate user and retrieve token
    data = request.get_json()
    if not data:
        return jsonify({'error': 'User not found in request'}), 400
    user = session.query(User).filter_by(username=data['username']).first()
    if not user:
        return jsonify({'error': f'User {data["username"]} not found'}), 404
    token = user.generate_token()
    return jsonify({'token': token})

# Define error handling and logging middleware
@app.errorhandler(Exception)
def handle_error(e):
    # Log error and return HTTP status code 500
    logging.exception('Error occurred')
    return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    app.run(debug=True)
