```
#include <iostream>
#include <vector>
#include <memory>
#include <cstdlib>

class Octree {
public:
    // Constructor
    Octree(float featureSize, int initialLeafNodes, int maxDataCapacity) :
        m_featureSize(featureSize), m_initialLeafNodes(initialLeafNodes), m_maxDataCapacity(maxDataCapacity) {
        // Initialize the octree nodes and data capacity
        m_root = std::make_unique<Node>(m_featureSize, m_initialLeafNodes, m_maxDataCapacity);
    }

    // Destructor
    ~Octree() {
        // Deallocate the memory for the octree nodes and data capacity
        m_root.reset();
    }

    // Function to insert an object into the octree
    void insert(const Object& obj) {
        // Check if the object is within the bounds of the octree
        if (obj.getPosition().x() < -m_featureSize / 2 || obj.getPosition().x() > m_featureSize / 2 ||
            obj.getPosition().y() < -m_featureSize / 2 || obj.getPosition().y() > m_featureSize / 2 ||
            obj.getPosition().z() < -m_featureSize / 2 || obj.getPosition().z() > m_featureSize / 2) {
            std::cerr << "Error: Object is outside the bounds of the octree." << std::endl;
            return;
        }

        // Check if the object is already in the octree
        for (const auto& node : m_root->getChildren()) {
            if (node->isObjectInside(obj)) {
                node->insert(obj);
                return;
            }
        }

        // Insert the object into the root node
        m_root->insert(obj);
    }

    // Function to query the octree for objects within a given region
    std::vector<const Object*> query(const BoundingBox& box) const {
        // Check if the query box is within the bounds of the octree
        if (box.minCorner().x() < -m_featureSize / 2 || box.maxCorner().x() > m_featureSize / 2 ||
            box.minCorner().y() < -m_featureSize / 2 || box.maxCorner().y() > m_featureSize / 2 ||
            box.minCorner().z() < -m_featureSize / 2 || box.maxCorner().z() > m_featureSize / 2) {
            std::cerr << "Error: Query box is outside the bounds of the octree." << std::endl;
            return {};
        }

        // Recursively query the nodes that are within the bounds of the query box
        std::vector<const Object*> result;
        for (const auto& node : m_root->getChildren()) {
            if (node->isNodeInside(box)) {
                const auto& objects = node->queryObjects(box);
                result.insert(result.end(), objects.begin(), objects.end());
            }
        }

        // Return the list of objects within the query box
        return result;
    }

private:
    class Node {
    public:
        // Constructor
        Node(float featureSize, int initialLeafNodes, int maxDataCapacity) :
            m_featureSize(featureSize), m_initialLeafNodes(initialLeafNodes), m_maxDataCapacity(maxDataCapacity) {
            // Initialize the node's bounds and data capacity
            m_bounds = BoundingBox(-m_featureSize / 2, m_featureSize / 2);
            m_data.reserve(m_initialLeafNodes * (m_initialLeafNodes + 1) / 2);
        }

        // Destructor
        ~Node() {
            for (const auto& child : m_children) {
                delete child;
            }
        }

        // Function to insert an object into the node
        void insert(const Object& obj) {
            if (!m_bounds.containsPoint(obj.getPosition())) {
                std::cerr << "Error: Object is outside the bounds of the node." << std::endl;
                return;
            }

            // Check if the node has reached its maximum data capacity
            if (m_data.size() == m_maxDataCapacity) {
                // If so, split the node into child nodes
                split();
            }

            // Add the object to the node's data
            m_data.push_back(obj);
        }

        // Function to query objects within a given region
        std::vector<const Object*> queryObjects(const BoundingBox& box) const {
            // Check if the query box is within the bounds of the node
            if (!m_bounds.intersectsWith(box)) {
                return {};
            }

            // Recursively query the child nodes that are within the bounds of the query box
            std::vector<const Object*> result;
            for (const auto& child : m_children) {
                if (child->isNodeInside(box)) {
                    const auto& objects = child->queryObjects(box);
                    result.insert(result.end(), objects.begin(), objects.end());
                }
            }

            // Return the list of objects within the query box
            return result;
        }

        // Function to split the node into child nodes
        void split() {
            // Split the node into eight child nodes with a size that is half the size of the parent node
            m_children = std::vector<std::unique_ptr<Node>>();
            for (int i = 0; i < 8; ++i) {
                const auto& bounds = m_bounds.split(i);
                m_children.push_back(std::make_unique<Node>(m_featureSize / 2, m_initialLeafNodes, m_maxDataCapacity));
                m_children[i]->setBounds(bounds);
            }

            // Move the objects in the node to the child nodes
            for (const auto& obj : m_data) {
                addObjectToChildNode(obj);
            }
        }

        // Function to move an object to a child node
        void addObjectToChildNode(const Object& obj) {
            for (auto& child : m_children) {
                if (child->isObjectInside(obj)) {
                    child->insert(obj);
                    return;
                }
            }
        }

        // Function to check if a node is inside the query box
        bool isNodeInside(const BoundingBox& box) const {
            return m_bounds.intersectsWith(box);
        }

        // Function to check if an object is inside the node
        bool isObjectInside(const Object& obj) const {
            return m_bounds.containsPoint(obj.getPosition());
        }

        // Setter for the node's bounds
        void setBounds(const BoundingBox& bounds) {
            m_bounds = bounds;
        }

    private:
        // The size of each node in the octree
        float m_featureSize;

        // The initial number of leaf nodes to allocate for a new node
        int m_initialLeafNodes;

        // The maximum data capacity for each node
        int m_maxDataCapacity;

        // The bounds of the node
        BoundingBox m_bounds;

        // The list of objects in the node
        std::vector<Object> m_data;

        // The child nodes of the node
        std::vector<std::unique_ptr<Node>> m_children;
    };
    """

The above code is a C++ implementation of an octree. The `Octree` class has functions to insert objects into the tree, query objects within a given region, and split nodes when they reach their maximum data capacity. The `BoundingBox` class represents the bounds of each node in the tree and provides functions to check for intersections with other boxes and to split a box into eight sub-boxes.

