Here is the Java function that generates a JSON Web Token (JWT) signed with a private key retrieved from a secure Key Management Service (KMS) upon receiving an HTTP request containing authentication credentials:
```java
import java.security.Key;
import java.util.Base64;
import java.util.Map;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.RSAKeyProvider;

public class JWTSigner {
    private static final String PRIVATE_KEY = "YOUR_PRIVATE_KEY"; // Replace with your actual private key
    private static final Map<String, Object> CLAIMS = new HashMap<>();

    public static String generateJWT(Map<String, Object> claims) {
        try {
            // Retrieve private key from Key Management Service (KMS)
            Key kmsKey = KMS.getPrivateKey();

            // Create RSA key provider for signing JWT
            SecretKeySpec secretKey = new SecretKeySpec(kmsKey.getEncoded(), "RSA");
            RSAKeyProvider rsaKeyProvider = new RSAKeyProvider(secretKey);

            // Generate JWT with claims and signed using private key from KMS
            Algorithm algorithm = Algorithm.RSA256(null, rsaKeyProvider);
            String jwt = JWT.create()
                    .withClaims(claims)
                    .sign(algorithm);

            return jwt;
        } catch (Exception e) {
            System.out.println("Error generating JWT: " + e.getMessage());
            return null;
        }
    }
}
