import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class FileReader {
    private static final String REGEX = "(?i)(error|warning)";
    private static final Pattern PATTERN = Pattern.compile(REGEX);

    public List<String> readFiles(List<File> files, boolean includeKeywords, boolean includeSummary) {
        return files.stream()
                .flatMap(file -> readFile(file, includeKeywords).stream())
                .collect(Collectors.toList());
    }

    public List<String> readFile(File file, boolean includeKeywords) {
        try {
            List<String> lines = Files.readAllLines(file.toPath(), StandardCharsets.UTF_8);
            if (includeKeywords) {
                return lines.stream()
                        .filter(line -> PATTERN.matcher(line).find())
                        .collect(Collectors.toList());
            } else {
                return lines;
            }
        } catch (IOException e) {
            e.printStackTrace();
            return new ArrayList<>();
        }
    }
}
