import com.fasterxml.jackson.databind.ObjectMapper;

public class SerializationUtils {
    private static final int MAX_CACHE_SIZE = 1024; // maximum number of cached classes and their constructors
    private static final LRUCache<String, Class<?>> CLASS_CACHE = new LRUCache<>(MAX_CACHE_SIZE); // cache for frequently used classes and their constructors

    public static <T> T deserialize(byte[] bytes, Class<T> clazz) throws IOException {
        String className = clazz.getName();
        if (CLASS_CACHE.containsKey(className)) {
            return (T) CLASS_CACHE.get(className).newInstance(); // instantiate class from cache
        } else {
            try {
                Class<?> cls = Class.forName(className); // get class definition from external data source
                CLASS_CACHE.put(className, cls); // add class to cache
                return (T) cls.newInstance(); // instantiate class
            } catch (ClassNotFoundException e) {
                System.err.println("Class not found: " + className);
                throw new IOException(e);
