                    tasks.Add(StopSite(siteName));
                    break;
                case WebsiteOperation.Restart:
                    tasks.Add(RestartSite(siteName));
                    break;
            }
        }

        // Wait for all tasks to complete
        await Task.WhenAll(tasks);

        // Check if any task failed and report the errors
        foreach (var task in tasks)
        {
            if (task.IsFaulted)
