const { WorkerPool } = require('workerpool');
const fetch = require('node-fetch');

async function reduceArray(array, initialValue, callback) {
  if (!Array.isArray(array)) {
    throw new Error(`Invalid input: ${array} is not an array`);
  }

  // Split the array into smaller chunks for concurrent processing
  const chunkSize = 100;
  const numChunks = Math.ceil(array.length / chunkSize);
  const chunks = [];
  for (let i = 0; i < numChunks; i++) {
    chunks.push(array.slice(i * chunkSize, (i + 1) * chunkSize));
  }

  // Create a worker pool to handle concurrent processing of chunks
  const workerPool = new WorkerPool({
    numWorkers: 4,
  });

  // Initialize variables for progress tracking and resource management
  let totalProgress = 0;
  let currentChunk = null;
  let currentValue = initialValue;

  // Iterate over chunks and perform reduction operation concurrently using workers
  await Promise.all(chunks.map((chunk, i) => {
    return new Promise((resolve, reject) => {
      workerPool.exec({
        chunk,
        currentValue,
        callback,
      }, (err, result) => {
        if (err) {
          reject(err);
        } else {
          totalProgress += 100 / numChunks;
          currentChunk = i;
          currentValue = result;
          resolve();
        }
      });
    });
  }));

  // Close the worker pool and return the final reduced value
  await workerPool.destroy();
  console.log(`Reduction complete: ${totalProgress}%`);
  console.log(`Current chunk: ${currentChunk}`);
  return currentValue;
}

