using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

namespace WebServerManagement
{
    public class AddAndStartWebsite
    {
        // Define constants for the chunk size and retries
        private const int CHUNK_SIZE = 1024 * 1024;
        private const int RETRIES = 3;

        // Define a logger to log actions and errors
        private static readonly ILogger Logger = LogManager.GetLogger(typeof(AddAndStartWebsite));

        public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName, List<CustomConfigurationSetting> customSettings)
        {
            // Verify that the web.config file exists in the specified directory
            if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            {
                Logger.Error("Missing web.config file in directory: {0}", directoryPath);
                return "error: missing web.config file";
            }

            // Create a new website using the external API
            try
            {
                await ExternalApi.CreateWebsiteAsync(directoryPath, siteName, customSettings);
            }
            catch (Exception ex)
            {
                Logger.Error("Failed to create website: {0}", ex);
                return "error: failed to create website";
            }

            // Calculate the MD5 hash of the web.config file
            string md5Hash = await CalculateFileMd5Async(Path.Combine(directoryPath, "web.config"), RETRIES);
            if (md5Hash == null)
            {
                Logger.Error("Failed to calculate MD5 hash for web.config file in directory: {0}", directoryPath);
                return "error: failed to calculate MD5 hash";
            }

            // Start the website using the external API
            try
            {
                await ExternalApi.StartWebsiteAsync(directoryPath, siteName);
            }
            catch (Exception ex)
            {
                Logger.Error("Failed to start website: {0}", ex);
                return "error: failed to start website";
            }

            // Return the hexdigest of the MD5 hash for confirmation
            return md5Hash;
        }

        private async Task<string> CalculateFileMd5Async(string filePath, int retries)
        {
            try
            {
                using (var fileStream = new FileStream(filePath, FileMode.Open))
                {
                    // Read the file in chunks to optimize memory usage for large files
                    var buffer = new byte[CHUNK_SIZE];
                    int bytesRead;
                    while ((bytesRead = await fileStream.ReadAsync(buffer, 0, CHUNK_SIZE)) > 0)
                    {
                        // Calculate the MD5 hash for each chunk
                        var md5 = new System.Security.Cryptography.MD5CryptoServiceProvider();
                        var hashBytes = md5.ComputeHash(buffer, 0, bytesRead);
                        var hexdigest = BitConverter.ToString(hashBytes).Replace("-", "");

                        // Resume download in case of an interruption
                        if (retries > 0 && !fileStream.CanSeek)
                        {
                            fileStream.Position = fileStream.Length - bytesRead;
                        }
                    }

                    return hexdigest;
                }
            }
            catch (Exception ex) when (retries > 0)
            {
                // Retry with a new chunk size or retries if necessary
                int newChunkSize = CHUNK_SIZE * 2;
                if (newChunkSize > 1024 * 1024 * 5)
                {
                    return null;
                }
                return await CalculateFileMd5Async(filePath, retries - 1, newChunkSize);
            }
        }
    }
}
