import java.net.*;
import java.io.*;
import javax.net.ssl.*;

public class SecureSocket {
    private final int BUFFER_SIZE = 1024;
    private Socket socket;
    private InputStream inputStream;
    private OutputStream outputStream;

    public void establishConnection(String hostname, int port) throws IOException {
        SSLSocketFactory factory = (SSLSocketFactory) SSLSocketFactory.getDefault();
        socket = factory.createSocket(hostname, port);
        inputStream = new BufferedInputStream(socket.getInputStream(), BUFFER_SIZE);
        outputStream = new BufferedOutputStream(socket.getOutputStream(), BUFFER_SIZE);
    }

    public void handleStateChange() throws IOException {
        while (true) {
            int state = socket.getState();
            switch (state) {
                case Socket.CONNECTED:
                    System.out.println("Socket is connected");
                    break;
                case Socket.LISTENING:
                    System.out.println("Socket is listening");
                    break;
                case Socket.CLOSED:
                    System.out.println("Socket is closed");
                    return;
            }
        }
    }

    public void handleError() throws IOException {
        if (socket.isClosed()) {
            throw new IOException("Socket is closed");
        } else if (socket.isBound()) {
            throw new IOException("Socket is bound");
        } else if (socket.isConnected()) {
            throw new IOException("Socket is connected");
        } else if (socket.isInputShutdown()) {
            throw new IOException("Input stream is shutdown");
        } else if (socket.isOutputShutdown()) {
            throw new IOException("Output stream is shutdown");
        }
    }

    public void handleResourceManagement() throws IOException {
        inputStream.close();
        outputStream.close();
        socket.close();
    }
}
