Here is a sample C++ utility that processes an array of integers using a Union-Find data structure for efficient set management and validation:
```c++
#include <iostream>
#include <string>
#include <unordered_map>
#include <variant>
#include <vector>

// Define the configuration settings as a std::unordered_map<std::string, std::variant<int, double, std::string, bool>>
typedef struct {
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> config;
} ConfigSettings;

// Define the Union-Find data structure for efficient set management and validation
struct UnionFind {
    int parent[100]; // Parent element of each element in the set
    int rank[100];  // Rank of each element in the set (0 = root, >0 = non-root)

    void init(int size) {
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    int find(int x) {
        if (x != parent[x]) {
            return find(parent[x]);
        }
        return x;
    }

    void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        // Unite the two sets by attaching the smaller set to the larger one
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootX] = rootY;
        }
    }
};

int main() {
    // Read configuration settings from a secure JSON file
    ConfigSettings config;
    std::string json_file = "config.json";

    if (config.load(json_file)) {
        std::cout << "Config loaded successfully." << std::endl;
    } else {
        std::cerr << "Error loading config file: " << json_file << std::endl;
        return 1;
    }

    // Initialize the Union-Find data structure with the array size from the configuration settings
    UnionFind uf(config.array_size);

    // Fetch element metadata from an external API based on the configuration settings
    for (int i = 0; i < config.array_size; i++) {
        int element = config.array[i];
        std::string api_url = "https://api.example.com/elements/" + std::to_string(element);

        // Make a request to the API and handle potential errors gracefully with meaningful error messages
        std::string response;
        if (makeRequest(api_url, config.security_credentials, response)) {
            // If the response contains metadata, extract it and add it to the Union-Find data structure
            auto metadata = parseMetadata(response);
            uf.union(metadata["set_id"], i);
        } else {
            std::cerr << "Error fetching element metadata for element " << element << std::endl;
        }
    }

    // Identify all disjoint pairs of elements in the Union-Find data structure
    for (int i = 0; i < config.array_size; i++) {
        if (!uf.find(i)) {
            continue;
        }

        int parent = uf.parent[i];
        std::cout << "Disjoint pair found: (" << config.array[i] << ", " << config.array[parent] << ")" << std::endl;
    }

    return 0;
}
```
