            // Update the temperature in the weather conditions list
            _weatherConditions.Add(new WeatherCondition { Temperature = temperature });

            // Send an HTTP POST request to update the temperature in the external API or database
            var response = await _httpClient.PostAsync("https://example.com/update-temperature", new StringContent($"{{ \"temperature\": {temperature} }}"));
        }

        public async Task SimulateHumidity(int min, int max)
        {
            // Generate a random humidity percentage between the given range
            var humidity = Random.Next(min, max);

            // Update the humidity in the weather conditions list
            _weatherConditions.Add(new WeatherCondition { Humidity = humidity });

            // Send an HTTP POST request to update the humidity in the external API or database
            var response = await _httpClient.PostAsync("https://example.com/update-humidity", new StringContent($"{{ \"humidity\": {humidity} }}"));
