            // Update the wind speed in the weather conditions list
            _weatherConditions.Add(new WeatherCondition { WindSpeed = windSpeed });

            // Send an HTTP POST request to update the wind speed in the external API or database
            var response = await _httpClient.PostAsync("https://example.com/update-wind-speed", new StringContent($"{{ \"windSpeed\": {windSpeed} }}"));
