            // Update the precipitation in the weather conditions list
            _weatherConditions.Add(new WeatherCondition { Precipitation = precipitation });

            // Send an HTTP POST request to update the precipitation in the external API or database
            var response = await _httpClient.PostAsync("https://example.com/update-precipitation", new StringContent($"{{ \"precipitation\": {precipitation} }}"));
