// Read environment variables from .env file
void read_env(const char *filename, struct Environment *env) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open %s\n", filename);
        exit(1);
    }

    // Read line by line and parse the environment variables
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Split the line into key-value pairs using = as a delimiter
        char *key, *value;
        if ((key = strtok(line, "=")) != NULL && (value = strtok(NULL, "\n")) != NULL) {
            // Check if the key is a supported environment variable
            if (!strcmp(key, "DB_HOST") || !strcmp(key, "DB_PORT") ||
                !strcmp(key, "DB_USER") || !strcmp(key, "DB_PASSWORD") ||
                !strcmp(key, "CACHE_TYPE")) {
                    // Set the environment variable in the struct
                    if (!strcmp(key, "DB_HOST")) {
                        env->db_host = value;
                    } else if (!strcmp(key, "DB_PORT")) {
                        env->db_port = atoi(value);
                    } else if (!strcmp(key, "DB_USER")) {
                        env->db_user = value;
                    } else if (!strcmp(key, "DB_PASSWORD")) {
                        env->db_password = value;
                    } else if (!strcmp(key, "CACHE_TYPE")) {
                        env->cache_type = value;
                    }
            } else {
                printf("Error: invalid environment variable %s\n", key);
                exit(1);
            }
        }
    }

    fclose(file);
}

// Initialize a database connection and cache based on the environment variables
void init_database(struct Environment *env) {
    // Check if DB_HOST, DB_PORT, and DB_USER are set
    if (env->db_host == NULL || env->db_port == 0 || env->db_user == NULL) {
        printf("Error: missing database connection information\n");
        exit(1);
    }

    // Connect to the database and create a cache based on the environment variables
    struct Database *database = connect_to_database(env->db_host, env->db_port, env->db_user);
    if (database == NULL) {
        printf("Error: unable to connect to the database\n");
        exit(1);
    }

    struct Cache *cache = create_cache(env->cache_type);
    if (cache == NULL) {
        printf("Error: unable to create a cache\n");
        exit(1);
    }
}

// Parse a TIFF image file and extract information about the image's bits per sample and sample per pixel
ImageInfo parse_tiff_image(const char *filename) {
    // Check if the filename is valid
    if (filename == NULL || access(filename, F_OK)) {
        printf("Error: invalid filename\n");
        exit(1);
    }

    // Open the file and read the header information
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: unable to open %s\n", filename);
        exit(1);
    }

    ImageInfo image_info;
    // Read the header and extract the bits per sample and sample per pixel information
    fseek(file, 0, SEEK_SET);
    char magic_number[4];
    fread(magic_number, 1, 4, file);
    if (strncmp(magic_number, "MM\x00\x2a", 4) == 0 || strncmp(magic_number, "II\x2a\x00", 4) == 0) {
        image_info.bits_per_sample = 16;
    } else if (strncmp(magic_number, "MM\x01\x00", 4) == 0 || strncmp(magic_number, "II\x00\x2a", 4) == 0) {
        image_info.bits_per_sample = 32;
    } else if (strncmp(magic_number, "MM\x02\x00", 4) == 0 || strncmp(magic_number, "II\x2a\x01", 4) == 0) {
        image_info.bits_per_sample = 64;
    } else if (strncmp(magic_number, "MM\x03\x00", 4) == 0 || strncmp(magic_number, "II\x01\x2a", 4) == 0) {
        image_info.bits_per_sample = 8;
    } else if (strncmp(magic_number, "MM\x04\x00", 4) == 0 || strncmp(magic_number, "II\x2a\x02", 4) == 0) {
        image_info.bits_per_sample = 16;
    } else if (strncmp(magic_number, "MM\x05\x00", 4) == 0 || strncmp(magic_number, "II\x02\x2a", 4) == 0) {
        image_info.bits_per_sample = 32;
    } else if (strncmp(magic_number, "MM\x06\x00", 4) == 0 || strncmp(magic_number, "II\x2a\x03", 4) == 0) {
        image_info.bits_per_sample = 64;
    } else if (strncmp(magic_number, "MM\x07\x00", 4) == 0 || strncmp(magic_number, "II\x03\x2a", 4) == 0) {
        image_info.bits_per_sample = 8;
    } else if (strncmp(magic_number, "MM\x08\x00", 4) == 0 || strncmp(magic_number, "II\x2a\x04", 4) == 0) {
        image_info.bits_per_sample = 16;
    } else if (strncmp(magic_number, "MM\x09\x00", 4) == 0 || strncmp(magic_number, "II\x04\x2a", 4) == 0) {
        image_info.bits_per_sample = 32;
    } else if (strncmp(magic_number, "MM\x0A\x00", 4) == 0 || strncmp(magic_number, "II\x2a\x05", 4) == 0) {
