    }

    // Clean up and exit the function
    fclose(pdf);
}

void *processRequestThread(void *arg) {
    char *request = (char *)arg;
    processRequest(request);
}

int main() {
    // Initialize thread pool for concurrent processing of multiple requests
    pthread_t threads[10];
    int i, rc;

    for(i=0; i<10; i++) {
        rc = pthread_create(&threads[i], NULL, processRequestThread, (void *)requests[i]);
        if(rc) {
            logMessage("Failed to create thread.", "Error: pthread_create() failed.");
            return 1;
        }
    }

    for(i=0; i<10; i++) {
