public class XmlAndBinaryParser
{
    private readonly string _xmlUrl;
    private readonly string _binaryFilePath;
    private readonly XPathExpression _xpathExpression;
    private readonly CacheSettings _cacheSettings;

    public XmlAndBinaryParser(string xmlUrl, string binaryFilePath, XPathExpression xpathExpression, CacheSettings cacheSettings)
    {
        _xmlUrl = xmlUrl;
        _binaryFilePath = binaryFilePath;
        _xpathExpression = xpathExpression;
        _cacheSettings = cacheSettings;
    }

    public async Task<XElement> GetFirstMatchingElement(CancellationToken cancellationToken)
    {
        // Fetch XML content from the remote server and cache it locally
        var xmlContent = await FetchXmlContentAsync(_xmlUrl, cancellationToken);
        var xDoc = XDocument.Parse(xmlContent);

        // Parse the XML document using the specified XPath expression
        var matchingElements = xDoc.XPathSelectElements(_xpathExpression.ToString());

        // Load binary data from the file and integrate with the database for fallbacks
        byte[] binaryData;
        try
        {
            binaryData = File.ReadAllBytes(_binaryFilePath);
        }
        catch (Exception ex) when (ex is IOException || ex is InvalidOperationException)
        {
            // Handle exceptions related to loading the binary file
            Console.WriteLine($"Failed to load binary data from '{_binaryFilePath}': {ex.Message}");
            return null;
        }

        // Deserialize the binary data using an existing database for fallbacks
        var deserializedData = DeserializeBinaryData(binaryData);

        // Combine the matching elements and the deserialized data to create a combined list
        var combinedList = new List<object>();
        foreach (var element in matchingElements)
        {
            combinedList.Add(element);
        }

        if (deserializedData != null)
        {
            foreach (var item in deserializedData)
            {
                combinedList.Add(item);
            }
        }

        // Return the first element from the combined list
        return (XElement)combinedList.FirstOrDefault();
    }

    private async Task<string> FetchXmlContentAsync(string xmlUrl, CancellationToken cancellationToken)
    {
        using var httpClient = new HttpClient();
        var request = new HttpRequestMessage(HttpMethod.Get, xmlUrl);
        request.Headers.CacheControl = new CacheControlHeaderValue()
        {
            MaxAge = _cacheSettings.MaxAge,
            MustRevalidate = true
        };
        request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/xml"));

        var response = await httpClient.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync();
    }

