```rust
use reqwest::blocking::RequestBuilder;
use reqwest::{Client, header};
use std::time::Duration;
use std::collections::HashMap;

struct HttpClientConfig {
    disable_certificate_validation: bool,
    retries: usize,
    retry_interval: Duration,
    timeout: Duration,
    custom_headers: HashMap<String, String>,
}

fn create_http_client(config: HttpClientConfig) -> Result<RequestBuilder, HttpClientError> {
    // Create a new client with the specified configuration.
    let mut client = Client::builder()
        .timeout(config.timeout)
        .connect_timeout(config.retry_interval)
        .disable_certificate_validation(config.disable_certificate_validation)
        .build()?;

    // Create a new request builder with the specified URL and custom headers.
    let mut request = client.get("https://example.com");
    for (key, value) in config.custom_headers {
        request = request.header(key, value);
    }

    // Set up automatic token refresh for token-based authorization.
    if config.auth_type == "token" {
        let refresh_token = get_refresh_token();
        client = client.with_token_refresh(move || {
            Some((
                "Bearer",
                format!("{} {}", refresh_token, ""),
            ))
        });
    }

    // Set up retries for failed requests.
    let mut retry_count = 0;
    loop {
        match client.execute(request).await {
            Ok(response) => {
                return Ok(response);
            }
            Err(error) => {
                if error.is_server_error() || error.is_timeout() {
                    retry_count += 1;
                    if retry_count > config.retries {
                        return Err(HttpClientError::MaxRetriesExceeded);
                    }
                } else {
                    return Err(error);
                }
            }
        }
    }
}
```
This implementation uses the `reqwest` crate to create a new client with the specified configuration. It then creates a new request builder with the specified URL and custom headers, and sets up automatic token refresh for token-based authorization if necessary. The function also sets up retries for failed requests, using the `retry_count` variable to keep track of the number of attempts made so far.

The function returns a `Result` value, with an error value of type `HttpClientError` if any errors occur during the execution of the request or the automatic token refresh. The error values that can be returned by this function are:

* `HttpClientError::MaxRetriesExceeded`: If the maximum number of retries is exceeded before a successful response is received.
* `reqwest::Error`: Any other errors that occur during the execution of the request or the automatic token refresh.

Note that this implementation assumes that the `get_refresh_token()` function is available for obtaining a new access token if the previous one has expired. You will need to implement this function yourself, depending on how your authentication service handles token refresh.

