// Define the test function
function runTests(moduleName, testCases, setUpFunction) {
  // Load the module using require
  const module = require(moduleName);

  // Reset the mocking library after each test
  blueslip.reset();

  // Set up any necessary resources before running tests
  if (setUpFunction) {
    setUpFunction();
  }

  // Run all test cases
  for (const testCase of testCases) {
    try {
      // Run the test case
      testCase(module);

      // Log successful test
      console.log(`Successfully ran test case ${testCase.name} on module ${moduleName}`);
    } catch (error) {
      // Log failed test with error details
      console.error(`Failed to run test case ${testCase.name} on module ${moduleName}:`, error);
    }
  }

  // Clean up resources
  if (setUpFunction) {
    setUpFunction();
  }
}
