#include <iostream>
#include <vector>
#include <memory>
#include <openssl/aes.h>
#include <openssl/chacha20.h>
#include <openssl/sha.h>
#include <openssl/err.h>

void initializeSecureMessagingLibrary(const std::string& config) {
  // Load the OpenSSL library
  SSL_library_init();

  // Parse the configuration string to determine which algorithms to enable
  std::vector<std::string> algorithms = parseConfigString(config);

  // Create a vector of unique pointers to hold the buffered data chunks
  std::vector<std::unique_ptr<uint8_t[]>> buffers;

  // Initialize the cryptographic resources
  for (const auto& algorithm : algorithms) {
    if (algorithm == "AES-256") {
      AES_KEY aesKey;
      AES_set_encrypt_key(aesKey, 256);
      buffers.push_back(std::make_unique<uint8_t[]>(AES_BLOCK_SIZE));
    } else if (algorithm == "ChaCha20") {
      ChaCha20_KEY chachaKey;
      ChaCha20_set_encrypt_key(chachaKey, 256);
      buffers.push_back(std::make_unique<uint8_t[]>(CHACHA20_BLOCK_SIZE));
    } else if (algorithm == "SHA-256") {
      SHA256_CTX shaCtx;
      SHA256_Init(&shaCtx);
      buffers.push_back(std::make_unique<uint8_t[]>(SHA256_DIGEST_LENGTH));
    } else if (algorithm == "SHA-384") {
      SHA384_CTX shaCtx;
      SHA384_Init(&shaCtx);
      buffers.push_back(std::make_unique<uint8_t[]>(SHA384_DIGEST_LENGTH));
    } else if (algorithm == "SHA-512") {
      SHA512_CTX shaCtx;
      SHA512_Init(&shaCtx);
      buffers.push_back(std::make_unique<uint8_t[]>(SHA512_DIGEST_LENGTH));
    } else {
      throw std::runtime_error("Unknown algorithm: " + algorithm);
    }
  }

  // Initialize the hashes for each buffer
  for (const auto& buffer : buffers) {
    SHA256_Init(buffer.get());
  }
}

void copyBufferedData(size_t numBytes, const std::vector<std::unique_ptr<uint8_t[]>>& buffers, uint8_t* newBuffer) {
  // Copy the specified number of bytes from each buffer to the new buffer
  for (const auto& buffer : buffers) {
    memcpy(newBuffer, buffer.get(), numBytes);
    newBuffer += numBytes;
  }
}

void cleanupSecureMessagingLibrary() {
  // Clean up any resources that were allocated in the library
  for (const auto& buffer : buffers) {
    if (buffer) {
      SSL_free(buffer.get());
    }
  }
}
```
