import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        // Check if file exists and delete it if necessary
        File file = new File("output.log");
        if (file.exists()) {
            file.delete();
        }

        // Execute command using Runtime.getRuntime().exec(String, String, File)
        Process process = Runtime.getRuntime().exec("command", null, new File("./"));

        // Read and log output stream of executed command
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            logMessage(line);
        }

        // Read and log error stream of executed command
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        String error;
        while ((error = errorReader.readLine()) != null) {
            logMessage(error);
        }
    }

    // Logging function that uses snprintf for formatting the message
    public static void logMessage(String message) {
        int size = 1024;
        char[] buffer = new char[size];
        String formattedMessage = null;

        try {
            snprintf(buffer, size, "LOG: %s\n", message);
            formattedMessage = String.valueOf(buffer);
        } catch (Exception e) {
            // Handle exception
        }

        if (formattedMessage != null) {
            System.out.println(formattedMessage);
        }
    }
}
