using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class WebsiteLifecycleManager {
    private static readonly string ConfigFilePath = "/path/to/config/file";
    private static readonly List<string> SiteNames = new List<string>() { "site1", "site2" };
    private static readonly Dictionary<string, int> SiteOperationPriorities = new Dictionary<string, int>() {
        { "start", 0 },
        { "stop", 1 },
        { "remove", 2 },
        { "add", 3 }
    };

    public static async Task ManageWebsiteLifecycle(string configFilePath, List<string> siteNames, List<string> operations) {
        // Validate inputs
        if (!Directory.Exists(configFilePath)) {
            throw new DirectoryNotFoundException($"The configuration file path '{configFilePath}' does not exist.");
        }
        foreach (var siteName in siteNames) {
            if (!SiteNames.Contains(siteName)) {
                throw new ArgumentException($"The site name '{siteName}' is invalid or not supported.");
            }
        }
        foreach (var operation in operations) {
            if (!SiteOperationPriorities.Keys.Contains(operation)) {
                throw new ArgumentException($"The operation '{operation}' is invalid or not supported.");
            }
        }

        // Load configuration file and validate sites
        var config = File.ReadAllText(configFilePath);
        foreach (var siteName in siteNames) {
            if (!config.Contains(siteName)) {
                throw new ArgumentException($"The site '{siteName}' is not found in the configuration file.");
            }
        }

        // Perform operations concurrently using task parallel library
        var tasks = new List<Task>();
        foreach (var operation in operations) {
            switch (operation) {
                case "start":
                    tasks.Add(StartWebsiteAsync(config, siteNames));
                    break;
                case "stop":
                    tasks.Add(StopWebsiteAsync(config, siteNames));
                    break;
                case "remove":
                    tasks.Add(RemoveWebsiteAsync(config, siteNames));
                    break;
                case "add":
                    tasks.Add(AddWebsiteAsync(config, siteNames));
                    break;
            }
        }
        await Task.WhenAll(tasks);

        // Log actions and errors
        var logFilePath = Path.Combine(Directory.GetCurrentDirectory(), "website_lifecycle_manager.log");
        using (var streamWriter = new StreamWriter(logFilePath, true)) {
            foreach (var task in tasks) {
                if (task.Status == TaskStatus.RanToCompletion) {
                    streamWriter.WriteLine($"{DateTime.Now}: Successfully performed operation '{task.Result}' on site '{siteNames[0]}'");
                } else {
                    streamWriter.WriteLine($"{DateTime.Now}: Failed to perform operation '{operation}' on site '{siteNames[0]}' with error: {task.Exception.Message}");
                }
            }
        }
    }

    private static async Task StartWebsiteAsync(string config, List<string> siteNames) {
        // Check if web.config file exists for each site
        foreach (var siteName in siteNames) {
            var webConfigFilePath = Path.Combine(config, $"{siteName}.web.config");
            if (!File.Exists(webConfigFilePath)) {
                throw new FileNotFoundException($"The web configuration file '{webConfigFilePath}' for site '{siteName}' does not exist.");
            }
        }

        // Start sites concurrently using task parallel library
        var tasks = new List<Task>();
        foreach (var siteName in siteNames) {
            tasks.Add(StartSiteAsync(config, siteName));
        }
        await Task.WhenAll(tasks);

        return "start";
    }

    private static async Task StopWebsiteAsync(string config, List<string> siteNames) {
        // Check if web.config file exists for each site
        foreach (var siteName in siteNames) {
            var webConfigFilePath = Path.Combine(config, $"{siteName}.web.config");
            if (!File.Exists(webConfigFilePath)) {
                throw new FileNotFoundException($"The web configuration file '{webConfigFilePath}' for site '{siteName}' does not exist.");
            }
        }

        // Stop sites concurrently using task parallel library
        var tasks = new List<Task>();
        foreach (var siteName in siteNames) {
            tasks.Add(StopSiteAsync(config, siteName));
        }
        await Task.WhenAll(tasks);

        return "stop";
    }

    private static async Task RemoveWebsiteAsync(string config, List<string> siteNames) {
        // Check if web.config file exists for each site
        foreach (var siteName in siteNames) {
            var webConfigFilePath = Path.Combine(config, $"{siteName}.web.config");
            if (!File.Exists(webConfigFilePath)) {
                throw new FileNotFoundException($"The web configuration file '{webConfigFilePath}' for site '{siteName}' does not exist.");
            }
        }

        // Remove sites concurrently using task parallel library
        var tasks = new List<Task>();
        foreach (var siteName in siteNames) {
            tasks.Add(RemoveSiteAsync(config, siteName));
        }
        await Task.WhenAll(tasks);

        return "remove";
    }

    private static async Task AddWebsiteAsync(string config, List<string> siteNames) {
        // Check if web.config file exists for each site
        foreach (var siteName in siteNames) {
            var webConfigFilePath = Path.Combine(config, $"{siteName}.web.config");
            if (!File.Exists(webConfigFilePath)) {
                throw new FileNotFoundException($"The web configuration file '{webConfigFilePath}' for site '{siteName}' does not exist.");
            }
        }

        // Add sites concurrently using task parallel library
        var tasks = new List<Task>();
        foreach (var siteName in siteNames) {
            tasks.Add(AddSiteAsync(config, siteName));
        }
        await Task.WhenAll(tasks);

        return "add";
    }

    private static async Task StartSiteAsync(string config, string siteName) {
        // Implement code to start the website here
        await Task.Delay(1000);
        return;
    }

    private static async Task StopSiteAsync(string config, string siteName) {
        // Implement code to stop the website here
        await Task.Delay(1000);
        return;
    }

    private static async Task RemoveSiteAsync(string config, string siteName) {
        // Implement code to remove the website here
        await Task.Delay(1000);
