package com.example.inventory;

import java.util.List;
import java.util.Map;

public class InventoryManager {
    private static final int NUM_WAREHOUSES = 5;
    private static final int NUM_PRODUCTS = 1000;
    private static final int TIMEOUT_SECONDS = 30;

    // Map of product IDs to their current stock levels across all warehouses
    private static final Map<Integer, Integer> inventoryMap = new HashMap<>();

    // List of pending transactions that are waiting to be processed
    private static final List<Transaction> transactionQueue = new ArrayList<>();

    public static void main(String[] args) {
        // Initialize the inventory map with random stock levels for each product
        for (int i = 0; i < NUM_PRODUCTS; i++) {
            inventoryMap.put(i, ThreadLocalRandom.current().nextInt(1, 100));
        }

        // Start the transaction processing thread
        new TransactionProcessorThread().start();

        // Start the RESTful API server
        new InventoryApiServer().start();
    }

    public static void updateInventory(int productId, int delta) {
        synchronized (inventoryMap) {
            // Acquire a lock on the inventory map to prevent concurrent updates
            int currentStock = inventoryMap.get(productId);
            int newStock = currentStock + delta;
            if (newStock < 0) {
                throw new IllegalArgumentException("Insufficient stock");
            }
            inventoryMap.put(productId, newStock);
        }
    }

    public static int getInventory(int productId) {
        return inventoryMap.getOrDefault(productId, 0);
    }

    public static void processTransaction(Transaction transaction) {
        synchronized (transactionQueue) {
            // Add the transaction to the queue for processing
            transactionQueue.add(transaction);
        }
    }

    private static class TransactionProcessorThread extends Thread {
        @Override
        public void run() {
            while (true) {
                synchronized (transactionQueue) {
                    // Process transactions from the queue
                    for (Transaction transaction : transactionQueue) {
                        try {
                            updateInventory(transaction.productId, transaction.delta);
                        } catch (IllegalArgumentException e) {
                            System.out.println("Transaction failed: " + e.getMessage());
                        }
                    }
                }
                // Sleep for a short period to prevent busy waiting
                try {
                    Thread.sleep(TIMEOUT_SECONDS * 1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    private static class InventoryApiServer extends HttpServer {
        @Override
        public void start() throws IOException {
            // Configure the server with a RESTful API for querying and updating inventory
            get("/products/:id", (request, response) -> {
                int productId = Integer.parseInt(request.params(":id"));
                return getInventory(productId);
            });

            post("/transactions", (request, response) -> {
                Transaction transaction = new Transaction(Integer.parseInt(request.queryParams("productId")),
                        Integer.parseInt(request.queryParams("delta")));
                processTransaction(transaction);
                return "OK";
            });
        }
    }

    private static class Transaction {
        public int productId;
        public int delta;

        public Transaction(int productId, int delta) {
            this.productId = productId;
            this.delta = delta;
        }
    }
}
