using System;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using MyApp.Services;
using MyApp.Models;
using MyApp.Caching;

namespace MyApp.Controllers
{
    public class PageController : ControllerBase
    {
        private readonly IPageService _pageService;
        private readonly ICacheManager _cacheManager;

        public PageController(IPageService pageService, ICacheManager cacheManager)
        {
            _pageService = pageService;
            _cacheManager = cacheManager;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElementAsync([FromBody]UpdateElementRequest request)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            // Validate input IDs
            if (!_pageService.IsValidPageId(request.PageId))
                return NotFound();

            if (!_pageService.IsValidElementId(request.ElementId))
                return BadRequest("Invalid element ID");

            // Check permissions
            var user = await _cacheManager.GetUserAsync(HttpContext.User.Identity.Name);
            if (user == null || !user.HasPermission(_pageService.GetPage(request.PageId).Permissions))
                return Forbid();

            try
            {
                // Update element HTML content
                await _pageService.UpdateElementAsync(request.PageId, request.ElementId, request.HtmlContent);

                // Add log entry for successful update
                await _cacheManager.AddLogEntryAsync(new LogEntry()
                {
                    User = user,
                    PageId = request.PageId,
                    ElementId = request.ElementId,
                    HtmlContent = request.HtmlContent,
                    DateUpdated = DateTime.UtcNow
                });
            }
            catch (Exception e)
            {
                // Log error and return error response
                await _cacheManager.AddLogEntryAsync(new LogEntry()
                {
                    User = user,
                    PageId = request.PageId,
                    ElementId = request.ElementId,
                    HtmlContent = request.HtmlContent,
                    DateUpdated = DateTime.UtcNow,
                    ErrorMessage = e.Message
                });

                return StatusCode(500);
            }

            // Return response indicating page refresh should be triggered
            return Ok("Page refresh required");
        }
    }
}
