using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class UpdateUserProfile
{
    public static async Task<bool> UpdateUserProfilesAsync(string configFilePath, List<int> userIds, Dictionary<string, string> updatedProfileDetails)
    {
        // Load configuration from file
        var config = JsonConvert.DeserializeObject<UpdateUserProfileConfig>(File.ReadAllText(configFilePath));

        // Validate directory paths and user IDs
        foreach (var userId in userIds)
        {
            if (!int.TryParse(userId, out int parsedUserId))
                throw new ArgumentException("Invalid user ID", nameof(userIds));

            var directoryPath = Path.Combine(config.ProfileDirectory, parsedUserId.ToString());
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"Profile directory for user {parsedUserId} does not exist");
        }

        // Implement caching mechanisms to minimize API calls
        var cachedProfiles = new Dictionary<int, UserProfile>();

        // Iterate over each user ID and update their profile information concurrently
        foreach (var userId in userIds)
        {
            var parsedUserId = int.Parse(userId);
            var directoryPath = Path.Combine(config.ProfileDirectory, parsedUserId.ToString());
            var filePath = Path.Combine(directoryPath, "profile.json");

            // Check if the profile is already cached and return it if so
            if (cachedProfiles.ContainsKey(parsedUserId))
                continue;

            // Make an API call to retrieve the user's profile information
            var httpClient = new HttpClient();
            var apiResponse = await httpClient.GetAsync($"{config.ApiUrl}/users/{parsedUserId}");

            if (!apiResponse.IsSuccessStatusCode)
                throw new Exception("Failed to retrieve user profile information from API");

            // Deserialize the API response and update the profile details
            var apiResponseBody = await apiResponse.Content.ReadAsStringAsync();
            var apiProfile = JsonConvert.DeserializeObject<UserProfile>(apiResponseBody);

            // Update the profile details with any new information
            foreach (var updatedField in updatedProfileDetails)
                apiProfile[updatedField.Key] = updatedField.Value;

            // Serialize the updated profile and save it to disk
            var serializedProfile = JsonConvert.SerializeObject(apiProfile);
            File.WriteAllText(filePath, serializedProfile);

            // Add the updated profile to the cache for future reference
            cachedProfiles[parsedUserId] = apiProfile;
        }

        return true;
    }

    public class UpdateUserProfileConfig
    {
        [JsonProperty("api_url")]
        public string ApiUrl { get; set; }

        [JsonProperty("profile_directory")]
        public string ProfileDirectory { get; set; }
    }

    public class UserProfile
    {
        [JsonProperty("email")]
        public string Email { get; set; }

        [JsonProperty("phone_number")]
        public string PhoneNumber { get; set; }
    }
}
