using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DynamicWeatherMiddleware
{
    public class WeatherMiddleware
    {
        private readonly string _latitude;
        private readonly string _longitude;
        private readonly string _weatherSource;

        public WeatherMiddleware(string latitude, string longitude)
        {
            _latitude = latitude;
            _longitude = longitude;
            _weatherSource = "OpenWeatherMap"; // Default weather source
        }

        public async Task<dynamic> GetWeatherAsync()
        {
            var client = new HttpClient();
            var url = $"https://api.openweathermap.org/data/2.5/weather?lat={_latitude}&lon={_longitude}&appid=YOUR_API_KEY";
            var response = await client.GetAsync(url);
            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<dynamic>(json);
        }

        public async Task<double> GetTemperatureAsync()
        {
            var weather = await GetWeatherAsync();
            return Convert.ToDouble(weather.main.temp);
        }

        public async Task<double> GetHumidityAsync()
        {
            var weather = await GetWeatherAsync();
            return Convert.ToDouble(weather.main.humidity);
        }

        public async Task<double> GetWindSpeedAsync()
        {
            var weather = await GetWeatherAsync();
            return Convert.ToDouble(weather.wind.speed);
        }

        public async Task<double> GetPrecipitationLevelAsync()
        {
            var weather = await GetWeatherAsync();
            return Convert.ToDouble(weather.rain["1h"]);
        }

        private static string GetRandomCondition(string[] conditions)
        {
            var rng = new Random();
            return conditions[rng.Next(conditions.Length)];
        }

        public async Task<dynamic> SimulateWeatherAsync()
        {
            // Generate a random weather condition
            string[] conditions = new[] { "rain", "snow", "clear" };
            var condition = GetRandomCondition(conditions);

            switch (condition)
            {
                case "rain":
                    return await GetRainyWeatherAsync();
                case "snow":
                    return await GetSnowyWeatherAsync();
                default:
                    return await GetClearWeatherAsync();
            }
        }

        private async Task<dynamic> GetRainyWeatherAsync()
        {
            // Rainy weather simulation
            var client = new HttpClient();
            var url = $"https://api.openweathermap.org/data/2.5/weather?lat={_latitude}&lon={_longitude}&appid=YOUR_API_KEY&units=metric";
            var response = await client.GetAsync(url);
            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<dynamic>(json);
        }

        private async Task<dynamic> GetSnowyWeatherAsync()
        {
            // Snowy weather simulation
            var client = new HttpClient();
            var url = $"https://api.openweathermap.org/data/2.5/weather?lat={_latitude}&lon={_longitude}&appid=YOUR_API_KEY&units=metric";
            var response = await client.GetAsync(url);
            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<dynamic>(json);
        }

        private async Task<dynamic> GetClearWeatherAsync()
        {
            // Clear weather simulation
            var client = new HttpClient();
            var url = $"https://api.openweathermap.org/data/2.5/weather?lat={_latitude}&lon={_longitude}&appid=YOUR_API_KEY&units=metric";
            var response = await client.GetAsync(url);
            var json = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<dynamic>(json);
        }
    }
}
