    public void addVertex(String pokemonId) {
        // Fetch weaknesses, evolution details, and habitat information from external APIs
        List<String> weaknesses = fetchWeaknesses(pokemonId);
        String evolutionStage = fetchEvolutionStage(pokemonId);
        String habitatDescription = fetchHabitat(pokemonId);

        // Add vertex to graph database with properties
        Vertex vertex = graphDatabase.addVertex();
        vertex.setProperty("name", pokemonId);
        vertex.setProperty("type", "Pokemon");
        vertex.setProperty("weaknesses", weaknesses);
        vertex.setProperty("evolutionStage", evolutionStage);
        vertex.setProperty("habitatDescription", habitatDescription);
    }

    public void addEdge(String pokemonId, String relatedPokemonId) {
        // Fetch relationship between two Pokemon from external API
        String relationship = fetchRelationship(pokemonId, relatedPokemonId);

        // Add edge to graph database
        Edge edge = graphDatabase.addEdge();
        edge.setProperty("name", relationship);
        edge.setProperty("type", "Relation");
    }

    public JSONObject fetchData(String pokemonId) {
        JSONObject response = new JSONObject();

        // Fetch weaknesses, evolution details, and habitat information from external APIs
        List<String> weaknesses = fetchWeaknesses(pokemonId);
        String evolutionStage = fetchEvolutionStage(pokemonId);
        String habitatDescription = fetchHabitat(pokemonId);

        // Set properties on vertex in graph database
        Vertex vertex = graphDatabase.getVertex(pokemonId);
        if (vertex != null) {
            vertex.setProperty("weaknesses", weaknesses);
            vertex.setProperty("evolutionStage", evolutionStage);
            vertex.setProperty("habitatDescription", habitatDescription);
        }

