    private List<String> fetchWeaknesses(String pokemonId) {
        // Fetch weaknesses from external API
        String url = WEAKNESS_API + "/" + pokemonId;
        try {
            URL apiUrl = new URL(url);
            HttpURLConnection conn = (HttpURLConnection) apiUrl.openConnection();
            conn.setRequestMethod("GET");
            conn.setConnectTimeout(REQUEST_TIMEOUT);
            conn.setReadTimeout(REQUEST_TIMEOUT);
            int status = conn.getResponseCode();
            if (status == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                String inputLine;
                StringBuffer response = new StringBuffer();
                while ((inputLine = in.readLine()) != null) {
                    response.append(inputLine);
                }
                in.close();
                return parseWeaknesses(response.toString());
            } else {
                System.out.println("Failed to fetch weaknesses from API");
                return Collections.emptyList();
            }
        } catch (IOException e) {
            System.out.println("Failed to connect to API: " + e.getMessage());
            return Collections.emptyList();
        }
    }

