  private String generateSalesSummaryForPostgresql(Map<String, Object> parameters, List<Map<String, Object>> data) {
    // Generate the sales summary report for PostgreSQL using the cached data and parameters
    StringBuilder sb = new StringBuilder();
    for (Map<String, Object> row : data) {
