  private String generateCustomerReportForPostgresql(Map<String, Object> parameters, List<Map<String, Object>> data) {
    // Generate the customer report for PostgreSQL using the cached data and parameters
    StringBuilder sb = new StringBuilder();
    for (Map<String, Object> row : data) {
