#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/mman.h>
#include <errno.h>

// Define the modes supported by the library
enum DES_MODES {
    ECB,
    EDE,
    EDE3,
    CFB
};

// Define the structure for holding the encryption key
typedef struct {
    uint8_t* key;
    size_t key_len;
} DES_KEY;

// Define the structure for holding the encryption/decryption context
typedef struct {
    enum DES_MODES mode;
    DES_KEY key;
    uint8_t* iv;
} DES_CTX;

// Define the function for initializing the encryption/decryption context
DES_CTX* des_init(enum DES_MODES mode, const char* key, size_t key_len) {
    // Allocate memory for the encryption/decryption context
    DES_CTX* ctx = (DES_CTX*)malloc(sizeof(DES_CTX));
    if (!ctx) {
        perror("Failed to allocate memory for the encryption/decryption context");
        return NULL;
    }

    // Set the mode and key for the context
    ctx->mode = mode;
    ctx->key.key = (uint8_t*)malloc(key_len);
    if (!ctx->key.key) {
        perror("Failed to allocate memory for the encryption key");
        free(ctx);
        return NULL;
    }
    memcpy(ctx->key.key, key, key_len);
    ctx->key.key_len = key_len;

    // Set the initialization vector for the context (if necessary)
    if (mode == CFB) {
        ctx->iv = (uint8_t*)malloc(DES_BLOCK_SIZE);
        if (!ctx->iv) {
            perror("Failed to allocate memory for the initialization vector");
            free(ctx->key.key);
            free(ctx);
            return NULL;
        }
    }

    return ctx;
}

// Define the function for encrypting data using the DES algorithm
int des_encrypt(DES_CTX* ctx, const uint8_t* plaintext, size_t plaintext_len, uint8_t* ciphertext) {
    // Check if the context is valid
    if (!ctx || !plaintext || !ciphertext) {
        return -1;
    }

    // Check if the key and initialization vector are set for the context
    if (!ctx->key.key || (ctx->mode == CFB && !ctx->iv)) {
        fprintf(stderr, "The encryption/decryption context is not properly initialized\n");
        return -1;
    }

    // Check if the input data is a multiple of the block size
    if (plaintext_len % DES_BLOCK_SIZE != 0) {
        fprintf(stderr, "The input data length is not a multiple of the block size\n");
        return -1;
    }

    // Set the output buffer for the encrypted data
    uint8_t* buf = (uint8_t*)malloc(plaintext_len);
    if (!buf) {
        perror("Failed to allocate memory for the encrypted data buffer");
        return -1;
    }

    // Perform the encryption operation
    switch (ctx->mode) {
        case ECB:
            des_ecb_encrypt(ctx, plaintext, plaintext_len, buf);
            break;
        case EDE:
            des_ede_encrypt(ctx, plaintext, plaintext_len, buf);
            break;
        case EDE3:
            des_ede3_encrypt(ctx, plaintext, plaintext_len, buf);
            break;
        case CFB:
            des_cfb_encrypt(ctx, plaintext, plaintext_len, buf);
            break;
    }

    // Copy the encrypted data to the output buffer
    memcpy(ciphertext, buf, plaintext_len);

    // Free the memory for the encrypted data buffer
    free(buf);

    return 0;
}

// Define the function for decrypting data using the DES algorithm
int des_decrypt(DES_CTX* ctx, const uint8_t* ciphertext, size_t ciphertext_len, uint8_t* plaintext) {
    // Check if the context is valid
    if (!ctx || !ciphertext || !plaintext) {
        return -1;
    }

    // Check if the key and initialization vector are set for the context
    if (!ctx->key.key || (ctx->mode == CFB && !ctx->iv)) {
        fprintf(stderr, "The encryption/decryption context is not properly initialized\n");
        return -1;
    }

    // Check if the input data is a multiple of the block size
    if (ciphertext_len % DES_BLOCK_SIZE != 0) {
        fprintf(stderr, "The input data length is not a multiple of the block size\n");
        return -1;
    }

    // Set the output buffer for the decrypted data
    uint8_t* buf = (uint8_t*)malloc(ciphertext_len);
    if (!buf) {
        perror("Failed to allocate memory for the decrypted data buffer");
        return -1;
    }

    // Perform the decryption operation
    switch (ctx->mode) {
        case ECB:
            des_ecb_decrypt(ctx, ciphertext, ciphertext_len, buf);
            break;
        case EDE:
            des_ede_decrypt(ctx, ciphertext, ciphertext_len, buf);
            break;
        case EDE3:
            des_ede3_decrypt(ctx, ciphertext, ciphertext_len, buf);
            break;
        case CFB:
            des_cfb_decrypt(ctx, ciphertext, ciphertext_len, buf);
            break;
    }

    // Copy the decrypted data to the output buffer
    memcpy(plaintext, buf, ciphertext_len);

    // Free the memory for the decrypted data buffer
    free(buf);

    return 0;
}

// Define the function for encrypting data using the DES algorithm in ECB mode
void des_ecb_encrypt(DES_CTX* ctx, const uint8_t* plaintext, size_t plaintext_len, uint8_t* ciphertext) {
    // Calculate the number of blocks to encrypt
    size_t num_blocks = plaintext_len / DES_BLOCK_SIZE;

    // Encrypt each block of data
    for (size_t i = 0; i < num_blocks; i++) {
        des_encrypt_block(ctx, plaintext + i * DES_BLOCK_SIZE, ciphertext + i * DES_BLOCK_SIZE);
    }
}

// Define the function for encrypting data using the DES algorithm in EDE mode
void des_ede_encrypt(DES_CTX* ctx, const uint8_t* plaintext, size_t plaintext_len, uint8_t* ciphertext) {
    // Calculate the number of blocks to encrypt
    size_t num_blocks = plaintext_len / DES_BLOCK_SIZE;

    // Encrypt each block of data
    for (size_t i = 0; i < num_blocks; i++) {
        des_encrypt_block(ctx, plaintext + i * DES_BLOCK_SIZE, ciphertext + i * DES_BLOCK_SIZE);
        des_decrypt_block(ctx, ciphertext + i * DES_BLOCK_SIZE, ciphertext + i * DES_BLOCK_SIZE);
    }
}

// Define the function for encrypting data using the DES algorithm in EDE3 mode
void des_ede3_encrypt(DES_CTX* ctx, const uint8_t* plaintext, size_t plaintext_len, uint8_t* ciphertext) {
    // Calculate the number of blocks to encrypt
