// Configuration file format: [algorithm] = [key]|[iv]|[salt]
const char *config_file = "config.txt";

// Algorithm enumeration
enum algorithm { AES256, CHACHA20 };

// Key structure
struct key {
  unsigned char *data;
  size_t len;
};

// IV structure
struct iv {
  unsigned char *data;
  size_t len;
};

// Salt structure
struct salt {
  unsigned char *data;
  size_t len;
};

// Encryption function pointer
typedef int (*encrypt_func)(const struct key, const struct iv, const struct salt);

// Decryption function pointer
typedef int (*decrypt_func)(const struct key, const struct iv, const struct salt);

// Hashing function pointer
typedef unsigned char *(*hash_func)(const unsigned char *, size_t);

// Algorithm structure
struct algorithm_info {
  enum algorithm type;
  encrypt_func encrypt;
  decrypt_func decrypt;
  hash_func hash;
};

// Load algorithms from configuration file
int load_algorithms(const char *config_file, struct algorithm_info **algs) {
  // Open configuration file
  FILE *fp = fopen(config_file, "r");
  if (fp == NULL) {
    printf("Error: unable to open configuration file\n");
    return -1;
  }

  // Read algorithm definitions from file
  while (!feof(fp)) {
    char line[256];
    fgets(line, sizeof(line), fp);

    // Skip empty lines and comments
    if (strlen(line) == 0 || line[0] == '#') continue;

    // Parse algorithm name and key
    char *algorithm_name = strtok(line, "=");
    char *key = strtok(NULL, "|");
    char *iv = strtok(NULL, "|");
    char *salt = strtok(NULL, "\n");

    // Load algorithm from OpenSSL library
    struct algorithm_info *alg = load_algorithm(algorithm_name, key, iv, salt);
    if (alg == NULL) {
      printf("Error: unable to load algorithm %s\n", algorithm_name);
      return -1;
    }

    // Add algorithm to list
    algs[i] = alg;
  }

  // Close configuration file
  fclose(fp);

  return 0;
}

// Load algorithm from OpenSSL library
struct algorithm_info *load_algorithm(const char *name, const unsigned char *key, const unsigned char *iv, const unsigned char *salt) {
  // Initialize OpenSSL library
  OPENSSL_init_crypto(OPENSSL_INIT_LOAD_CONFIG, NULL);

  // Load algorithm from OpenSSL library
  if (strcmp(name, "AES256") == 0) {
    return load_aes256(key, iv, salt);
  } else if (strcmp(name, "CHACHA20") == 0) {
    return load_chacha20(key, iv, salt);
  }

  // Unknown algorithm
  printf("Error: unknown algorithm %s\n", name);
  return NULL;
}

// Load AES-256 algorithm from OpenSSL library
struct algorithm_info *load_aes256(const unsigned char *key, const unsigned char *iv, const unsigned char *salt) {
  // Initialize AES-256 encryption/decryption functions
  encrypt_func aes256_encrypt = AES_encrypt;
  decrypt_func aes256_decrypt = AES_decrypt;

  // Initialize SHA-256 hashing function
  hash_func sha256_hash = SHA256;

  // Allocate memory for algorithm structure
  struct algorithm_info *alg = malloc(sizeof(struct algorithm_info));
  if (alg == NULL) {
    printf("Error: unable to allocate memory for AES-256 algorithm\n");
    return NULL;
  }

  // Set algorithm type and functions
  alg->type = AES256;
  alg->encrypt = aes256_encrypt;
  alg->decrypt = aes256_decrypt;
  alg->hash = sha256_hash;

  return alg;
}

// Load ChaCha20 algorithm from OpenSSL library
struct algorithm_info *load_chacha20(const unsigned char *key, const unsigned char *iv, const unsigned char *salt) {
  // Initialize ChaCha20 encryption/decryption functions
  encrypt_func chacha20_encrypt = CHACHA_encrypt;
  decrypt_func chacha20_decrypt = CHACHA_decrypt;

  // Initialize SHA-512 hashing function
  hash_func sha512_hash = SHA512;

  // Allocate memory for algorithm structure
  struct algorithm_info *alg = malloc(sizeof(struct algorithm_info));
  if (alg == NULL) {
    printf("Error: unable to allocate memory for ChaCha20 algorithm\n");
    return NULL;
  }

  // Set algorithm type and functions
  alg->type = CHACHA20;
  alg->encrypt = chacha20_encrypt;
  alg->decrypt = chacha20_decrypt;
  alg->hash = sha512_hash;

  return alg;
}

// Encrypt data using selected algorithm
int encrypt(struct algorithm_info *alg, const unsigned char *data, size_t len, unsigned char **encrypted) {
  // Initialize encryption function
  encrypt_func func = alg->encrypt;

  // Allocate memory for encrypted data
  *encrypted = malloc(sizeof(unsigned char) * (len + 16));
  if (*encrypted == NULL) {
    printf("Error: unable to allocate memory for encrypted data\n");
    return -1;
  }

  // Encrypt data
  int res = func(data, len, *encrypted);
  if (res < 0) {
    printf("Error: encryption failed\n");
    free(*encrypted);
    return -1;
  }

  return 0;
}

// Decrypt data using selected algorithm
int decrypt(struct algorithm_info *alg, const unsigned char *data, size_t len, unsigned char **decrypted) {
  // Initialize decryption function
  decrypt_func func = alg->decrypt;

  // Allocate memory for decrypted data
  *decrypted = malloc(sizeof(unsigned char) * (len + 16));
  if (*decrypted == NULL) {
    printf("Error: unable to allocate memory for decrypted data\n");
    return -1;
  }

  // Decrypt data
  int res = func(data, len, *decrypted);
  if (res < 0) {
    printf("Error: decryption failed\n");
    free(*decrypted);
    return -1;
  }

  return 0;
}

// Hash data using selected algorithm
int hash(struct algorithm_info *alg, const unsigned char *data, size_t len, unsigned char **hash) {
  // Initialize hashing function
  hash_func func = alg->hash;

  // Allocate memory for hash value
  *hash = malloc(sizeof(unsigned char) * (SHA512_DIGEST_LENGTH + 16));
  if (*hash == NULL) {
    printf("Error: unable to allocate memory for hash\n");
    return -1;
  }

  // Hash data
  int res = func(data, len, *hash);
  if (res < 0) {
    printf("Error: hashing failed\n");
    free(*hash);
    return -1;
  }

  return 0;
}

// Print algorithm information
void print_info(struct algorithm_info *alg) {
  // Get algorithm type
  char *type = NULL;
  if (alg->type == AES256) {
    type = "AES-256";
  } else if (alg->type == CHACHA20) {
    type = "ChaCha20";
  }

  // Print algorithm information
  printf("Algorithm: %s\n", type);
  printf("Encryption function: %p\n", alg->encrypt);
  printf("Decryption function: %p\n", alg->decrypt);
  printf("Hashing function: %p\n", alg->hash);
}

// Main function
int main(void) {
  // Load algorithms from configuration file
  struct algorithm_info *algorithms = NULL;
  load_algorithms(&algorithms, "config.txt");

  // Encrypt data using first algorithm
  unsigned char *encrypted = NULL;
  encrypt(algorithms[0], data, len, &encrypted);

  // Decrypt data using second algorithm
  unsigned char *decrypted = NULL;
  decrypt(algorithms[1], encrypted, len, &decrypted);

  // Hash data using third algorithm
  unsigned char *hash = NULL;
  hash(algorithms[2], decrypted, len, &hash);

  // Print algorithm information
  print_info(algorithms[0]);
  print_info(algorithms[1]);
  print_info(algorithms[2]);

  return 0;
}
