public class DynamicNestedDeserializer {
    private static final Map<String, Class<?>> CLASS_CACHE = new ConcurrentHashMap<>();
    private static final Map<String, Constructor<?>> CONSTRUCTOR_CACHE = new HashMap<>();

    public <T> T deserialize(byte[] bytes) {
        try {
            JSONObject jsonObject = new JSONObject(new String(bytes));
            return deserialize(jsonObject);
        } catch (JSONException | ClassNotFoundException | IOException e) {
            // handle exceptions and log appropriate error messages
            throw new RuntimeException("Failed to deserialize bytes", e);
        }
    }

    public <T> T deserialize(JSONObject jsonObject) throws JSONException, ClassNotFoundException, IOException {
        String className = jsonObject.getString("class");
        Class<?> clazz = getClassFromCache(className);
        Constructor<?> constructor = getConstructorFromCache(clazz);

        try {
            return (T) constructor.newInstance();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
            // handle exceptions and log appropriate error messages
            throw new RuntimeException("Failed to create instance of class " + className, e);
        }
    }

    private Class<?> getClassFromCache(String className) throws ClassNotFoundException {
        Class<?> clazz = CLASS_CACHE.get(className);
        if (clazz == null) {
            JSONObject jsonObject = retrieveClassDefinitionFromExternalAPI(className);
            clazz = Class.forName(jsonObject.getString("class"));
            CLASS_CACHE.put(className, clazz);
        }
        return clazz;
    }

    private Constructor<?> getConstructorFromCache(Class<?> clazz) {
        Constructor<?> constructor = CONSTRUCTOR_CACHE.get(clazz);
        if (constructor == null) {
            constructor = clazz.getDeclaredConstructor();
            CONSTRUCTOR_CACHE.put(clazz, constructor);
        }
        return constructor;
    }

    private JSONObject retrieveClassDefinitionFromExternalAPI(String className) throws IOException {
        // implement the logic to retrieve class information from an external API
        throw new UnsupportedOperationException("Implement me");
    }
}
