#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sqlite3.h>

#define MAX_RECORDS 1000000 // maximum number of records to store
#define INITIAL_RANGE 10000000 // initial range of random values

// structure to hold the record data
typedef struct {
    int key;
    long long offset;
} Record;

// function to initialize the record database
void init_records(sqlite3 *db) {
    char sql[256];
    sprintf(sql, "CREATE TABLE records (key INTEGER PRIMARY KEY, offset BIGINT);");
    sqlite3_exec(db, sql, NULL, NULL, NULL);
}

// function to add a new record to the database
void add_record(sqlite3 *db, int key, long long offset) {
    char sql[256];
    sprintf(sql, "INSERT INTO records (key, offset) VALUES (%d, %lld);", key, offset);
    sqlite3_exec(db, sql, NULL, NULL, NULL);
}

// function to retrieve a record from the database by key
Record *get_record(sqlite3 *db, int key) {
    char sql[256];
    sprintf(sql, "SELECT offset FROM records WHERE key = %d;", key);
    sqlite3_stmt *stmt = sqlite3_prepare_v2(db, sql, -1, NULL);
    if (!stmt) {
        printf("Error preparing statement: %s\n", sqlite3_errmsg(db));
        return NULL;
    }
    int rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        printf("No record found for key %d\n", key);
        return NULL;
    }
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = sqlite3_column_int64(stmt, 0);
    sqlite3_finalize(stmt);
    return record;
}

// function to update a record in the database by key
void update_record(sqlite3 *db, int key, long long offset) {
    char sql[256];
    sprintf(sql, "UPDATE records SET offset = %lld WHERE key = %d;", offset, key);
    sqlite3_exec(db, sql, NULL, NULL, NULL);
}

// function to delete a record from the database by key
void delete_record(sqlite3 *db, int key) {
    char sql[256];
    sprintf(sql, "DELETE FROM records WHERE key = %d;", key);
    sqlite3_exec(db, sql, NULL, NULL, NULL);
}

// function to initialize the system with random values from a configuration file
void init_system(char *config_file) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        printf("Error opening configuration file %s\n", config_file);
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        int key = atoi(line);
        long long offset = random() % INITIAL_RANGE;
        add_record(key, offset);
    }
    fclose(fp);
}

// function to retrieve a record from the system by key
Record *get_system(int key) {
    Record *record = get_record(db, key);
    if (!record) {
        printf("No record found for key %d\n", key);
        return NULL;
    }
    return record;
}

// function to update a record in the system by key
void update_system(int key, long long offset) {
    update_record(db, key, offset);
}

// function to delete a record from the system by key
void delete_system(int key) {
    delete_record(db, key);
}
```
This code implements the described functionality using SQLite as the underlying database engine. The `init_records` function initializes the record database with the specified number of records and their corresponding random offsets. The `add_record`, `get_record`, `update_record`, and `delete_record` functions provide a way to add, retrieve, update, and delete records from the database.

The `init_system` function initializes the system with random values from a configuration file. It reads the configuration file line by line, creating a new record for each key-value pair in the file. The `get_system`, `update_system`, and `delete_system` functions provide a way to retrieve, update, and delete records from the system.

