// UserProfileService class

public class UserProfileService {
  private final UserRepository userRepository;

  public UserProfileService(UserRepository userRepository) {
    this.userRepository = userRepository;
  }

  @PUT
  @Path("/{id}")
  public void updateUserProfile(@PathParam("id") long id, @RequestBody Map<String, Object> updatedData) throws Exception {
    // Validate input data
    if (!updatedData.containsKey("name")) {
      throw new BadRequestException("Name is required");
    }

    // Merge updated data with existing profile data efficiently
    User user = userRepository.getUser(id);
    user.setName((String) updatedData.get("name"));
    if (updatedData.containsKey("email")) {
      user.setEmail((String) updatedData.get("email"));
    }
    if (updatedData.containsKey("address")) {
      user.setAddress((String) updatedData.get("address"));
    }

    // Update profile data in repository
    userRepository.updateUser(user);
  }

  @PATCH
  @Path("/{id}")
  public void softDeleteUserProfile(@PathParam("id") long id) throws Exception {
    // Validate input data
    if (!userRepository.existsById(id)) {
      throw new NotFoundException("User with ID " + id + " not found");
    }

    // Soft-delete user profile
    User user = userRepository.getUser(id);
    user.setDeletedAt(new Date());
    userRepository.updateUser(user);
  }

  @GET
  @Path("/")
  public List<User> getAllActiveProfiles() throws Exception {
    // Get all users from repository
    return userRepository.findAll();
  }
}
