  private static final Map<String, UserProfile> userProfiles = new HashMap<>();

  // Define method for initializing messaging service adapters
  public static void initMessageServiceAdapters() {
    // Add supported messaging services and their corresponding adapter classes here
    messageServiceAdapters.put("sms", new SMSAdapter());
    messageServiceAdapters.put("email", new EmailAdapter());
    messageServiceAdapters.put("socialmedia", new SocialMediaAdapter());
  }

