  public static void handleIncomingMessage(String userId, String message) {
    UserProfile userProfile = getUserProfile(userId);
    if (userProfile != null) {
      MessageServiceAdapter adapter = getMessageServiceAdapter(userProfile.getMessageService());
      adapter.sendMessage(message, userProfile.getContactInfo());
    }
  }

  // Define method for handling incoming message delivery receipts
  public static void handleIncomingDeliveryReceipt(String userId, String messageId) {
    UserProfile userProfile = getUserProfile(userId);
    if (userProfile != null) {
      MessageServiceAdapter adapter = getMessageServiceAdapter(userProfile.getMessageService());
      adapter.acknowledgeMessage(messageId, userProfile.getContactInfo());
    }
  }

  // Define method for handling incoming message rejections
  public static void handleIncomingRejection(String userId, String messageId) {
    UserProfile userProfile = getUserProfile(userId);
    if (userProfile != null) {
      MessageServiceAdapter adapter = getMessageServiceAdapter(userProfile.getMessageService());
      adapter.rejectMessage(messageId, userProfile.getContactInfo());
    }
  }

