    UserProfile userProfile = getUserProfile(userId);
    if (userProfile != null) {
      MessageServiceAdapter adapter = getMessageServiceAdapter(userProfile.getMessageService());
      adapter.rejectMessage(messageId, userProfile.getContactInfo());
