import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.logging.Logger;

public class EvolutionService {
    private static final Logger logger = Logger.getLogger(EvolutionService.class.getName());
    private ClassProvider classProvider;
    private Map<Integer, Pokemon> pokemons;
    private Map<String, List<Weakness>> weaknesses;
    private Map<Integer, EvolutionStage> evolutionStages;
    private int cacheSize = 1000;
    private long cacheTimeoutMillis = 3600000L; // 1 hour

    public EvolutionService(ClassProvider classProvider) {
        this.classProvider = classProvider;
        pokemons = new HashMap<>();
        weaknesses = new HashMap<>();
        evolutionStages = new HashMap<>();
    }

    public void init() throws Exception {
        // Initialize the service with data from the external data source
        List<Pokemon> allPokemons = classProvider.getAllPokemons();
        for (Pokemon pokemon : allPokemons) {
            pokemons.put(pokemon.id, pokemon);
            weaknesses.put(pokemon.name, new ArrayList<Weakness>());
            evolutionStages.put(pokemon.id, new EvolutionStage());
        }
    }

    public List<Pokemon> getAllPokemons() {
        return new ArrayList<>(pokemons.values());
    }

    public Pokemon getPokemonById(int id) {
        return pokemons.get(id);
    }

    public List<Weakness> getWeaknessesByName(String name) {
        return weaknesses.get(name);
    }

    public EvolutionStage getEvolutionStageById(int id) {
        return evolutionStages.get(id);
    }

    private void cachePokemonData(Pokemon pokemon) {
        // Cache the data for this Pokemon
        pokemons.put(pokemon.id, pokemon);
        weaknesses.put(pokemon.name, new ArrayList<Weakness>());
        evolutionStages.put(pokemon.id, new EvolutionStage());
    }

    private void cacheEvolutionData(int id, EvolutionStage stage) {
        // Cache the data for this evolution stage
        evolutionStages.put(id, stage);
    }

    private void removeCachedPokemonData(int id) {
        // Remove cached data for this Pokemon
        pokemons.remove(id);
        weaknesses.remove(id);
        evolutionStages.remove(id);
    }

    private void cacheWeaknessData(String name, List<Weakness> weaknesses) {
        // Cache the data for this Pokemon's weaknesses
        this.weaknesses.put(name, weaknesses);
    }

    public CompletableFuture<Pokemon> getPokemonByIdAsync(int id) {
        return CompletableFuture.supplyAsync(() -> {
            // Check if the Pokemon is in the cache
            if (pokemons.containsKey(id)) {
                logger.info("Returning cached Pokemon data for ID " + id);
                return pokemons.get(id);
            } else {
                try {
                    // Get the latest data from the external API
                    Pokemon pokemon = classProvider.getPokemonById(id);
                    cachePokemonData(pokemon);
                    return pokemon;
                } catch (Exception e) {
                    logger.severe("Error fetching Pokemon data for ID " + id);
                    removeCachedPokemonData(id);
                    throw new RuntimeException("Failed to get Pokemon data");
                }
            }
        });
    }

    public CompletableFuture<List<Weakness>> getWeaknessesByNameAsync(String name) {
        return CompletableFuture.supplyAsync(() -> {
            // Check if the weaknesses are in the cache
            if (weaknesses.containsKey(name)) {
                logger.info("Returning cached weakness data for name " + name);
                return weaknesses.get(name);
            } else {
                try {
                    // Get the latest data from the external API
                    List<Weakness> weaknesses = classProvider.getWeaknessesByName(name);
                    cacheWeaknessData(name, weaknesses);
                    return weaknesses;
                } catch (Exception e) {
                    logger.severe("Error fetching weakness data for name " + name);
                    throw new RuntimeException("Failed to get weakness data");
                }
            }
        });
    }

    public CompletableFuture<EvolutionStage> getEvolutionStageByIdAsync(int id) {
        return CompletableFuture.supplyAsync(() -> {
            // Check if the evolution stage is in the cache
            if (evolutionStages.containsKey(id)) {
                logger.info("Returning cached evolution data for ID " + id);
                return evolutionStages.get(id);
            } else {
                try {
                    // Get the latest data from the external API
                    EvolutionStage stage = classProvider.getEvolutionStageById(id);
                    cacheEvolutionData(id, stage);
                    return stage;
                } catch (Exception e) {
                    logger.severe("Error fetching evolution data for ID " + id);
                    throw new RuntimeException("Failed to get evolution data");
                }
            }
        });
    }
}
