using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using Microsoft.Extensions.Logging;

public class UpdateUserProfile
{
    private readonly ILogger _logger;
    private readonly HttpClient _httpClient;
    private readonly string _configFilePath;
    private readonly List<int> _userIds;
    private readonly Dictionary<int, UserProfile> _userProfiles;

    public UpdateUserProfile(ILogger logger, HttpClient httpClient, string configFilePath, List<int> userIds)
    {
        _logger = logger;
        _httpClient = httpClient;
        _configFilePath = configFilePath;
        _userIds = userIds;
        _userProfiles = new Dictionary<int, UserProfile>();
    }

    public async Task ExecuteAsync()
    {
        // Validate configuration file and user IDs
        if (!File.Exists(_configFilePath))
        {
            _logger.LogError($"Configuration file not found: {_configFilePath}");
            return;
        }

        var config = JsonConvert.DeserializeObject<Config>(File.ReadAllText(_configFilePath));
        if (config == null)
        {
            _logger.LogError($"Invalid configuration file: {_configFilePath}");
            return;
        }

        foreach (var userId in _userIds)
        {
            // Validate user ID
            if (!userId.HasValue)
            {
                _logger.LogWarning("User ID is not specified.");
                continue;
            }

            var userProfile = new UserProfile()
            {
                Id = userId.Value,
                Email = config.Email,
                PhoneNumber = config.PhoneNumber,
                Address = config.Address,
                DateOfBirth = config.DateOfBirth,
                EmploymentStatus = config.EmploymentStatus
            };

            // Update user profile in external API
            var response = await _httpClient.PutAsync($"https://api.example.com/users/{userId}", JsonConvert.SerializeObject(userProfile));
            if (!response.IsSuccessStatusCode)
            {
                _logger.LogError($"Failed to update user profile for user ID: {userId}. Response status code: {response.StatusCode}");
                continue;
            }

            // Update local cache
            _userProfiles[userId] = userProfile;
        }
    }

    public class UserProfile
    {
        public int Id { get; set; }
        public string Email { get; set; }
        public string PhoneNumber { get; set; }
        public string Address { get; set; }
        public DateTime DateOfBirth { get; set; }
        public string EmploymentStatus { get; set; }
    }

    public class Config
    {
        public string Email { get; set; }
        public string PhoneNumber { get; set; }
        public string Address { get; set; }
        public DateTime DateOfBirth { get; set; }
        public string EmploymentStatus { get; set; }
    }
}
