import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    private static final String CONFIG_FILE = "config.txt";
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_INTERVAL = TimeUnit.SECONDS.toMillis(1);
    private static final Pattern OUTPUT_PATTERN = Pattern.compile(".*");
    private static final Pattern ERROR_PATTERN = Pattern.compile(".*");

    public static void main(String[] args) {
        List<Command> commands = new ArrayList<>();
        // Add the list of commands to execute here
        commands.add(new Command("command1", "arg1", "arg2"));
        commands.add(new Command("command2", "arg3", "arg4"));
        commands.add(new Command("command3", "arg5", "arg6"));

        // Check and delete the configuration file if it exists
        File configFile = new File(CONFIG_FILE);
        if (configFile.exists()) {
            configFile.delete();
        }

        // Execute each command sequentially, handling race conditions
        for (Command command : commands) {
            executeCommand(command);
        }
    }

    private static void executeCommand(Command command) {
        int retries = 0;
        boolean success = false;
        while (!success && retries < MAX_RETRIES) {
            try {
                Process process = Runtime.getRuntime().exec(command.toString());
                BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                String line;
                while ((line = outputReader.readLine()) != null) {
                    logMessage(line);
                }
                while ((line = errorReader.readLine()) != null) {
                    logMessage(line);
                }
                success = process.waitFor() == 0;
            } catch (IOException | InterruptedException e) {
                retries++;
                // Backoff and retry if the command failed
                try {
                    Thread.sleep(BACKOFF_INTERVAL * retries);
                } catch (InterruptedException ex) {
                    // Ignore
                }
            }
        }
        if (!success) {
            logMessage("Command " + command + " failed after " + retries + " retries");
        }
    }

    private static void logMessage(String message) {
        Matcher outputMatcher = OUTPUT_PATTERN.matcher(message);
        if (outputMatcher.matches()) {
            System.out.println("Output: " + message);
        } else {
            Matcher errorMatcher = ERROR_PATTERN.matcher(message);
            if (errorMatcher.matches()) {
                System.err.println("Error: " + message);
            } else {
                // Log the message to an error log if it doesn't match either pattern
                logToErrorLog(message);
            }
        }
    }

    private static void logToErrorLog(String message) {
        // Implement a mechanism to write the message to an error log here
        System.err.println("Error: " + message);
    }
}

class Command {
    private String command;
    private List<String> args = new ArrayList<>();

    public Command(String command, String... args) {
        this.command = command;
        for (String arg : args) {
            this.args.add(arg);
        }
    }

    @Override
    public String toString() {
        return command + " " + String.join(" ", args);
    }
}
