            metrics->total_amount += transaction->amount * weight;
            if (metrics->max_weighted_sum < metrics->total_amount) {
                metrics->max_weighted_sum = metrics->total_amount;
            }
        }
    }

    // Find the category with the highest maximum weighted sum and return its ID, transaction ID, and timestamp
    int max_category_id = -1;
    double max_weighted_sum = 0.0;
    for (int i = 0; i < num_categories; i++) {
        Metrics* metrics = &metrics[i];
        if (max_weighted_sum < metrics->max_weighted_sum) {
            max_category_id = i;
            max_weighted_sum = metrics->max_weighted_sum;
        }
    }

    // Return the category with the highest maximum weighted sum, or a default struct if no valid transactions are found
    if (max_category_id == -1) {
        return NULL;
    } else {
        Transaction* transaction = &transactions[find_transaction(max_category_id)];
        return (struct metrics*)malloc(sizeof(Metrics));
    }
}

