public static class CryptographyHelper
{
    private static readonly Dictionary<string, CipherMode> cipherModes = new Dictionary<string, CipherMode>();
    private static readonly Dictionary<string, ICryptoTransform> transforms = new Dictionary<string, ICryptoTransform>();

    public static void Initialize(string[] availableCiphers, string[] availableModes)
    {
        // Initialize the cipher modes and transforms for each available cipher and mode
        foreach (string cipher in availableCiphers)
        {
            foreach (string mode in availableModes)
            {
                CipherMode cipherMode = GetCipherMode(mode);
                ICryptoTransform transform = CreateCryptoTransform(cipher, cipherMode);
                transforms[$"{cipher}-{mode}"] = transform;
            }
        }
    }

    public static CipherMode GetCipherMode(string mode)
    {
        // Get the corresponding cipher mode for the specified mode
        switch (mode.ToUpper())
        {
            case "ECB":
                return CipherMode.ECB;
            case "CBC":
                return CipherMode.CBC;
            case "CFB":
                return CipherMode.CFB;
            default:
                throw new ArgumentException("Invalid cipher mode", nameof(mode));
        }
    }

    public static ICryptoTransform CreateCryptoTransform(string cipher, CipherMode mode)
    {
        // Create a new instance of the specified cryptographic transform for encryption or decryption
        switch (cipher.ToUpper())
        {
            case "DES-ECB":
                return DES.Create().CreateEncryptor(new byte[8], new byte[8]);
            case "DES-CBC":
                return DES.Create().CreateEncryptor(new byte[8], new byte[8]);
            case "DES-CFB":
                return DES.Create().CreateEncryptor(new byte[8], new byte[8]);
            default:
                throw new ArgumentException("Invalid cipher", nameof(cipher));
        }
    }
}
```

