using System;
using System.IO;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Microsoft.Extensions.Logging;

namespace LargeFileService
{
    public class LargeFileService : IDisposable
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<LargeFileService> _logger;
        private readonly string _apiUrl;

        public LargeFileService(HttpClient httpClient, ILogger<LargeFileService> logger)
        {
            _httpClient = httpClient;
            _logger = logger;
            _apiUrl = "https://example.com/api/v1";
        }

        public async Task<ValidationResult> ValidateAsync(string filePath)
        {
            var result = new ValidationResult();
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    // Lazy loading: only load the first 100 bytes of the file to determine its size.
                    if (fileStream.Length > 100)
                    {
                        var buffer = new byte[100];
                        await fileStream.ReadAsync(buffer, 0, 100);
                        result.FileSize = BitConverter.ToInt64(buffer, 0);
                    }
                }

                if (result.FileSize > 10 * 1024 * 1024) // 10MB limit
                {
                    throw new Exception("File size exceeds the maximum allowed.");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to validate file.");
                result.Errors = new[] { "File validation failed." };
            }

            return result;
        }

        public async Task<bool> DeserializeAsync(string filePath, out object data)
        {
            var success = false;
            data = null;

            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    // Chunk processing: read the file in chunks to avoid overloading memory with large files.
                    var bufferSize = 4096;
                    var buffer = new byte[bufferSize];
                    int bytesRead;
                    while ((bytesRead = await fileStream.ReadAsync(buffer, 0, bufferSize)) > 0)
                    {
                        // Caching: store the binary formatter in a static field to avoid re-initializing it for each chunk.
                        var formatter = new BinaryFormatter();
                        using (var stream = new MemoryStream())
                        {
                            stream.Write(buffer, 0, bytesRead);
                            data = formatter.Deserialize(stream);
                        }
                    }
                }
                success = true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to deserialize file.");
            }

            return success;
        }

        public async Task<bool> ValidateAsync(object data, out string[] errors)
        {
            var success = false;
            errors = Array.Empty<string>();

            try
            {
                using (var stream = new MemoryStream())
                {
                    // Caching: store the JSON formatter in a static field to avoid re-initializing it for each chunk.
                    var formatter = new JsonSerializer();
                    formatter.Serialize(stream, data);
                    stream.Position = 0;

                    using (var reader = new StreamReader(stream))
                    {
                        // Fetch the latest schema definition from the external API.
                        var response = await _httpClient.GetAsync(_apiUrl + "/schema");
                        if (!response.IsSuccessStatusCode)
                        {
                            throw new Exception("Failed to retrieve schema definition.");
                        }

                        // Deserialize the JSON response and validate the data against it.
                        var schema = JObject.Parse(await response.Content.ReadAsStringAsync());
                        errors = formatter.Deserialize<JObject>(reader).Validate(schema);
                    }
                }
                success = true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to validate data.");
            }

            return success;
        }

        public void Dispose()
        {
            _httpClient.Dispose();
        }
    }
}
