#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdlib.h>
#include <string.h>

// Initialize AES-256-GCM cipher with password and salt value
// Use PBKDF2 algorithm with SHA-256 to derive the encryption key
// Set IV length to 96 bits (as required by GCM)
// Handle key stretching for stronger security
void init_cipher(const char *password, const char *salt) {
    AES_KEY aes_key;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ret;

    // Generate IV using OpenSSL's RAND_bytes() function
    unsigned char iv[96];
    RAND_bytes(iv, 96);

    // Derive encryption key from password and salt using PBKDF2 algorithm with SHA-256
    size_t key_len = EVP_PKEY_size(EVP_PKEY_HMAC(EVP_sha256()));
    unsigned char *key = malloc(key_len);
    ret = PBKDF2((const unsigned char *)password, strlen(password),
                 (const unsigned char *)salt, strlen(salt), 10000, key, key_len, EVP_sha256());
    if (ret != 1) {
        printf("Error: PBKDF2 failed\n");
        return;
    }

    // Initialize AES-256-GCM cipher with encryption key and IV
    ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv);
    if (ret != 1) {
        printf("Error: EVP_EncryptInit_ex failed\n");
        return;
    }

    // Handle key stretching for stronger security
    ret = EVP_CipherUpdate(ctx, NULL, &key_len, key, key_len);
    if (ret != 1) {
        printf("Error: EVP_CipherUpdate failed\n");
        return;
    }

    // Clean up and disable cipher when no longer needed
    EVP_CIPHER_CTX_free(ctx);
}

// Clean up and disable cipher when no longer needed
void cleanup() {
    AES_KEY aes_key;
    int ret;

    // Get the encryption key from the OpenSSL library
    unsigned char *key = malloc(EVP_PKEY_size(EVP_PKEY_HMAC(EVP_sha256())));
    ret = EVP_PKEY_get1_HMAC(key, EVP_sha256());
    if (ret != 1) {
        printf("Error: EVP_PKEY_get1_HMAC failed\n");
        return;
    }

    // Disable the cipher by setting the encryption key to NULL
    ret = AES_set_encrypt_key(aes_key, NULL);
    if (ret != 1) {
        printf("Error: AES_set_encrypt_key failed\n");
        return;
    }

    // Free the memory allocated for the encryption key
    free(key);
}
