```scss
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import com.stripe.Stripe;
import com.stripe.model.InventoryItem;
import com.stripe.net.RequestOptions;

public class InventoryManager {
    private static final Map<String, Integer> inventoryMap = new ConcurrentHashMap<>();
    private static final Stripe stripe = new Stripe(
        "YOUR_STRIPE_SECRET_KEY",
        RequestOptions.builder().setConnectTimeout(10 * 1000).setReadTimeout(20 * 1000).build()
    );

    public static void updateInventory(String productId, int quantity) {
        if (inventoryMap.containsKey(productId)) {
            int currentQuantity = inventoryMap.get(productId);
            currentQuantity += quantity;
            inventoryMap.put(productId, currentQuantity);
        } else {
            inventoryMap.put(productId, quantity);
        }
    }

    public static int getInventoryLevel(String productId) {
        return inventoryMap.getOrDefault(productId, 0);
    }

    public static void processTransaction(String productId, int quantity) throws Exception {
        InventoryItem item = new InventoryItem()
            .setProductId(productId)
            .setQuantity(quantity);
        stripe.createInventoryItem(item).execute();
    }

    public static void clearCache() {
        inventoryMap.clear();
    }
}
