#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <zip.h>

#define RESOURCE_BUNDLE_MAX_SIZE 1024 // maximum size of the resource bundle
#define CONCURRENT_OPERATIONS_MAX 32 // maximum number of concurrent operations

typedef struct ResourceItem {
    char *name;
    char *data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem *items;
    int num_items;
} ResourceBundle;

// Load a resource bundle from a compressed file and return the number of items in the bundle.
int loadResourceBundle(const char *filename) {
    // Open the zip archive for reading.
    zip *archive = zip_open(filename, 0, 'r');
    if (!archive) {
        printf("Failed to open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    // Create a new resource bundle and initialize it.
    ResourceBundle *bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    if (!bundle) {
        printf("Failed to allocate memory for resource bundle: %s\n", strerror(errno));
        return -1;
    }
    bundle->items = (ResourceItem *)malloc(RESOURCE_BUNDLE_MAX_SIZE * sizeof(ResourceItem));
    if (!bundle->items) {
        printf("Failed to allocate memory for resource items: %s\n", strerror(errno));
        return -1;
    }
    bundle->num_items = 0;

    // Iterate over the files in the zip archive and extract each file.
    zip_int64_t num_files = zip_get_num_files(archive);
    for (zip_int64_t i = 0; i < num_files; ++i) {
        const char *filename = zip_get_name(archive, i, 0);
        if (!filename) {
            printf("Failed to get filename: %s\n", strerror(errno));
            return -1;
        }

        // Extract the file and store it in the resource bundle.
        zip_file *file = zip_fopen(archive, filename, 0);
        if (!file) {
            printf("Failed to open %s: %s\n", filename, strerror(errno));
            return -1;
        }
        size_t file_size = zip_get_file_size(file, 0);
        if (file_size > RESOURCE_BUNDLE_MAX_SIZE) {
            printf("File size exceeds maximum allowed: %lu\n", RESOURCE_BUNDLE_MAX_SIZE);
            return -1;
        }
        char *data = (char *)malloc(file_size + 1);
        if (!data) {
            printf("Failed to allocate memory for file data: %s\n", strerror(errno));
            return -1;
        }
        size_t read_size = zip_fread(file, data, file_size);
        if (read_size != file_size) {
            printf("Failed to read entire file: %s\n", strerror(errno));
            return -1;
        }
        data[file_size] = '\0'; // null-terminate the data
        ResourceItem item = { .name = filename, .data = data };
        bundle->items[bundle->num_items++] = item;
    }

    // Close the zip archive and return the number of items in the bundle.
    int result = zip_close(archive);
    if (result != 0) {
        printf("Failed to close %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return bundle->num_items;
}
