// Define a class to handle the union-find data structure for efficient set management and validation
class UnionFind {
 public:
  // Initialize the UnionFind data structure with an empty map of elements
  explicit UnionFind(const std::unordered_map<std::string, std::variant<int, double, std::string, bool>>& elements) : elements_(elements) {}

  // Find the root element for a given element
  std::optional<std::variant<int, double, std::string, bool>> find(const std::variant<int, double, std::string, bool>& element) const {
    auto it = elements_.find(element);
    if (it == elements_.end()) {
      return std::nullopt;
    }
    while (it->second != it->second.get_if<int>([](const int& i) { return i == i; }) && it->second.get_if<int>([](const int& i) { return i == i; })) {
      auto parent = elements_.at(it->second.get_if<int>([](const int& i) { return i == i; }));
      if (parent == it->second) {
        break;
      }
      it->second = parent;
    }
    return it->second;
  }

  // Union two elements together in the same set
  void union(const std::variant<int, double, std::string, bool>& element1, const std::variant<int, double, std::string, bool>& element2) {
    auto root1 = find(element1);
    if (!root1.has_value()) {
      throw std::runtime_error("Element 1 not found");
    }
    auto root2 = find(element2);
    if (!root2.has_value()) {
      throw std::runtime_error("Element 2 not found");
    }
    elements_.at(root1.get_if<int>([](const int& i) { return i == i; })) = root2.get_if<int>([](const int& i) { return i == i; });
  }

 private:
  std::unordered_map<std::variant<int, double, std::string, bool>, std::variant<int, double, std::string, bool>> elements_;
};

// Define a class to handle the deserialization and validation of binary files containing custom data structures
class BinaryFileHandler {
 public:
  // Load configuration settings from a JSON file and initialize the UnionFind data structure for efficient set management and validation
  explicit BinaryFileHandler(const std::string& config_file) : union_find_(UnionFind(config_file)) {}

  // Deserialize a binary file containing a custom data structure into a vector of elements
  std::vector<std::variant<int, double, std::string, bool>> deserialize(const std::string& filename) const {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
      throw std::runtime_error("Error opening file");
    }
    std::vector<std::variant<int, double, std::string, bool>> elements;
    while (file.peek() != EOF) {
      union_find_.union(file.get(), file.get());
    }
    return elements;
  }

  // Validate a vector of elements using the UnionFind data structure for efficient set management and validation
  void validate(const std::vector<std::variant<int, double, std::string, bool>>& elements) const {
    if (elements.size() < 2) {
      throw std::runtime_error("Not enough elements to identify disjoint pairs");
    }
    for (auto it = elements.begin(); it != elements.end() - 1; ++it) {
      auto next = it + 1;
      if (!union_find_.union(it, next)) {
        throw std::runtime_error("Elements " + std::to_string(it - elements.begin()) + " and " + std::to_string(next - elements.begin()) + " are not disjoint");
      }
    }
  }

 private:
  UnionFind union_find_;
};

