    private string _latitude;
    private string _longitude;
    private WeatherServiceClient _weatherServiceClient;

    public DynamicWeatherUpdaterMiddleware()
    {
        _weatherServiceClient = new WeatherServiceClient();
    }

    public void UpdateWeather(string elementId, string latitude, string longitude)
    {
        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID cannot be null or empty", nameof(elementId));

        if (string.IsNullOrEmpty(latitude))
            throw new ArgumentException("Latitude cannot be null or empty", nameof(latitude));

        if (string.IsNullOrEmpty(longitude))
            throw new ArgumentException("Longitude cannot be null or empty", nameof(longitude));

        _latitude = latitude;
        _longitude = longitude;

        var weatherConditions = _weatherServiceClient.GetWeatherConditions(_latitude, _longitude);
        UpdateElement(elementId, weatherConditions);
    }

    private void UpdateElement(string elementId, WeatherConditions weatherConditions)
    {
        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentException("Element ID cannot be null or empty", nameof(elementId));

        var htmlElement = Page.FindControl(elementId);

        if (htmlElement == null)
            throw new InvalidOperationException($"Element with ID '{elementId}' not found");

        htmlElement.InnerHtml = $@"<div class='weather-conditions'>
                                    <span>Temperature: {weatherConditions.Temperature}</span>
                                    <span>Humidity: {weatherConditions.Humidity}%</span>
                                    <span>Wind Speed: {weatherConditions.WindSpeed} m/s</span>
                                    <span>Precipitation Level: {weatherConditions.PrecipitationLevel}%</span>
                                </div>";
    }

    public override void Dispose()
    {
        _weatherServiceClient.Dispose();
    }
}
