    private String directoryPath;
    private List<String> keywords;
    private Charset encoding;
    private String outputFormat;
    private boolean compressReport;
    private int logLevel;
    private FileLogger logger;

    public LargeTextFileReader(String directoryPath, List<String> keywords, Charset encoding, String outputFormat, boolean compressReport, int logLevel) {
        this.directoryPath = directoryPath;
        this.keywords = keywords;
        this.encoding = encoding;
        this.outputFormat = outputFormat;
        this.compressReport = compressReport;
        this.logLevel = logLevel;
        logger = new FileLogger(logLevel);
    }

    public void readFiles() {
        List<File> files = getFiles();
        for (File file : files) {
            try {
                readFile(file);
            } catch (IOException e) {
                logger.logError("Failed to read file " + file.getName(), e);
            }
        }
    }

    private List<File> getFiles() {
        File directory = new File(directoryPath);
        if (!directory.exists()) {
            throw new IllegalArgumentException("Directory does not exist: " + directoryPath);
        }
        if (!directory.isDirectory()) {
            throw new IllegalArgumentException("File is not a directory: " + directoryPath);
        }
        List<File> files = new ArrayList<>();
        for (File file : directory.listFiles()) {
            if (file.getName().endsWith(".txt")) {
                files.add(file);
            }
        }
        return files;
    }

    private void readFile(File file) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(file, encoding))) {
            String line;
            while ((line = reader.readLine()) != null) {
                for (String keyword : keywords) {
                    if (line.contains(keyword)) {
                        logger.logInfo("Found keyword " + keyword + " in file " + file.getName());
                        break;
                    }
                }
            }
        } catch (IOException e) {
            logger.logError("Failed to read file " + file.getName(), e);
        }
    }

    private String generateReport() {
        // Generate report based on output format and compress if necessary
        return null;
    }

    public void uploadReport() {
        try {
            String report = generateReport();
            if (compressReport) {
                report = compress(report);
            }
            int retries = 0;
            while (retries < RETRY_COUNT) {
                try {
                    uploadReportToApi(report);
                    break;
                } catch (IOException e) {
                    logger.logError("Failed to upload report to API", e);
                }
                retries++;
            }
        } catch (Exception e) {
            logger.logError("Failed to generate and upload report", e);
        }
    }

    private void uploadReportToApi(String report) throws IOException {
        // Implement API integration here
    }

    private String compress(String text) {
        byte[] bytes = text.getBytes();
        ByteArrayOutputStream bos = new ByteArrayOutputStream(bytes.length);
        GZIPOutputStream gos = new GZIPOutputStream(bos);
        gos.write(bytes);
        gos.close();
        return bos.toString();
    }
}

class FileLogger {
    private int logLevel;

    public FileLogger(int logLevel) {
        this.logLevel = logLevel;
    }

    public void logInfo(String message) {
        if (logLevel >= 1) {
            System.out.println("INFO: " + message);
        }
    }

    public void logError(String message, Exception e) {
        if (logLevel >= 4) {
            System.err.println("ERROR: " + message);
            e.printStackTrace();
        }
    }
}
