void encryptMessage(const std::string& plaintext, const Config& config) {
  // Load the required encryption algorithms from OpenSSL
  EVP_add_algorithms();

  // Initialize the KMS integration if enabled in the configuration
  if (config.enableKMSIntegration) {
    KMS_init(config.kmsEndpoint, config.kmsPort);
