  EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(config.encryptionAlgorithm.c_str()), NULL, NULL, NULL);
  std::vector<uint8_t> ciphertext;
  int len;
  while ((len = EVP_EncryptUpdate(ctx, ciphertext.data(), ciphertext.size(), plaintext.data(), plaintext.size())) > 0) {
    ciphertext.resize(ciphertext.size() + len);
  }
  EVP_EncryptFinal_ex(ctx, ciphertext.data(), &len);
  EVP_CIPHER_CTX_free(ctx);

