  EVP_DecryptInit_ex(ctx, EVP_get_cipherbyname(config.encryptionAlgorithm.c_str()), NULL, NULL, NULL);
  std::vector<uint8_t> plaintext;
  int len;
  while ((len = EVP_DecryptUpdate(ctx, plaintext.data(), plaintext.size(), ciphertext.data(), ciphertext.size())) > 0) {
    plaintext.resize(plaintext.size() + len);
  }
  EVP_DecryptFinal_ex(ctx, plaintext.data(), &len);
  EVP_CIPHER_CTX_free(ctx);

  // Log the decryption event to the specified file
  std::ofstream logFile;
  logFile.open("decryption_log.txt", std::ios_base::app);
