    if (json->access_token == NULL || json->expires_in <= 0 || json->token_type == NULL || json->scope == NULL) {
        valid = false;
        printf("Missing required field in OAuth2 access token response\n");
    }

    // Validate the expiration time
    if (json->expires_in > 3600) {
        valid = false;
        printf("Expiration time in OAuth2 access token response is greater than 1 hour\n");
    }

    // Check for invalid token type
    if (strcmp(json->token_type, "Bearer") != 0) {
        valid = false;
        printf("Invalid token type in OAuth2 access token response\n");
    }

    // Validate the refresh token
    if (json->refresh_token != NULL && !validate_refresh_token(json->refresh_token)) {
        valid = false;
        printf("Invalid refresh token in OAuth2 access token response\n");
    }

    // Check for invalid scope
    if (!validate_scope(json->scope)) {
        valid = false;
        printf("Invalid scope in OAuth2 access token response\n");
