```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/gcm.h>
#include <openssl/err.h>

typedef enum {
    AES_128,
    AES_256,
    CHACHA20,
    GCM,
} CipherMode;

void encrypt(CipherMode mode, unsigned char *key, unsigned char *iv, size_t len) {
    switch (mode) {
        case AES_128:
            AES_encrypt(key, iv, len);
            break;
        case AES_256:
            AES_encrypt(key, iv, len);
            break;
        case CHACHA20:
            ChaCha20_encrypt(key, iv, len);
            break;
        case GCM:
            GCM_encrypt(key, iv, len);
            break;
    }
}

void decrypt(CipherMode mode, unsigned char *key, unsigned char *iv, size_t len) {
    switch (mode) {
        case AES_128:
            AES_decrypt(key, iv, len);
            break;
        case AES_256:
            AES_decrypt(key, iv, len);
            break;
        case CHACHA20:
            ChaCha20_decrypt(key, iv, len);
            break;
        case GCM:
            GCM_decrypt(key, iv, len);
            break;
    }
}

int main() {
    unsigned char key[16];
    unsigned char iv[16];
    size_t len = 16;
    CipherMode mode = AES_128;

    encrypt(mode, key, iv, len);
    decrypt(mode, key, iv, len);

    return 0;
}
```
