const encryptionIv = crypto.generateRandomBytes(16);

// Function to encrypt incoming data packets
const encryptDataPacket = (data) => {
  const cipher = crypto.createCipheriv('aes-256-cbc', encryptionKey, encryptionIv);
  return cipher.update(data).toString();
};

// Function to decrypt incoming data packets
const decryptDataPacket = (data) => {
  const decipher = crypto.createDecipheriv('aes-256-cbc', encryptionKey, encryptionIv);
  return decipher.update(data).toString();
};

// Function to handle incoming data packets
const handleDataPacket = (data) => {
  // Decrypt the data packet
  const decryptedData = decryptDataPacket(data);

  // Process the decrypted data
  console.log(`Received encrypted data: ${decryptedData}`);
};

