// Union-Find data structure for efficient identification of disjoint pairs within the array
struct UnionFind {
  std::vector<int> parents;
  std::vector<int> sizes;

  // constructor initializes an empty Union-Find data structure with N elements
  UnionFind(size_t N) : parents(N), sizes(N, 1) {}

  // function to find the root element of a given element
  int FindRoot(int x) {
    while (parents[x] != x) {
      x = parents[x];
    }
    return x;
  }

  // function to merge two elements into the same set
  void Union(int x, int y) {
    int rootX = FindRoot(x);
    int rootY = FindRoot(y);
    if (rootX == rootY) {
      return;
    }
    sizes[rootX] += sizes[rootY];
    parents[rootY] = rootX;
  }
};

