Here is an example of how this microservice could be integrated with an external KMS for key retrieval and a distributed caching layer to optimize performance:
```java
import com.google.cloud.kms.v1.CryptoKeyName;
import com.google.cloud.kms.v1.GetPublicKeyRequest;
import com.google.cloud.kms.v1.GetPublicKeyResponse;
import com.google.cloud.kms.v1.ImportCryptoKeyVersionRequest;
import com.google.cloud.kms.v1.CryptoKeyVersionName;
import com.google.protobuf.ByteString;
import com.google.protobuf.ListValue;
import com.google.protobuf.Value;
import java.util.Map;
import java.util.HashMap;
import java.util.logging.Logger;

public class KMSService {
  private static final Logger logger = Logger.getLogger(KMSService.class.getName());
  private String kmsKeyName;
  private int cacheRefreshInterval;
  private Map<String, String> cachedKeys;

  public KMSService(String kmsKeyName, int cacheRefreshInterval) {
    this.kmsKeyName = kmsKeyName;
    this.cacheRefreshInterval = cacheRefreshInterval;
    this.cachedKeys = new HashMap<>();
  }

  public String getPublicKey() throws Exception {
    // Retrieve the public key from the KMS and cache it locally for the refresh interval
    GetPublicKeyRequest request = GetPublicKeyRequest.newBuilder().setName(CryptoKeyName.of(kmsKeyName)).build();
    GetPublicKeyResponse response = kmsServiceClient.getPublicKey(request);
    cachedKeys.put(kmsKeyName, response.getPem());
    logger.info("Retrieved public key: " + response.getPem());
  }

  public String importCryptoKeyVersion(String cryptoKeyVersion) throws Exception {
    // Import the provided crypto key version into the KMS and cache it locally for the refresh interval
    CryptoKeyName cryptoKeyName = CryptoKeyName.of(kmsKeyName);
    ImportCryptoKeyVersionRequest request = ImportCryptoKeyVersionRequest.newBuilder()
            .setParent(cryptoKeyName.toString())
            .setAlgorithm("RSA_OAEP_2048_SHA512")
            .setWrappedKeyMaterial(ByteString.copyFromUtf8(cryptoKeyVersion))
            .build();
    kmsServiceClient.importCryptoKeyVersion(request);
    cachedKeys.put(kmsKeyName, cryptoKeyVersion);
    logger.info("Imported new crypto key version: " + cryptoKeyVersion);
  }

  public void refreshCache() {
    // Refresh the cache of KMS keys and update the current token
    Map<String, String> updatedKeys = new HashMap<>();
    for (Map.Entry<String, String> entry : cachedKeys.entrySet()) {
      CryptoKeyName cryptoKeyName = CryptoKeyName.of(kmsKeyName);
      ImportCryptoKeyVersionRequest request = ImportCryptoKeyVersionRequest.newBuilder()
              .setParent(cryptoKeyName.toString())
              .setAlgorithm("RSA_OAEP_2048_SHA512")
              .setWrappedKeyMaterial(ByteString.copyFromUtf8(entry.getValue()))
              .build();
      kmsServiceClient.importCryptoKeyVersion(request);
      updatedKeys.put(kmsKeyName, entry.getValue());
    }
    this.cachedKeys = updatedKeys;
    logger.info("Refreshed cache of KMS keys.");
  }
}
```
