Microservice for JSON Web Token (JWT) Generation and Validation:
```java
import java.security.PrivateKey;
import javax.crypto.spec.SecretKeySpec;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.common.serialization.StringSerializer;
import org.json.JSONObject;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class JWTService {
    private static final Map<String, PrivateKey> keyCache = new ConcurrentHashMap<>(); // Cache for KMS keys
    private static final int TOKEN_EXPIRY_SECONDS = 3600; // Expiry time for JWT tokens (1 hour)
    private static final String KEY_ALGORITHM = "RSA"; // Algorithm used to generate keys
    private static final String SIGNING_ALGORITHM = "SHA256withRSA"; // Signing algorithm for JWTs

    public static JSONObject generateJWT(String kid) throws Exception {
        PrivateKey key = getKey(kid); // Get the KMS key for the specified ID
        String token = Base64.getEncoder().encodeToString(generateToken(key)); // Generate JWT using the key
        return new JSONObject().put("token", token).put("expires_at", System.currentTimeMillis() + TOKEN_EXPIRY_SECONDS * 1000);
    }

    public static boolean validateJWT(String jwt) throws Exception {
        String[] parts = jwt.split("\\."); // Split the JWT into its three parts
        if (parts.length != 3) {
            throw new IllegalArgumentException("Invalid JWT");
        }
        byte[] headerBytes = Base64.getUrlDecoder().decode(parts[0]);
        JSONObject header = new JSONObject(new String(headerBytes, "UTF-8"));
        String kid = header.getString("kid"); // Get the ID of the KMS key used to generate the JWT
        PrivateKey key = getKey(kid); // Get the corresponding private key from the cache
        if (key == null) {
            return false;
        }
        byte[] signatureBytes = Base64.getUrlDecoder().decode(parts[2]);
        String signedData = parts[0] + "." + parts[1];
        Signature sig = Signature.getInstance(SIGNING_ALGORITHM);
        sig.initVerify(key);
        sig.update(signedData.getBytes("UTF-8"));
        return sig.verify(signatureBytes);
    }

    private static PrivateKey getKey(String kid) throws Exception {
        if (kid == null || keyCache.containsKey(kid)) {
            return keyCache.get(kid); // Return the cached key if it exists
        }
        SecretKeySpec secretKey = new SecretKeySpec(kid.getBytes("UTF-8"), KEY_ALGORITHM);
        PrivateKey key = (PrivateKey) secretKey; // Cast to PrivateKey
        keyCache.put(kid, key); // Cache the key for future use
        return key;
    }

    private static byte[] generateToken(PrivateKey key) throws Exception {
        JSONObject header = new JSONObject();
        header.put("typ", "JWT");
        header.put("alg", SIGNING_ALGORITHM);
        header.put("kid", key.getKid()); // Get the ID of the KMS key used to generate the token
        String headerStr = new JSONObject().put("header", header).toString();
        String payloadStr = new JSONObject().put("expires_at", System.currentTimeMillis() + TOKEN_EXPIRY_SECONDS * 1000).toString();
        return generateSignedToken(key, headerStr, payloadStr);
    }

    private static byte[] generateSignedToken(PrivateKey key, String headerStr, String payloadStr) throws Exception {
        Signature sig = Signature.getInstance(SIGNING_ALGORITHM);
        sig.initSign(key); // Initialize the signature with the private key
        sig.update(headerStr.getBytes("UTF-8"));
        sig.update(payloadStr.getBytes("UTF-8"));
        return sig.sign();
    }
}
```
