// Function for dynamically generating a state list for a given finite state automaton (FSA) and integrating it with an existing state machine system
void generateStateList(int* states, int numStates, FSA* fsa, int lastState) {
    // Check for invalid input parameters
    if (states == NULL || numStates < 0 || fsa == NULL || lastState < 0 || lastState >= numStates) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Dynamically allocate memory for the new state list
    int* newStateList = malloc(sizeof(int) * (numStates + 1));
    if (newStateList == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Copy the existing states to the new state list
    memcpy(newStateList, states, sizeof(int) * numStates);

    // Generate new states for the FSA
    int i = 0;
    while (i < fsa->numStates) {
        if (fsa->states[i] == lastState) {
            newStateList[numStates++] = generateNewState(fsa, i);
        }
        ++i;
    }

    // Update the 'next' pointer of the last state in the original list to point to the newly generated state list
    states[lastState].next = newStateList;

    free(newStateList);
}

