import asyncio
from aiohttp import ClientSession
from typing import Type, Optional

class StorageServiceClient:
    def __init__(self):
        self.session = None
        self.concurrency_semaphore = asyncio.Semaphore(10)

    async def connect(self) -> bool:
        if not self.session:
            try:
                # Create a new ClientSession object and store it in the session attribute
                self.session = ClientSession()
                return True
            except Exception as e:
                print(f'Error occurred while connecting to storage service: {e}')
                return False
        else:
            return True

    async def disconnect(self):
        if self.session:
            # Close the ClientSession object and set it to None
            await self.session.close()
            self.session = None

    async def validate_file_format(self, file_path: str, metadata: Metadata) -> bool:
        try:
            # Make a GET request to the storage service to retrieve the file schema definition
            response = await self.session.get(f'{self.base_url}/files/{file_path}')
            if not response.ok:
                raise Exception('Failed to retrieve file schema definition')

            # Extract the file schema definition from the response
            schema = response.json()

            # Validate the metadata against the file schema definition
            for key in metadata:
                if key not in schema:
                    return False

            return True
        except Exception as e:
            print(f'Error occurred while validating file format: {e}')
            return False
