#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_FILES 100
#define MAX_CONCURRENT_CONVERSIONS 5

struct file_info {
    char *file_name;
    char *output_dir;
};

struct conversion_status {
    int status;
    char *error_message;
};

int convert_files(struct file_info files[], int num_files, char *output_dir) {
    // Initialize variables
    int i, j;
    pid_t pid;
    int status;
    struct conversion_status *statuses = (struct conversion_status *)malloc(sizeof(struct conversion_status) * num_files);
    memset(statuses, 0, sizeof(struct conversion_status) * num_files);

    // Fetch metadata for each file from the simulated external REST API
    for (i = 0; i < num_files; i++) {
        status = fetch_metadata(files[i].file_name, &statuses[i]);
        if (status != 0) {
            // Handle error condition
            return -1;
        }
    }

    // Create output directories for each file
    for (i = 0; i < num_files; i++) {
        status = create_output_directory(files[i].output_dir);
        if (status != 0) {
            // Handle error condition
            return -1;
        }
    }

    // Initialize conversion queue and start conversions in parallel
    int queue[MAX_CONCURRENT_CONVERSIONS];
    for (i = 0; i < num_files; i++) {
        if (queue[i] != NULL) {
            continue;
        }
        pid = fork();
        if (pid == 0) {
            // Child process
            status = convert_file(files[i].file_name, files[i].output_dir);
            return status;
        } else if (pid > 0) {
            // Parent process
            queue[i] = pid;
        } else {
            // Error handling
            perror("fork");
            return -1;
        }
    }

    // Wait for all child processes to complete and collect statuses
    for (i = 0; i < num_files; i++) {
        if (queue[i] == NULL) {
            continue;
        }
        waitpid(queue[i], &status, 0);
        if (WIFEXITED(status)) {
            // Handle exit status
        } else if (WIFSIGNALED(status)) {
            // Handle signal
        } else {
            // Handle unknown error condition
        }
    }

    // Clean up and return status
    free(queue);
    return 0;
}

int fetch_metadata(char *file_name, struct conversion_status *status) {
    // Simulated external REST API call
    char url[256];
    snprintf(url, sizeof(url), "http://api.example.com/files/%s", file_name);
    int status_code = 0;
    struct conversion_status *metadata = (struct conversion_status *)malloc(sizeof(struct conversion_status));
    metadata->status = status_code;
    metadata->error_message = NULL;
    if (status_code != 200) {
        // Handle error condition
        return -1;
    }
    free(metadata);
    return 0;
}

int create_output_directory(char *output_dir) {
    // Create output directory
    int status = mkdir(output_dir, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
    if (status != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

int convert_file(char *file_name, char *output_dir) {
    // Convert file to PDF using an external tool
    int status = system("/path/to/tool --input-file=file_name --output-directory=output_dir");
    if (status != 0) {
        perror("system");
        return -1;
    }
    return 0;
}
