def process_log(file_path):
    # Open the log file and read its contents
    with open(file_path, "r") as f:
        data = json.load(f)

    # Aggregate the sensor data
    aggregated_data = {}
    for reading in data["readings"]:
        if reading["sensor"] not in aggregated_data:
            aggregated_data[reading["sensor"]] = {
                "mean": 0.0,
                "stddev": 0.0,
                "count": 0
            }

        aggregated_data[reading["sensor"]]["mean"] += reading["value"]
        aggregated_data[reading["sensor"]]["stddev"] += (reading["value"] - aggregated_data[reading["sensor"]]["mean"]) ** 2
        aggregated_data[reading["sensor"]]["count"] += 1

    # Filter out anomalies based on statistical models
    for sensor in aggregated_data:
        mean = aggregated_data[sensor]["mean"] / aggregated_data[sensor]["count"]
        stddev = aggregated_data[sensor]["stddev"] / aggregated_data[sensor]["count"]
        if abs(aggregated_data[sensor]["value"] - mean) > 2 * stddev:
            del cleaned_data[reading["sensor"]]

    # Store the cleaned sensor data in a distributed database system
    for reading in cleaned_data:
        db.save(reading)

# Create a pool of processes to process log files concurrently
