function integrateWeatherAPI(cities) {
  // Define a cache object to store weather data
  const cache = {};

  // Initialize an array to store the updated UI values
  const uiValues = [];

  // Define a function to fetch weather data for a single city
  async function fetchWeather(city) {
    try {
      const response = await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=YOUR_API_KEY`);
      const data = await response.json();

      // Check if the API call was successful
      if (data.cod === 200) {
        // Add the weather data to the cache object
        cache[city] = data;

        // Update the UI with the new data
        const uiValue = `${city}: ${data.main.temp}°C, ${data.weather[0].description}`;
        uiValues.push(uiValue);
      } else {
        console.log(`Error fetching weather data for ${city}. Code: ${data.cod}, Message: ${data.message}`);
      }
    } catch (error) {
      console.log(`An error occurred while fetching weather data for ${city}: ${error}`);
    }
  }

  // Fetch the weather data for each city in parallel using async/await syntax
  const promises = cities.map(fetchWeather);
  await Promise.all(promises);

  return uiValues;
}
