#include <boost/asio.hpp>
#include <iostream>
#include <string>
#include <vector>

using namespace boost::asio;
using namespace std;

class TCPClient {
public:
    TCPClient(io_context& io_context, const string& hostname, const string& port)
        : socket_(io_context), resolver_(io_context), hostname_(hostname), port_(port) {}

    void connect() {
        error_code ec;
        auto endpoint = *resolver_.resolve(hostname_, port_);
        socket_.connect(endpoint, ec);
        if (ec) {
            cout << "Error connecting to the server: " << ec.message() << endl;
            return;
        }
    }

    void sendRequest(const string& request) {
        error_code ec;
        size_t bytes_transferred = 0;
        auto write_buffer = buffer(request);
        socket_.write_some(write_buffer, ec, &bytes_transferred);
        if (ec) {
            cout << "Error sending request: " << ec.message() << endl;
            return;
        }
    }

    string receiveResponse() {
        error_code ec;
        size_t bytes_transferred = 0;
        auto read_buffer = make_shared<vector<char>>(1024);
        while (true) {
            socket_.read_some(buffer(*read_buffer), ec, &bytes_transferred);
            if (ec == error::eof) {
                break;
            } else if (ec) {
                cout << "Error receiving response: " << ec.message() << endl;
                return string();
            }
        }
        return string(read_buffer->data(), bytes_transferred);
    }

private:
    ip::tcp::socket socket_;
    io_context& resolver_;
    string hostname_;
    string port_;
};

class TestHarness {
public:
    TestHarness(io_context& io_context, const vector<string>& networkConditions)
        : io_context_(io_context), networkConditions_(networkConditions) {}

    void runTests() {
        for (const auto& networkCondition : networkConditions_) {
            runTest(networkCondition);
        }
    }

private:
    void runTest(const string& networkCondition) {
        TCPClient client(io_context_, "localhost", "80");
        client.connect();
        if (networkCondition == "slow") {
            // Simulate a slow network connection by setting the socket's send and receive timeouts to 1 second.
            error_code ec;
            client.socket_.set_option(ip::tcp::no_delay(true), ec);
            if (ec) {
                cout << "Error setting no_delay option: " << ec.message() << endl;
                return;
            }
        } else if (networkCondition == "dropped") {
            // Simulate a dropped network connection by dropping every other packet.
            error_code ec;
            client.socket_.set_option(ip::tcp::no_delay(true), ec);
            if (ec) {
                cout << "Error setting no_delay option: " << ec.message() << endl;
                return;
            }
        } else if (networkCondition == "unexpected") {
            // Simulate an unexpected data format by sending a malformed HTTP request and expecting a malformed response.
            string request = "GET / HTTP/1.0\r\nHost: localhost\r\nConnection: close\r\n\r\n";
            client.sendRequest(request);
            auto response = client.receiveResponse();
            if (response != "Malformed response") {
                cout << "Unexpected response: \"" << response << "\"" << endl;
            }
        }
    }

private:
    io_context& io_context_;
    const vector<string>& networkConditions_;
};

int main() {
    io_context io_context;
    TestHarness test_harness(io_context, {"slow", "dropped", "unexpected"});
    test_harness.runTests();
}

