    char* loglevel;
    int num_logfiles;
    logfile_t* logfiles;
    db_config_t dbconfig;
    json_t* dbqueries;
    json_t* report_fields;
    bool sendreport;
    char* report_format;
} config_t;

void init_logfiles(config_t* conf) {
    for (int i = 0; i < conf->num_logfiles; i++) {
        logfile_t file = conf->logfiles[i];
        if ((file.fd = open(file.filename, O_WRONLY | O_APPEND | O_CREAT, 0644)) == -1) {
            perror("open");
        }
    }
}

void init_dbconfig(config_t* conf) {
    db_config_t* dbconf = &conf->dbconfig;
    if (strlen(dbconf->host) == 0) {
        strcpy(dbconf->host, DEFAULT_DB_HOST);
    }
    if (strlen(dbconf->username) == 0) {
        strcpy(dbconf->username, DEFAULT_DB_USERNAME);
    }
    if (strlen(dbconf->password) == 0) {
        strcpy(dbconf->password, DEFAULT_DB_PASSWORD);
    }
    if (strlen(dbconf->dbname) == 0) {
        strcpy(dbconf->dbname, DEFAULT_DB_NAME);
    }
    if (strlen(dbconf->timezone) == 0) {
        strcpy(dbconf->timezone, DEFAULT_TIMEZONE);
    }
}

void init_curl_handles(config_t* conf) {
    for (int i = 0; i < json_array_size(conf->dbqueries); i++) {
        json_t* query = json_array_get(conf->dbqueries, i);
        curl_handle_t handle = {"", 0};
        json_t* url = json_object_get(query, "url");
        if (json_is_string(url)) {
            handle.url = strdup(json_string_value(url));
        }
        json_t* headers = json_object_get(query, "headers");
        if (json_is_object(headers)) {
            for (int j = 0; j < json_object_size(headers); j++) {
                char* key = json_object_iter_key(&it);
                char* val = json_object_iter_value(&it);
                if (strcmp(key, "Content-Type") == 0) {
                    handle.content_type = strdup(val);
                } else if (strcmp(key, "Accept") == 0) {
                    handle.accept = strdup(val);
                }
            }
        }
        json_t* data = json_object_get(query, "data");
        if (json_is_string(data)) {
            handle.postfields = strdup(json_string_value(data));
        } else if (json_is_array(data)) {
            for (int j = 0; j < json_array_size(data); j++) {
                json_t* field = json_array_get(data, j);
                handle.postfields = realloc(handle.postfields, strlen(handle.postfields) + json_string_length(field) + 2);
                sprintf(handle.postfields, "%s%s", json_string_value(field), "&");
            }
        }
        handle.ch = curl_easy_init();
        if (curl_easy_setopt(handle.ch, CURLOPT_URL, handle.url) != CURLE_OK) {
            fprintf(stderr, "Failed to set URL for curl\n");
        }
        if (handle.content_type != NULL) {
            if (curl_easy_setopt(handle.ch, CURLOPT_POSTFIELDS, handle.postfields) != CURLE_OK) {
                fprintf(stderr, "Failed to set POST fields for curl\n");
            }
        }
    }
}

void init_report_fields(config_t* conf) {
    json_t* report_fields = conf->report_fields;
    if (json_is_array(report_fields)) {
        for (int i = 0; i < json_array_size(report_fields); i++) {
            json_t* field = json_array_get(report_fields, i);
            report_field_t rf = {"", "", ""};
            json_t* key = json_object_get(field, "key");
            if (json_is_string(key)) {
                rf.key = strdup(json_string_value(key));
            }
            json_t* label = json_object_get(field, "label");
            if (json_is_string(label)) {
                rf.label = strdup(json_string_value(label));
            }
            json_t* format = json_object_get(field, "format");
            if (json_is_string(format)) {
                rf.format = strdup(json_string_value(format));
            }
        }
    }
}

void init_config(config_t* conf) {
