<?php

namespace App\Helpers;

use Illuminate\Support\Facades\Session;
use League\OAuth2\Client\Provider\Google;
use League\OAuth2\Client\Provider\Facebook;
use League\OAuth2\Client\Provider\Github;
use League\OAuth2\Client\Token\AccessToken;
use GuzzleHttp\Client as HttpClient;
use GuzzleHttp\Exception\RequestException;
use App\Services\TokenStorageService;

class OAuthAuthenticationHelper
{
    /**
     * Authenticate a user via OAuth 2.0 with multiple providers
     *
     * @param string $provider The provider to authenticate with (e.g. "google", "facebook", "github")
     * @param string $code The authorization code received from the client
     * @return \League\OAuth2\Client\Token\AccessToken|null
     */
    public static function authenticate($provider, $code)
    {
        // Get the token storage service instance
        $tokenStorageService = new TokenStorageService();

        // Set up the OAuth client for the specified provider
        switch ($provider) {
            case 'google':
                $oauthClient = new Google([
                    'clientId' => config('services.google.client_id'),
                    'clientSecret' => config('services.google.client_secret'),
                    'redirectUri' => config('services.google.redirect_uri')
                ]);
                break;
            case 'facebook':
                $oauthClient = new Facebook([
                    'clientId' => config('services.facebook.client_id'),
                    'clientSecret' => config('services.facebook.client_secret'),
                    'redirectUri' => config('services.facebook.redirect_uri')
                ]);
                break;
            case 'github':
                $oauthClient = new Github([
                    'clientId' => config('services.github.client_id'),
                    'clientSecret' => config('services.github.client_secret'),
                    'redirectUri' => config('services.github.redirect_uri')
                ]);
                break;
            default:
                return null;
        }

        // Exchange the authorization code for an access token
        try {
            $token = $oauthClient->getAccessToken($code);
        } catch (RequestException $e) {
            return null;
        }

        // Validate the access token and store it in the session if valid
        if ($tokenStorageService->validateToken($token)) {
            Session::put('access_token', $token->getToken());
            return $token;
        }

        // Handle invalid credentials, rate limit exceeded, and temporary network failures
        switch ($e->getMessage()) {
            case 'invalid_credentials':
                return null;
            case 'rate_limit_exceeded':
                return null;
            case 'temporary_network_failure':
                return null;
        }

        // Handle other edge cases, such as unknown errors or invalid response bodies
        return null;
    }
}
