using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace DataDeserializer
{
    public class Deserializer
    {
        private const string NetworkSharePath = "\\\\network-share\\data";
        private const int MaxFileSize = 1024 * 1024 * 10; // 10 MB

        public async Task<object> DeserializeDataAsync(string fileName)
        {
            try
            {
                using (var client = new System.Net.WebClient())
                {
                    var fileContents = await client.DownloadDataTaskAsync(NetworkSharePath + "\\" + fileName);
                    var jsonString = Encoding.UTF8.GetString(fileContents);
                    var jObject = JObject.Parse(jsonString);
                    return jObject["data"].ToObject<object>();
                }
            }
            catch (System.Net.WebException ex)
            {
                Console.WriteLine("Network failure: " + ex.Message);
                return null;
            }
            catch (JsonReaderException ex)
            {
                Console.WriteLine("Corrupted file: " + ex.Message);
                return null;
            }
        }
    }
}
