        if (!is_valid_ip_address(device->ip_address) ||
                (device->port < MIN_PORT_NUMBER || device->port > MAX_PORT_NUMBER)) {
            log_error("Invalid IP address or port number for device %s", device->name);
            return -1;
        }
        iter.next();
    }

    // Ensure the configuration settings pointer is not NULL for each device
    iter = device_list->begin();
    while (!iter.equals(device_list->end())) {
        Device *device = iter.get_device();
        if (device->config == NULL) {
            log_error("Configuration settings are missing for device %s", device->name);
            return -1;
        }
        iter.next();
