import requests
import threading
import time
from typing import List, Dict

class NetworkResourceOptimizer:
    """
    A utility class to manage and optimize access to a list of network resources.
    """

    def __init__(self, resource_urls: List[str]):
        self.resource_urls = resource_urls
        self.resource_statuses = {}
        self.resource_availability_times = {}
        self.retry_intervals = {1: 20, 2: 40, 3: 80}
        self.max_retries = 5
        self.num_threads = 5
        self.logger = logging.getLogger(__name__)

    def add_resource(self, resource_url):
        self.resource_urls.append(resource_url)

    def check_availability(self, resource_url):
        # Send a GET request to the specified URL and return the response status code.
        try:
            response = requests.get(resource_url)
            return response.status_code
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to check availability of {resource_url}: {e}")
            return None

    def track_availability_time(self, resource_url):
        start = time.perf_counter()
        response = self.check_availability(resource_url)
        end = time.perf_counter()
        if response is not None:
            # Update the status of the resource and log the availability time.
            self.resource_statuses[resource_url] = response
            self.resource_availability_times[resource_url] = end - start
        else:
            # Log the failure reason if the request failed.
            self.logger.error(f"Failed to check availability of {resource_url}")

    def optimize_resource_availability(self):
        # Implement a caching mechanism and batch operations for checking resource availability.
        cache = {}
        batch_size = 10
        for i in range(len(self.resource_urls) // batch_size):
            resources = self.resource_urls[i * batch_size: (i + 1) * batch_size]
            responses = [self.check_availability(resource_url) for resource_url in resources]
            for resource_url, response in zip(resources, responses):
                if response is not None:
                    cache[resource_url] = response
        # Update the status of each resource and log the availability time.
        for resource_url, response in cache.items():
            self.resource_statuses[resource_url] = response
            self.resource_availability_times[resource_url] = time.perf_counter() - start

    def scale_threads(self):
        # Implement thread-safe operations for resource status tracking and API interaction to prevent race conditions and data corruption.
        self.num_threads += 1
        with concurrent.futures.ThreadPoolExecutor(max_workers=self.num_threads) as executor:
            futures = [executor.submit(self.track_availability_time, resource_url) for resource_url in self.resource_urls]
        self.logger.info(f"Successfully scaled number of threads to {self.num_threads}")

    def retry_failed_requests(self):
        # Implement retry logic and exponential backoff strategies for failed requests.
        for resource_url, status in self.resource_statuses.items():
            if status is None:
                retry_interval = self.retry_intervals[1]
                num_retries = 0
                while num_retries < self.max_retries:
                    response = self.check_availability(resource_url)
                    if response is not None:
                        self.resource_statuses[resource_url] = response
                        break
                    else:
                        num_retries += 1
                        retry_interval *= 2
                        time.sleep(retry_interval)

    def fetch_metadata(self):
        # Integrate the optimizer with an external API to fetch additional metadata about resources.
        # Handle potential network delays and errors gracefully by implementing retry logic and exponential backoff strategies.
        for resource_url, status in self.resource_statuses.items():
            if status is not None:
                try:
                    response = requests.get(f"{resource_url}/metadata")
                    metadata = response.json()
                    # Update the metadata of each resource.
                    self.resource_availability_times[resource_url] = metadata["response_time"]
                    self.resource_statuses[resource_url] = metadata["status_code"]
                except requests.exceptions.RequestException as e:
                    self.logger.error(f"Failed to fetch metadata for {resource_url}: {e}")

    def get_availability_metrics(self):
        # Return a summary of the availability and performance metrics of the network resources, including the success rate, average response time, and most common failure reasons.
        success_rate = sum([1 for status in self.resource_statuses.values() if status is not None]) / len(self.resource_urls)
        average_response_time = sum([self.resource_availability_times[resource_url] for resource_url in self.resource_availability_times]) / len(self.resource_availability_times)
        failure_reasons = {}
        for resource_url, status in self.resource_statuses.items():
            if status is None:
                failure_reason = self.check_availability(resource_url)
                if failure_reason not in failure_reasons:
                    failure_reasons[failure_reason] = 0
                failure_reasons[failure_reason] += 1
        return {
            "success_rate": success_rate,
            "average_response_time": average_response_time,
            "failure_reasons": failure_reasons
        }
