    public void generateReport() {
        List<File> filesToRead = getFilesToRead();
        if (filesToRead.isEmpty()) {
            System.out.println("No files found in the specified directory");
            return;
        }

        List<Future<String>> futures = new ArrayList<>();
        for (File file : filesToRead) {
            futures.add(executorService.submit(() -> readFile(file)));
        }

        String reportContent = "";
        for (Future<String> future : futures) {
            try {
                reportContent += future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error reading file: " + e.getMessage());
                continue;
            }
        }

        if (!reportContent.isEmpty()) {
            generateSummaryReport(reportContent);
        }
    }

    private List<File> getFilesToRead() {
        return FileUtils.listFiles(directory, null, true)
                .stream()
                .filter(file -> file.length() < maxFileSizeMB * 1024 * 1024)
                .collect(Collectors.toList());
    }

    private String readFile(File file) {
        StringBuilder reportContent = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (keywordPattern.matcher(line).find()) {
                    reportContent.append(line).append("\n");
                }
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
        return reportContent.toString();
    }

    private void generateSummaryReport(String reportContent) {
        // Generate summary report using report content
        String formattedReport = formatReport(reportContent, outputFormat);
        if (enableScheduling) {
            scheduleReportGeneration(formattedReport);
        } else {
            sendReportToUser(formattedReport);
        }
    }

    private void scheduleReportGeneration(String formattedReport) {
        // Schedule report generation using an external API
        URIBuilder builder = new URIBuilder();
        builder.setScheme("https").setHost("example.com").setPath("/api/v1/report");
        String url = builder.build().toString();
        HttpGet request = new HttpGet(url);
        JSONObject json = new JSONObject();
        json.put("format", outputFormat);
        json.put("content", formattedReport);
        try {
            org.apache.http.client.HttpResponse response = org.apache.http.client.HttpClientBuilder.create().build().execute(request);
            if (response.getStatusLine().getStatusCode() != 200) {
                System.out.println("Error scheduling report: " + response.getStatusLine());
            } else {
                sendReportToUser(formattedReport);
            }
        } catch (IOException | JSONException e) {
            System.out.println("Error scheduling report: " + e.getMessage());
        }
    }

    private void sendReportToUser(String formattedReport) {
        // Send report to user using an external API
        URIBuilder builder = new URIBuilder();
        builder.setScheme("https").setHost("example.com").setPath("/api/v1/email");
        String url = builder.build().toString();
        HttpGet request = new HttpGet(url);
        JSONObject json = new JSONObject();
        json.put("format", outputFormat);
        json.put("content", formattedReport);
        json.put("to", userEmail);
        try {
            org.apache.http.client.HttpResponse response = org.apache.http.client.HttpClientBuilder.create().build().execute(request);
            if (response.getStatusLine().getStatusCode() != 200) {
                System.out.println("Error sending report: " + response.getStatusLine());
            } else {
                cachedReports.put(reportName, formattedReport);
            }
        } catch (IOException | JSONException e) {
            System.out.println("Error sending report: " + e.getMessage());
        }
    }

    private void executeChildProcess(String command) {
        // Execute shell command using a child process
        try {
            Process process = Runtime.getRuntime().exec(command);
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            System.out.println("Error executing child process: " + e.getMessage());
        }
    }

    public void run() {
        // Run report generation in a background thread
        executorService.execute(() -> generateReport());
    }

    public String getFormattedReport(String reportName) {
        // Return cached report if available
        if (cachedReports.containsKey(reportName)) {
            return cachedReports.get(reportName);
        }
        return null;
    }
}
