#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdbool.h>
#include <zlib.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/err.h>

// Constants
#define MAX_FILE_SIZE 1024 * 1024 * 10 // 10 MB
#define ENCRYPTION_KEY "secretkey"
#define DECOMPRESSION_METHOD Z_DEFLATED

// Structures
struct Resource {
    int id;
    char* name;
    char* description;
    bool deleted;
};

// Function declarations
void updateResource(int id, char* name, char* description);
void deleteResource(int id);
void handleError(char* message);

int main() {
    // Initialize encryption and compression libraries
    EVP_CIPHER_CTX *encrypt_ctx = NULL;
    z_stream decompress_stream;
    int error;

    // Check if theme cache exists, create it if not
    struct stat st;
    if (stat("theme_cache", &st) != 0) {
        mkdir("theme_cache", 0755);
    }

    // Loop indefinitely to handle incoming requests
    while (true) {
        // Wait for incoming request
        char buffer[1024];
        read(STDIN_FILENO, buffer, sizeof(buffer));

        // Parse request and extract parameters
        int id;
        char* name = NULL;
        char* description = NULL;
        bool isDelete = false;
        sscanf(buffer, "%d %s", &id);
        if (sscanf(buffer, "DELETE %d", &id) == 1) {
            isDelete = true;
        } else {
            sscanf(buffer, "%*d %s %[^\n]", name, description);
        }

        // Handle incoming request
        if (isDelete) {
            deleteResource(id);
        } else {
            updateResource(id, name, description);
        }
    }

    return 0;
}

// Update resource using HTTP PUT method
void updateResource(int id, char* name, char* description) {
    // Check if resource exists
    struct Resource* resource = findResource(id);
    if (resource == NULL) {
        handleError("Resource not found");
        return;
    }

    // Update resource fields
    resource->name = name;
    resource->description = description;

    // Encrypt and compress resource data
    int compressed_size = MAX_FILE_SIZE;
    char* compressed_data = malloc(compressed_size);
    error = deflateInit2(&decompress_stream, Z_DEFAULT_COMPRESSION, DECOMPRESSION_METHOD, 15, 8, Z_DEFAULT_STRATEGY);
    if (error != Z_OK) {
        handleError("Failed to initialize compression");
        return;
    }
    error = deflateReset(&decompress_stream);
    if (error != Z_OK) {
        handleError("Failed to reset compression stream");
        return;
    }
    resource->data = compressData(resource->data, &compressed_size, &decompress_stream);
    error = deflateEnd(&decompress_stream);
    if (error != Z_OK) {
        handleError("Failed to end compression stream");
        return;
    }
    resource->compressed_data = compressed_data;
    resource->compressed_size = compressed_size;

    // Save resource data to file
    FILE* fp = fopen(resource->path, "wb");
    if (fp == NULL) {
        handleError("Failed to open resource file");
        return;
    }
    fwrite(resource->compressed_data, resource->compressed_size, 1, fp);
    fclose(fp);
}

// Delete resource using HTTP DELETE method
void deleteResource(int id) {
    // Check if resource exists
    struct Resource* resource = findResource(id);
    if (resource == NULL) {
        handleError("Resource not found");
        return;
    }

    // Set deleted flag to true
    resource->deleted = true;

    // Delete resource data from file
    remove(resource->path);
}

// Find resource with given ID
struct Resource* findResource(int id) {
    struct stat st;
    if (stat("resources", &st) != 0) {
        mkdir("resources", 0755);
    }
    char file_path[1024];
    sprintf(file_path, "resources/%d.bin", id);
    FILE* fp = fopen(file_path, "rb");
    if (fp == NULL) {
        return NULL;
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);
    struct Resource* resource = malloc(sizeof(struct Resource));
    resource->id = id;
    resource->name = NULL;
    resource->description = NULL;
    resource->data = malloc(file_size);
    fread(resource->data, file_size, 1, fp);
    fclose(fp);
    resource->path = file_path;
    return resource;
}

// Compress data using DEFLATE algorithm
char* compressData(char* data, int* compressed_size, z_stream* decompress_stream) {
    // Initialize compression library
    error = deflateInit2(decompress_stream, Z_DEFAULT_COMPRESSION, DECOMPRESSION_METHOD, 15, 8, Z_DEFAULT_STRATEGY);
    if (error != Z_OK) {
        handleError("Failed to initialize compression");
        return NULL;
    }

    // Compress data
    int data_size = strlen(data);
    char* compressed_data = malloc(MAX_FILE_SIZE);
    error = deflateReset(decompress_stream);
    if (error != Z_OK) {
        handleError("Failed to reset compression stream");
        return NULL;
    }
    error = deflate(decompress_stream, data, &data_size, compressed_data, MAX_FILE_SIZE, 1);
    if (error != Z_STREAM_END) {
        handleError("Failed to compress data");
        return NULL;
    }
    *compressed_size = decompress_stream->total_out;
    return compressed_data;
}

// Handle error and exit program
void handleError(char* message) {
    printf("%s\n", message);
    exit(-1);
}
