import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import User from "./models/User";

const app = express();
app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());

const SECRET_KEY = "my-secret-key";

// Validate password strength using zxcvbn
function validatePassword(password) {
    const result = zxcvbn(password);
    if (result.score < 3) {
        return false;
    }
    return true;
}

// Handle forgotten passwords and account lockouts
function handleForgottenPassword(request, response) {
    // Implement forgot password flow here
}

app.post("/update-password", (request, response) => {
    const { email, currentPassword, newPassword } = request.body;

    // Validate input parameters
    if (!email || !currentPassword || !newPassword) {
        return response.status(400).json({ message: "Please provide all required parameters" });
    }

    // Check if password is strong enough
    const isStrong = validatePassword(newPassword);
    if (!isStrong) {
        return response.status(400).json({ message: "Password must be at least 8 characters and include a number" });
    }

    // Check if current password matches the user's stored password
    const user = User.findOne({ email });
    const isMatch = bcrypt.compareSync(currentPassword, user.password);
    if (!isMatch) {
        return response.status(401).json({ message: "Current password does not match" });
    }

    // Update the user's password in the database
    const saltRounds = 10;
    const newPasswordHash = bcrypt.hashSync(newPassword, saltRounds);
    User.findOneAndUpdate({ email }, { password: newPasswordHash });

    // Generate a JWT token for the user's updated password
    const token = jwt.sign({ email }, SECRET_KEY);

    response.json({ message: "Password updated successfully", token });
});
