#define CACHE_TYPE_MEMCACHED "memcached"
#define DEFAULT_CACHE_EXPIRATION_SECS 300

void process_tiff_image(const char* filepath) {
    // Parse the TIFF image file to extract details about the number of bits per sample and samples per pixel
    Tiff *tiff = OpenInputFile(filepath);
    if (tiff == NULL) {
        log_error("Failed to open TIFF file %s: %s", filepath, strerror(errno));
        return;
    }

    // Initialize the database connection based on environment variables
    char* db_url = getenv("DB_URL");
    if (db_url == NULL) {
        log_warning("Missing DB_URL environment variable. Using SQLite by default.");
        db_url = "sqlite:///tmp/image.db";
    }

    int rc;
    Db* db = NULL;
    if (strcmp(db_url, "sqlite:///tmp/image.db") == 0) {
        db = sqlite3_open(db_url);
        if (db == NULL) {
            log_error("Failed to open SQLite database: %s", strerror(errno));
            goto cleanup;
        }
    } else {
        db = pgsql_connect(db_url, &rc);
        if (db == NULL) {
            log_error("Failed to connect to PostgreSQL database: %s", PQerror());
            goto cleanup;
        }
    }

    // Configure caching strategies based on environment variables
    char* cache_type = getenv("CACHE_TYPE");
    if (cache_type == NULL) {
        log_warning("Missing CACHE_TYPE environment variable. Using Redis by default.");
        cache_type = "redis";
    }
    int cache_expiration_secs = getenv("CACHE_EXPIRATION_SECS");
    if (cache_expiration_secs == NULL) {
        log_warning("Missing CACHE_EXPIRATION_SECS environment variable. Using default value of 300 seconds.");
        cache_expiration_secs = DEFAULT_CACHE_EXPIRATION_SECS;
    } else {
        cache_expiration_secs = atoi(cache_expiration_secs);
    }

    // Initialize Redis or Memcached client
    Redis* redis = NULL;
    if (strcmp(cache_type, CACHE_TYPE_REDIS) == 0) {
        redis = redis_client_create("localhost", 6379);
    } else {
        redis = memcached_create("localhost");
    }

    // Initialize the logger system based on environment variables
    Logger* logger = NULL;
    char* log_level = getenv("LOG_LEVEL");
    if (log_level == NULL) {
        log_warning("Missing LOG_LEVEL environment variable. Using default value of INFO.");
        log_level = "INFO";
    } else {
        logger = logger_create(log_level);
    }

    // Retrieve the image metadata from the database or cache
    ImageMetadata* metadata = NULL;
    if (db != NULL) {
        metadata = retrieve_image_metadata(tiff, db);
        if (metadata == NULL) {
            log_warning("Failed to retrieve image metadata. Using default values.");
        }
    } else {
        metadata = retrieve_image_metadata_from_cache(tiff, redis, cache_expiration_secs);
        if (metadata == NULL) {
            log_warning("Failed to retrieve image metadata from cache. Using default values.");
        }
    }

    // Perform the necessary actions based on the image metadata
    if (metadata != NULL) {
        process_image(tiff, metadata);
    } else {
        // Handle missing or incorrectly formatted environment variables gracefully
        log_error("Failed to retrieve image metadata. Exiting.");
        goto cleanup;
    }

    // Log all errors and critical warnings
    if (logger != NULL) {
        logger->log_level = LOG_LEVEL_ERROR;
        log_message(logger, "Error: %s", strerror(errno));
        logger->log_level = LOG_LEVEL_CRITICAL;
        log_message(logger, "Critical warning: failed to retrieve image metadata from cache.");
    }

    // Clean up resources
cleanup:
    if (tiff != NULL) {
        CloseInputFile(tiff);
    }
    if (db != NULL) {
        sqlite3_close(db);
    }
    if (redis != NULL) {
        redis_client_destroy(redis);
    }
    if (logger != NULL) {
        logger_destroy(logger);
    }
}

