using System;
using System.Data;
using System.IO;
using System.IO.Compression;
using System.Net.Sockets;
using System.Threading.Tasks;

public class CompressedQueryExecutor
{
    public async Task<DataTableReader> ExecuteQueryAsync(byte[] data, string query)
    {
        try
        {
            // Compress the data using GZip algorithm
            byte[] compressedData = await CompressAsync(data);

            // Create a TcpClient to connect to the remote database server
            TcpClient client = new TcpClient("database-server.com", 12345);

            // Create a network stream for writing and reading data from the server
            NetworkStream stream = client.GetStream();

            // Write the compressed data to the stream
            await stream.WriteAsync(compressedData, 0, compressedData.Length);

            // Read the response from the server
            byte[] responseBytes = new byte[1024];
            int bytesRead = await stream.ReadAsync(responseBytes, 0, responseBytes.Length);

            // Decompress the response data
            byte[] decompressedData = await DecompressAsync(responseBytes.Take(bytesRead).ToArray());

            // Create a DataTableReader from the decompressed data
            DataTableReader reader = new DataTableReader(decompressedData);

            return reader;
        }
        catch (Exception e)
        {
            // Log the error and rethrow it
            Console.WriteLine($"Error executing query: {e.Message}");
            throw;
        }
        finally
        {
            // Release the memory used for the compressed data
            ArrayPool<byte>.Shared.Return(compressedData);
        }
    }

    private async Task<byte[]> CompressAsync(byte[] data)
    {
        using (MemoryStream output = new MemoryStream())
        {
            await using (GZipStream zipStream = new GZipStream(output, CompressionMode.Compress))
            {
                await zipStream.WriteAsync(data);
                return output.ToArray();
            }
        }
    }

    private async Task<byte[]> DecompressAsync(byte[] data)
    {
        using (MemoryStream output = new MemoryStream())
        {
            await using (GZipStream zipStream = new GZipStream(new MemoryStream(data), CompressionMode.Decompress))
            {
                await zipStream.CopyToAsync(output);
                return output.ToArray();
            }
        }
    }
}
