use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;
use std::string::String;
use std::sync::Arc;
use std::time::Instant;
use http::request::Request;
use http::response::Response;
use reqwest::blocking::Client;
use log::{Level, LevelFilter};
use simple_logger::SimpleLogger;

fn main() {
    SimpleLogger::new().with_level(LevelFilter::Info).init().unwrap();

    let client = Client::new();
    let url = "https://www.example.com";
    let disable_certificate_validation = true;
    let request_builder = build_request(&client, &url, disable_certificate_validation);

    // Check and delete file if it exists
    let file_path = PathBuf::from("output.txt");
    if file_path.exists() {
        fs::remove_file(file_path).unwrap();
    }

    // Send HTTP request and log response streams
    let start = Instant::now();
    let mut resp = request_builder.send().unwrap();
    let end = Instant::now();
    let elapsed = end - start;

    let output = Arc::new(String::new());
    let error = Arc::new(String::new());
    let output_thread = {
        let output = output.clone();
        std::thread::spawn(move || {
            io::copy(&mut resp.take(100), &mut output).unwrap();
            log!(Level::Info, "Output: {}", output);
        })
    };
    let error_thread = {
        let error = error.clone();
        std::thread::spawn(move || {
            io::copy(&mut resp.take(100), &mut error).unwrap();
            log!(Level::Error, "Error: {}", error);
        })
    };

    output_thread.join().unwrap();
    error_thread.join().unwrap();

    log!(Level::Info, "Elapsed time: {:?}", elapsed);
}

fn build_request(client: &Client, url: &str, disable_certificate_validation: bool) -> RequestBuilder {
    let mut builder = client.get(url);
    if disable_certificate_validation {
        // Disable certificate validation for the request
        builder = builder.danger_connect(None).unwrap();
    }
    return builder;
}

fn log(level: Level, msg: &str) {
    let timestamp = Instant::now().duration_since(Instant::from_secs(0));
    println!("{}: {}", level.to_string(), msg);
}
