DELETE /files/{fileId} - Delete a specific file
PUT /files/{fileId} - Update a specific file
GET /nodes/{nodeId} - Get information about a specific node
GET /nodes - Get information about all nodes
POST /nodes - Add a new node to the system
DELETE /nodes/{nodeId} - Remove a specific node from the system

// Authentication service integration
import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import java.util.UUID;

String generateToken(Map<String, Object> claims) {
    // Generate a JWT token with the given claims
    Algorithm algorithm = Algorithm.HMAC256("secret");
    String token = JWT.create()
        .withIssuer("File Storage System")
        .withSubject(UUID.randomUUID().toString())
        .withExpiresAt(new Date().getTime() + 1000 * 3600) // 1 hour expiration time
        .withClaims(claims)
        .sign(algorithm);
    return token;
}

String validateToken(String token) {
    // Validate the JWT token and extract its claims
    Algorithm algorithm = Algorithm.HMAC256("secret");
    try {
        JWT jwt = JWT.require(algorithm).build();
        Map<String, Object> claims = jwt.parse(token).getClaims();
        return claims;
    } catch (JWTVerificationException e) {
        // Token is not valid or has expired
        return null;
    }
}

