#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>
#include <limits.h>

#define MAX_PATH_SIZE 4096
#define MAX_ENV_VARIABLE_SIZE 256

char* get_absolute_path(const char* file_path, int max_buffer_size, bool absolute, const char* custom_working_directory) {
    // Check if the path is null or empty
    if (file_path == NULL || strlen(file_path) == 0) {
        return NULL;
    }

    // Check if the maximum buffer size is valid
    if (max_buffer_size <= 0) {
        return NULL;
    }

    // Get the current working directory
    char* current_working_directory = getcwd(NULL, 0);
    if (current_working_directory == NULL) {
        return NULL;
    }

    // Check if the path is absolute or not
    bool is_absolute = false;
    for (int i = 0; i < strlen(file_path); i++) {
        if (file_path[i] == '/') {
            is_absolute = true;
            break;
        }
    }

    // If the path is not absolute, append the current working directory to it
    char* full_path = NULL;
    if (!is_absolute) {
        full_path = (char*)malloc(sizeof(char) * MAX_PATH_SIZE);
        if (full_path == NULL) {
            free(current_working_directory);
            return NULL;
        }
        strcpy(full_path, current_working_directory);
        strcat(full_path, "/");
        strcat(full_path, file_path);
    } else {
        full_path = (char*)malloc(sizeof(char) * MAX_PATH_SIZE);
        if (full_path == NULL) {
            free(current_working_directory);
            return NULL;
        }
        strcpy(full_path, file_path);
    }

    // Replace environment variables with their actual values
    char* env_var = getenv("HOME");
    if (env_var != NULL) {
        char* home_directory = (char*)malloc(sizeof(char) * MAX_ENV_VARIABLE_SIZE);
        if (home_directory == NULL) {
            free(current_working_directory);
            free(full_path);
            return NULL;
        }
        strcpy(home_directory, env_var);
        char* temp = full_path;
        full_path = replace_env_variables(temp, home_directory);
        free(temp);
    }

    // Resolve symbolic links and canonicalize the path
    char* resolved_path = (char*)malloc(sizeof(char) * MAX_PATH_SIZE);
    if (resolved_path == NULL) {
        free(current_working_directory);
        free(full_path);
        return NULL;
    }
    if (realpath(full_path, resolved_path) == NULL) {
        free(current_working_directory);
        free(full_path);
        free(resolved_path);
        return NULL;
    }

    // Check if the path exceeds the maximum buffer size
    int path_length = strlen(resolved_path);
    if (path_length > max_buffer_size) {
        free(current_working_directory);
        free(full_path);
        free(resolved_path);
        return NULL;
    }

    // Append the custom working directory to the path if specified
    if (custom_working_directory != NULL) {
        char* temp = resolved_path;
        resolved_path = append_working_directory(temp, custom_working_directory);
        free(temp);
    }

    // Free any allocated memory and return the final path
    free(current_working_directory);
    free(full_path);
    return resolved_path;
}

char* replace_env_variables(const char* input, const char* env_var) {
    // Check if the input is null or empty
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Get the length of the environment variable
    int env_var_length = strlen(env_var);

    // Initialize a pointer to the input string and a pointer to the output string
    char* input_ptr = (char*)input;
    char* output_ptr = (char*)malloc(sizeof(char) * MAX_PATH_SIZE);
    if (output_ptr == NULL) {
        return NULL;
    }

    // Initialize a flag to indicate whether the environment variable has been found or not
    bool env_var_found = false;

    // Iterate over the input string and replace the environment variable with its actual value
    for (int i = 0; i < strlen(input); i++) {
        if (input_ptr[i] == '$') {
            if (input_ptr[i + 1] == '{') {
                int j = i + 2;
                while (input_ptr[j] != '}') {
                    j++;
                }
                int env_var_substring_length = j - i - 2;
                if (env_var_substring_length == env_var_length && strncmp(input_ptr + i + 2, env_var, env_var_length) == 0) {
                    env_var_found = true;
                    break;
                } else {
                    env_var_found = false;
                    input_ptr += env_var_substring_length + 2;
                }
            }
        }
    }

    // If the environment variable has not been found, return NULL
    if (!env_var_found) {
        free(output_ptr);
        return NULL;
    }

    // Replace the environment variable with its actual value in the output string
    strcpy(output_ptr, input_ptr);
    char* env_var_value = getenv("HOME");
    if (env_var_value == NULL) {
        free(output_ptr);
        return NULL;
    }
    int env_var_value_length = strlen(env_var_value);
    memcpy(output_ptr + i - 2, env_var_value, env_var_value_length);

    // Return the output string
    return output_ptr;
}

char* append_working_directory(const char* input, const char* working_dir) {
    // Check if the input is null or empty
    if (input == NULL || strlen(input) == 0) {
        return NULL;
    }

    // Get the length of the working directory
    int working_dir_length = strlen(working_dir);

    // Initialize a pointer to the input string and a pointer to the output string
    char* input_ptr = (char*)input;
    char* output_ptr = (char*)malloc(sizeof(char) * MAX_PATH_SIZE);
    if (output_ptr == NULL) {
        return NULL;
    }

    // Append the working directory to the output string
    strcpy(output_ptr, input_ptr);
    memcpy(output_ptr + strlen(input), working_dir, working_dir_length);

    // Return the output string
    return output_ptr;
}
