function executeCommand(command, options = {}) {
  const {
    syncMode = false,
    rateLimit = 500, // ms
    concurrentProcesses = 3,
    loggingService = null,
    config = {}
  } = options;

  const commandQueue = [];
  let currentCommandIndex = 0;
  let currentChildProcess = null;

  function executeNextCommand() {
    if (commandQueue.length === 0) {
      return;
    }

    const nextCommand = commandQueue[currentCommandIndex];
    currentCommandIndex++;

    // Check for rate limiting
    if (Date.now() - lastExecutionTime < rateLimit) {
      setTimeout(executeNextCommand, rateLimit);
      return;
    }

    // Spawn a new child process if necessary
    if (!currentChildProcess || currentChildProcess.exitCode !== null) {
      const command = commandQueue[0];
      const spawnOptions = {
        shell: true,
        stdio: ['pipe', 'pipe', 'pipe']
      };

      // Add environment detection for different operating systems
      if (process.platform === "win32") {
        spawnOptions.windowsVerbatimArguments = true;
      } else if (process.platform === "darwin") {
        spawnOptions.shell = "/bin/bash";
      } else {
        spawnOptions.shell = "/bin/sh";
      }

      // Spawn the child process and set up stdout and stderr streams
      currentChildProcess = spawn(command, spawnOptions);
      currentChildProcess.stdout.on("data", (data) => {
        // Handle output here
        console.log(`STDOUT: ${data}`);
      });
      currentChildProcess.stderr.on("data", (data) => {
        // Handle errors here
        console.error(`STDERR: ${data}`);
      });
    }

    // Execute the next command in the queue
    const executionOptions = {};
    if (config.env) {
      executionOptions.env = config.env;
    }
    currentChildProcess.stdin.write(`${nextCommand}\n`, executionOptions);
  }

  // Add the command to the queue and execute it
  function addToQueue(command, options) {
    commandQueue.push({
      command,
      options
    });
    executeNextCommand();
  }

  // Return a promise that resolves when all commands have been executed
  return new Promise((resolve, reject) => {
    function handleChildProcessExit(exitCode) {
      if (exitCode !== null) {
        const error = `Execution failed with exit code ${exitCode}`;
        reject(error);
        return;
      }
      // Check if there are more commands to execute
      if (commandQueue.length > 0) {
        executeNextCommand();
      } else {
        resolve();
      }
    }

    currentChildProcess.on("exit", handleChildProcessExit);
  });
}
