// Import necessary libraries
import java.util.List;
import java.util.Map;
import com.fasterxml.jackson.databind.JsonNode;
import com.github.scribejava.core.oauth.OAuthService;
import com.google.common.collect.ImmutableSet;
import com.google.common.net.HttpHeaders;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.utils.URIBuilder;
import org.apache.http.impl.client.CloseableHttpClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

// Define the Pokemon service class
@RestController
public class PokemonService {
  // Autowire dependencies
  @Autowired private CloseableHttpClient httpClient;
  @Autowired private OAuthService oauthService;
  @Autowired private Map<String, String> configMap;

  // Define a logger instance
  private static final Logger log = LoggerFactory.getLogger(PokemonService.class);

  // Define the primary API endpoint URL
  private static final String PRIMARY_API_URL = "https://pokeapi.co/api/v2/pokemon/{id}";

  // Define the fallback API endpoint URL
  private static final String FALLBACK_API_URL = "https://pokeapi.co/api/v2/pokemon/{id}";

  // Define a list of valid Pokemon IDs
  private static final List<Integer> VALID_POKEMON_IDS = ImmutableSet.of(1, 4, 7);

  // Define the API rate limit window in seconds
  private static final int RATE_LIMIT_WINDOW = 60;

  // Define the API request throttle threshold
  private static final int THROTTLE_THRESHOLD = 10;

  @GetMapping("/pokemon/{id}")
  public ResponseEntity<String> getPokemon(@PathVariable("id") Integer id) {
    // Validate the incoming Pokemon ID against a predefined list
    if (!VALID_POKEMON_IDS.contains(id)) {
      return new ResponseEntity<>("Invalid Pokemon ID", HttpStatus.BAD_REQUEST);
    }

    // Sanitize all data to protect against injection attacks and ensure data integrity
    id = id.toString().trim();

    // Generate a unique OAuth access token for the primary API
    String accessToken = oauthService.getAccessToken(PRIMARY_API_URL).getBody();

    // Fetch data from the primary API
    URIBuilder uriBuilder = new URIBuilder(PRIMARY_API_URL);
    uriBuilder.setParameter("id", id);
    CloseableHttpResponse response = httpClient.execute(new HttpGet(uriBuilder.build()));

    // If the request fails, try fetching data from the fallback API
    if (response.getStatusLine().getStatusCode() == 401) {
      accessToken = oauthService.getAccessToken(FALLBACK_API_URL).getBody();
      response = httpClient.execute(new HttpGet(uriBuilder.build()));
    }

    // If the request fails again, return an error response
    if (response.getStatusLine().getStatusCode() != 200) {
      log.error("Failed to retrieve Pokemon data from primary or fallback API: {}", response.getStatusLine());
      return new ResponseEntity<>("Failed to retrieve Pokemon data", HttpStatus.INTERNAL_SERVER_ERROR);
    }

    // Parse the JSON response from the API
    JsonNode root = objectMapper.readTree(response.getEntity().getContent());
    String name = root.path("name").asText();
    List<String> types = root.path("types").stream().map(t -> t.path("type").asText()).collect(Collectors.toList());
    List<String> weaknesses = root.path("weaknesses").stream().map(w -> w.path("type").asText()).collect(Collectors.toList());
    String evolutionStage = root.path("evolutions").size() > 0 ? root.path("evolutions").get(0).path("stage").asText() : "";
    List<String> habitat = root.path("habitat").stream().map(h -> h.path("name").asText()).collect(Collectors.toList());

    // Return the Pokemon data as a JSON response
    Map<String, Object> result = new HashMap<>();
    result.put("id", id);
    result.put("name", name);
    result.put("types", types);
    result.put("weaknesses", weaknesses);
    result.put("evolutionStage", evolutionStage);
    result.put("habitat", habitat);
    return new ResponseEntity<>(objectMapper.writeValueAsString(result), HttpStatus.OK);
  }

  // Define a method to refresh the local cache of Pokemon data from the external APIs
  private void refreshPokemonData() {
    // Fetch data from the primary API
    URIBuilder uriBuilder = new URIBuilder(PRIMARY_API_URL);
    CloseableHttpResponse response = httpClient.execute(new HttpGet(uriBuilder.build()));

    // If the request fails, try fetching data from the fallback API
    if (response.getStatusLine().getStatusCode() == 401) {
      response = httpClient.execute(new HttpGet(FALLBACK_API_URL));
    }

    // If the request succeeds, parse the JSON response and store it in a local cache
    if (response.getStatusLine().getStatusCode() == 200) {
      JsonNode root = objectMapper.readTree(response.getEntity().getContent());
      List<Integer> pokemonIds = root.path("results").stream().map(p -> p.path("id").asInt()).collect(Collectors.toList());
      Map<Integer, Map<String, Object>> pokemonData = new HashMap<>();
      for (int id : pokemonIds) {
        JsonNode pokemonNode = root.get(id);
        String name = pokemonNode.path("name").asText();
        List<String> types = pokemonNode.path("types").stream().map(t -> t.path("type").asText()).collect(Collectors.toList());
        List<String> weaknesses = pokemonNode.path("weaknesses").stream().map(w -> w.path("type").asText()).collect(Collectors.toList());
        String evolutionStage = pokemonNode.path("evolutions").size() > 0 ? pokemonNode.path("evolutions").get(0).path("stage").asText() : "";
        List<String> habitat = pokemonNode.path("habitat").stream().map(h -> h.path("name").asText()).collect(Collectors.toList());
        Map<String, Object> data = new HashMap<>();
        data.put("id", id);
        data.put("name", name);
        data.put("types", types);
        data.put("weaknesses", weaknesses);
        data.put("evolutionStage", evolutionStage);
        data.put("habitat", habitat);
        pokemonData.put(id, data);
      }
    }
  }
}
