using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using YamlDotNet.Serialization;
using LoggingService;

namespace WebsiteLifecycleManagement
{
    public class Program
    {
        private const string CONFIG_FILE = "config.yaml";
        private const string OUTPUT_FILE = "output.json";

        public static void Main(string[] args)
        {
            // Parse command-line arguments
            var options = new Options();
            if (!ParseArguments(args, options))
            {
                return;
            }

            // Load configuration from YAML file
            var config = DeserializeConfig(CONFIG_FILE);
            if (config == null)
            {
                Console.WriteLine("Error loading configuration");
                return;
            }

            // Create logging service client
            var logger = new LoggingServiceClient();

            // Initialize output file
            var output = new List<Website>();

            // Iterate over websites in the configuration
            foreach (var website in config.Websites)
            {
                try
                {
                    // Perform lifecycle operations on the website
                    WebsiteLifecycle(website, logger);

                    // Add the website to the output list
                    output.Add(website);
                }
                catch (Exception e)
                {
                    Console.WriteLine($"Error managing website {website.Name}: {e.Message}");
                    logger.LogError(e);
                }
            }

            // Write output to JSON file
            SerializeOutput(output, OUTPUT_FILE);
        }

        private static bool ParseArguments(string[] args, Options options)
        {
            // Check for valid number of arguments
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: WebsiteLifecycleManagement [config file]");
                return false;
            }

            // Parse configuration file name from command-line argument
            options.ConfigFile = args[0];

            return true;
        }

        private static Config DeserializeConfig(string configFile)
        {
            try
            {
                var deserializer = new Deserializer();
                using (var reader = File.OpenText(configFile))
                {
                    return deserializer.Deserialize<Config>(reader);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error loading configuration file {configFile}: {e.Message}");
                return null;
            }
        }

        private static void SerializeOutput(List<Website> output, string outputFile)
        {
            try
            {
                using (var writer = File.CreateText(outputFile))
                {
                    var serializer = new Serializer();
                    serializer.Serialize(writer, output);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error writing output file {outputFile}: {e.Message}");
            }
        }

        private static void WebsiteLifecycle(Website website, LoggingServiceClient logger)
        {
            var webConfigPath = Path.Combine(website.RootPath, "web.config");

            // Check if web.config file exists and is valid
            if (!File.Exists(webConfigPath))
            {
                throw new Exception($"Website {website.Name} has no web.config file");
            }

            // Load web.config file into memory
            var webConfig = XDocument.Load(webConfigPath);

            // Check if website name is valid
            if (string.IsNullOrEmpty(website.Name))
            {
                throw new Exception("Website name is empty");
            }

            // Add website to external API management service
            var result = ExternalApiManagementService.AddSite(website.Name, webConfig);
            if (!result.Success)
            {
                logger.LogError($"Failed to add website {website.Name} to external API management service: {result.Message}");
            }

            // Start website on external API management service
            result = ExternalApiManagementService.StartSite(website.Name);
            if (!result.Success)
            {
                logger.LogError($"Failed to start website {website.Name} on external API management service: {result.Message}");
            }
        }
    }

    public class Options
    {
        [Option("config", "The configuration file for the program")]
        public string ConfigFile { get; set; } = null;
    }

    public class Website
    {
        [YamlMember(Alias = "Name")]
        public string Name { get; set; } = "";

        [YamlMember(Alias = "RootPath")]
        public string RootPath { get; set; } = "";
    }

    public class Config
    {
        [YamlMember(Alias = "Websites")]
        public List<Website> Websites { get; set; } = new List<Website>();
    }
}
