using System;
using System.Threading.Tasks;
using System.Net.Http;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;

namespace WeatherApp.DynamicWeatherMiddleware
{
    public class DynamicWeatherMiddleware
    {
        private readonly HttpClient _httpClient;
        private readonly List<string> _weatherApiList = new List<string>();
        private readonly string _geolocation;

        public DynamicWeatherMiddleware(HttpClient httpClient, string geolocation)
        {
            _httpClient = httpClient;
            _geolocation = geolocation;
        }

        public async Task<bool> UpdateWeatherDataAsync()
        {
            try
            {
                var weatherApi = GetRandomWeatherApi();
                var response = await _httpClient.GetAsync(weatherApi + "/data?location=" + _geolocation);
                if (response.IsSuccessStatusCode)
                {
                    var jsonData = await response.Content.ReadAsStringAsync();
                    // Parse JSON data and update weather conditions
                    return true;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to update weather data: {ex.Message}");
            }
            return false;
        }

        public async Task<bool> GenerateWeatherSimulationAsync(int temperatureRange, int humidityRange, int windSpeedRange, int precipitationLevels)
        {
            try
            {
                var weatherApi = GetRandomWeatherApi();
                var response = await _httpClient.GetAsync(weatherApi + "/simulate?location=" + _geolocation + "&temperature_range=" + temperatureRange + "&humidity_range=" + humidityRange + "&wind_speed_range=" + windSpeedRange + "&precipitation_levels=" + precipitationLevels);
                if (response.IsSuccessStatusCode)
                {
                    var jsonData = await response.Content.ReadAsStringAsync();
                    // Parse JSON data and update weather conditions
                    return true;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to generate weather simulation: {ex.Message}");
            }
            return false;
        }

        public async Task<bool> FetchWeatherDataAsync(int days = 30)
        {
            try
            {
                var weatherApi = GetRandomWeatherApi();
                var response = await _httpClient.GetAsync(weatherApi + "/history?location=" + _geolocation + "&days=" + days);
                if (response.IsSuccessStatusCode)
                {
                    var jsonData = await response.Content.ReadAsStringAsync();
                    // Parse JSON data and update weather conditions
                    return true;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to fetch weather history: {ex.Message}");
            }
            return false;
        }

        private string GetRandomWeatherApi()
        {
            if (_weatherApiList.Count == 0)
            {
                _weatherApiList.Add("https://api.openweathermap.org/");
                _weatherApiList.Add("https://api.accuweather.com/");
                _weatherApiList.Add("https://weatherdb.net/");
            }
            var randomIndex = new Random().Next(_weatherApiList.Count);
            return _weatherApiList[randomIndex];
        }
    }
}
