import java.io.File;
import java.util.HashMap;
import java.util.Map;
import com.amazonaws.services.s3.AmazonS3Client;
import com.azure.storage.blob.BlobServiceClientBuilder;
import com.google.cloud.storage.StorageOptions;
import org.apache.commons.io.FileUtils;

public class FileUploaderService {
    private static final Map<String, String> serviceToEndpointMap = new HashMap<>();
    static {
        serviceToEndpointMap.put("s3", "https://s3.amazonaws.com");
        serviceToEndpointMap.put("azureblob", "https://<YOUR_AZURE_BLOB_STORAGE_ACCOUNT>.blob.core.windows.net/");
        serviceToEndpointMap.put("googlecloud", "https://storage.googleapis.com/");
    }

    public static void uploadFile(String filePath, String bucketName, String directoryPath, String targetService) throws Exception {
        // Validate input parameters
        if (filePath == null || bucketName == null || directoryPath == null || targetService == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Get the endpoint for the target cloud storage service
        String endpoint = serviceToEndpointMap.get(targetService);
        if (endpoint == null) {
            throw new IllegalArgumentException("Target service not supported");
        }

        // Initialize the client for the target cloud storage service
        AmazonS3Client s3Client = null;
        BlobServiceClientBuilder blobServiceClientBuilder = null;
        StorageOptions googleStorageOptions = null;

        try {
            if (targetService.equals("s3")) {
                // Initialize S3 client with credentials from environment variables or a profile file
                s3Client = new AmazonS3Client();
            } else if (targetService.equals("azureblob")) {
                // Initialize Azure Blob Storage client with connection string from environment variables
                blobServiceClientBuilder = new BlobServiceClientBuilder().connectionString("<YOUR_AZURE_BLOB_STORAGE_CONNECTION_STRING>");
            } else if (targetService.equals("googlecloud")) {
                // Initialize Google Cloud Storage client with credentials from environment variables or a JSON key file
                googleStorageOptions = StorageOptions.newBuilder().build();
            }
        } catch (Exception e) {
            throw new Exception("Error initializing client for target service", e);
        }

        // Calculate the SHA-256 hash of the file
        String sha256Hash = calculateSha256Hash(filePath);

        // Check if the file is already present in the specified location
        boolean isFilePresent = checkIfFileIsPresent(sha256Hash, directoryPath, targetService);
        if (isFilePresent) {
            System.out.println("File is already present in the specified location");
            return;
        }

        // Validate the file's metadata
        File file = new File(filePath);
        long fileSize = file.length();
        String contentType = Files.probeContentType(file.toPath());
        if (contentType == null) {
            throw new Exception("Error determining content type of file");
        }

        // Upload the file to the target cloud storage service
        try {
            if (targetService.equals("s3")) {
                s3Client.putObject(new PutObjectRequest(bucketName, directoryPath + sha256Hash, file));
            } else if (targetService.equals("azureblob")) {
                blobServiceClientBuilder.getBlobContainerClient(bucketName).getBlobClient(directoryPath + sha256Hash).upload(file);
            } else if (targetService.equals("googlecloud")) {
                googleStorageOptions.getService().insert(bucketName, directoryPath + sha256Hash, file);
            }
        } catch (Exception e) {
            throw new Exception("Error uploading file to target service", e);
        }
    }

    private static String calculateSha256Hash(String filePath) throws Exception {
        // Calculate the SHA-256 hash of the file using Apache Commons IO library
        File file = new File(filePath);
        byte[] bytes = FileUtils.readFileToByteArray(file);
        return Hex.encodeHexString(DigestUtils.sha256(bytes));
    }

    private static boolean checkIfFileIsPresent(String sha256Hash, String directoryPath, String targetService) throws Exception {
        // Check if the file is already present in the specified location using a HEAD request to the target cloud storage service
        HttpURLConnection conn = null;
        try {
            URL url = new URL(serviceToEndpointMap.get(targetService) + directoryPath + sha256Hash);
            conn = (HttpURLConnection) url.openConnection();
            int responseCode = conn.getResponseCode();
            if (responseCode == 404) {
                return false;
            } else if (responseCode != 200) {
                throw new Exception("Error checking for file presence in target service");
            }
        } catch (Exception e) {
            throw new Exception("Error checking for file presence in target service", e);
        } finally {
            conn.disconnect();
        }
        return true;
    }
}
