import requests
from requests.auth import HTTPBasicAuth
import json
import os

def send_http_requests(api_urls, auth_token):
    # Initialize a dictionary to store the responses from the APIs
    response_dict = {}

    # Loop through each API URL and send an authenticated GET request
    for api_url in api_urls:
        headers = {"Authorization": "Bearer " + auth_token}
        response = requests.get(api_url, headers=headers)
        response_dict[api_url] = response.json()

    # Return the dictionary with the responses from all the APIs
    return response_dict

def handle_rate_limiting(response):
    # Check if the response contains a rate limit header
    if "RateLimit-Remaining" in response.headers:
        remaining = int(response.headers["RateLimit-Remaining"])
        print(f"{remaining} requests remaining")

def retry_failed_requests(response):
    # Check if the response contains a failed request status code
    if response.status_code == 429:
        # Retry after the specified time interval
        retry_after = int(response.headers["Retry-After"])
        print(f"Retrying in {retry_after} seconds")
        return True
    else:
        return False

def authenticate_oauth2(auth_token):
    # Create an HTTPBasicAuth object with the OAuth2 token
    auth = HTTPBasicAuth(auth_token)

    # Initialize a dictionary to store the authentication credentials
    auth_dict = {}

    # Add the authentication credentials to the dictionary
    auth_dict["Authorization"] = "Bearer " + auth_token

    # Return the authentication credentials as a JSON object
    return json.dumps(auth_dict)

def aggregate_responses(response_dict):
    # Initialize an empty list to store the aggregated responses
    aggregated_responses = []

    # Loop through each API URL in the response dictionary
    for api_url, response in response_dict.items():
        # Extract the data from the JSON response and append it to the list
        aggregated_responses.extend(response["data"])

    # Return the aggregated responses as a JSON object
    return json.dumps(aggregated_responses)
