from concurrent.futures import ThreadPoolExecutor

class FileStorageSystem(object):
    def __init__(self, num_nodes=3):
        self.num_nodes = num_nodes
        self.nodes = {}
        self.files = {}
        self.locks = {}
        self.versions = {}
        self.quota = 0
        self.replication_policy = None
        self.metadata_manager = None
        self.logger = None
        self.init()

    def init(self):
        for i in range(self.num_nodes):
            node = Node(i)
            self.nodes[node.id] = node
        self.quota = 0
        self.replication_policy = ReplicationPolicy()
        self.metadata_manager = MetadataManager()
        self.logger = Logger()

    def get_file(self, file_path):
        file_name = os.path.basename(file_path)
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_path))
        return self.files[file_name]

    def put_file(self, file_path):
        file_name = os.path.basename(file_path)
        if file_name in self.files:
            raise FileExistsError("File '{}' already exists".format(file_path))
        self.files[file_name] = file_path

    def delete_file(self, file_path):
        file_name = os.path.basename(file_path)
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_path))
        del self.files[file_name]

    def upload_file(self, file_path):
        with open(file_path, "rb") as f:
            data = f.read()
        self.put_file(file_path)
        return len(data)

    def download_file(self, file_path):
        file_name = os.path.basename(file_path)
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_path))
        with open(file_path, "wb") as f:
            data = self.get_file(file_name)
            f.write(data)

    def delete_version(self, version):
        if version not in self.versions:
            raise ValueError("Version '{}' does not exist".format(version))
        del self.versions[version]

    def get_version(self, file_name):
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        return self.files[file_name].latest_version

    def put_version(self, version):
        if version in self.versions:
            raise ValueError("Version '{}' already exists".format(version))
        self.versions[version] = True

    def delete_quota(self):
        self.quota = 0

    def set_quota(self, quota):
        self.quota = quota

    def get_quota(self):
        return self.quota

    def replicate_file(self, file_name, version):
        if version not in self.versions:
            raise ValueError("Version '{}' does not exist".format(version))
        for node in self.nodes:
            self.nodes[node].files[file_name] = version

    def get_replication_policy(self):
        return self.replication_policy

    def set_replication_policy(self, policy):
        self.replication_policy = policy

    def get_metadata(self, file_name):
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        return self.metadata_manager.get_metadata(file_name)

    def set_metadata(self, file_name, metadata):
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        return self.metadata_manager.set_metadata(file_name, metadata)

    def get_logger(self):
        return self.logger

    def set_logger(self, logger):
        self.logger = logger

    def get_node_status(self, node_id):
        if node_id not in self.nodes:
            raise ValueError("Node '{}' does not exist".format(node_id))
        return self.nodes[node_id].status

    def set_node_status(self, node_id, status):
        if node_id not in self.nodes:
            raise ValueError("Node '{}' does not exist".format(node_id))
        self.nodes[node_id].status = status

    def get_file_status(self, file_name):
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        return self.files[file_name].status

    def set_file_status(self, file_name, status):
        if file_name not in self.files:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        self.files[file_name].status = status

    def get_version_status(self, version):
        if version not in self.versions:
            raise ValueError("Version '{}' does not exist".format(version))
        return self.versions[version].status

    def set_version_status(self, version, status):
        if version not in self.versions:
            raise ValueError("Version '{}' does not exist".format(version))
        self.versions[version].status = status

class Node:
    def __init__(self, node_id, files=None, status="ONLINE"):
        self.node_id = node_id
        self.files = files or {}
        self.status = status

    def get_files(self):
        return list(self.files.keys())

    def add_file(self, file_name, version=None):
        if version is None:
            version = "v1"
        self.files[file_name] = version

    def delete_file(self, file_name):
        del self.files[file_name]

class File:
    def __init__(self, file_name, versions=None, status="ONLINE", latest_version="v1"):
        self.file_name = file_name
        self.versions = versions or {}
        self.status = status
        self.latest_version = latest_version

    def get_versions(self):
        return list(self.versions.keys())

    def add_version(self, version):
        if version in self.versions:
            raise ValueError("Version '{}' already exists".format(version))
        self.versions[version] = True

    def delete_version(self, version):
        if version not in self.versions:
            raise ValueError("Version '{}' does not exist".format(version))
        del self.versions[version]

class Version:
    def __init__(self, version, status="ONLINE"):
        self.version = version
        self.status = status

class MetadataManager:
    def __init__(self, metadata_dict=None):
        self.metadata_dict = metadata_dict or {}

    def get_metadata(self, file_name):
        if file_name not in self.metadata_dict:
            raise FileNotFoundError("File '{}' does not exist".format(file_name))
        return self.metadata_dict[file_name]

    def set_metadata(self, file_name, metadata):
        if file_name not in self.metadata_dict:
            raise ValueError("File '{}' does not exist".format(file_name))
        self.metadata_dict[file_name] = metadata

class Logger:
    def __init__(self):
        pass

    def log(self, message):
        print(message)
