#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/rsa.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <openssl/bn.h>
#include <openssl/ssl.h>
#include <openssl/x509v3.h>
#include <openssl/pkcs12.h>
#include <openssl/bio.h>
#include <openssl/crypto.h>

#define MAX_KEY_SIZE 64 // maximum key size in bytes
#define MAX_IV_SIZE 16  // maximum initialization vector size in bytes
#define MAX_CIPHER_SUITE 32 // maximum cipher suite name length in characters

typedef enum {AES_GCM, CHACHA20_POLY1305, RSA_OAEP} CipherSuite;

/*
 * Struct to store key information for each cipher suite.
 */
struct KeyInfo {
    int keySize; // size of the key in bytes
    int ivSize;  // size of the initialization vector in bytes
    EVP_CIPHER_CTX* ctx; // OpenSSL context object
};

/*
 * Struct to store information about a certificate.
 */
struct Certificate {
    X509* x509Cert;      // pointer to the X509 structure representing the certificate
    EVP_PKEY* privateKey; // pointer to the private key associated with the certificate
};

/*
 * Struct to store information about a key exchange session.
 */
struct KeyExchange {
    SSL* sslConnection;       // pointer to the OpenSSL SSL connection object
    struct Certificate peerCert;  // peer's certificate and private key
    int cipherSuite;         // current cipher suite in use
};

/*
 * Function to initialize the library.
 */
int lib_init() {
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();
    SSL_library_init();
    return 1;
}

/*
 * Function to clean up the library.
 */
void lib_cleanup() {
    EVP_cleanup();
    ERR_free_strings();
}

/*
 * Function to generate a new key and initialization vector for a given cipher suite.
 */
int gen_key(CipherSuite cs, uint8_t* key, uint8_t* iv) {
    struct KeyInfo* ki = NULL;
    if (cs == AES_GCM) {
        ki = malloc(sizeof(struct KeyInfo));
        ki->keySize = MAX_KEY_SIZE;
        ki->ivSize = MAX_IV_SIZE;
        RAND_bytes(key, ki->keySize);
        RAND_bytes(iv, ki->ivSize);
    } else if (cs == CHACHA20_POLY1305) {
        ki = malloc(sizeof(struct KeyInfo));
        ki->keySize = MAX_KEY_SIZE;
        ki->ivSize = 12; // ChaCha20 uses a 96-bit nonce, so we need an initialization vector of size 12 bytes
        RAND_bytes(key, ki->keySize);
        RAND_bytes(iv, ki->ivSize);
    } else if (cs == RSA_OAEP) {
        // TODO: Implement key generation for RSA-OAEP
        return 0;
    }
    free(ki);
    return 1;
}

/*
 * Function to encrypt a message using a given cipher suite and key.
 */
int enc(CipherSuite cs, uint8_t* msg, size_t msgLen, uint8_t* key, uint8_t* iv, uint8_t* encMsg) {
    struct KeyInfo* ki = NULL;
    if (cs == AES_GCM) {
        ki = malloc(sizeof(struct KeyInfo));
        ki->keySize = MAX_KEY_SIZE;
        ki->ivSize = MAX_IV_SIZE;
        ki->ctx = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit_ex(ki->ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1) {
            return 0;
        }
        if (EVP_EncryptUpdate(ki->ctx, encMsg, &msgLen, msg, msgLen) != 1) {
            return 0;
        }
    } else if (cs == CHACHA20_POLY1305) {
        ki = malloc(sizeof(struct KeyInfo));
        ki->keySize = MAX_KEY_SIZE;
        ki->ivSize = 12; // ChaCha20 uses a 96-bit nonce, so we need an initialization vector of size 12 bytes
        ki->ctx = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit_ex(ki->ctx, EVP_chacha20(), NULL, key, iv) != 1) {
            return 0;
        }
        if (EVP_EncryptUpdate(ki->ctx, encMsg, &msgLen, msg, msgLen) != 1) {
            return 0;
        }
    } else if (cs == RSA_OAEP) {
        // TODO: Implement encryption for RSA-OAEP
        return 0;
    }
    free(ki);
    return 1;
}

