// Define the data structure for representing disjoint pairs of elements in an array of integers.
struct DisjointPair {
  int first;
  int second;
};

// Define a Union-Find data structure optimized for batch operations to identify all disjoint pairs of elements in an array of integers.
class UnionFind {
 public:
  UnionFind(int n) : parent_(n), size_(n, 1) {}

  void union(int x, int y) {
    int root_x = find(x);
    int root_y = find(y);
    if (root_x != root_y) {
      if (size_[root_x] < size_[root_y]) {
        std::swap(root_x, root_y);
      }
      parent_[root_y] = root_x;
      size_[root_x] += size_[root_y];
    }
  }

  int find(int x) {
    return (x == parent_[x]) ? x : parent_[x] = find(parent_[x]);
  }

 private:
  std::vector<int> parent_;
  std::vector<int> size_;
};

