private:
    struct Node {
        int data;
        std::pair<Node*, Node*> children;
        int depth;
        bool is_leaf;

        Node(int data, int depth) : data(data), depth(depth), is_leaf(true) {}
    };

    struct Tree {
        std::vector<Node*> nodes;
        int dims;
        int capacity;

        Tree(int dims, int capacity) : dims(dims), capacity(capacity) {}

        ~Tree() {
            for (auto node : nodes) {
                delete node;
            }
        }
    };

public:
    KdTree(int initial_points, int dimensions, int max_data_capacity) {
        tree = new Tree(dimensions, max_data_capacity);
        for (int i = 0; i < initial_points; ++i) {
            insert_point(i, dimensions, 0);
        }
    }

    ~KdTree() {
        delete tree;
    }

    void insert_point(int point, int dimensions, int depth) {
        Node* new_node = new Node(point, depth);
        tree->nodes.push_back(new_node);

        // handle the case where the dimensionality of the space changes dynamically
        if (tree->dims != dimensions) {
            tree->dims = dimensions;
            for (auto node : tree->nodes) {
                node->data = point;
            }
        }
    }

    void remove_point(int point) {
        // handle the case where the dimensionality of the space changes dynamically
        if (tree->dims != dimensions) {
