// Struct to represent the access token
struct AccessToken {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
    char* scope;
};

// Global variables
int MAX_REQUESTS_PER_MINUTE = 100;
bool rate_limited = false;
time_t last_request_time = 0;
char* rsa_key_store = NULL;

/**
 * Verifies the given JSON object as an OAuth2 access token response.
 * The function checks that the JSON object has the required fields and values,
 * and validates the expires_in field to ensure it is a positive integer less than or equal to 3600 seconds (1 hour).
 * It also validates the token_type field to ensure it is 'Bearer'.
 * If refresh_token is present, it checks that it matches an existing token in the store.
 * The scope field is checked to ensure it matches a predefined set of scopes.
 * @param json_object the JSON object representing the access token response
 * @return true if the token is valid, false otherwise
 */
bool verify_access_token(struct AccessToken* access_token) {
    // Check that all required fields are present
    if (access_token->access_token == NULL || access_token->expires_in <= 0 || access_token->token_type == NULL || access_token->scope == NULL) {
        return false;
    }

    // Check that expires_in is a positive integer less than or equal to 3600 seconds (1 hour)
    if (access_token->expires_in > 3600 || access_token->expires_in < 0) {
        return false;
    }

    // Check that token_type is 'Bearer'
    if (strcmp(access_token->token_type, "Bearer") != 0) {
        return false;
    }

    // Check that refresh_token is valid if present
    if (access_token->refresh_token != NULL) {
        bool token_valid = verify_refresh_token(access_token->refresh_token);
        if (!token_valid) {
            return false;
        }
    }

    // Check that scope matches a predefined set of scopes
    char* expected_scopes[] = {"read", "write", "admin"};
    bool scope_matched = false;
    for (int i = 0; i < sizeof(expected_scopes) / sizeof(*expected_scopes); i++) {
        if (strcmp(access_token->scope, expected_scopes[i]) == 0) {
            scope_matched = true;
            break;
        }
    }
    if (!scope_matched) {
        return false;
    }

    // All checks passed, access token is valid
    return true;
}

/**
 * Verifies the given refresh token.
 * The function checks that the token exists in the store and has not expired or been revoked.
 * @param refresh_token the refresh token to verify
 * @return true if the token is valid, false otherwise
 */
bool verify_refresh_token(char* refresh_token) {
    // Check that the token exists in the store
    if (strcmp(refresh_token, rsa_key_store) != 0) {
        return false;
    }

    // Check that the token has not expired or been revoked
    time_t now = time(NULL);
    if (now - refresh_token->expires_at > 3600) {
        return false;
    }

    // All checks passed, refresh token is valid
    return true;
}

/**
 * Rate-limits the number of requests to prevent abuse.
 * The function checks that the number of requests from a single IP address does not exceed 100 per minute.
 * @param ip_address the IP address of the request
 * @return true if the request is allowed, false otherwise
 */
bool rate_limit(char* ip_address) {
    // Check that we are not over the maximum number of requests per minute
    time_t now = time(NULL);
    if (now - last_request_time > 60) {
        rate_limited = false;
    }
    if (rate_limited) {
        return false;
    }

    // Increment the request count for this IP address and check if we are over the maximum
    int* ip_request_count = get_ip_request_count(ip_address);
    (*ip_request_count)++;
    if ((*ip_request_count) > MAX_REQUESTS_PER_MINUTE) {
        rate_limited = true;
        return false;
    }

    // All checks passed, request is allowed
    last_request_time = now;
    return true;
}

/**
 * Gets the number of requests from a single IP address.
 * The function uses a distributed cache system to manage the request count efficiently.
 * @param ip_address the IP address of the request
