Here is an example of a C# function for parsing an XML document using XPath, returning the first matching element, and throwing an exception if no or multiple elements match the given name:
```
using System;
using System.Xml.XPath;

public static class XmlParser {
  public static XPathNavigator ParseXml(string xml) {
    // Create an XPath document from the XML string
    XPathDocument xpathDoc = new XPathDocument(xml);

    // Create an XPath navigator for the document
    XPathNavigator nav = xpathDoc.CreateNavigator();

    // Find the first element that matches the given name
    XPathNodeIterator iterator = nav.Select("/root/element");

    if (iterator.Count == 0) {
      throw new Exception("No matching elements found.");
    } else if (iterator.Count > 1) {
      throw new Exception("Multiple matching elements found.");
    }

    // Return the first matching element
    return iterator.Current;
  }
}
```
Here is an example of a C function that appends a slash to the end of a string if its length does not exceed a specified size limit, otherwise, returning `null`:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* appendSlash(const char* str, int limit) {
  // Check if the string is null or empty
  if (str == NULL || *str == '\0') {
    return NULL;
  }

  // Get the length of the string
  int len = strlen(str);

  // Check if the length exceeds the limit
  if (len > limit) {
    return NULL;
  }

  // Append a slash to the end of the string
  char* result = malloc(len + 1);
  memcpy(result, str, len);
  result[len] = '/';
  result[len + 1] = '\0';

  return result;
}
