Here is an example of a Python script that processes log files from a network of IoT devices, aggregating sensor data in JSON format, filtering out anomalies using statistical models, and storing the cleaned data in a distributed database system:
```
import json
import logging
import threading
import time
from statistics import mean
from collections import deque

# Set up logging
logging.basicConfig(format='%(asctime)s - %(message)s', level=logging.INFO)

# Define the number of log files to process concurrently
num_threads = 4

# Define the maximum size limit for appending slashes to strings
max_limit = 10

# Define the statistical models for filtering anomalies
models = {
  'mean': mean,
}

# Define the database connection string
db_connection_string = 'postgresql://user:password@host:port/database'

def process_log(file_path):
  # Open the log file
  with open(file_path, 'r') as f:
    # Read the contents of the log file
    data = json.loads(f.read())

  # Aggregate sensor data in JSON format
  aggregated_data = {}
  for device in data['devices']:
    aggregated_data[device['id']] = {
      'temperature': sum(device['temperature']),
      'humidity': sum(device['humidity']),
      'pressure': sum(device['pressure']),
    }

  # Filter out anomalies using statistical models
  for device_id, data in aggregated_data.items():
    temperature = data['temperature']
    humidity = data['humidity']
    pressure = data['pressure']
    if abs(temperature - mean(temperature)) > 3 or abs(humidity - mean(humidity)) > 3 or abs(pressure - mean(pressure)) > 3:
      logging.warning('Anomaly detected in device %s', device_id)
      continue

  # Store the cleaned data in a distributed database system
  with psycopg2.connect(db_connection_string) as conn:
    cur = conn.cursor()
    for device_id, data in aggregated_data.items():
      query = 'INSERT INTO sensor_readings (device_id, temperature, humidity, pressure) VALUES (%s, %s, %s, %s)'
      cur.execute(query, (device_id, data['temperature'], data['humidity'], data['pressure']))
    conn.commit()

# Define the function for processing log files concurrently
def process_log_files():
  # Create a list of log file paths
  log_file_paths = ['/path/to/log1', '/path/to/log2', '/path/to/log3']

  # Create a queue to store the log files
  queue = deque(log_file_paths)

  # Create a list of threads for processing the log files
  threads = []
  for _ in range(num_threads):
    t = threading.Thread(target=process_log, args=(queue.popleft(),))
    threads.append(t)

  # Start the threads and join them to ensure they are all completed
  for t in threads:
    t.start()
  for t in threads:
    t.join()
```
Here is an example of a JavaScript function that fetches weather data for a list of cities from a third-party API, updating the UI of a web application with the fetched data:
```
function fetchWeatherData(cities) {
  // Create a queue to store the API responses
  const queue = [];

  // Fetch weather data for each city in parallel
  cities.forEach((city) => {
    // Set up an API call with retry logic and rate limiting
    fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=YOUR_API_KEY`)
      .then((response) => {
        // Check if the response is successful
        if (response.ok) {
          // Cache the weather data in the queue
          const weatherData = response.json();
          queue.push(weatherData);
          // Update the UI with the fetched weather data
          updateUIWithWeatherData(queue);
        } else {
          // Check if the API call has failed due to rate limiting
          if (response.status === 429) {
            // Pause for a short period of time before retrying the API call
            setTimeout(() => fetchWeatherData(cities), 1000);
          } else {
            // Log an error message
            console.error('Failed to fetch weather data from API:', response.statusText);
          }
        }
      })
      .catch((error) => {
        // Log an error message
        console.error('Error occurred while fetching weather data:', error);
      });
  });
}
