const { threadPool } = require('threadpool');
const { CacheManager } = require('cachemgr');
const { RateLimiter, Queue } = require('ratelimit');

const app = express();
app.use(express.json());

// Set up cache manager
const cacheMgr = new CacheManager();
cacheMgr.addCache('weather-data', 'memory', {
  size: 100,
  maxAge: 60 * 1000 // 1 minute
});

// Set up rate limiter
const rateLimiter = new RateLimiter({
  concurrentLimit: 50,
  rateLimit: 20,
  burstLimit: 30,
  retryLimit: 5,
  retryDelay: 1000 // 1 second
});

// Set up thread pool
const threadPool = new ThreadPool({
  size: 4,
  maxThreads: 8,
  minThreads: 2,
  idleTimeout: 60 * 1000 // 1 minute
});

// API Endpoint for fetching weather data
app.get('/weather', (req, res) => {
  const { lat, lon } = req.query;
  if (!lat || !lon) {
    return res.status(400).json({ error: 'Missing required query parameters' });
  }

  // Check cache for weather data
  const cacheKey = `weather-data-${lat}-${lon}`;
  const cachedData = cacheMgr.get(cacheKey);
  if (cachedData) {
    return res.json({ success: true, data: cachedData });
  }

  // Fetch weather data from primary API
  const primaryApiUrl = `https://api.openweathermap.org/data/2.5/weather?lat=${lat}&lon=${lon}`;
  axios.get(primaryApiUrl)
    .then((response) => {
      if (response.status === 200 && response.data.cod === '200') {
        // Cache weather data for next 1 minute
        cacheMgr.set(cacheKey, response.data);
        return res.json({ success: true, data: response.data });
      } else {
        // Fallback to secondary API in case of error or invalid response
        const fallbackApiUrl = `https://api.darksky.net/forecast/${process.env.DARKSKY_API_KEY}/${lat},${lon}`;
        axios.get(fallbackApiUrl)
          .then((response) => {
            if (response.status === 200 && response.data.cod === '200') {
              // Cache weather data for next 1 minute
              cacheMgr.set(cacheKey, response.data);
              return res.json({ success: true, data: response.data });
            } else {
              return res.status(500).json({ error: 'Failed to fetch weather data' });
            }
          })
          .catch((error) => {
            console.log(`Error fetching weather data from secondary API: ${error}`);
            return res.status(500).json({ error: 'Failed to fetch weather data' });
          });
      }
    })
    .catch((error) => {
      console.log(`Error fetching weather data from primary API: ${error}`);
      return res.status(500).json({ error: 'Failed to fetch weather data' });
