// Function to handle request and generate response
void handle_request(int id, int argc, char **argv) {
    char *data = fetch_data(argv[0], argc - 1, &argv[1]);
    if (data == NULL) {
        log_error("Error while fetching data");
        release_db_connection(id);
        return;
    }
    generate_report(data);
    release_db_connection(id);
}

// Function to handle batch request and generate response for each item
