    db_pool = malloc(num_threads * sizeof(sqlite3*));
    for (int i = 0; i < num_threads; i++) {
        db_pool[i] = sqlite3_open("mydatabase");
    }
    db_conds = malloc(num_threads * sizeof(pthread_cond_t));
