```java
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import com.fasterxml.jackson.databind.ObjectMapper;

import redis.clients.jedis.JedisPool;

@Service
public class InventoryService {
    @Autowired
    private KafkaProducer<String, String> kafkaProducer;

    @Autowired
    private JedisPool jedisPool;

    private Map<Integer, Long> stockLevels = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newCachedThreadPool();

    public List<InventoryItem> getItems() {
        return inventoryRepository.findAll();
    }

    public InventoryItem getItem(int id) {
        return inventoryRepository.findById(id);
    }

    public void updateStockLevels(List<InventoryItem> items) {
        for (InventoryItem item : items) {
            executorService.submit(() -> {
                try {
                    Long stockLevel = jedisPool.getResource().zScore("stock-levels", String.valueOf(item.getId()));
                    if (stockLevel == null) {
                        // Item not in cache, fetch from database
                        InventoryItem dbItem = inventoryRepository.findById(item.getId());
                        stockLevel = dbItem.getStockLevel();
                    }

                    jedisPool.getResource().zAdd("stock-levels", item.getId(), stockLevel);
                } catch (Exception e) {
                    // Handle error
                }
            });
        }
    }

    public void updateStockLevel(int id, long newStockLevel) {
        InventoryItem item = inventoryRepository.findById(id);
        if (item != null) {
            jedisPool.getResource().zAdd("stock-levels", id, newStockLevel);
        }
    }

    public void handleTransaction(int id, int quantity) {
        InventoryItem item = inventoryRepository.findById(id);
        if (item != null && item.getStockLevel() >= quantity) {
            try {
                // Update stock levels in database
                item.setStockLevel(item.getStockLevel() - quantity);
                inventoryRepository.save(item);

                // Update cache
                jedisPool.getResource().zAdd("stock-levels", id, item.getStockLevel());

                // Send transaction notification to payment gateway
                kafkaProducer.send(new ProducerRecord<String, String>("transactions", new ObjectMapper().writeValueAsString(item)));
            } catch (Exception e) {
                // Handle error
            }
        }
    }
}

