public class LoggingExample {
  private static final String ERROR_LOG = "error.log";
  private static final String INFO_LOG = "info.log";

  public static void main(String[] args) {
    // Read configuration file
    Map<String, String> config = readConfigFile();

    // Set log levels and file paths dynamically
    int errorLogLevel = Integer.parseInt(config.get("error_log_level"));
    File errorLogFile = new File(config.get("error_log_file"));
    int infoLogLevel = Integer.parseInt(config.get("info_log_level"));
    File infoLogFile = new File(config.get("info_log_file"));

    // Check and delete error log file if it exists
    if (errorLogFile.exists()) {
      errorLogFile.delete();
    }

    // Execute a series of commands using Runtime.getRuntime().exec()
    List<String> commands = Arrays.asList("command1", "command2", "command3");
    for (String command : commands) {
      try {
        Process process = Runtime.getRuntime().exec(command, null, new File("."));
        logStream(process.getInputStream(), INFO_LOG, infoLogLevel);
        logStream(process.getErrorStream(), ERROR_LOG, errorLogLevel);
        int exitCode = process.waitFor();
        if (exitCode != 0) {
          // Handle command execution errors gracefully
          System.err.println("Command " + command + " exited with code " + exitCode);
        }
      } catch (IOException | InterruptedException e) {
        // Handle I/O errors and thread interruptions gracefully
        System.err.println("Error executing command: " + e.getMessage());
      }
    }
  }

  private static void logStream(InputStream stream, String logFile, int logLevel) {
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream))) {
      String line;
      while ((line = reader.readLine()) != null) {
        // Format and log the message according to the severity level
        if (logLevel >= 1) {
          System.out.println("[" + new Date() + "] " + line);
        } else {
          System.err.println("[" + new Date() + "] " + line);
        }
      }
    } catch (IOException e) {
      // Handle I/O errors gracefully
      System.err.println("Error reading from stream: " + e.getMessage());
    }
  }

  private static Map<String, String> readConfigFile() {
    // Read configuration file using FileReader and BufferedReader
    try (FileReader reader = new FileReader("config.properties");
            BufferedReader bufferedReader = new BufferedReader(reader)) {
      Map<String, String> config = new HashMap<>();
      String line;
      while ((line = bufferedReader.readLine()) != null) {
        // Parse the configuration file and populate the map
        if (line.startsWith("#") || line.isBlank()) {
          continue;
        }
        String[] keyValue = line.split("=");
        config.put(keyValue[0], keyValue[1]);
      }
      return config;
    } catch (FileNotFoundException e) {
      // Handle file not found errors gracefully
      System.err.println("Error reading configuration file: " + e.getMessage());
    } catch (IOException e) {
      // Handle I/O errors gracefully
      System.err.println("Error reading configuration file: " + e.getMessage());
    }
    return null;
  }
}
