namespace WebSiteManagement
{
    public class WebsiteManager
    {
        private readonly string _directoryPath;
        private readonly string _siteName;
        private readonly string _webConfigFilePath;
        private readonly Process _process;
        private readonly object _lock = new object();
        private bool _isRunning;

        public WebsiteManager(string directoryPath, string siteName)
        {
            if (string.IsNullOrEmpty(directoryPath))
                throw new ArgumentException("Directory path cannot be empty", nameof(directoryPath));

            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"Directory '{directoryPath}' does not exist");

            _directoryPath = directoryPath;
            _siteName = siteName;
            _webConfigFilePath = Path.Combine(_directoryPath, "web.config");
        }

        public void StartWebsite()
        {
            lock (_lock)
            {
                if (!_isRunning)
                {
                    if (File.Exists(_webConfigFilePath))
                    {
                        _process = new Process();
                        _process.StartInfo.FileName = "httpd"; // or other web server executable based on the presence of specific files (e.g., `applicationHost.config` for IIS)
                        _process.StartInfo.Arguments = "-k start";
                        _process.StartInfo.UseShellExecute = false;
                        _process.StartInfo.RedirectStandardOutput = true;
                        _process.Start();
                        _isRunning = true;
                    }
                    else
                    {
                        // log error and return null if web.config file is missing
                        Console.WriteLine($"Website '{_directoryPath}' does not have a valid 'web.config' file");
                        return;
                    }
                }
            }
        }

        public void StopWebsite()
        {
            lock (_lock)
            {
                if (_isRunning)
                {
                    _process.Kill();
                    _isRunning = false;
                }
            }
        }

        public void RestartWebsite()
        {
            StopWebsite();
            StartWebsite();
        }

        private bool IsWebsiteRunning()
        {
            return _process != null && _process.HasExited == false;
        }

        public static WebsiteManager Load(string directoryPath, string siteName)
        {
            if (string.IsNullOrEmpty(directoryPath))
                throw new ArgumentException("Directory path cannot be empty", nameof(directoryPath));

            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"Directory '{directoryPath}' does not exist");

            var websiteManager = new WebsiteManager(directoryPath, siteName);

            return websiteManager;
        }

        public static void Save(WebsiteManager websiteManager)
        {
            if (websiteManager == null)
                throw new ArgumentNullException(nameof(websiteManager));

            // save website manager details to a configuration management system (e.g., database, file)
        }

        public static WebsiteManager LoadFromConfiguration()
        {
            // load website manager details from a configuration management system (e.g., database, file)
            return new WebsiteManager(directoryPath, siteName);
        }
    }
}
