$logMessage = "Environment: {$currentEnvironment}\nConfiguration File: {$configFilePath}\n";
foreach ($config as $key => $value) {
    $logMessage .= "{$key}: {$value}\n";
}
\file_put_contents('logs/application.log', $logMessage, FILE_APPEND);

// Cache parsed configuration files to avoid repeatedly parsing the same file
$cache = new ArrayObject();
if ($cache->offsetExists($configFilePath)) {
    $config = $cache->offsetGet($configFilePath);
} else {
    $config = json_decode(file_get_contents($configFilePath), true);
    $cache->offsetSet($configFilePath, $config);
}

// Dynamically configure the application using the loaded configuration file
foreach ($config as $key => $value) {
    putenv("{$key}={$value}");
}
