import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

import org.apache.http.client.HttpClient;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class PokemonService {
    private static final String API_ENDPOINT = "https://pokeapi.co/api/v2/pokemon/";
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final CloseableHttpClient HTTP_CLIENT = HttpClients.createDefault();

    private LoadingCache<Integer, Pokemon> pokemonCache;

    public PokemonService() {
        this.pokemonCache = CacheBuilder.newBuilder()
                .expireAfterWrite(5, TimeUnit.MINUTES)
                .build(new CacheLoader<Integer, Pokemon>() {
                    @Override
                    public Pokemon load(Integer id) throws Exception {
                        return retrievePokemon(id);
                    }
                });
    }

    private Pokemon retrievePokemon(Integer id) throws Exception {
        String url = API_ENDPOINT + id;
        HttpGet request = new HttpGet(url);
        HttpResponse response = HTTP_CLIENT.execute(request);
        if (response.getStatusLine().getStatusCode() != 200) {
            throw new RuntimeException("Failed to retrieve Pokemon data for ID " + id);
        }
        String jsonResponse = EntityUtils.toString(response.getEntity());
        return OBJECT_MAPPER.readValue(jsonResponse, Pokemon.class);
    }

    public Pokemon getPokemon(Integer id) {
        try {
            return pokemonCache.get(id);
        } catch (Exception e) {
            throw new RuntimeException("Failed to retrieve Pokemon data for ID " + id, e);
        }
    }
}
