using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Xml.XPath;
using NoSQLDatabase;

namespace SensorDataParser
{
    public class Program
    {
        private static readonly Dictionary<string, string> DeviceMetadata = new Dictionary<string, string>();

        public static async Task Main(string[] args)
        {
            // Initialize device metadata from a file or database
            await InitializeDeviceMetadata();

            // Create a list of IoT devices to parse data for
            var devices = new List<IoTDevice>
            {
                new IoTDevice("device1", "sensor1"),
                new IoTDevice("device2", "sensor2"),
                new IoTDevice("device3", "sensor3")
            };

            // Create a list of XML documents containing sensor data
            var xmlDocuments = new List<XDocument>
            {
                XDocument.Parse("<root><device1><sensor1>10</sensor1></device1><device2><sensor2>20</sensor2></device2><device3><sensor3>30</sensor3></device3></root>"),
                XDocument.Parse("<root><device1><sensor1>15</sensor1></device1><device2><sensor2>30</sensor2></device2><device3><sensor3>40</sensor3></device3></root>"),
                XDocument.Parse("<root><device1><sensor1>20</sensor1></device1><device2><sensor2>25</sensor2></device2><device3><sensor3>50</sensor3></device3></root>")
            };

            // Parse the XML documents and extract the most recent sensor reading for each device
            var sensorReadings = new List<SensorReading>();
            foreach (var device in devices)
            {
                var xmlDocument = xmlDocuments.FirstOrDefault(x => x.Root.Name == device.Name);
                if (xmlDocument != null)
                {
                    var sensorValue = xmlDocument.XPathSelectElement($"//{device.Name}/{device.Sensor}");
                    if (sensorValue != null)
                    {
                        sensorReadings.Add(new SensorReading(device, sensorValue.Value));
                    }
                }
            }

            // Store the sensor readings in a NoSQL database
            await using var db = new NoSQLDatabase();
            foreach (var reading in sensorReadings)
            {
                await db.AddAsync(reading);
            }
        }

        private static async Task InitializeDeviceMetadata()
        {
            // Fetch device metadata from a file or database and add it to the dictionary
            DeviceMetadata = new Dictionary<string, string>
            {
                {"device1", "sensor1"},
                {"device2", "sensor2"},
                {"device3", "sensor3"}
            };
        }
    }

    public class IoTDevice
    {
        public string Name { get; set; }
        public string Sensor { get; set; }

        public IoTDevice(string name, string sensor)
        {
            Name = name;
            Sensor = sensor;
        }
    }

    public class SensorReading
    {
        public IoTDevice Device { get; set; }
        public double Value { get; set; }

        public SensorReading(IoTDevice device, double value)
        {
            Device = device;
            Value = value;
        }
    }
}
