using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;

namespace DynamicCryptoGenerator
{
    public class RandomNumberGenerator
    {
        private readonly OpenSSL.LibraryLoader _libraryLoader = new OpenSSL.LibraryLoader();
        private readonly Dictionary<string, Func<int>> _distributions = new Dictionary<string, Func<int>>();

        // Constructor to initialize the library loader and set up the distribution dictionary
        public RandomNumberGenerator()
        {
            _libraryLoader.LoadLibrary("openssl");
            _distributions["gaussian"] = Gaussian;
            _distributions["uniform"] = Uniform;
            _distributions["exponential"] = Exponential;
        }

        // Method to generate a random number within a specified range, both inclusively and exclusively
        public int Next(int minValue, int maxValue)
        {
            return UnityEngine.Random.Range(minValue, maxValue + 1);
        }

        // Method to generate a random number within a specified range, both inclusively and exclusively, with a custom distribution
        public int NextCustom(int minValue, int maxValue, string distribution)
        {
            if (!_distributions.ContainsKey(distribution))
                throw new ArgumentException("Invalid distribution type");
            return _distributions[distribution](minValue, maxValue);
        }

        // Method to generate a random number within a specified range, both inclusively and exclusively, with a custom distribution and parameters
        public int NextCustom(int minValue, int maxValue, string distribution, params object[] parameters)
        {
            if (!_distributions.ContainsKey(distribution))
                throw new ArgumentException("Invalid distribution type");
            return _distributions[distribution](minValue, maxValue, parameters);
        }

        // Gaussian distribution method
        private int Gaussian(int minValue, int maxValue)
        {
            var random = UnityEngine.Random.Range(minValue, maxValue + 1);
            return (int)(random * Mathf.Exp(-0.5f));
        }

        // Uniform distribution method
        private int Uniform(int minValue, int maxValue)
        {
            var random = UnityEngine.Random.Range(minValue, maxValue + 1);
            return (int)(random * Mathf.Exp(-0.5f));
        }

        // Exponential distribution method
        private int Exponential(int minValue, int maxValue)
        {
            var random = UnityEngine.Random.Range(minValue, maxValue + 1);
            return (int)(random * Mathf.Exp(-0.5f));
        }
    }
}
