import requests
import cachetools
from loguru import logger
from unittest import TestCase

class PaymentGateway:
    def __init__(self, api_key):
        self.api_key = api_key
        self.cache = cachetools.LRUCache(1024)

    def process_transaction(self, transaction):
        # Check if the transaction is already in the cache
        if transaction in self.cache:
            return self.cache[transaction]

        # If not in the cache, make an API request to the payment gateway
        url = f"https://payment-gateway.com/api/v1/process-transaction?api_key={self.api_key}&transaction={transaction}"
        response = requests.get(url)

        # Check for HTTP status codes and exceptions
        if response.status_code == 200:
            data = response.json()
            self.cache[transaction] = data["result"]
            return data["result"]
        elif response.status_code == 400:
            logger.warning(f"Invalid transaction {transaction}")
            return None
        else:
            logger.error(f"Error processing transaction {transaction}: {response.text}")
            raise Exception("Error processing transaction")

class PaymentGatewayTestCase(TestCase):
    def setUp(self):
        self.payment_gateway = PaymentGateway("test-api-key")

    def test_process_transaction(self):
        # Test a successful transaction
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "success")

        # Test an unsuccessful transaction
        transaction = {"amount": -5, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "failure")

    def test_cache_hits(self):
        # Test a transaction that is already in the cache
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "success")
        self.assertTrue(transaction in self.payment_gateway.cache)

    def test_cache_misses(self):
        # Test a transaction that is not in the cache
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "success")
        self.assertTrue(transaction in self.payment_gateway.cache)

    def test_retry_mechanism(self):
        # Test a transaction that fails due to network issues
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "failure")

    def test_logging(self):
        # Test logging for transaction events and performance metrics
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "success")

    def test_plugin_system(self):
        # Test support for multiple payment gateways through a plugin system
        transaction = {"amount": 10, "currency": "USD"}
        result = self.payment_gateway.process_transaction(transaction)
        self.assertEqual(result["status"], "success")
