#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

struct tiff_info {
    int bits_per_sample;
    int samples_per_pixel;
};

int crossover(void* ptr) {
    struct connection *conn = (struct connection*)ptr;
    char* password = conn->password;
    char* title = conn->title;
    void (*callback)(void) = conn->callback;

    if (!password || !title || !callback) {
        return -1; // Error: Password, title, and callback must be set.
    }

    TIFF *tiff = TIFFOpen(conn->file_name, "r");
    if (tiff == NULL) {
        return -2; // Error: Could not open TIFF file.
    }

    uint16 bps = 0;
    uint16 spp = 0;

    int ret = TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bps);
    if (ret == 0) {
        return -3; // Error: Could not get bits per sample.
    }

    ret = TIFFGetField(tiff, TIFFTAG_SAMPLES_PER_PIXEL, &spp);
    if (ret == 0) {
        return -4; // Error: Could not get samples per pixel.
    }

    int extra_samples = 0;
    uint16 *extra_sample_info = NULL;

    ret = TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extra_samples, &extra_sample_info);
    if (ret == 0) {
        return -5; // Error: Could not get extra samples.
    }

    struct tiff_info info = {bps, spp};

    if (bps != 1 && bps != 2 && bps != 4 && bps != 8 && bps != 16) {
        return -6; // Error: Bits per sample not supported.
    }

    TIFFClose(tiff);

    callback(info, extra_samples, extra_sample_info);

    return 0;
}
```
