// Function to safely copy a string into a buffer
int safeStringCopy(const char* src, char* dest, size_t destSize) {
    // Check if the source string is longer than the destination buffer
    if (strlen(src) > destSize - 1) {
        // Truncate the source string to fit within the bounds of the destination buffer
        strncpy(dest, src, destSize - 1);
        // Append a null terminator to the end of the copied string
        dest[destSize - 1] = '\0';
        // Log an error message indicating that the string was truncated
        logError("String truncated due to buffer overflow");
        return destSize - 1;
    } else {
        // Copy the source string into the destination buffer
        strcpy(dest, src);
        // Return the number of characters copied including the null terminator
        return strlen(src) + 1;
    }
}
```
