  return new Promise((resolve, reject) => {
    const cacheKey = `weather-${location}`;
    if (cache.has(cacheKey)) {
      return resolve(cache.get(cacheKey));
    }
    https.get(apiEndpoints.weather + '&q=' + location, (res) => {
