        }
      });
    }).on('error', (err) => {
      reject(new Error(`Error fetching weather data for ${location}: ${err}`));
    });
  });
}
function getClimateData(location) {
  return new Promise((resolve, reject) => {
    const cacheKey = `climate-${location}`;
    if (cache.has(cacheKey)) {
      return resolve(cache.get(cacheKey));
    }
    https.get(apiEndpoints.climate + '&q=' + location, (res) => {
