const fs = require('fs');
const path = require('path');

function readDirectory(directory) {
  return new Promise((resolve, reject) => {
    fs.readdir(directory, (err, files) => {
      if (err) {
        reject(err);
        return;
      }

      const filePromises = [];
      for (const file of files) {
        const filePath = path.join(directory, file);
        if (!file.startsWith('.')) {
          filePromises.push(readFileContents(filePath));
        }
      }

      Promise.all(filePromises).then((contents) => {
        resolve({ contents });
      }).catch((err) => {
        console.warn(`Error reading directory: ${directory}`);
        reject(err);
      });
    });
  });
}

function readFileContents(filePath) {
  return new Promise((resolve, reject) => {
    fs.readFile(filePath, (err, contents) => {
      if (err) {
        reject(err);
        return;
      }

      resolve({ file: path.basename(filePath), contents });
    });
  });
}

function skipLargeFiles(contents) {
  const largeFileLimit = 1024 * 1024; // 1MB
  return contents.filter((content) => content.size < largeFileLimit);
}
