using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;
using Microsoft.Extensions.Logging;
using MyMiddleware.Models;
using MyMiddleware.Helpers;

namespace MyMiddleware.Controllers
{
    [ApiController]
    [Route("api/v1/clinics")]
    public class ClinicController : ControllerBase
    {
        private readonly ILogger<ClinicController> _logger;
        private readonly ICmsClient _cmsClient;

        public ClinicController(ILogger<ClinicController> logger, ICmsClient cmsClient)
        {
            _logger = logger;
            _cmsClient = cmsClient;
        }

        [HttpPost("update")]
        public async Task<IActionResult> UpdateClinicStatus([FromBody] UpdateClinicStatusRequest request)
        {
            var clinicId = request.ClinicId;
            var newStatus = request.NewStatus;
            var lastModifiedIpAddress = request.LastModifiedIpAddress;
            var lastModifiedByUserId = request.LastModifiedByUserId;

            // Validate input parameters
            if (string.IsNullOrEmpty(clinicId))
                return BadRequest("Clinic ID cannot be empty");

            if (!Enum.TryParse<Status>(newStatus, out var status) || status == Status.Unknown)
                return BadRequest($"Invalid new status: {newStatus}");

            if (string.IsNullOrEmpty(lastModifiedIpAddress))
                lastModifiedIpAddress = HttpContext.Connection.RemoteIpAddress.ToString();

            // Fetch clinic details from CMS
            var clinicDetails = await _cmsClient.GetClinicDetailsAsync(clinicId);
            if (clinicDetails == null)
                return NotFound($"Clinic with ID {clinicId} not found");

            // Update clinic status in database
            var updatedClinic = await _database.UpdateClinicStatusAsync(clinicId, newStatus, lastModifiedIpAddress, lastModifiedByUserId);
            if (updatedClinic == null)
                return BadRequest($"Failed to update clinic status for ID {clinicId}");

            // Log update details
            _logger.LogInformation($"Updated clinic status for ID {clinicId}: {status}");

            // Send email notification (if configured)
            if (!string.IsNullOrEmpty(_config["Email:Sender"]))
            {
                var subject = $"Clinic status updated - ID {clinicId}";
                var message = $"The clinic status for ID {clinicId} has been updated to {status} by user {lastModifiedByUserId}. The previous status was {updatedClinic.Status}.";
                await _emailService.SendEmailAsync(_config["Email:Sender"], _config["Email:Recipients"], subject, message);
            }

            // Return response object with updated clinic details and success status
            return Ok(new UpdateClinicStatusResponse
            {
                Success = true,
                ClinicDetails = updatedClinic,
                ErrorMessage = null
            });
        }
    }
}
