from concurrent.futures import ThreadPoolExecutor

logger = logging.getLogger(__name__)

class BatchProcessor:
    def __init__(self, pool_size=5):
        self.pool_size = pool_size
        self.executor = ThreadPoolExecutor(max_workers=pool_size)

    def process_batch(self, review_streams):
        batch_size = math.ceil(len(review_streams) / self.pool_size)
        futures = []
        for i in range(0, len(review_streams), batch_size):
            future = self.executor.submit(self._process_batch, review_streams[i:i+batch_size])
            futures.append(future)
        return [future.result() for future in futures]

    def _process_batch(self, batch):
        results = []
        for review in batch:
            result = self._fetch_sentiment_score(review)
            if result is not None:
                results.append(result)
        return results

    def _fetch_sentiment_score(self, review):
