class ReviewStream:
    def __init__(self, stream_id, api_url, api_key):
        self.stream_id = stream_id
        self.api_url = api_url
        self.api_key = api_key
        self.review_queue = []
        self.fetching_in_progress = False

    def add_review(self, review):
        self.review_queue.append(review)
        if not self.fetching_in_progress:
            self._start_fetching()

    def _start_fetching(self):
        if len(self.review_queue) == 0:
            return
        self.fetching_in_progress = True
        batch = []
        for i in range(min(len(self.review_queue), BatchProcessor.pool_size)):
            batch.append(self.review_queue.pop(0))
        BatchProcessor().process_batch(batch).then(self._handle_results)

    def _handle_results(self, results):
        for result in results:
            logger.info(f"Stream {self.stream_id} processed sentiment score {result}")
        if len(self.review_queue) > 0:
            self._start_fetching()
        else:
            self.fetching_in_progress = False
