using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;
using MongoDB.Driver;
using MongoDB.Bson;
using Microsoft.ML;

namespace RealTimeDataProcessingPipeline
{
    public class Program
    {
        private static IConfiguration _configuration;
        private static ILogger<Program> _logger;
        private static RabbitMQConnectionManager _rabbitMqConnectionManager;
        private static MongoDBConnectionManager _mongodbConnectionManager;
        private static MLContext _mlContext;

        public static async Task Main(string[] args)
        {
            _configuration = new ConfigurationBuilder()
                .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
                .Build();

            _logger = LoggerFactory.Create(_configuration).CreateLogger<Program>();

            _rabbitMqConnectionManager = new RabbitMQConnectionManager(_configuration["RabbitMQHost"], _configuration["RabbitMQPort"]);
            _mongodbConnectionManager = new MongoDBConnectionManager(_configuration["MongoDBHost"], _configuration["MongoDBPort"]);
            _mlContext = new MLContext();

            await StartConsumingAsync();
        }

        private static async Task StartConsumingAsync()
        {
            var connectionFactory = new ConnectionFactory
            {
                HostName = _rabbitMqConnectionManager.Host,
                Port = _rabbitMqConnectionManager.Port
            };

            using (var connection = await connectionFactory.CreateConnectionAsync())
            {
                connection.CallbackException += (sender, eventArgs) =>
                {
                    _logger.LogError(eventArgs.Exception, "RabbitMQ connection failed");
                };

                connection.RecoverySucceeded += (sender, eventArgs) =>
                {
                    _logger.LogInformation("RabbitMQ connection recovered");
                };

                var channel = await connection.CreateModelAsync();

                channel.BasicQos(0, 1, false);

                var queueName = "data";

                if (channel.QueueDeclarePassive(queueName) == false)
                {
                    _logger.LogInformation("Creating RabbitMQ queue {QueueName}", queueName);
                    channel.QueueDeclare(queue: queueName, durable: true, exclusive: false, autoDelete: false, arguments: null);
                }

                var consumer = new EventingBasicConsumer(channel);

                consumer.Received += async (model, ea) =>
                {
                    var body = ea.Body;
                    var message = Encoding.UTF8.GetString(body.ToArray());

                    try
                    {
                        var deviceData = JsonConvert.DeserializeObject<DeviceData>(message);
                        _logger.LogInformation("Received data from device {DeviceName}", deviceData.DeviceName);

                        var parsedData = ParseData(deviceData);
                        if (parsedData != null)
                        {
                            await WriteToMongoDBAsync(parsedData);
                        }
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Failed to process data");
                    }
                };

                channel.BasicConsume(queue: queueName, noAck: true, consumer: consumer);
            }
        }

        private static async Task WriteToMongoDBAsync(IEnumerable<DeviceData> parsedData)
        {
            var collection = _mongodbConnectionManager.GetCollection("device_data");

            foreach (var deviceData in parsedData)
            {
                try
                {
                    var deviceName = deviceData.DeviceName;
                    var dataType = deviceData.DataType;
                    var dataValue = deviceData.DataValue;

                    var document = new BsonDocument
                    {
                        { "device_name", deviceName },
                        { "data_type", dataType },
                        { "data_value", dataValue }
                    };

                    await collection.InsertOneAsync(document);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to write data to MongoDB");
                }
            }
        }

        private static IEnumerable<DeviceData> ParseData(DeviceData deviceData)
        {
            var parsedData = new List<DeviceData>();

            switch (deviceData.Protocol)
            {
                case ProtocolType.Json:
                    parsedData.AddRange(ParseJsonData(deviceData));
                    break;
                case ProtocolType.Csv:
                    parsedData.AddRange(ParseCsvData(deviceData));
                    break;
                case ProtocolType.Xml:
                    parsedData.AddRange(ParseXmlData(deviceData));
                    break;
            }

            return parsedData;
        }

        private static IEnumerable<DeviceData> ParseJsonData(DeviceData deviceData)
        {
            var jsonText = deviceData.DataValue as string;
            if (string.IsNullOrEmpty(jsonText))
            {
                return Enumerable.Empty<DeviceData>();
            }

            try
            {
                var parsedData = JsonConvert.DeserializeObject<List<DeviceData>>(jsonText);
                return parsedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to parse JSON data");
                return Enumerable.Empty<DeviceData>();
            }
        }

        private static IEnumerable<DeviceData> ParseCsvData(DeviceData deviceData)
        {
            var csvText = deviceData.DataValue as string;
            if (string.IsNullOrEmpty(csvText))
            {
                return Enumerable.Empty<DeviceData>();
            }

            try
            {
                var parsedData = CsvParser.ParseCsv(csvText);
                return parsedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to parse CSV data");
                return Enumerable.Empty<DeviceData>();
            }
        }

        private static IEnumerable<DeviceData> ParseXmlData(DeviceData deviceData)
        {
            var xmlText = deviceData.DataValue as string;
            if (string.IsNullOrEmpty(xmlText))
            {
                return Enumerable.Empty<DeviceData>();
            }

            try
            {
                var parsedData = XmlParser.ParseXml(xmlText);
                return parsedData;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to parse XML data");
                return Enumerable.Empty<DeviceData>();
            }
        }
    }
}
```
