public class UpdateUserProfile {
    private readonly HttpClient _httpClient;
    private readonly string _configFilePath;
    private readonly List<string> _userIds;
    private readonly Dictionary<string, object> _updatedProfileDetails;
    private readonly List<string> _cachedApiResults = new List<string>();
    private readonly object _lockObj = new object();

    public UpdateUserProfile(HttpClient httpClient, string configFilePath, List<string> userIds, Dictionary<string, object> updatedProfileDetails) {
        _httpClient = httpClient;
        _configFilePath = configFilePath;
        _userIds = userIds;
        _updatedProfileDetails = updatedProfileDetails;
    }

    public async Task ExecuteAsync() {
        // Load the configuration file and verify the directory paths and user IDs
        var config = LoadConfig(_configFilePath);
        if (config == null) {
            throw new Exception("Invalid configuration file path.");
        }
        var apiUrls = config["api_urls"] as Dictionary<string, object>;
        foreach (var userId in _userIds) {
            if (!VerifyUserId(userId)) {
                throw new Exception($"Invalid user ID: {userId}");
            }
        }

        // Update the profiles concurrently for each user
        var tasks = new List<Task>();
        foreach (var userId in _userIds) {
            tasks.Add(UpdateProfileAsync(userId, apiUrls));
        }
        await Task.WhenAll(tasks);
    }

    private async Task UpdateProfileAsync(string userId, Dictionary<string, object> apiUrls) {
        // Get the cached API result for the user ID, if available
        var cachedResult = _cachedApiResults.FirstOrDefault(x => x["userId"].ToString() == userId);
        if (cachedResult != null) {
            // If the cache is valid, use it to update the profile without calling the API again
            var updatedProfileDetails = JsonConvert.DeserializeObject<Dictionary<string, object>>(cachedResult["profile"].ToString());
            await UpdateUserProfileAsync(userId, updatedProfileDetails);
        } else {
            // If the cache is invalid or missing, call the API to retrieve the latest profile details
            var apiUrl = apiUrls["update_user_profile"] as string;
            var request = new HttpRequestMessage(HttpMethod.Post, apiUrl) { Content = new StringContent($"{{ \"userId\": \"{userId}\", \"updatedProfileDetails\": {JsonConvert.SerializeObject(_updatedProfileDetails)} }}") };
            var response = await _httpClient.SendAsync(request);
            if (response.StatusCode == HttpStatusCode.OK) {
                // Cache the API result for future use
                cachedResult = new Dictionary<string, object>();
                cachedResult["userId"] = userId;
                cachedResult["profile"] = await response.Content.ReadAsStringAsync();
                lock (_lockObj) {
                    _cachedApiResults.Add(cachedResult);
                }
            } else {
                // If the API call fails, log the error and continue with updating the profile without calling the API again
                var errorMessage = await response.Content.ReadAsStringAsync();
                Console.WriteLine($"Error updating user profile for user ID: {userId}. Error message: {errorMessage}");
            }
        }
    }

    private async Task UpdateUserProfileAsync(string userId, Dictionary<string, object> updatedProfileDetails) {
        // Validate the updated profile details and ensure they are correct and valid
        var validatedUpdatedProfileDetails = ValidateUpdatedProfileDetails(updatedProfileDetails);
        if (validatedUpdatedProfileDetails == null) {
            throw new Exception($"Invalid updated profile details for user ID: {userId}");
        }

        // Update the user's profile in the local storage
        var userProfile = LoadUserProfile(userId);
        userProfile.Update(updatedProfileDetails);
        SaveUserProfile(userProfile);

        // Notify relevant stakeholders about the updated profile details
        var notificationEmailAddress = config["notification_email_address"] as string;
        if (notificationEmailAddress != null) {
            await SendNotificationAsync($"{userId} - Updated profile details: {JsonConvert.SerializeObject(updatedProfileDetails)}");
        }
    }

