import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.tuple.Pair;
import org.eclipse.paho.client.mqttv3.*;
import org.springframework.context.annotation.Bean;
import org.springframework.stereotype.Component;

@Component
public class IoTAnomalyDetectionApplication {
  private static final String MQTT_BROKER_URL = "tcp://localhost:1883";
  private static final String MQTT_TOPIC_SUBSCRIBE = "/sensorData";
  private static final String MQTT_CLIENT_ID = "IoTAnomalyDetectionApplication";

  @Bean
  public MqttClient mqttClient() {
    return new MqttClient(MQTT_BROKER_URL, MQTT_CLIENT_ID);
  }

  @Bean
  public MqttConnectOptions mqttConnectOptions() {
    MqttConnectOptions options = new MqttConnectOptions();
    options.setCleanSession(true);
    options.setAutomaticReconnect(true);
    return options;
  }

  @Bean
  public MqttClientPersistence mqttClientPersistence() {
    return new MemoryPersistence();
  }

  @Bean
  public MqttSubscribeOptions mqttSubscribeOptions() {
    MqttSubscribeOptions options = new MqttSubscribeOptions();
    options.setTopics(List.of(MQTT_TOPIC_SUBSCRIBE));
    return options;
  }

  @Bean
  public MqttAsyncClient mqttAsyncClient() {
    return new MqttAsyncClient(mqttClient(), mqttConnectOptions(), mqttClientPersistence());
  }

  @Bean
  public MqttMessageHandler mqttMessageHandler() {
    return new MqttMessageHandler();
  }

  @Bean
  public IoTDeviceDataManager ioTDeviceDataManager() {
    return new IoTDeviceDataManager();
  }

  @Bean
  public AnomalyDetectionModelManager anomalyDetectionModelManager() {
    return new AnomalyDetectionModelManager();
  }

  @Bean
  public NotificationService notificationService() {
    return new NotificationService();
  }

  @Bean
  public MqttSubscription subscription() {
    return new MqttSubscription(mqttAsyncClient(), mqttMessageHandler(), ioTDeviceDataManager(), anomalyDetectionModelManager(), notificationService());
  }

  @Bean
  public MqttConnector mqttConnector() {
    return new MqttConnector(subscription());
  }

  @Bean
  public IoTDeviceMetadataManager ioTDeviceMetadataManager() {
    return new IoTDeviceMetadataManager();
  }

  @Bean
  public DeviceDataIntegration deviceDataIntegration() {
    return new DeviceDataIntegration(ioTDeviceMetadataManager(), anomalyDetectionModelManager());
  }
}
```
This code defines a Spring Boot application that uses the Eclipse Paho MQTT client to subscribe to an MQTT topic and process sensor data in real-time. It also includes functionality for dynamically loading different anomaly detection models based on device type and configuration parameters provided via a REST API, as well as integration with various external data sources for device metadata.

The application uses the `MqttClient` class from the Eclipse Paho MQTT client library to connect to an MQTT broker and subscribe to a specific topic. It also includes a `MqttMessageHandler` class that handles incoming messages from the MQTT topic, as well as a `IoTDeviceDataManager` class that manages the data processing pipeline for IoT devices.

The `AnomalyDetectionModelManager` class is responsible for loading and updating different anomaly detection models based on device type and configuration parameters provided via a REST API. It also includes functionality for evaluating the performance of different machine learning algorithms under varying data conditions.

The application also includes a `NotificationService` class that handles notifications for alerts, as well as a `DeviceDataIntegration` class that integrates with various external data sources for device metadata.

The code is designed to be scalable and support future expansion to include more IoT devices and models. It also includes robust error handling and clear diagnostics for edge cases and failed anomaly detections.

