        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_cipher(EVP_chacha20());
        EVP_add_digest(EVP_sha256());
        EVP_add_digest(EVP_sha384());
        EVP_add_digest(EVP_sha512());
    }

    void SendRequest(string url) {
        // Use Boost library to send GET request to server
        boost::asio::io_service io;
        boost::asio::ip::tcp::socket socket(io);
        boost::asio::ip::tcp::resolver resolver(io);
        boost::asio::connect(socket, resolver.resolve(url));
        boost::asio::write(socket, boost::asio::buffer("GET / HTTP/1.0\r\n"));
        boost::asio::read_until(socket, boost::asio::buffer(response), "\r\n");
    }

    string GetResponse() {
