        client.SendRequest(url);
        string response = client.GetResponse();
        if (response == "404 Not Found") {
            log.WriteLine("Error: API request failed for " + url);
        } else if (stoi(response) != i) {
            log.WriteLine("Warning: API request returned incorrect value for " + url);
        } else {
            log.WriteLine("Success: API request succeeded for " + url);
        }
    }

    // Override FindVmUuidFromMetadataIp function in InterfaceTable class test double
    table.FindVmUuidFromMetadataIp = [&](string ip) { return true; };

    // Maintain log of API requests and responses
    for (int i : array) {
        string url = "http://example.com/api/" + to_string(i);
        client.SendRequest(url);
