                await response.WriteAsync("Failed to generate report");
                return;
            }

            // Send the report back to the client
            response.ContentType = "application/pdf";
            response.Headers["Content-Disposition"] = $"attachment; filename=\"{report.Filename}\"";
            await response.WriteAsync(report.Data);
        }

        private static RateLimit CheckRateLimit(HttpRequest request, HttpResponse response)
        {
            // Get the IP address and user ID from the request parameters
            var ipAddress = request.Headers["X-Forwarded-For"].FirstOrDefault();
            var userId = request.Query["user_id"];

            if (string.IsNullOrEmpty(ipAddress) || string.IsNullOrEmpty(userId))
            {
                response.StatusCode = 400;
                await response.WriteAsync("Invalid IP address or user ID");
                return null;
            }

            // Check the rate limit for the IP address and user ID
            var rateLimit = _databaseContext.RateLimits.FirstOrDefault(rl => rl.IpAddress == ipAddress && rl.UserId == userId);
            if (rateLimit == null)
            {
                response.StatusCode = 403;
                await response.WriteAsync("Exceeded rate limit");
                return null;
            }

            // Update the rate limit with the current timestamp
            rateLimit.LastUpdated = DateTime.UtcNow;
            _databaseContext.SaveChanges();

            return rateLimit;
        }

