import json
from typing import Dict, Optional, Any

class JSONObject:
    def __init__(self, data: dict = None, schema: Optional[Dict] = None):
        self.data = {} if data is None else data
        self.schema = schema

    @staticmethod
    def from_json(json_str: str) -> 'JSONObject':
        return JSONObject(json.loads(json_str))

    @staticmethod
    def to_json(self) -> str:
        return json.dumps(self.data, indent=4)

    def validate(self, schema: Dict[str, Any]) -> bool:
        try:
            jsonschema.validate(self.data, schema)
            return True
        except jsonschema.ValidationError as e:
            print(f"Validation failed for JSON object {self}: {e}")
            return False

    def add_factory(self, id: str, factory: Callable[[Any], 'JSONObject']) -> None:
        if id in self.factories:
            raise KeyError(f"Factory with ID '{id}' already exists")
        self.factories[id] = factory

    def remove_factory(self, id: str) -> bool:
        try:
            del self.factories[id]
            return True
        except KeyError:
            return False

    def create_instance(self, id: str, data: Any) -> 'JSONObject':
        if id not in self.factories:
            raise KeyError(f"No factory with ID '{id}' found")
        return self.factories[id](data)
