import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.cassandra.db.marshal.CompositeType;
import org.apache.cassandra.index.Index;
import org.apache.cassandra.schema.Schema;
import org.apache.cassandra.service.StorageService;
import org.apache.cassandra.utils.ByteBufferUtil;
import org.apache.spark.streaming.api.java.*;
import org.apache.spark.streaming.kafka010.*;
import scala.collection.immutable.Set;
import scala.util.Try;

public class RealTimeDataIngestion {
  private static final String KEYSPACE_NAME = "real_time_data";
  private static final String TABLE_NAME = "ingested_data";
  private static final int MAX_THREADS = 10;
  private static final int RETRY_DELAY = 5000; // in milliseconds
  private static final int MAX_RETRIES = 3;

  public static void main(String[] args) {
    ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
    Schema schema = new Schema();
    schema.createKeyspaceIfNotExists(KEYSPACE_NAME, Set.empty(), Set.of());
    schema.createTableIfNotExists(KEYSPACE_NAME, TABLE_NAME,
            CompositeType.getInstance(ByteBufferUtil.bytes("id"), ByteBufferUtil.bytes("data")),
            Index.fullIndex(ByteBufferUtil.bytes("data")));

    StorageService.instance.initServer();

    KafkaConsumer<String, String> consumer = new KafkaConsumer<>(getKafkaProperties());
    consumer.subscribe(Set.of("my-topic"));

    SparkSession spark = SparkSession.builder().appName("RealTimeDataIngestion").master("local[*]").getOrCreate();

    JavaDStream<String> messages = spark.readStream()
            .format("kafka")
            .option("kafka.bootstrap.servers", "localhost:9092")
            .option("subscribe", "my-topic")
            .load()
            .selectExpr("CAST(value AS STRING)");

    messages.foreachRDD(rdd -> {
      Try<Void> result = rdd.forEachPartition(partition -> {
        partition.onClose(() -> {
          executor.shutdown();
          return null;
        });
        while (true) {
          if (!partition.hasNext()) {
            break;
          }
          String record = partition.next().getRecord();
          try {
            insertIntoDB(record);
          } catch (Exception e) {
            System.out.println("Error inserting record: " + record);
          }
        }
      });
    });
  }

  private static Properties getKafkaProperties() {
    Properties props = new Properties();
    props.put("bootstrap.servers", "localhost:9092");
    props.put("key.deserializer", StringDeserializer.class);
    props.put("value.deserializer", StringDeserializer.class);
    props.put("group.id", "my-group");
    return props;
  }

  private static void insertIntoDB(String record) {
    try {
      executor.submit(() -> {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
          try {
            StorageService.instance.getPartition(KEYSPACE_NAME, TABLE_NAME)
                    .put("id", ByteBufferUtil.bytes("1"), "data", record);
            return null;
          } catch (Exception e) {
            System.out.println("Error inserting record: " + record);
            retryCount++;
            if (retryCount < MAX_RETRIES) {
              try {
                Thread.sleep(RETRY_DELAY * retryCount);
              } catch (InterruptedException ex) {
                // ignore
              }
            }
          }
        }
      });
    } catch (Exception e) {
      System.out.println("Error inserting record: " + record);
    }
  }
}
