// Custom logging system functions
void logMessage(int level, const char *message);
int getLogLevel();

// Helper function to format a string with variable arguments
char* formatString(const char *format, va_list args) {
  // Allocate enough space for the formatted string
  int size = vsnprintf(NULL, 0, format, args);
  if (size < 0) {
    return NULL;
  }
  char* buffer = malloc(size + 1);
  if (!buffer) {
    return NULL;
  }

  // Format the string and store it in the buffer
  vsnprintf(buffer, size + 1, format, args);
  return buffer;
}

// Logs a message when a specific condition is met
void logCondition(int condition, const char *format, ...) {
  va_list args;
  va_start(args, format);

  // Check if the logging system is available and the formatted string is not too long
  if (condition && getLogLevel() != LOG_NONE && vsnprintf(NULL, 0, format, args) < 256) {
    char* message = formatString(format, args);
    logMessage(LOG_INFO, message);
    free(message);
  }

  va_end(args);
}
