                continue;
            }
            if (strcmp(env_var, "CDN_URL") == 0) {
                cdn_config.url = env_val;
            } else if (strcmp(env_var, "CDN_ENABLED") == 0) {
                cdn_config.enabled = strcmp(env_val, "true") == 0 ? true : false;
            }
        }
    }
}

// Initialize the image processing pipeline
void initialize_image_processing_pipeline() {
    // Read environment variables and update the image processing pipeline configuration accordingly
    for (int i = 0; i < sizeof(env_var) / sizeof(char*); i++) {
        char *env_file = env_var[i];
        if (access(env_file, F_OK)) {
            continue;
        }
        FILE *fp = fopen(env_file, "r");
        if (!fp) {
            perror("fopen");
            return;
        }
        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            // Parse the environment variable and update the image processing pipeline configuration
            char *env_var = strtok(line, "=");
            if (!env_var) {
                continue;
            }
            char *env_val = strtok(NULL, "\n");
            if (!env_val) {
                continue;
            }
            if (strcmp(env_var, "IMAGE_PROCESSING_THREADS") == 0) {
                image_processing_pipeline.threads = atoi(env_val);
            } else if (strcmp(env_var, "IMAGE_PROCESSING_QUEUE_SIZE") == 0) {
                image_processing_pipeline.queue_size = atoi(env_val);
            }
        }
    }
}

// Initialize the logging configuration
void initialize_logging() {
    // Read environment variables and update the logging configuration accordingly
    for (int i = 0; i < sizeof(env_var) / sizeof(char*); i++) {
        char *env_file = env_var[i];
        if (access(env_file, F_OK)) {
            continue;
        }
        FILE *fp = fopen(env_file, "r");
        if (!fp) {
            perror("fopen");
            return;
        }
        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            // Parse the environment variable and update the logging configuration
            char *env_var = strtok(line, "=");
            if (!env_var) {
                continue;
            }
            char *env_val = strtok(NULL, "\n");
            if (!env_val) {
                continue;
            }
            if (strcmp(env_var, "LOGGING_LEVEL") == 0) {
                logging.level = env_val;
            } else if (strcmp(env_var, "LOGGING_FILENAME") == 0) {
                logging.filename = env_val;
            }
        }
    }
}

// Main function
int main() {
    // Initialize the environment variables
    initialize_environment();

    // Initialize the database connection
    initialize_database_connection();

    // Initialize the logging configuration
    initialize_logging();

    // Initialize the image processing pipeline
    initialize_image_processing_pipeline();

    // Initialize the content delivery network (CDN) connection
    initialize_cdn();

    // Initialize the server
    initialize_server();

    return 0;
}

