            "email": "https://api.example.com/users/{user_id}/email",
            "phone": "https://api.example.com/users/{user_id}/phone",
            "address": "https://api.example.com/users/{user_id}/address",
            "dob": "https://api.example.com/users/{user_id}/dob",
            "employment": "https://api.example.com/users/{user_id}/employment"
