using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Threading.Tasks;
using System.Net.Http;
using System.Data.NoSql;
using System.Text.Json;
using System.Diagnostics;
using System.Threading;
using System.Security.Cryptography.X509Certificates;
using System.Globalization;
using System.IO;

namespace SensorDataParser
{
    public class Program
    {
        private static readonly HttpClient _httpClient = new();
        private static readonly Dictionary<string, XPathNavigator> _xpathNavs = new();
        private static readonly NoSqlDatabase _noSqlDb = new();
        private static readonly List<SensorReading> _sensorReadings = new();
        private static readonly Stopwatch _stopwatch = new();

        public static async Task Main(string[] args)
        {
            Console.WriteLine("Initializing...");

            // Initialize HTTP client for XML parsing and NoSQL database connection
            await _httpClient.GetAsync("https://example.com/sensordata.xml");
            _noSqlDb.Connect();

            // XPath navigator initialization
            var xpathNav = new XPathNavigator(_httpClient.ResponseStream);
            foreach (var deviceType in GetDeviceTypes())
            {
                _xpathNavs[deviceType] = xpathNav;
            }

            Console.WriteLine("Starting sensor data parsing...");

            // Start parsing sensor data from XML files
            var tasks = new List<Task>();
            foreach (var deviceType in GetDeviceTypes())
            {
                tasks.Add(ParseSensorData(deviceType));
            }

            await Task.WhenAll(tasks);

            Console.WriteLine("Parsing completed.");

            // Print sensor readings for debugging purposes
            foreach (var reading in _sensorReadings)
            {
                Console.WriteLine($"{reading.DeviceId}: {reading.Value}");
            }
        }

        private static async Task ParseSensorData(string deviceType)
        {
            var xpathNav = _xpathNavs[deviceType];
            while (await xpathNav.ReadAsync())
            {
                var deviceId = xpathNav.Evaluate("//device/@id");
                if (!int.TryParse(deviceId, out var reading)) continue;
                _sensorReadings.Add(new SensorReading(deviceType, reading));
            }
        }

        private static IEnumerable<string> GetDeviceTypes()
        {
            yield return "temperature";
            yield return "humidity";
            yield return "pressure";
        }
    }

    public class SensorReading
    {
        public string DeviceType { get; set; }
        public int Value { get; set; }

        public SensorReading(string deviceType, int value)
        {
            DeviceType = deviceType;
            Value = value;
        }
    }
}
