class DataFetcher {
    private:
        vector<shared_ptr<DataSource>> dataSources_;
        mutex dataSourceMutex_;
        condition_variable dataSourceCV_;
        thread poolThread_;
        bool shutdownPoolThread_ = false;

        void fetchData(const string& source, const string& query) {
            unique_lock<mutex> lock(dataSourceMutex_);
            for (auto& ds : dataSources_) {
                if (ds->getHostname() == hostname && ds->getPort() == port && ds->getUsername() == username && ds->getPassword() == password) {
                    ds->fetchData(source, query);
                    break;
                }
            }
        }

        void poolThreadFunc() {
            while (!shutdownPoolThread_) {
                unique_lock<mutex> lock(dataSourceMutex_);
                dataSourceCV_.wait(lock);
                for (auto& ds : dataSources_) {
                    if (!ds->isBusy()) {
                        ds->fetchData();
                        break;
                    }
                }
            }
        }

        void startPoolThread() {
            poolThread_ = thread(bind(&DataFetcher::poolThreadFunc, this));
        }

        void stopPoolThread() {
            shutdownPoolThread_ = true;
            poolThread_.join();
        }

    public:
        DataFetcher() {}

        ~DataFetcher() {
            stopPoolThread();
        }

        void addDataSource(const string& hostname, int port, const string& username, const string& password) {
            unique_lock<mutex> lock(dataSourceMutex_);
            dataSources_.push_back(make_shared<MySQLDataSource>(hostname, port, username, password));
        }

        void removeDataSource(const string& hostname, int port, const string& username, const string& password) {
            unique_lock<mutex> lock(dataSourceMutex_);
            auto it = find_if(dataSources_.begin(), dataSources_.end(), [=](shared_ptr<DataSource>& ds) {
                return ds->getHostname() == hostname && ds->getPort() == port && ds->getUsername() == username && ds->getPassword() == password;
            });
            if (it != dataSources_.end()) {
                dataSources_.erase(it);
            }
        }

        void fetchData(const string& source, const string& query) {
            unique_lock<mutex> lock(dataSourceMutex_);
            dataSourceCV_.notify_all();
        }
};

class DataProcessor {
    private:
        vector<string> sources_;
        map<string, function<void(const string&)>> processors_;
        mutex sourceMutex_;
        condition_variable sourceCV_;
        thread poolThread_;
        bool shutdownPoolThread_ = false;

        void processSource(const string& source) {
            unique_lock<mutex> lock(sourceMutex_);
            auto it = find(sources_.begin(), sources_.end(), source);
            if (it != sources_.end()) {
                for (auto& processor : processors_) {
                    processor.second(source);
                }
            }
        }

        void poolThreadFunc() {
            while (!shutdownPoolThread_) {
                unique_lock<mutex> lock(sourceMutex_);
                sourceCV_.wait(lock);
                for (auto& source : sources_) {
                    processSource(source);
                }
            }
        }

        void startPoolThread() {
            poolThread_ = thread(bind(&DataProcessor::poolThreadFunc, this));
        }

        void stopPoolThread() {
            shutdownPoolThread_ = true;
            poolThread_.join();
        }

    public:
        DataProcessor() {}

        ~DataProcessor() {
            stopPoolThread();
        }

        void addSource(const string& source) {
            unique_lock<mutex> lock(sourceMutex_);
            sources_.push_back(source);
        }

        void removeSource(const string& source) {
            unique_lock<mutex> lock(sourceMutex_);
            auto it = find(sources_.begin(), sources_.end(), source);
            if (it != sources_.end()) {
                sources_.erase(it);
            }
        }

        void addProcessor(const string& source, function<void(const string&)> processor) {
            unique_lock<mutex> lock(sourceMutex_);
            processors_[source] = processor;
        }

        void removeProcessor(const string& source, function<void(const string&)> processor) {
            unique_lock<mutex> lock(sourceMutex_);
            auto it = find(processors_.begin(), processors_.end(), [=](pair<string, function<void(const string&)>>& processorPair) {
                return processorPair.first == source && processorPair.second == processor;
            });
            if (it != processors_.end()) {
                processors_.erase(it);
            }
        }
};
