using namespace Aws::Utils;
using namespace Aws::S3::Model;
using namespace GoogleCloudStorage::OAuth2Authorization;
using namespace GoogleCloudStorage::OAuth2ServiceAccount;
using namespace GoogleCloudStorage::Retry;
using namespace GoogleCloudStorage::RateLimiter;
using namespace GoogleCloudStorage::Logging;
using namespace GoogleCloudStorage::Util;

class UploadAndDecryptFile {
public:
    UploadAndDecryptFile(const string& filePath, const string& bucketName, const unordered_map<string, string>& metadata = {}, size_t chunkSize = 1024 * 1024)
        : filePath_(filePath), bucketName_(bucketName), metadata_(metadata), chunkSize_(chunkSize) {
    }

    int uploadAndDecryptFile() {
        // Check if the file exists and is accessible before uploading
        if (!checkFileAccessibility()) {
            return 1;
        }

        // Initialize the cloud storage service client
        auto profileProvider = make_shared<Aws::Auth::ProfileConfigFileAWSCredentialsProvider>();
        auto s3Client = make_shared<Aws::S3::S3Client>(profileProvider, Aws::ClientConfiguration());
        if (bucketName_.find("google") != string::npos) {
            auto oauth2ServiceAccount = make_shared<OAuth2ServiceAccount>();
            auto authorizationUrl = "https://accounts.google.com/o/oauth2/token";
            auto authHeaderValue = getAuthorizationHeaderValue(oauth2ServiceAccount);
            s3Client->SetCredentialsEndpoint(authorizationUrl, authHeaderValue);
        }

        // Calculate the SHA-256 hash of the file in chunks to optimize memory usage
        string fileHash;
        auto fileStream = make_shared<fstream>(filePath_, ios::binary | ios::in);
        auto chunkBuffer = make_shared<vector<uint8_t>>(chunkSize_);
        auto hashCtx = SHA256_CTX();
        uint64_t fileSize = getFileSize(fileStream);
        while (fileStream->read(reinterpret_cast<char*>(chunkBuffer->data()), chunkSize_).gcount() > 0) {
            auto buffer = make_shared<vector<uint8_t>>(chunkBuffer->size());
            fileStream->read(reinterpret_cast<char*>(buffer->data()), buffer->size());
            SHA256_Update(&hashCtx, buffer->data(), buffer->size());
        }
        auto digest = make_shared<vector<uint8_t>>(SHA256_DIGEST_LENGTH);
        SHA256_Final(digest->data(), &hashCtx);
        fileHash = getHexDigest(digest);

        // Upload the file to the specified bucket with metadata and monitoring progress
        auto uploadProgress = make_shared<vector<UploadProgress>>(10);
        auto uploadHandle = s3Client->PutObjectAsync(bucketName_, filePath_, fileHash, metadata_, chunkBuffer, &uploadProgress);
        while (!uploadHandle.IsComplete()) {
            this_thread::sleep_for(chrono::milliseconds(5));
            for (auto& progress : uploadProgress) {
                cerr << "Uploaded " << setprecision(2) << fixed << progress.GetBytesSent() / 1024.0 / 1024.0 << "MB of " << setprecision(2) << fixed << fileSize / 1024.0 / 1024.0 << "MB." << endl;
            }
        }

        // Decrypt the uploaded file if necessary
        auto decryptedFilePath = filePath_ + ".decrypted";
        auto decryptionStatus = decryptFile(filePath_, decryptedFilePath);
        if (decryptionStatus != 0) {
            cerr << "Error: Failed to decrypt file." << endl;
            return decryptionStatus;
        }

        // Remove the uploaded file and replace it with the decrypted file
        s3Client->DeleteObject(bucketName_, fileHash);
        fileStream = make_shared<fstream>(decryptedFilePath, ios::binary | ios::in);
        auto putObjectRequest = PutObjectRequest().WithBucket(bucketName_).WithKey(fileHash);
        s3Client->PutObjectAsync(putObjectRequest, chunkBuffer);

        // Log the successful upload and decryption
        Logger logger;
        logger.LogInfo("Uploaded " + filePath_ + " to bucket " + bucketName_ + " with SHA-256 hash " + fileHash);

        return 0;
    }

private:
    const string& filePath_;
    const string& bucketName_;
    const unordered_map<string, string>& metadata_;
    size_t chunkSize_;

    bool checkFileAccessibility() {
        // Check if the file exists and is accessible
        auto fileStream = make_shared<fstream>(filePath_, ios::binary | ios::in);
        if (!fileStream->good()) {
            cerr << "Error: File " + filePath_ + " does not exist or is not accessible." << endl;
            return false;
        }
        fileStream.reset();
        return true;
    }

    uint64_t getFileSize(const shared_ptr<fstream>& fileStream) {
        // Get the size of the file in bytes
        auto filePosition = fileStream->tellg();
        fileStream->seekg(0, ios::end);
        auto fileSize = fileStream->tellg() - filePosition;
        fileStream->seekg(filePosition);
        return fileSize;
    }

    string getHexDigest(const shared_ptr<vector<uint8_t>>& digest) {
        // Get the hexadecimal representation of a hash value
        auto result = make_shared<string>();
        for (auto& byte : *digest) {
            *result += to_hex(byte);
        }
        return *result;
    }

    string getAuthorizationHeaderValue(const shared_ptr<OAuth2ServiceAccount>& oauth2ServiceAccount) {
        // Get the value for the Authorization header of an OAuth 2.0 bearer token request
        auto authorizationUrl = "https://accounts.google.com/o/oauth2/token";
        auto postContent = make_shared<stringstream>();
        *postContent << "client_id=" << oauth2ServiceAccount->GetClientId()
                     << "&client_secret=" << oauth2ServiceAccount->GetClientSecret()
                     << "&grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer"
                     << "&assertion=" << oauth2ServiceAccount->GetAssertion();
        auto response = oauth2ServiceAccount->GetToken(authorizationUrl, postContent);
        auto headers = response.second;
        return headers["Authorization"];
    }

    int decryptFile(const string& filePath, const string& decryptedFilePath) {
        // Decrypt a file using AES-256 encryption with the specified key and initialization vector
