// JavaScript function to load and execute a specified JavaScript file within the context of a web page
function loadScript(url) {
  // Check if the script is already loaded
  if (document.querySelector(`script[src="${url}"]`) !== null) {
    return;
  }

  // Create a new script element and set its source to the specified URL
  const script = document.createElement("script");
  script.src = url;

  // Add the script to the head of the document
  document.head.appendChild(script);

  // Wait for the script to load and execute
  script.onload = () => {
    // Handle cases where the file is not available or cannot be executed
    if (script.status === "loading" || script.status === "uninitialized") {
      console.warn(`Failed to load ${url}`);
    } else {
      // Execute the loaded script
      const result = script.execute();
      console.log(result);
    }
  };
}

// Java method to load a state object from a file using an ObjectInputStream
public MoSTState loadStateFromFile(String filename) throws IOException, ClassNotFoundException {
  // Open the file and create an ObjectInputStream
  FileInputStream fis = new FileInputStream(filename);
  ObjectInputStream ois = new ObjectInputStream(fis);

  // Read the object from the stream
  Object obj = ois.readObject();

  // Check if the loaded object is an instance of MoSTState
  if (obj instanceof MoSTState) {
    return (MoSTState) obj;
  } else {
    return null;
  }
}
