// Define a function for reading data from a client's socket
void *read_data(void *args) {
    int socket = (int) args;

    // Allocate memory for the buffer
    char *buffer = malloc(BUFFER_SIZE);
    size_t buffer_size = BUFFER_SIZE;

    // Set up a loop to read data from the client's socket
    while (true) {
        int bytes_read = recv(socket, buffer, buffer_size, 0);

        if (bytes_read <= 0) {
            break;
        }

        // Increment the read position in the buffer
        size_t read_pos = pthread_mutex_lock(&client_data_streams_mutex);
        client_data_streams[socket].read_pos += bytes_read;
        pthread_mutex_unlock(&client_data_streams_mutex);
    }

    // Free the buffer and return
    free(buffer);
    return NULL;
}

// Define a function for parsing data using a set of rules loaded from an external API endpoint
void *parse_data(void *args) {
    parsed_data_t *parsed_data = malloc(sizeof(parsed_data_t));
    parsing_rule_t *parsing_rule = (parsing_rule_t *) args;

    // Initialize the parsed data structure
    parsed_data->format = parsing_rule->format;
    parsed_data->field_count = parsing_rule->field_count;
    parsed_data->field_indices = parsing_rule->field_indices;
    parsed_data->data = malloc(parsing_rule->field_count * sizeof(char *));

    // Loop over each piece of data in the queue
    while (true) {
        pthread_mutex_lock(&queue_mutex);

        if (queue_size == 0) {
            pthread_cond_wait(&queue_cv, &queue_mutex);
        }

        queue_element_t *queue_element = dequeue();
        pthread_mutex_unlock(&queue_mutex);

        // Parse the data using the parsing rules
        parsed_data->data[queue_element->client_index] = parse_piece_of_data(queue_element->parsed_data, parsing_rule);
    }

    // Free the parsed data structure and return
    free(parsed_data->data);
    free(parsed_data);
    return NULL;
}

// Define a function for parsing a single piece of data using a set of rules loaded from an external API endpoint
char *parse_piece_of_data(parsed_data_t *parsed_data, parsing_rule_t *parsing_rule) {
    char *data = malloc(BUFFER_SIZE);
    size_t data_size = BUFFER_SIZE;

    // Initialize the data structure with the parsed data
    for (int i = 0; i < parsing_rule->field_count; i++) {
        if (parsed_data->field_indices[i] >= 0) {
            strncpy(data, parsed_data->data[i], data_size);
            break;
        }
    }

    // Return the parsed data
    return data;
}

// Define a function for enqueuing data from clients
void enqueue(parsed_data_t *parsed_data, int client_index) {
    queue_element_t *queue_element = malloc(sizeof(queue_element_t));
    queue_element->parsed_data = parsed_data;
    queue_element->client_index = client_index;

    pthread_mutex_lock(&queue_mutex);
    queue[queue_size++] = queue_element;
    pthread_cond_signal(&queue_cv);
    pthread_mutex_unlock(&queue_mutex);
}

// Define a function for dequeuing data from clients
void *dequeue() {
    void *element = NULL;

    pthread_mutex_lock(&queue_mutex);

    if (queue_size > 0) {
        element = queue[--queue_size];
        free(queue[queue_size]);
    }

    pthread_mutex_unlock(&queue_mutex);
    return element;
}

