```c
// modular_library.c
#include "modular_library.h"

char* append_slash(const char* str, size_t len) {
  // Append a slash to the given string only if its length is less than or equal to the specified size limit
  if (strlen(str) <= len) {
    return realloc(str, sizeof(char) * (strlen(str) + 1));
  } else {
    return NULL;
  }
}

void log_error(const char* format, ...) {
  // Use snprintf to format the message and va_start/va_end to retrieve the arguments
  va_list args;
  va_start(args, format);
  int len = vsnprintf(NULL, 0, format, args) + 1;
  char* buffer = malloc(len);
  vsnprintf(buffer, len, format, args);
  // Log the message to the error log
  printf("[ERROR] %s\n", buffer);
  free(buffer);
  va_end(args);
}
```

