using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using ExternalApiClient;

public static class FileHashVerifier
{
    private const int BUFFER_SIZE = 1024 * 1024; // 1 MB
    private const int MAX_RETRIES = 3;
    private const int RATE_LIMIT = 100;
    private static readonly ConcurrentDictionary<string, bool> VerifiedHashes = new();

    public static async Task<bool> VerifyFileAsync(string filePath)
    {
        var source = GetSourceFromPath(filePath);
        var hashAlgorithm = MD5.Create();
        var buffer = new byte[BUFFER_SIZE];
        var verified = false;

        try
        {
            using (var stream = OpenStream(source))
            {
                var fileSize = stream.Length;
                var chunkSize = Math.Min(fileSize, BUFFER_SIZE);
                var hash = hashAlgorithm.ComputeHash(stream);
                verified = await VerifyHashAsync(hash).ConfigureAwait(false);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error verifying file {filePath}: {ex.Message}");
        }

        return verified;
    }

    private static async Task<bool> VerifyHashAsync(byte[] hash)
    {
        var apiClient = new ExternalApiClient();
        try
        {
            var response = await apiClient.GetVerificationResponseAsync(hash).ConfigureAwait(false);
            if (response.Status == 200)
            {
                VerifiedHashes[hash] = true;
                return true;
            }
            else
            {
                Console.WriteLine($"Error verifying hash: {response.Status}");
                return false;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error verifying hash: {ex.Message}");
            return false;
        }
    }

    private static async Task<Stream> OpenStream(string source)
    {
        var stream = new MemoryStream();
        if (source.StartsWith("ftp://") || source.StartsWith("sftp://"))
        {
            var ftpClient = new FtpClient(source);
            await ftpClient.ConnectAsync().ConfigureAwait(false);
            await ftpClient.DownloadFileAsync(stream).ConfigureAwait(false);
            await ftpClient.DisconnectAsync().ConfigureAwait(false);
        }
        else if (source.StartsWith("http://") || source.StartsWith("https://"))
        {
            var webClient = new WebClient();
            await webClient.DownloadFileTaskAsync(source, stream).ConfigureAwait(false);
        }
        else
        {
            using (var fileStream = File.OpenRead(source))
            {
                fileStream.CopyTo(stream);
            }
        }

        return new MemoryStream(stream.ToArray());
    }

    private static string GetSourceFromPath(string filePath)
    {
        if (File.Exists(filePath))
        {
            return filePath;
        }
        else if (Uri.TryCreate(filePath, UriKind.Absolute, out var uri))
        {
            return uri.ToString();
        }
        else
        {
            throw new ArgumentException($"Invalid file path: {filePath}");
        }
    }
}
