#include <iostream>
#include <fstream>
#include <cmath>
#include <limits>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

using namespace std;

const int MIN_MAX_ALGORITHM = 1; // 1 for custom min-max algorithm, 2 for standard algorithm

struct Statistic {
    double minimum;
    double maximum;
    int count;
};

void processData(vector<double>& data) {
    if (data.empty()) {
        cout << "No data to process" << endl;
        return;
    }

    // Custom min-max algorithm
    if (MIN_MAX_ALGORITHM == 1) {
        double currentMin = data[0];
        double currentMax = data[0];

        for (int i = 0; i < data.size(); ++i) {
            if (data[i] < currentMin) {
                currentMin = data[i];
            } else if (data[i] > currentMax) {
                currentMax = data[i];
            }
        }

        Statistic stat;
        stat.minimum = currentMin;
        stat.maximum = currentMax;
        stat.count = data.size();

        return stat;
    } else { // Standard min-max algorithm
        auto minMax = minmax_element(data.begin(), data.end());
        Statistic stat;
        stat.minimum = *minMax.first;
        stat.maximum = *minMax.second;
        stat.count = data.size();

        return stat;
    }
}

int main() {
    // Open file for reading and writing
    ifstream inFile("input_file.txt");
    ofstream outFile("output_file.txt");

    // Check for errors
    if (!inFile || !outFile) {
        cout << "Error opening files" << endl;
        return 1;
    }

    // Read data from file
    vector<double> data;
    string line;
    while (getline(inFile, line)) {
        istringstream ss(line);
        double number;
        if (!(ss >> number)) {
            cout << "Invalid data format" << endl;
            return 1;
        }
        data.push_back(number);
    }

    // Process data and write to output file
    Statistic stat = processData(data);
    outFile << "Minimum: " << stat.minimum << "\n";
    outFile << "Maximum: " << stat.maximum << "\n";
    outFile << "Count: " << stat.count << endl;

    // Close files
    inFile.close();
    outFile.close();

    return 0;
}
```
