  virtual bool FindVmUuidFromMetadataIp(const string& metadata_ip) = 0;
};

class SandeshClient {
 public:
  explicit SandeshClient(InterfaceTable* interface_table);

  void SendAsyncGetRequest(const string& url, const string& body);
  bool VerifyResponse(const string& response, int time_limit);
  void Log(const string& message);

 private:
  InterfaceTable* interface_table_;
};

class TestDouble : public InterfaceTable {
 public:
  explicit TestDouble();

  bool FindVmUuidFromMetadataIp(const string& metadata_ip) override;
};

int main() {
  InterfaceTable* interface_table = new TestDouble();

  SandeshClient client(interface_table);
  vector<string> integers;

  for (string line; getline(cin, line);) {
    integers.push_back(line);
  }

  int largest_integer = -1;

  for (int i = 0; i < integers.size(); ++i) {
    string metadata_ip = "metadata-ip-" + to_string(i);
    bool found_vm_uuid = interface_table->FindVmUuidFromMetadataIp(metadata_ip);
    if (found_vm_uuid) {
      client.SendAsyncGetRequest("http://server/api/data", metadata_ip);
    }
  }

  // Verify responses and log API requests
  for (int i = 0; i < integers.size(); ++i) {
    string response = "response-" + to_string(i);
    bool verified = client.VerifyResponse(response, 1000);
    if (verified) {
      client.Log("Success: " + response);
    } else {
      client.Log("Failed: " + response);
    }
  }

  // Print largest integer
  if (largest_integer != -1) {
    cout << "Largest integer: " << largest_integer << endl;
  } else {
    cout << "No integers found" << endl;
  }

  return 0;
}

SandeshClient::SandeshClient(InterfaceTable* interface_table) : interface_table_(interface_table) {}

void SandeshClient::SendAsyncGetRequest(const string& url, const string& body) {
  // Send asynchronous GET request to server
  boost::asio::io_context context;
  tcp::socket socket(context);
  beast::http::request<beast::http::string_body> req{boost::beast::version{1, 0}, "GET", url, 1};
  req.set("Connection", "close");
  req.set("Host", "server");
  req.body() = body;
  req.prepare_payload();
  beast::http::write(socket, req);
}

bool SandeshClient::VerifyResponse(const string& response, int time_limit) {
  // Verify response matches expected values within specified time limit
  boost::asio::io_context context;
  tcp::socket socket(context);
  beast::http::request<beast::http::string_body> req{boost::beast::version{1, 0}, "GET", "http://server/api/data", 1};
  req.set("Connection", "close");
  req.set("Host", "server");
  req.body() = response;
  req.prepare_payload();
  beast::http::write(socket, req);
  boost::beast::flat_buffer buffer;
  beast::http::response<beast::http::string_body> res;
  beast::http::read(socket, buffer, res);
  if (res.result() == "200 OK") {
    auto json = nlohmann::json::parse(res.body());
    if (json["data"]["integer"] > largest_integer) {
      largest_integer = json["data"]["integer"];
    }
  } else {
    return false;
  }
}

