using System;
using System.Security.Cryptography;
using System.Text;

namespace SecureEncryptionManager
{
    public class AESCipher
    {
        private readonly int _keySize;
        private readonly Encoding _encoding;

        // Constructor that takes the key size and encoding scheme as parameters
        public AESCipher(int keySize = 256, Encoding encoding = null)
        {
            _keySize = keySize;
            _encoding = encoding ?? Encoding.UTF8;
        }

        // Method to decrypt a given ciphertext using AES-CBC mode with the provided key and IV
        public byte[] DecryptAESCBC(byte[] cipherText, byte[] key, byte[] iv)
        {
            if (cipherText == null || key == null || iv == null)
                throw new ArgumentNullException("Invalid input parameters");

            // Create a new instance of the AES-CBC decryption class
            using var aes = new AesCbcDecryptor(key, iv);

            // Decrypt the ciphertext and return the plaintext
            return aes.TransformFinalBlock(cipherText, 0, cipherText.Length);
        }

        // Method to decrypt a given ciphertext using AES-GCM mode with the provided key and IV
        public byte[] DecryptAESGCM(byte[] cipherText, byte[] key, byte[] iv)
        {
            if (cipherText == null || key == null || iv == null)
                throw new ArgumentNullException("Invalid input parameters");

            // Create a new instance of the AES-GCM decryption class
            using var aes = new AesGcmDecryptor(key, iv);

            // Decrypt the ciphertext and return the plaintext
            return aes.TransformFinalBlock(cipherText, 0, cipherText.Length);
        }

        // Method to generate a secure random IV with the specified length
        public byte[] GenerateRandomIV(int ivLength)
        {
            if (ivLength <= 0)
                throw new ArgumentOutOfRangeException("Invalid IV length");

            using var rng = new RNGCryptoServiceProvider();
            var iv = new byte[ivLength];
            rng.GetBytes(iv);
            return iv;
        }

        // Method to generate a secure random key with the specified length
        public byte[] GenerateRandomKey(int keyLength)
        {
            if (keyLength <= 0)
                throw new ArgumentOutOfRangeException("Invalid key length");

            using var rng = new RNGCryptoServiceProvider();
            var key = new byte[keyLength];
            rng.GetBytes(key);
            return key;
        }
    }
}
