            for (int i = 0; i < array.length; i++) {
                int root1 = uf.find(i);
                for (int j = i + 1; j < array.length; j++) {
                    int root2 = uf.find(j);
                    if (root1 != root2) {
                        numDisjointPairs++;
                        uf.union(i, j);
                    }
                }
            }

            // store the result in the cache if specified
            if (USE_CACHING && array.length < CACHE_SIZE) {
