        }
    }

    private static void removeDuplicates(int[] array, int maxFrequencyThreshold) {
        // sort the array in descending order of frequency
        Arrays.sort(array);

        // remove duplicates based on the maximum frequency threshold
        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] == array[i + 1]) {
                int count = Math.min(maxFrequencyThreshold, array[i]);
                for (int j = i + 2; j <= i + count; j++) {
                    array[j - 1] = array[j];
                }
            }
        }
    }
}

class UnionFind {
    private int[] parent; // array of parents for each element in the set
    private int[] rank; // rank of each element in the set (used for union by rank)
    private int size; // number of elements in the set

    public UnionFind(int size) {
        this.size = size;
        parent = new int[size];
        rank = new int[size];
        Arrays.fill(parent, -1);
        Arrays.fill(rank, 0);
    }

    public int find(int i) {
        // path compression: set the parent of each element to its grandparent (or itself if it has no grandparent)
        while (parent[i] != -1) {
            i = parent[i];
        }
        return i;
    }

    public void union(int i, int j) {
        // union by rank: merge the sets containing i and j if their ranks are equal, otherwise merge the set containing i into the set containing j
        int root1 = find(i);
        int root2 = find(j);
        if (root1 == root2) {
            return;
        }
        if (rank[root1] > rank[root2]) {
            parent[root2] = root1;
        } else if (rank[root1] < rank[root2]) {
            parent[root1] = root2;
        } else {
            parent[root1] = root2;
            rank[root2]++;
        }
    }
}
