using UnityEngine;

public class DynamicValueGenerator
{
    // Private field for storing the current distribution type and parameters
    private DistributionType _distributionType = DistributionType.Gaussian;
    private double[] _parameters = new double[2];

    // Methods for returning a random float value and an integer value within the specified range, taking into account the current distribution
    public float NextFloat(float minValue, float maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int NextInteger(int minValue, int maxValue)
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    // Override of the ToString method to display the range of values, the current distribution type, and relevant parameters
    public override string ToString()
    {
        return $"DynamicValueGenerator: Range={minValue}-{maxValue}, DistributionType={_distributionType}, Parameters={_parameters.ToString()}";
    }

    // Integration with an external configuration system that can store and retrieve different types of distributions and their parameters. This system should also support dynamic updates during runtime without causing a performance hit.
    public void LoadDistribution(string distributionName, string[] parameters)
    {
        // Validate input parameters
        if (!Enum.TryParse<DistributionType>(distributionName, out _distributionType))
        {
            throw new ArgumentException($"Invalid distribution type: {distributionName}");
        }

        if (parameters.Length != 2)
        {
            throw new ArgumentException("Expected two parameters for the distribution", nameof(parameters));
        }

        _parameters = parameters.Select(double.Parse).ToArray();
    }

    // Error handling and robustness, including validation of input ranges, distribution types, and parameters. Implement a fallback mechanism for unsupported distributions.
    public void FallbackDistribution()
    {
        _distributionType = DistributionType.Gaussian;
        _parameters[0] = 1.0;
        _parameters[1] = 0.5;
    }

    // Scalability and resource management, ensuring that the cache is efficiently managed and does not consume excessive memory. The cache should automatically evict least recently used (LRU) entries to maintain a fixed size.
    private readonly Dictionary<int, float> _cache = new Dictionary<int, float>();

    public void Cache(int key, float value)
    {
        if (_cache.Count >= 1024)
        {
            int oldestKey = _cache.Keys.OrderByDescending(k => k).First();
            _cache.Remove(oldestKey);
        }

        _cache[key] = value;
    }

    public float GetCachedValue(int key)
    {
        if (_cache.ContainsKey(key))
        {
            return _cache[key];
        }

        return -1.0f;
    }

    // User experience and usability considerations, such as clear error messages and user-friendly feedback when invalid distributions are requested. Provide an intuitive API for setting up and querying the generator.
    public void SetDistributionType(DistributionType distributionType)
    {
        if (distributionType != DistributionType.Gaussian && distributionType != DistributionType.Uniform)
        {
            throw new ArgumentException("Invalid distribution type", nameof(distributionType));
        }

        _distributionType = distributionType;
    }

    public void SetParameters(double[] parameters)
    {
        if (parameters.Length != 2)
        {
            throw new ArgumentException("Expected two parameters for the distribution", nameof(parameters));
        }

        _parameters = parameters;
    }

    // Maintainability and code organization, with separate classes or modules for different distribution types and their respective implementations, including unit tests for each distribution. Ensure that the distribution implementations are modular and easy to extend.
    public enum DistributionType
    {
        Gaussian,
        Uniform
    }

    public class GaussianDistribution : IDistribution
    {
        private readonly double[] _parameters;

        public GaussianDistribution(double[] parameters)
        {
            _parameters = parameters;
        }

        public float NextFloat(float minValue, float maxValue)
        {
            // Implement the Gaussian distribution using the Box-Muller transform
            double u1 = UnityEngine.Random.Range(0.0, 1.0);
            double u2 = UnityEngine.Random.Range(0.0, 1.0);
            double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
            return (float)Math.Min(maxValue, maxValue + _parameters[0] * randStdNormal + _parameters[1]);
        }
    }

    public class UniformDistribution : IDistribution
    {
        private readonly double[] _parameters;

        public UniformDistribution(double[] parameters)
        {
            _parameters = parameters;
        }

        public float NextFloat(float minValue, float maxValue)
        {
            // Implement the uniform distribution using a random number between min and max values
            return UnityEngine.Random.Range((float)_parameters[0], (float)_parameters[1]);
        }
    }

    public interface IDistribution
    {
        float NextFloat(float minValue, float maxValue);
    }
}
