        File file = new File(filePath);
        if (!file.exists()) {
            System.out.println("File not found: " + filePath);
            return;
        }

        // Validate the file's metadata before uploading
        long fileSize = Files.size(file.toPath());
        String checksum = calculateFileChecksum(file);
        System.out.println("File size: " + fileSize + " bytes");
        System.out.println("SHA-256 checksum: " + checksum);

        // Check if the file is already present in the specified location
        boolean exists = doesFileExist(bucketName, directoryPath, checksum);
        if (exists) {
            System.out.println("File already exists in cloud storage");
            return;
        }

        // Upload the file to the cloud storage service
        try {
            URL url = new URL("https://api.cloudstorage.com/buckets/" + bucketName + "/" + directoryPath);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("PUT");
            connection.setRequestProperty("Content-Type", "application/octet-stream");
            connection.setDoOutput(true);
            try (OutputStream os = connection.getOutputStream()) {
                Files.copy(file.toPath(), os);
            }
            int responseCode = connection.getResponseCode();
            if (responseCode == 201) {
                System.out.println("File uploaded successfully");
            } else {
                System.out.println("Error uploading file: " + responseCode);
            }
        } catch (IOException e) {
            System.out.println("Error connecting to cloud storage service: " + e.getMessage());
        }
    }

    private static String calculateFileChecksum(File file) throws IOException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[4096];
        try (InputStream is = Files.newInputStream(file.toPath())) {
            int read;
            while ((read = is.read(buffer)) > 0) {
                digest.update(buffer, 0, read);
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
        return new BigInteger(1, digest.digest()).toString(16);
    }

    private static boolean doesFileExist(String bucketName, String directoryPath, String checksum) {
