    async_read(*socket_, boost::asio::buffer(responseBuffer_),
               [this](boost::system::error_code ec, std::size_t bytesTransferred) {
      if (ec) {
        // Handle error
      } else {
        // Process response
      }
    });
  }

 private:
  string metadataServiceUrl_;
  string serverUrl_;
  boost::asio::ip::tcp::socket socket_;
  std::vector<char> responseBuffer_;
};

int main() {
  // Create a Sandesh client and initialize it with the URL of the remote server
  SandeshClient client("http://metadata-service.example.com/", "https://server.example.com");

  // Set up logging mechanisms for tracking request statistics
  std::ofstream logFile;
  logFile.open("sandesh_client_log.txt");
  boost::log::core::get()->add_sink(boost::make_shared<boost::log::sinks::text_file_backend>(
                                       boost::log::keywords::file_name = "sandesh_client_log.txt"));

  // Periodically check the server's status and retry failed requests up to a specified number of times
  while (true) {
    try {
      client.sendGetRequest("path/to/resource");
      logFile << "GET request sent successfully" << endl;
      break;
    } catch (const boost::system::error_code& ec) {
      if (ec == boost::asio::error::connection_refused ||
          ec == boost::asio::error::timed_out) {
        // Handle connection refused or timeout errors
      } else {
        logFile << "GET request failed with error: " << ec.message() << endl;
      }
    }
  }

  while (true) {
    try {
      client.sendPostRequest("path/to/resource", "{\"key\": \"value\"}");
      logFile << "POST request sent successfully" << endl;
      break;
    } catch (const boost::system::error_code& ec) {
      if (ec == boost::asio::error::connection_refused ||
          ec == boost::asio::error::timed_out) {
        // Handle connection refused or timeout errors
      } else {
        logFile << "POST request failed with error: " << ec.message() << endl;
      }
    }
  }

  return 0;
}
