public class AsynchronousFileReportGenerator {
    private static final String CONFIG_FILE = "config.properties";
    private static final int DEFAULT_CHUNK_SIZE = 1024 * 1024; // 1MB

    private Map<String, File> filesToProcess = new HashMap<>();
    private Map<String, String> fileHashes = new HashMap<>();
    private Map<String, Integer> fileSizes = new HashMap<>();
    private Map<String, List<Integer>> lineNumbers = new HashMap<>();
    private List<String> keywords = new ArrayList<>();
    private List<String> outputFormats = new ArrayList<>();
    private Set<CloudStorageService> cloudStorages = new HashSet<>();
    private Map<String, CloudStorageService> cachedMetadata = new HashMap<>();

    public AsynchronousFileReportGenerator() {
        this.loadConfig();
        this.initCaching();
    }

    public void loadConfig() {
        // Load config file and set up keyword and output format lists
        Properties properties = new Properties();
        try (InputStream is = getClass().getResourceAsStream(CONFIG_FILE)) {
            properties.load(is);
        } catch (IOException e) {
            System.out.println("Error loading config file: " + CONFIG_FILE);
            return;
        }

        String keywordsStr = properties.getProperty("keywords");
        if (keywordsStr != null && !keywordsStr.isEmpty()) {
            this.keywords = Arrays.asList(keywordsStr.split(","));
        }

        String outputFormatsStr = properties.getProperty("outputFormats");
        if (outputFormatsStr != null && !outputFormatsStr.isEmpty()) {
            this.outputFormats = Arrays.asList(outputFormatsStr.split(","));
        }
    }

    public void initCaching() {
        // Initialize caching mechanism for frequently accessed metadata and hashes
        this.cachedMetadata = new HashMap<>();
    }

    public void processFile(String filePath) {
        File file = new File(filePath);
        if (!file.exists()) {
            System.out.println("Error: file does not exist");
            return;
        }

        // Compute SHA-256 hash of the file and check for existence in the cache
        String hash = DigestUtils.sha256Hex(file);
        if (this.cachedMetadata.containsKey(hash)) {
            System.out.println("Found cached metadata for file " + filePath);
            FileMetaData metaData = this.cachedMetadata.get(hash);
            // Update the hashes and sizes maps with the cached data
            this.fileHashes.put(filePath, hash);
            this.fileSizes.put(filePath, metaData.size());
        } else {
            System.out.println("Computing metadata for file " + filePath);
            // Compute the file size and update the sizes map
            long size = file.length();
            this.fileSizes.put(filePath, size);

            // Compute the SHA-256 hash of the file content and update the hashes map
            String computedHash = DigestUtils.sha256Hex(file);
            this.fileHashes.put(filePath, computedHash);

            // Update the cached metadata with the new data
            FileMetaData metaData = new FileMetaData(size, computedHash);
            this.cachedMetadata.put(hash, metaData);
        }

        // Add the file to the list of files to process
        this.filesToProcess.put(filePath, file);
    }

    public void generateReport() {
        for (Map.Entry<String, File> entry : this.filesToProcess.entrySet()) {
            String filePath = entry.getKey();
            File file = entry.getValue();

            // Read the file line by line and identify lines containing keywords
            List<Integer> lineNumbersList = new ArrayList<>();
            try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                int lineNumber = 1;
                String line;
                while ((line = reader.readLine()) != null) {
                    for (String keyword : this.keywords) {
                        if (line.contains(keyword)) {
                            lineNumbersList.add(lineNumber);
                            break;
                        }
                    }
                }
            } catch (IOException e) {
                System.out.println("Error reading file " + filePath);
                continue;
            }

            // Update the line numbers map with the found lines
            this.lineNumbers.put(filePath, lineNumbersList);
        }

        // Generate summary report for each output format
        for (String outputFormat : this.outputFormats) {
            System.out.println("Generating summary report in " + outputFormat);
            // TODO: Implement the logic to generate the summary report for a specific output format
        }
    }

    public void uploadReportsToCloud() {
        for (String filePath : this.filesToProcess.keySet()) {
            File file = this.filesToProcess.get(filePath);
            String hash = this.fileHashes.get(filePath);
            int size = this.fileSizes.get(filePath);
            List<Integer> lineNumbers = this.lineNumbers.get(filePath);

            // Compute the SHA-256 hash of the file content and compare with the cached hash
            String computedHash = DigestUtils.sha256Hex(file);
            if (!computedHash.equals(hash)) {
                System.out.println("Error: uploaded file has different hash than expected");
                continue;
            }

            // Determine the most suitable cloud storage service based on cost, performance, and geographical proximity
            CloudStorageService bestCloudStorage = null;
            for (CloudStorageService cloudStorage : this.cloudStorages) {
                if (bestCloudStorage == null || cloudStorage.compareTo(bestCloudStorage) > 0) {
                    bestCloudStorage = cloudStorage;
                }
            }

            // Upload the file to the chosen cloud storage service
            try {
                bestCloudStorage.uploadFile(file, hash);
            } catch (IOException e) {
                System.out.println("Error uploading file " + filePath + " to cloud");
                continue;
            }

            // Send notifications to the user when the summary report is uploaded successfully
            for (String outputFormat : this.outputFormats) {
                if (bestCloudStorage.supportsOutputFormat(outputFormat)) {
                    System.out.println("Summary report uploaded successfully");
                    break;
                }
            }
        }
    }
}
