using System;
using System.IO;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace CompressionTransfer {
    public class TransferManager {
        private const int MAX_CONCURRENT_REQUESTS = 10;
        private const int RATE_LIMIT_WINDOW = 60; // seconds
        private const int MINIMUM_COMPRESSION_RATIO = 5; // minimum compression ratio to use GZIP
        private static readonly Dictionary<string, string> ALGORITHMS = new Dictionary<string, string>() {
            {"gzip", "GZIP"},
            {"deflate", "DEFLATE"},
            {"lz4", "LZ4"}
        };

        public async Task Transfer(byte[] data) {
            var algorithm = GetAlgorithm(data);
            var compressedData = Compress(data, algorithm);
            var transferStartTime = DateTime.UtcNow;

            try {
                using (var client = new TcpClient()) {
                    await client.ConnectAsync("remote-server", 8080);
                    var networkStream = client.GetStream();
                    using (var compressionStream = new GZipStream(networkStream, CompressionMode.Compress)) {
                        await compressionStream.WriteAsync(compressedData, 0, compressedData.Length);
                    }
                }
            } catch (Exception e) {
                LogError("Transfer failed", e);
            } finally {
                var transferEndTime = DateTime.UtcNow;
                var elapsedTime = transferEndTime - transferStartTime;
                LogInformation($"Transfer completed in {elapsedTime.TotalSeconds} seconds");
            }
        }

        private string GetAlgorithm(byte[] data) {
            if (data.Length <= MINIMUM_COMPRESSION_RATIO) {
                return "gzip";
            } else {
                return "lz4";
            }
        }

        private byte[] Compress(byte[] data, string algorithm) {
            switch (algorithm) {
                case "GZIP":
                    using (var memoryStream = new MemoryStream()) {
                        using (var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress)) {
                            gzipStream.Write(data, 0, data.Length);
                        }
                        return memoryStream.ToArray();
                    }
                case "DEFLATE":
                    using (var memoryStream = new MemoryStream()) {
                        using (var deflateStream = new DeflateStream(memoryStream, CompressionMode.Compress)) {
                            deflateStream.Write(data, 0, data.Length);
                        }
                        return memoryStream.ToArray();
                    }
                case "LZ4":
                    using (var memoryStream = new MemoryStream()) {
                        using (var lz4Stream = new LZ4Stream(memoryStream, CompressionMode.Compress)) {
                            lz4Stream.Write(data, 0, data.Length);
                        }
                        return memoryStream.ToArray();
                    }
                default:
                    throw new Exception("Invalid compression algorithm");
            }
        }

        private void LogInformation(string message) {
            // log information to file or console
        }

        private void LogError(string message, Exception e) {
            // log error to file or console with details
        }
    }
}
