#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sqlite3.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    double timestamp;
    char* tags[];
} Record;

// Define the function to populate the list of records from multiple external SQL servers
void populateRecords(Record** records, size_t numRecords) {
    // Allocate memory for the four arrays
    long* offsetArray = malloc(numRecords * sizeof(long));
    int* keyArray = malloc(numRecords * sizeof(int));
    double* timestampArray = malloc(numRecords * sizeof(double));
    char** tagArray = malloc(numRecords * sizeof(char*));

    // Initialize the arrays with default values
    memset(offsetArray, 0, numRecords * sizeof(long));
    memset(keyArray, 0, numRecords * sizeof(int));
    memset(timestampArray, 0.0, numRecords * sizeof(double));
    for (size_t i = 0; i < numRecords; i++) {
        tagArray[i] = malloc(16 * sizeof(char*)); // allocate memory for each string
        memset(tagArray[i], 0, 16 * sizeof(char*));
    }

    // Loop through the records and populate the arrays
    for (size_t i = 0; i < numRecords; i++) {
        Record record = records[i];
        offsetArray[i] = record.offset;
        keyArray[i] = record.key;
        timestampArray[i] = record.timestamp;
        for (size_t j = 0; j < record.tagsLen; j++) {
            strcpy(tagArray[i][j], record.tags[j]);
        }
    }

    // Create a cache for the records to reduce database queries
    sqlite3_cache* cache = sqlite3_create_cache();

    // Loop through the servers and populate the records
    for (size_t i = 0; i < numServers; i++) {
        Server server = serverList[i];

        // Connect to the database on the server
        sqlite3* db = sqlite3_connect(server.address);

        if (db == NULL) {
            printf("Failed to connect to %s\n", server.address);
            continue;
        }

        // Query the database for the records
        sqlite3_stmt* stmt = sqlite3_prepare_v2(db, query, -1, &error);

        if (stmt == NULL) {
            printf("Failed to prepare statement: %s\n", error);
            continue;
        }

        // Fetch the records from the database
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            long offset = sqlite3_column_int(stmt, 0);
            int key = sqlite3_column_int(stmt, 1);
            double timestamp = sqlite3_column_double(stmt, 2);
            char* tags[record.tagsLen];

            for (size_t j = 0; j < record.tagsLen; j++) {
                tags[j] = (char*)sqlite3_column_text(stmt, 3 + j);
            }

            // Add the record to the cache
            sqlite3_cache_add(cache, offset, key, timestamp, tags);
        }

        // Close the database connection
        sqlite3_close(db);
    }

    // Loop through the records and populate the arrays
    for (size_t i = 0; i < numRecords; i++) {
        Record record = sqlite3_cache_get(cache, i);
        offsetArray[i] = record.offset;
        keyArray[i] = record.key;
        timestampArray[i] = record.timestamp;
        for (size_t j = 0; j < record.tagsLen; j++) {
            strcpy(tagArray[i][j], record.tags[j]);
        }
    }

    // Release the cache and free the memory allocated for the arrays
    sqlite3_cache_release();
    free(offsetArray);
    free(keyArray);
    free(timestampArray);
    for (size_t i = 0; i < numRecords; i++) {
        free(tagArray[i]);
    }
    free(tagArray);
}
