#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>

#define MAX_DNS_RESOLUTION_REQUESTS 100 // Maximum number of concurrent DNS resolution requests allowed
#define DNS_CACHE_SIZE 50               // Size of the DNS cache (number of IPs)

// Structure to store a DNS resolution request
struct dns_request {
    char *hostname;
    struct in_addr ip_address;
};

// Structure to store a DNS resolution result
struct dns_result {
    struct in_addr ip_address;
    int error_code;
};

// Function to perform DNS resolution for a given hostname
// Returns the IP address in a u_char array, or NULL if an error occurs
u_char *resolveHostname(const char *hostname) {
    // Check if there are too many concurrent DNS resolution requests
    if (dns_request_count >= MAX_DNS_RESOLUTION_REQUESTS) {
        printf("Too many concurrent DNS resolution requests\n");
        return NULL;
    }

    // Increment the number of DNS resolution requests
    dns_request_count++;

    // Initialize the DNS cache, if necessary
    if (dns_cache == NULL) {
        dns_cache = calloc(DNS_CACHE_SIZE, sizeof(struct dns_result));
    }

    // Check if the hostname is already in the DNS cache
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(hostname, dns_cache[i].hostname) == 0) {
            return &dns_cache[i].ip_address.s_addr;
        }
    }

    // Perform the DNS resolution query
    struct addrinfo hints = {
        .ai_family = AF_INET,
        .ai_socktype = SOCK_DGRAM,
        .ai_flags = AI_CANONNAME
    };
    struct addrinfo *result;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        printf("Error: DNS resolution failed for %s\n", hostname);
        return NULL;
    }

    // Check if the IP address is cached
    for (struct addrinfo *ptr = result; ptr != NULL; ptr = ptr->ai_next) {
        struct sockaddr_in *sa = (struct sockaddr_in *)(ptr->ai_addr);
        inet_ntop(AF_INET, &(sa->sin_addr), hostname, NI_MAXHOST);
        for (int i = 0; i < DNS_CACHE_SIZE; i++) {
            if (strcmp(hostname, dns_cache[i].hostname) == 0) {
                freeaddrinfo(result);
                return &dns_cache[i].ip_address.s_addr;
            }
        }
    }

    // Cache the resolved IP address if it's not already cached
    struct dns_request *new_req = malloc(sizeof(struct dns_request));
    new_req->hostname = hostname;
    inet_pton(AF_INET, hostname, &(new_req->ip_address.s_addr));
    if (dns_cache_count < DNS_CACHE_SIZE) {
        dns_cache[dns_cache_count++] = new_req;
    } else {
        // If the cache is full, remove the oldest entry and add the new one
        struct dns_request *oldest_req = dns_cache[0];
        for (int i = 1; i < DNS_CACHE_SIZE; i++) {
            if (dns_cache[i].timestamp < oldest_req->timestamp) {
                oldest_req = dns_cache[i];
            }
        }
        free(oldest_req);
        dns_cache[0] = new_req;
    }

    // Return the resolved IP address
    return &new_req->ip_address.s_addr;
}

// Cleanup function to release resources after each DNS resolution attempt
void cleanup(struct addrinfo *result) {
    freeaddrinfo(result);
}
