// Function to generate secure random passwords and hash them using different algorithms
void processUserCredentials(char* username, char* password) {
    // Generate a secure random password
    char pwd[PWD_LEN + 1];
    RAND_bytes(pwd, PWD_LEN);
    pwd[PWD_LEN] = '\0';

    // Hash the password using bcrypt and argon2id
    unsigned char hash1[HASH_LEN], hash2[HASH_LEN];
    EVP_MD_CTX* ctx = EVP_MD_CTX_create();
    EVP_DigestInit(ctx, EVP_sha512());
    EVP_DigestUpdate(ctx, pwd, PWD_LEN);
    EVP_DigestFinal(ctx, hash1, HASH_LEN);
    EVP_MD_CTX_destroy(ctx);
    argon2id_hash(10, 1024, 3, pwd, strlen(pwd), salt, SALT_LEN, hash2, HASH_LEN, NULL, 0);

    // Check if the user has exceeded their login attempt limit within the last hour
    time_t now = time(NULL);
    int i;
    for (i = 0; i < MAX_USERS; i++) {
        if (strcmp(username, usernames[i]) == 0) {
            break;
        }
    }
    if (i >= MAX_USERS) {
        // User not found in cache, generate a new salt and hash
        char salt[SALT_LEN + 1];
        RAND_bytes(salt, SALT_LEN);
        salt[SALT_LEN] = '\0';
        argon2id_hash(10, 1024, 3, password, strlen(password), salt, SALT_LEN, hashes[i], HASH_LEN, NULL, 0);
    } else {
        // User found in cache, check if the password matches the stored hash
        if (strcmp(hash1, hash2) != 0) {
            // Password doesn't match the stored hash, generate a new salt and hash
            char salt[SALT_LEN + 1];
            RAND_bytes(salt, SALT_LEN);
            salt[SALT_LEN] = '\0';
            argon2id_hash(10, 1024, 3, password, strlen(password), salt, SALT_LEN, hashes[i], HASH_LEN, NULL, 0);
        }
    }

    // Update the user's login attempt count and expiration time
    int attempts = 0;
    for (i = 0; i < MAX_USERS; i++) {
        if (strcmp(username, usernames[i]) == 0) {
            break;
        }
    }
    if (i >= MAX_USERS) {
        // User not found in cache, create a new record
        usernames[user_count] = username;
        passwords[user_count] = password;
        salts[user_count] = salt;
        hashes[user_count][HASH_LEN - 1] = '\0';
        user_count++;
    } else {
        // User found in cache, update the record with new information
        passwords[i] = password;
        salts[i] = salt;
        hashes[i][HASH_LEN - 1] = '\0';
    }

    // Handle errors and logging
    if (errno != 0) {
        perror("Error generating random bytes");
        return;
    }
    if (RAND_bytes(pwd, PWD_LEN) == -1) {
        perror("Error generating password");
        return;
    }
}

// Function to check if a given password matches a stored hashed password using the correct algorithm and salt
int checkPassword(char* username, char* password) {
    // Find the user's record in the cache
    int i;
    for (i = 0; i < MAX_USERS; i++) {
        if (strcmp(username, usernames[i]) == 0) {
            break;
        }
    }
    if (i >= MAX_USERS) {
        // User not found in cache, return failure
        return 0;
    }

    // Generate a hash of the provided password using the same algorithm and salt as the stored hash
    unsigned char hash1[HASH_LEN], hash2[HASH_LEN];
    EVP_MD_CTX* ctx = EVP_MD_CTX_create();
    EVP_DigestInit(ctx, EVP_sha512());
    EVP_DigestUpdate(ctx, password, strlen(password));
    EVP_DigestFinal(ctx, hash1, HASH_LEN);
    EVP_MD_CTX_destroy(ctx);
    argon2id_hash(10, 1024, 3, password, strlen(password), salts[i], SALT_LEN, hash2, HASH_LEN, NULL, 0);

    // Compare the generated hash with the stored hash
    if (strcmp(hash1, hashes[i]) == 0) {
        return 1;
    } else {
        return 0;
    }
}

