        # Check if the file is valid and accessible
        if not os.path.exists('uploads'):
            return json.dumps({'error': 'Invalid file'}), 404

        # Save the file to the filesystem
        filename = secure_filename(uploaded_file.filename)
        uploaded_file.save(os.path.join('uploads', filename))

        # Return a JSON response with the uploaded file's metadata
        return json.dumps({'name': filename, 'size': uploaded_file.content_length})

# Define a resource for managing file deletions
class FileDeletionResource(Resource):
    def delete(self, filename):
        # Check if the file exists and is accessible
        if not os.path.exists(os.path.join('uploads', filename)):
            return json.dumps({'error': 'File does not exist'}), 404

        # Delete the file from the filesystem
        os.remove(os.path.join('uploads', filename))

        # Return a JSON response with the deleted file's metadata
        return json.dumps({'name': filename})

# Define a resource for managing user creation and deletion
class UserResource(Resource):
    def post(self):
        # Get the username from the request body
        username = request.form['username']

        # Check if the user exists and is accessible
        if os.path.exists(os.path.join('users', username)):
            return json.dumps({'error': 'User already exists'}), 409

        # Create a new directory for the user
        os.mkdir(os.path.join('users', username))

        # Return a JSON response with the created user's metadata
        return json.dumps({'name': username})

    def delete(self, username):
        # Check if the user exists and is accessible
        if not os.path.exists(os.path.join('users', username)):
            return json.dumps({'error': 'User does not exist'}), 404

        # Delete the user's directory from the filesystem
        shutil.rmtree(os.path.join('users', username))

        # Return a JSON response with the deleted user's metadata
        return json.dumps({'name': username})

# Define a resource for managing file permissions
class PermissionResource(Resource):
    def get(self, filename):
        # Check if the file exists and is accessible
        if not os.path.exists(os.path.join('uploads', filename)):
            return json.dumps({'error': 'File does not exist'}), 404

        # Get the list of users with access to the file
        users = []
        with open(os.path.join('access_control', filename), 'r') as f:
            for user in f.readlines():
                users.append(user.strip())

        # Return a JSON response with the file's metadata and permission list
        return json.dumps({'name': filename, 'users': users})

    def post(self, filename):
        # Check if the file exists and is accessible
        if not os.path.exists(os.path.join('uploads', filename)):
            return json.dumps({'error': 'File does not exist'}), 404

        # Get the username from the request body
        username = request.form['username']

        # Check if the user exists and is accessible
        if not os.path.exists(os.path.join('users', username)):
            return json.dumps({'error': 'User does not exist'}), 404

        # Add the user to the list of users with access to the file
        with open(os.path.join('access_control', filename), 'a') as f:
            f.write(username + '\n')

        # Return a JSON response with the updated permission list
        return self.get(filename)

    def delete(self, filename):
        # Check if the file exists and is accessible
        if not os.path.exists(os.path.join('uploads', filename)):
            return json.dumps({'error': 'File does not exist'}), 404

        # Get the username from the request body
        username = request.form['username']

        # Check if the user exists and is accessible
        if not os.path.exists(os.path.join('users', username)):
            return json.dumps({'error': 'User does not exist'}), 404

        # Remove the user from the list of users with access to the file
        with open(os.path.join('access_control', filename), 'r') as f:
            lines = f.readlines()
        with open(os.path.join('access_control', filename), 'w') as f:
            for line in lines:
                if username not in line:
                    f.write(line)

        # Return a JSON response with the updated permission list
        return self.get(filename)

