import os
import re
from datetime import datetime
from collections import defaultdict

def process_logs(log_dir):
    # Initialize variables
    logs = []
    anomalies = defaultdict(list)
    pattern = r'^(?P<ip>[\d.]+)\s+(?P<date>\S+)\s+(?P<time>\S+)\s+(?P<method>\S+)\s+(?P<url>\S+)\s+(?P<status>\d+)\s+(?P<size>\d+)$'
    sensitivity_levels = {
        'high': 10,
        'medium': 5,
        'low': 2
    }
    log_format = None

    # Walk through the directory and process each file
    for root, dirs, files in os.walk(log_dir):
        for filename in files:
            filepath = os.path.join(root, filename)
            with open(filepath, 'r') as f:
                # Identify the log format and set up the regular expression pattern
                if not log_format:
                    log_format = detect_log_format(f)
                    if log_format == 'apache':
                        pattern = r'^(?P<ip>[\d.]+)\s+(?P<date>\S+)\s+(?P<time>\S+)\s+(?P<method>\S+)\s+(?P<url>\S+)\s+(?P<status>\d+)\s+(?P<size>\d+)$'
                    elif log_format == 'nginx':
                        pattern = r'^(?P<ip>[\d.]+)\s+(?P<date>\S+)\s+(?P<time>\S+)\s+(?P<method>\S+)\s+(?P<url>\S+)\s+(?P<status>\d+)\s+(?P<size>\d+)$'
                    elif log_format == 'windows':
                        pattern = r'^(?P<date>\S+)\s+(?P<time>\S+)\s+(?P<ip>[\d.]+)\s+(?P<status>\d+)\s+(?P<method>\S+)\s+(?P<url>\S+)$'
                    else:
                        raise ValueError(f'Unsupported log format: {log_format}')
                # Process the file line by line and identify anomalies
                for line in f:
                    match = re.match(pattern, line)
                    if match:
                        ip = match.group('ip')
                        date = match.group('date')
                        time = match.group('time')
                        method = match.group('method')
                        url = match.group('url')
                        status = int(match.group('status'))
                        size = int(match.group('size'))
                        # Check for high-frequency requests
                        if sensitivity_levels['high'] > 0 and method == 'GET' and url != '/favicon.ico':
                            logs.append((filepath, ip, date, time, method, url, status, size))
                            anomalies[filename].append(f'{ip} made {status} requests to {url} at {date} {time}')
                        # Check for unauthorized access attempts
                        if sensitivity_levels['high'] > 0 and method == 'POST' and url == '/login':
                            logs.append((filepath, ip, date, time, method, url, status, size))
                            anomalies[filename].append(f'{ip} attempted to login at {date} {time}')
                        # Check for high-anomaly IP addresses
                        if sensitivity_levels['medium'] > 0 and ip in get_high_anomaly_ips():
                            logs.append((filepath, ip, date, time, method, url, status, size))
                            anomalies[filename].append(f'{ip} has high anomaly score')
                        # Check for unauthorized access attempts
                        if sensitivity_levels['low'] > 0 and method == 'POST' and url == '/login':
                            logs.append((filepath, ip, date, time, method, url, status, size))
                            anomalies[filename].append(f'{ip} attempted to login at {date} {time}')
    # Cross-reference detected IP addresses and domain names against the threat intelligence feed
    for filename in anomalies:
        for log in logs:
            if log[1] in get_malicious_ips():
                anomalies[filename].append(f'{log[1]} is a malicious IP address')
            elif log[2] in get_malicious_domains():
                anomalies[filename].append(f'{log[2]} is a malicious domain')
    # Filter out legitimate but benign activities
    for filename in anomalies:
        for index, entry in enumerate(anomalies[filename]):
            if entry.startswith('High-frequency requests'):
                del anomalies[filename][index]
            elif entry.startswith('Unauthorized access attempt'):
                del anomalies[filename][index]
    # Log all processing activities and summarize the anomaly reports
    log_processing_activities(logs)
    return anomalies

def detect_log_format(file):
    # Identify the log format by checking for specific patterns
    for line in file:
        if '[' in line:
            return 'apache'
        elif ',' in line:
            return 'nginx'
        else:
            return 'windows'

def get_high_anomaly_ips():
    # Return a list of high-anomaly IP addresses from the threat intelligence feed
    return ['192.0.2.1', '198.51.100.1']

def get_malicious_ips():
    # Return a list of malicious IP addresses from the threat intelligence feed
    return ['192.0.2.1', '198.51.100.1', '192.0.2.4']

def get_malicious_domains():
    # Return a list of malicious domains from the threat intelligence feed
    return ['example.com', 'example2.net']

def log_processing_activities(logs):
    # Log all processing activities to a file
    with open('processing_activities.log', 'a') as f:
        for log in logs:
            f.write(f'{datetime.now()} {log[0]} {log[1]} {log[2]} {log[3]} {log[4]} {log[5]} {log[6]}\n')
