async function reduce(numbers) {
  if (!Array.isArray(numbers)) {
    throw new Error("Invalid input type, expected an array");
  }

  const externalService = new ExternalService(); // encapsulate the external service interaction within a separate module/class
  const chunks = numbers.length > 1000 ? chunkArray(numbers, 1000) : [numbers]; // split the array into smaller chunks for processing

  let result = 0;
  for (const chunk of chunks) {
    try {
      const response = await externalService.fetchNumbers(chunk); // fetch numbers from the simulated database or API
      const numberList = response.data.map((number) => parseInt(number)); // convert string to number and filter out invalid numbers

      for (const number of numberList) {
        result += await externalService.reduceNumber(number); // reduce each number using the external service
      }
    } catch (error) {
      console.log(`Error fetching numbers: ${error}`);
    }
  }

  return result;
}
