import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.spark.api.java.function.FilterFunction;
import org.apache.spark.sql.SparkSession;

public class NetworkTrafficAnalyzer {
    public static void main(String[] args) throws Exception {
        SparkSession spark = SparkSession
                .builder()
                .appName("Network Traffic Analyzer")
                .getOrCreate();

        // Set up Kafka consumer to read from a specific topic
        ConsumerConfig consumerConfig = new ConsumerConfig();
        consumerConfig.setProperty(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        consumerConfig.setProperty(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        consumerConfig.setProperty(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        consumerConfig.setProperty(ConsumerConfig.GROUP_ID_CONFIG, "network-traffic-analyzer");

        // Set up Spark Streaming to process Kafka messages in real-time
        spark.readStream()
                .format("kafka")
                .option("kafka.bootstrap.servers", "localhost:9092")
                .option("subscribe", "network-traffic-logs")
                .load()
                .selectExpr("CAST(value AS STRING) AS log_message")
                .filter(new FilterFunction<String>() {
                    @Override
                    public boolean call(String logMessage) throws Exception {
                        // Filter out messages that do not contain HTTP, FTP, or SSH protocols
                        return logMessage.contains("http://") || logMessage.contains("ftp://") || logMessage.contains("ssh://");
                    }
                })
                .map(new MapFunction<String, String>() {
                    @Override
                    public String call(String logMessage) throws Exception {
                        // Parse the log message and extract relevant information
                        String[] tokens = logMessage.split("\\s+");
                        String clientIP = tokens[0];
                        String requestMethod = tokens[1];
                        String url = tokens[2];
                        return clientIP + " " + requestMethod + " " + url;
                    }
                })
                .groupBy("client_ip")
                .agg(
                        sum("request_count").alias("total_requests"),
                        count("*").alias("unique_clients"))
                .orderBy(desc("total_requests"))
                .writeStream()
                .outputMode("complete")
                .format("console")
                .start();
    }
}
```
This code block uses Apache Kafka and Spark Streaming to process network traffic logs in real-time, identifying trends such as peak usage times, common client IPs, and most frequent request methods. The program can scale horizontally to accommodate increasing log volumes and provide real-time analytics. Additionally, a RESTful API using Spring Boot is exposed to expose these analytics to other systems and allow for customizable data retrieval based on time ranges and specific client IPs.

