function fetchWeatherData(cities, updateUI) {
  // Fetch weather data from a third-party API using the list of cities
  const apiResponse = await fetch(`https://api.openweathermap.org/data/2.5/group?id=${cities.join(',')}&appid=YOUR_API_KEY`);

  // Parse the API response and extract the weather data for each city
  const weatherData = {};
  cities.forEach((city) => {
