// Define a class to manage the Sandesh client
class SandeshClient {
 public:
  // Constructor that takes a boost::asio::io_context and a remote server address
  explicit SandeshClient(io_context& io_ctx, const string& hostname) : io_ctx_(io_ctx), hostname_(hostname) {}

  // Send a GET request to the remote server
  void sendGetRequest(const string& url, function<void(const boost::system::error_code&)> handler) {
    auto resolver = io_ctx_.resolver().create_query(hostname_, "80", url);
    io_ctx_.async_resolve(resolver, [this, handler](const error_code& ec, iterator it) {
      if (ec) {
        handler(ec);
        return;
      }
      boost::asio::ip::tcp::socket socket(io_ctx_);
      io_ctx_.async_connect(socket, it, [this, &socket, handler](const error_code& ec, iterator) {
        if (ec) {
          handler(ec);
          return;
        }
        boost::asio::streambuf request;
        writeRequest(request);
        asyncSend(socket, request, handler);
      });
    });
  }

  // Send a POST request to the remote server
  void sendPostRequest(const string& url, const string& body, function<void(const boost::system::error_code&)> handler) {
    auto resolver = io_ctx_.resolver().create_query(hostname_, "80", url);
    io_ctx_.async_resolve(resolver, [this, handler](const error_code& ec, iterator it) {
      if (ec) {
        handler(ec);
        return;
      }
      boost::asio::ip::tcp::socket socket(io_ctx_);
      io_ctx_.async_connect(socket, it, [this, &socket, body, handler](const error_code& ec, iterator) {
        if (ec) {
          handler(ec);
          return;
        }
        boost::asio::streambuf request;
        writeRequest(request, body);
        asyncSend(socket, request, handler);
      });
    });
  }

 private:
  // Write the GET or POST request to the buffer
  void writeRequest(boost::asio::streambuf& buf, const string& body = "") {
    std::ostream os(&buf);
    os << "GET /" << url_ << " HTTP/1.1\r\n";
    os << "Host: " << hostname_ << "\r\n";
    if (!body.empty()) {
      os << "Content-Type: application/json\r\n";
      os << "Content-Length: " << body.size() << "\r\n";
      os << "\r\n";
      os << body;
    } else {
      os << "\r\n";
    }
  }

  // Send the request asynchronously and handle the response
  void asyncSend(boost::asio::ip::tcp::socket& socket, boost::asio::streambuf& buf, function<void(const boost::system::error_code&)> handler) {
    std::ostream os(&buf);
    os << "GET /" << url_ << " HTTP/1.1\r\n";
    os << "Host: " << hostname_ << "\r\n";
    if (!body_.empty()) {
      os << "Content-Type: application/json\r\n";
      os << "Content-Length: " << body_.size() << "\r\n";
      os << "\r\n";
      os << body_;
    } else {
      os << "\r\n";
    }
  }

 private:
  io_context& io_ctx_;
  string hostname_;
  string url_;
};

// Define a class to manage the cache of file metadata and hashes
class MetadataCache {
 public:
  // Constructor that takes a maximum size for the cache
  explicit MetadataCache(size_t max_size) : max_size_(max_size) {}

  // Add a new entry to the cache, evicting an existing entry if necessary
  void addEntry(const string& filename, const FileMetadata& metadata, const string& hash) {
    auto it = cache_.find(filename);
    if (it != cache_.end()) {
      cache_.erase(it);
    }
    cache_[filename] = make_shared<CacheEntry>(metadata, hash);
    if (cache_.size() > max_size_) {
      auto oldest_it = next(cache_.begin());
      cache_.erase(oldest_it);
    }
  }

  // Retrieve a cached entry for the given filename, or nullptr if none exists
  shared_ptr<CacheEntry> getEntry(const string& filename) {
    auto it = cache_.find(filename);
    return (it != cache_.end()) ? it->second : nullptr;
  }

 private:
  struct CacheEntry {
    FileMetadata metadata;
    string hash;
  };

  size_t max_size_;
  map<string, shared_ptr<CacheEntry>> cache_;
};

