const fs = require('fs');
const path = require('path');
const util = require('util');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const statAsync = promisify(fs.stat);
const readdirAsync = promisify(fs.readdir);
const uploadToCloud = async (file, content) => {
  // Implement the cloud storage service upload functionality here
};

async function readDirectory(directoryPath, fileExtension = null, timeout = 5000) {
  const files = await readdirAsync(directoryPath);
  const filteredFiles = files.filter((file) => {
    if (fileExtension && path.extname(file) !== fileExtension) return false;
    return !path.basename(file).startsWith('.');
  });
  const promises = [];
  for (const file of filteredFiles) {
    const fullPath = path.join(directoryPath, file);
    if (fs.statSync(fullPath).size > 1024 * 1024) continue; // skip large files
    promises.push(readFileAsync(fullPath, { timeout }).then((content) => {
      return {
        filename: file,
        content: content.toString(),
      };
    }).catch((err) => {
      console.warn(`Error reading file ${file}: ${err}`);
      return null;
    }));
  }
  const results = await Promise.all(promises);
  if (uploadToCloud) {
    for (const result of results) {
      if (result !== null) {
        await uploadToCloud(result.filename, result.content);
      }
    }
  }
  return results;
}
