Here's an example usage of the secure messaging service:
```c
int main() {
  // Load the cryptographic libraries and initialize the algorithms from a configuration file.
  const char* config_file = "config.txt";
  int result = initialize_secure_messaging_service(config_file);
  if (result != 0) {
    printf("Error initializing secure messaging service\n");
    return -1;
  }

  // Encrypt a message using AES-256.
  const char* plaintext = "Hello, world!";
  size_t plaintext_len = strlen(plaintext);
  unsigned char ciphertext[AES_BLOCK_SIZE * (plaintext_len / AES_BLOCK_SIZE + 1)];
  struct algorithm* alg = get_algorithm("AES-256");
  int error = encrypt(plaintext, plaintext_len, alg, ciphertext);
  if (error != 0) {
    printf("Error encrypting message\n");
    return -1;
  }

  // Decrypt the ciphertext using ChaCha20.
  unsigned char plaintext[AES_BLOCK_SIZE * (plaintext_len / AES_BLOCK_SIZE + 1)];
  struct algorithm* alg = get_algorithm("ChaCha20");
  error = decrypt(ciphertext, sizeof(ciphertext), alg, plaintext);
  if (error != 0) {
    printf("Error decrypting message\n");
    return -1;
  }

  // Compute a SHA-256 digest of the plaintext.
  unsigned char digest[SHA256_DIGEST_LENGTH];
  struct algorithm* alg = get_algorithm("SHA-256");
  error = hash(plaintext, sizeof(plaintext), alg, digest);
  if (error != 0) {
    printf("Error computing SHA-256 digest\n");
    return -1;
  }

  // Print the decrypted plaintext and the computed SHA-256 digest.
  printf("Decrypted plaintext: %s\n", plaintext);
  printf("SHA-256 digest: ");
  for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
    printf("%02x ", digest[i]);
  }
  printf("\n");

  // Free the allocated resources.
  free_algorithm(alg);

  return 0;
}
```
