import java.util.List;
import java.util.Map;

public class EvolutionsManager {
    private static final int CACHE_SIZE = 10000; // Size of the cache for evolutions and weaknesses
    private static final long CACHE_EXPIRATION_TIME = 60 * 60 * 1000; // Time in milliseconds to expire cached data

    private Map<String, Evolution> evolutionCache; // Cache of evolutions for each Pokemon
    private Map<String, List<String>> weaknessCache; // Cache of weaknesses for each Pokemon

    public EvolutionsManager() {
        this.evolutionCache = new HashMap<>();
        this.weaknessCache = new HashMap<>();
    }

    public Evolution getEvolution(String pokemonName) {
        Evolution evolution = evolutionCache.get(pokemonName);
        if (evolution == null || isExpired(evolution)) {
            try {
                evolution = fetchEvolutionFromApi(pokemonName);
                evolutionCache.put(pokemonName, evolution);
            } catch (Exception e) {
                // Handle exception by logging and returning default value
            }
        }
        return evolution;
    }

    public List<String> getWeaknesses(String pokemonName) {
        List<String> weaknesses = weaknessCache.get(pokemonName);
        if (weaknesses == null || isExpired(weaknesses)) {
            try {
                weaknesses = fetchWeaknessesFromApi(pokemonName);
                weaknessCache.put(pokemonName, weaknesses);
            } catch (Exception e) {
                // Handle exception by logging and returning default value
            }
        }
        return weaknesses;
    }

    private boolean isExpired(Object obj) {
        if (obj instanceof Evolution) {
