import java.util.HashMap;
import java.util.Map;
import org.springframework.web.client.RestTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;

@Service
public class EvolutionsHub {
    private static final String API_URL_1 = "https://api1.example.com/pokemon";
    private static final String API_URL_2 = "https://api2.example.com/pokemon";
    private static final String API_URL_3 = "https://api3.example.com/pokemon";

    @Autowired
    RestTemplate restTemplate;

    @Autowired
    ObjectMapper objectMapper;

    // Caching mechanism to reduce API calls and improve performance
    private Map<String, JsonNode> evolutionCache = new HashMap<>();

    public JsonNode getPokemon(String id) {
        // Check the cache for the Pokemon ID first
        if (evolutionCache.containsKey(id)) {
            return evolutionCache.get(id);
        }

        // Fetch the Pokemon data from the external APIs using a fallback mechanism
        JsonNode node = null;
        try {
            node = fetchPokemonFromApi1(id);
        } catch (Exception e) {
            // Try API 2 if API 1 is unavailable
            try {
                node = fetchPokemonFromApi2(id);
            } catch (Exception e2) {
                // Try API 3 if both APIs are unavailable
                try {
                    node = fetchPokemonFromApi3(id);
                } catch (Exception e3) {
                    // If all APIs are unavailable, return a JSON error message
                    JsonNode errorMessage = objectMapper.createObjectNode()
                            .put("error", "All APIs are unavailable");
                    return errorMessage;
                }
            }
        }

        // Cache the Pokemon data for future requests
        evolutionCache.put(id, node);

        // Return the JSON response
        return node;
    }

    private JsonNode fetchPokemonFromApi1(String id) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        String url = API_URL_1 + "/" + id;
        return restTemplate.exchange(url, HttpMethod.GET, null, JsonNode.class, new Object[]{}).getBody();
    }

    private JsonNode fetchPokemonFromApi2(String id) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        String url = API_URL_2 + "/" + id;
        return restTemplate.exchange(url, HttpMethod.GET, null, JsonNode.class, new Object[]{}).getBody();
    }

    private JsonNode fetchPokemonFromApi3(String id) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        String url = API_URL_3 + "/" + id;
        return restTemplate.exchange(url, HttpMethod.GET, null, JsonNode.class, new Object[]{}).getBody();
    }
}
