const path = require('path');
const fs = require('fs');
const { promisify } = require('util');
const npm = require('npm');

// Load modules from file paths and manage their execution order based on dependencies
class ModuleLoader {
  constructor(modules, dependencies) {
    this.modules = modules;
    this.dependencies = dependencies;
  }

  // Load module files asynchronously and cache them locally for faster access
  async loadModules() {
    const cache = {};
    await Promise.all(this.modules.map(async (module) => {
      try {
        const filePath = path.join(__dirname, 'modules', module);
        const content = await promisify(fs.readFile)(filePath, 'utf8');
        cache[module] = content;
      } catch (error) {
        console.log(`Failed to load ${module}:`, error.message);
      }
    }));
    return cache;
  }

  // Resolve module dependencies using npm's dependency graph and manage execution order
  async resolveDependencies() {
    const deps = {};
    for (const module of this.modules) {
      try {
        const json = await npm.getPackageJson(module);
        deps[json.name] = json.dependencies;
      } catch (error) {
        console.log(`Failed to resolve dependencies for ${module}:`, error.message);
      }
    }
    return this.resolveDependencyOrder(deps, this.modules);
  }

  // Recursively resolve module dependencies based on their dependencies
  resolveDependencyOrder(deps, modules) {
    const order = [];
    for (const module of modules) {
      if (!deps[module]) continue;
      const depList = deps[module];
      for (const dep of depList) {
        if (!order.includes(dep)) {
          order.push(dep);
          this.resolveDependencyOrder(deps, [dep]);
        }
      }
    }
    return order;
  }

  // Execute modules in the correct order based on their dependencies and handle errors
  async executeModules() {
    const cache = await this.loadModules();
    const deps = await this.resolveDependencies();
    for (const module of deps) {
      try {
        const filePath = path.join(__dirname, 'modules', module);
        const content = cache[module];
        if (!content) continue;
        console.log(`Executing ${module}...`);
        const result = await eval(content);
        console.log(`Finished executing ${module}:`, result);
      } catch (error) {
        console.log(`Failed to execute ${module}:`, error.message);
      }
    }
  }
}

// Configure the program to run in different environments with their own dependencies and requirements
const modules = ['module1', 'module2', 'module3'];
const dependencies = { module1: [], module2: [], module3: [] };
const loader = new ModuleLoader(modules, dependencies);
loader.executeModules().catch((error) => console.log('Error executing modules:', error));
```
