                cerr << "API call failed with error: " << e.what() << endl;

                // Handle transient failure and retry with exponential backoff
                chrono::steady_clock::time_point now = chrono::steady_clock::now();
                chrono::duration<double> elapsedTime = now - lastApiCallTime;
                if (elapsedTime.count() < 5) {
                    this_thread::sleep_for(chrono::milliseconds((int)(pow(2, apiCallCount) * 1000)));
                    apiCallCount++;
                } else {
                    cerr << "API rate limit exceeded. Retrying in " << (apiRateLimit - apiCallCount) << " attempts." << endl;
                    lastApiCallTime = now;
                    apiCallCount = 0;
                }
            }
        }

        // Handle API rate limit violation and retry with exponential backoff
        if (apiCallCount >= apiRateLimit) {
            chrono::steady_clock::time_point now = chrono::steady_clock::now();
            chrono::duration<double> elapsedTime = now - lastApiCallTime;
            if (elapsedTime.count() < 5) {
                this_thread::sleep_for(chrono::milliseconds((int)(pow(2, apiCallCount) * 1000)));
            } else {
                cerr << "API rate limit exceeded. Retrying in " << (apiRateLimit - apiCallCount) << " attempts." << endl;
                lastApiCallTime = now;
                apiCallCount = 0;
            }
        }

        // Update API call count and time
        apiCallsRemaining_++;
        lastApiCallTime_ = chrono::steady_clock::now();
    }

