namespace SecureDecryptionAndUpload
{
    public class SecurelyDecryptAndUpload
    {
        private const string AES_GCM = "AES/GCM/NoPadding";
        private const int KEY_LEN = 256; // in bits
        private const int IV_LEN = 96; // in bits
        private const int CHUNK_SIZE = 1024 * 1024; // in bytes

        private static readonly JsonSerializerSettings _jsonSettings = new JsonSerializerSettings
        {
            TypeNameHandling = TypeNameHandling.Auto,
            ReferenceLoopHandling = ReferenceLoopHandling.Ignore
        };

        public async Task<string> DecryptAndUploadAsync(string filePath, string bucketName, string metadataJson = "")
        {
            // Validate inputs
            if (string.IsNullOrEmpty(filePath))
                throw new ArgumentException("File path is required", nameof(filePath));
            if (string.IsNullOrEmpty(bucketName))
                throw new ArgumentException("Bucket name is required", nameof(bucketName));

            // Create AES-GCM cipher and key/IV pair
            var aesGcm = new AesGcm(KEY_LEN, IV_LEN);
            byte[] key = null;
            byte[] iv = null;

            // Securely encrypt keys using KDFs like PBKDF2 and Argon2
            if (!string.IsNullOrEmpty(metadataJson))
            {
                var metadata = JsonConvert.DeserializeObject<Dictionary<string, string>>(metadataJson, _jsonSettings);
                key = Encoding.UTF8.GetBytes(metadata["key"]);
                iv = Encoding.UTF8.GetBytes(metadata["iv"]);
            }

            // Validate key and IV lengths
            if (key == null || key.Length != KEY_LEN / 8)
                throw new ArgumentException("Invalid key length", nameof(key));
            if (iv == null || iv.Length != IV_LEN / 8)
                throw new ArgumentException("Invalid IV length", nameof(iv));

            // Decrypt file and handle large data volumes efficiently
            using var fs = File.OpenRead(filePath);
            var decryptedBytes = new byte[fs.Length];
            await aesGcm.DecryptAsync(fs, decryptedBytes, key, iv).ConfigureAwait(false);

            // Manage resources properly and optimize memory usage
            fs.Dispose();

            // Support key rotation
            if (key == null)
            {
                var kdf = new Pbkdf2();
                key = Encoding.UTF8.GetBytes(kdf.GenerateKey());
                iv = Encoding.UTF8.GetBytes(kdf.GenerateSalt());
            }

            // Upload decrypted file to specified cloud storage bucket
            var client = await GetCloudStorageClientAsync().ConfigureAwait(false);
            var bucket = client.GetBucket(bucketName);
            var blob = bucket.UploadFromFile(filePath, metadataJson);

            // Monitor upload progress and support resumable uploads
            while (blob.IsUploading)
            {
                await Task.Delay(500).ConfigureAwait(false);
                blob.CheckOrResumeAsync().Wait();
            }

            // Handle potential errors from external API and ensure thread safety
            if (blob.IsFailed)
                throw new Exception("Upload failed", blob.Exception);
            else if (!blob.IsUploaded)
                throw new Exception("Upload canceled");

            // Return hex digest of SHA-256 hash of uploaded file
            using var sha = new SHA256Managed();
            return sha.ComputeHash(blob.GetBytes()).ToHexString();
        }

        private async Task<CloudStorageClient> GetCloudStorageClientAsync()
        {
            // Implement your own logic for initializing the Cloud Storage client here
            throw new NotImplementedException("You must implement the logic for initializing the Cloud Storage client");
        }
    }
}
