import os
import json
from datetime import datetime, timedelta
from threading import Lock

# Weather API credentials and settings
WEATHER_API = "OPENWEATHERMAP" # or WEATHERAPI or ACCUWEATHER
api_key = os.getenv("WEATHER_API_KEY")
base_url = {
    "OPENWEATHERMAP": "https://api.openweathermap.org/data/2.5",
    "WEATHERAPI": "https://api.weatherapi.com/v1",
    "ACCUWEATHER": "https://dataservice.accuweather.com/currentconditions/v1"
}[WEATHER_API]
rate_limit = {
    "OPENWEATHERMAP": 5,
    "WEATHERAPI": 20,
    "ACCUWEATHER": 60
}[WEATHER_API]
cache_expiration = timedelta(minutes=30)

# Caching mechanism
class WeatherCache:
    def __init__(self):
        self.data = {}
        self.lock = Lock()

    def get(self, location):
        with self.lock:
            if location in self.data and (datetime.now() - self.data[location]["timestamp"] < cache_expiration):
                return self.data[location]["data"]
            else:
                return None

    def set(self, location, data):
        with self.lock:
            self.data[location] = {"data": data, "timestamp": datetime.now()}

# Weather API session management
class WeatherSession:
    def __init__(self, api_key, base_url):
        self.api_key = api_key
        self.base_url = base_url
        self.session = requests.Session()
        self.session.headers["Authorization"] = "Bearer {}".format(self.api_key)

    def request(self, method, url, params=None, data=None):
        url = self.base_url + url
        response = self.session.request(method, url, params=params, data=data)
        if response.status_code == 429:
            # Rate limit exceeded
            time.sleep(response.headers["Retry-After"])
            return self.request(method, url, params, data)
        elif response.status_code >= 500:
            # Server error
            return None
        else:
            return response.json()

# Weather API request wrapper
def weather_request(location):
    session = WeatherSession(api_key, base_url)
    cache = WeatherCache()

    data = cache.get(location)
    if not data:
        method = "GET"
        url = "/weather"
        params = {
            "q": location,
            "units": "imperial",
            "lang": "en"
        }
        response = session.request(method, url, params=params)
        if response:
            cache.set(location, response)
            data = response
    return data

# Weather data retrieval function
def get_weather_data(locations):
    data = {}
    for location in locations:
        try:
            weather_data = weather_request(location)
            if not weather_data:
                raise Exception("Failed to retrieve weather data")
            data[location] = weather_data
        except:
            # Handle exception
            pass
    return data

# CLI and web request interfaces
def cli_interface():
    locations = input("Enter location(s) separated by comma (e.g., New York, London): ")
    locations = [location.strip() for location in locations.split(",")]
    weather_data = get_weather_data(locations)
    print("Current weather conditions:")
    for location in locations:
        if not weather_data[location]:
            print("Failed to retrieve data for {}. Please try again.".format(location))
        else:
            print("Location: {}".format(location))
            print("Temperature: {}".format(weather_data[location]["main"]["temp"]))
            print("Humidity: {}".format(weather_data[location]["main"]["humidity"]))
    print("7-day forecast:")
    for location in locations:
        if not weather_data[location]:
            continue
        for day in weather_data[location]["forecast"]:
            print("Date: {}".format(day["date"]))
            print("Temperature: {}".format(day["temp"]["day"]))
            print("Humidity: {}".format(day["humidity"]))

def web_interface():
    locations = request.args.get("locations")
    if not locations:
        raise Exception("Locations are required")
    locations = [location.strip() for location in locations.split(",")]
    weather_data = get_weather_data(locations)
    return jsonify({"status": "success", "data": weather_data})
```
This code defines a `get_weather_data` function that takes a list of locations as input and returns the current weather conditions and 7-day forecasts for each location. It also defines a `cli_interface` function that provides a CLI interface to retrieve weather data, and a `web_interface` function that provides a web interface to retrieve weather data.

The `get_weather_data` function uses the `weather_request` function to make API requests to different weather APIs based on the environmental variable `WEATHER_API`. It also uses a caching mechanism to store weather data for up to 30 minutes to improve performance.

The `cli_interface` function prompts the user to enter locations separated by comma, and then retrieves the current weather conditions and 7-day forecasts for each location using the `get_weather_data` function. It then prints the results to the console.

The `web_interface` function takes a query parameter `locations` that contains a list of locations separated by comma, and then retrieves the current weather conditions and 7-day forecasts for each location using the `get_weather_data` function. It then returns the results in JSON format.

This code is designed to be modular, allowing easy updates and maintenance without affecting other parts of the code. It also provides a CLI and web interface for retrieving weather data, making it easier to use the functionality in different contexts.

