    public class ClimateMiddleware
    {
        private const string CLIMATE_API = "https://api.climateapi.com/";
        private const string METEOSTAT_API = "https://api.meteostat.com/";
        private const string WEATHERDB_API = "https://api.weatherdb.com/";

        private readonly Dictionary<string, string> _apiKeys;
        private readonly HashSet<string> _cachedData;
        private readonly HttpClient _httpClient;

        public ClimateMiddleware(Dictionary<string, string> apiKeys)
        {
            _apiKeys = apiKeys;
            _httpClient = new HttpClient();
            _cachedData = new HashSet<string>();
        }

        public async Task UpdateClimateData()
        {
            var tasks = new List<Task<HttpResponseMessage>>();

            foreach (var api in _apiKeys.Keys)
            {
                var task = GetClimateData(api);
                tasks.Add(task);
            }

            await Task.WhenAll(tasks);
        }

        private async Task<HttpResponseMessage> GetClimateData(string api)
        {
            try
            {
                var request = new HttpRequestMessage(HttpMethod.Get, $"{api}/climate-data");
                request.Headers.Add("Authorization", $"Bearer {_apiKeys[api]}");

                return await _httpClient.SendAsync(request);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching climate data from {api}: {ex.Message}");
                return null;
            }
        }

        public async Task<ClimateData> GetCachedClimateData(string api, string location)
        {
            if (_cachedData.ContainsKey($"{api}-{location}"))
            {
                var data = _cachedData[$"{api}-{location}"];
                return JsonConvert.DeserializeObject<ClimateData>(data);
            }

            var response = await GetClimateData(api, location);
            if (response != null)
            {
                var data = await response.Content.ReadAsStringAsync();
                _cachedData[$"{api}-{location}"] = data;
                return JsonConvert.DeserializeObject<ClimateData>(data);
            }

            return null;
        }

