namespace CustomRandomGenerators
{
    public class CustomRandomGenerator
    {
        private readonly int _seed;
        private readonly double _mean;
        private readonly Random _random;

        // Constructor to set the initial range and seed
        public CustomRandomGenerator(int min, int max, int seed)
        {
            _min = min;
            _max = max;
            _seed = seed;
            _random = new Random(_seed);
        }

        // Constructor to set the initial range and mean
        public CustomRandomGenerator(int min, int max, double mean)
        {
            _min = min;
            _max = max;
            _mean = mean;
            _random = new Random(_seed);
        }

        // Method to generate a random integer within the specified range
        public int GetRandomInt()
        {
            return _random.Next(_min, _max + 1);
        }

        // Method to generate a random float within the specified range
        public double GetRandomFloat()
        {
            return (double)_random.NextDouble() * (_max - _min) + _min;
        }

        // Method to generate a sequence of random integers or floats within the specified range
        public IEnumerable<int> GetSequence(int length)
        {
            for (int i = 0; i < length; i++)
            {
                yield return this.GetRandomInt();
            }
        }

        // Method to generate a sequence of random integers or floats within the specified range based on a normal distribution centered around the mean value
        public IEnumerable<double> GetSequence(int length, double mean)
        {
            for (int i = 0; i < length; i++)
            {
                yield return this.GetRandomFloat() * mean;
            }
        }

        // Method to reset the generator to its initial state
        public void Reset()
        {
            _random = new Random(_seed);
        }

        // Method to set the range dynamically after initialization
        public void SetRange(int min, int max)
        {
            _min = min;
            _max = max;
        }

        // Method to get the current seed value
        public int GetSeed()
        {
            return _seed;
        }

        // Method to set the seed value dynamically after initialization
        public void SetSeed(int newSeed)
        {
            _seed = newSeed;
        }

        // Override ToString method to display the current range, seed value, and additional relevant information about the generator's state
        public override string ToString()
        {
            return $"CustomRandomGenerator: Range={_min}-{_max}, Seed={_seed}, Mean={_mean}";
        }
    }
}
