public class UpdateClinicStatusManager {
    private static final Logger LOGGER = Logger.getLogger(UpdateClinicStatusManager.class.getName());

    // Configuration properties
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final long REQUEST_TIMEOUT = TimeUnit.MINUTES.toMillis(1);
    private static final long CACHE_EXPIRATION_TIME = TimeUnit.HOURS.toMillis(12);
