    public void fetchAndMergeClinicStatusUpdates(String clinicId, String newStatus, String lastModifiedIp, Map<String, String> environmentVariables, List<ClassProvider> externalDataSources) {
        // Create a semaphore to limit the number of concurrent requests from the same IP address
        Semaphore requestSemaphore = new Semaphore(MAX_CONCURRENT_REQUESTS);

        // Create an executor service for managing asynchronous tasks
        ExecutorService executor = Executors.newFixedThreadPool(5);

        try {
            // Verify clinic details through all specified external APIs
            boolean validDetails = verifyClinicDetails(clinicId, environmentVariables, externalDataSources);

            if (validDetails) {
                // Acquire a permit from the semaphore to proceed with the request
                requestSemaphore.acquire();

                // Fetch and merge clinic status updates from all external APIs in parallel
                List<Future<Object>> futures = executor.invokeAll(externalDataSources, new UpdateClinicStatusCallable(clinicId, newStatus, lastModifiedIp));

                // Merge data from different APIs and update the clinic status in the database
                mergeAndUpdateClinicStatus(futures);
            } else {
                LOGGER.warning("Invalid clinic details received, cannot proceed with updating clinic status");
            }
        } catch (InterruptedException e) {
            LOGGER.severe("Error occurred while acquiring semaphore permit: " + e.getMessage());
        } finally {
            // Release the semaphore if it's still acquired
            requestSemaphore.release();

            // Shut down the executor service to ensure all tasks are completed and resources are released
            executor.shutdownNow();
        }
