int main() {
  // Load an image from a file using OpenCV
  cv::Mat inputImage = cv::imread("input_image.jpg", CV_LOAD_IMAGE_COLOR);

  // Store the image data in the global variable "imageData"
  storeImageData(std::vector<unsigned char>(inputImage.data, inputImage.data + inputImage.total() * inputImage.elemSize()));

  // Set the image dimensions and channels using OpenCV
  width = inputImage.cols;
  height = inputImage.rows;
  channels = inputImage.channels();

  // Set the backend type to OpenCV by default
  setBackendType(OPENCV_BACKEND);

  // Demonstrate the use of the image processing library
  resizeImage(640, 480);
  cropImage(100, 100, 320, 240);
  colorConvert(3);
  edgeDetection();
  histogramEqualization();
  noiseReduction();

  // Save the processed image to a file using OpenCV
  cv::Mat outputImage = cv::imread("output_image.jpg", CV_LOAD_IMAGE_COLOR);
  saveImageDataToFile("output_image.jpg");

  return 0;
}

void resizeImage(const int newWidth, const int newHeight) {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat resizedImage = cv::resize(cv::Mat(height, width, CV_8UC3, imageData.data()), cv::Size(newWidth, newHeight));
    storeImageData(std::vector<unsigned char>(resizedImage.data, resizedImage.data + resizedImage.total() * resizedImage.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.Resize((unsigned int)newWidth, (unsigned int)newHeight);
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}

void cropImage(const int x, const int y, const int newWidth, const int newHeight) {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat croppedImage = cv::crop(cv::Mat(height, width, CV_8UC3, imageData.data()), cv::Rect(x, y, newWidth, newHeight));
    storeImageData(std::vector<unsigned char>(croppedImage.data, croppedImage.data + croppedImage.total() * croppedImage.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.Crop((unsigned int)x, (unsigned int)y, (unsigned int)newWidth, (unsigned int)newHeight);
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}

void colorConvert(const int newChannels) {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat convertedImage = cv::cvtColor(cv::Mat(height, width, CV_8UC3, imageData.data()), newChannels);
    storeImageData(std::vector<unsigned char>(convertedImage.data, convertedImage.data + convertedImage.total() * convertedImage.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.Convert((unsigned int)newChannels);
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}

void edgeDetection() {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat edges = cv::Canny(cv::Mat(height, width, CV_8UC3, imageData.data()), 100, 200);
    storeImageData(std::vector<unsigned char>(edges.data, edges.data + edges.total() * edges.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.EdgeDetect(true);
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}

void histogramEqualization() {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat equalizedImage = cv::equalizeHist(cv::Mat(height, width, CV_8UC3, imageData.data()));
    storeImageData(std::vector<unsigned char>(equalizedImage.data, equalizedImage.data + equalizedImage.total() * equalizedImage.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.HistogramEqualize();
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}

void noiseReduction() {
  // Check if the backend type is OpenCV or ImageMagick
  if (backendType == OPENCV_BACKEND) {
    cv::Mat reducedNoiseImage = cv::fastNlMeansDenoising(cv::Mat(height, width, CV_8UC3, imageData.data()), 10);
    storeImageData(std::vector<unsigned char>(reducedNoiseImage.data, reducedNoiseImage.data + reducedNoiseImage.total() * reducedNoiseImage.elemSize()));
  } else if (backendType == IMAGEMAGICK_BACKEND) {
    ImageMagick::Image image = ImageMagick::Image();
    image.Read(reinterpret_cast<const unsigned char*>(imageData.data()), imageData.size());
    image.Denoise(10);
    storeImageData(std::vector<unsigned char>(image.GetBlob(), image.GetBlob() + image.GetLength()));
  }
}
