#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

// Structure to hold data for each record
typedef struct {
  char uuid[37]; // UUID string
  int key;
  double timestamp;
  char tags[256]; // Array of strings for tags
} Record;

// Function to manage database connections and populate list of records
void getRecords(int numServers, char *serverAddresses[], long offsetValues[], int keys[], double timestamps[], char tags[][256]) {
  // Arrays for caching data
  Record *cachedRecords = NULL;
  int numCachedRecords = 0;

  // Set up database connections and get initial records
  pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
  int numThreads = 0;
  for (int i = 0; i < numServers; i++) {
    // Connect to each server and retrieve initial records
    Record *records = getInitialRecords(serverAddresses[i]);
    if (records) {
      // Add cached records to array
      int numNewRecords = 0;
      for (int j = 0; j < numThreads; j++) {
        numNewRecords += threads[j].numCachedRecords;
      }
      int newSize = numCachedRecords + numNewRecords;
      Record *newCachedRecords = realloc(cachedRecords, newSize * sizeof(Record));
      if (newCachedRecords) {
        cachedRecords = newCachedRecords;
        for (int j = 0; j < numThreads; j++) {
          memcpy(&cachedRecords[numCachedRecords], threads[j].cachedRecords, threads[j].numCachedRecords * sizeof(Record));
          numCachedRecords += threads[j].numCachedRecords;
        }
      } else {
        printf("Error: unable to allocate memory for cached records\n");
        return;
      }
    }
  }

  // Wait for all threads to complete
  pthread_mutex_lock(&mutex);
  while (numThreads > 0) {
    pthread_cond_wait(&cond, &mutex);
  }
  pthread_mutex_unlock(&mutex);

  // Populate arrays for offset values, keys, and timestamps
  int numRecords = 0;
  for (int i = 0; i < numCachedRecords; i++) {
    long offsetValue = cachedRecords[i].uuid[16] - '0';
    int key = atoi(cachedRecords[i].uuid + 17);
    double timestamp = (double)atoi(cachedRecords[i].uuid + 21) / 1000;
    strncpy(tags[i], cachedRecords[i].tags, sizeof(tags[i]));
    offsetValues[numRecords] = offsetValue;
    keys[numRecords] = key;
    timestamps[numRecords] = timestamp;
    numRecords++;
  }
}

// Function to get initial records from each server
