public class DynamicCryptoGenerator
{
    private static readonly Dictionary<string, IRandomAlgorithm> _algorithms = new Dictionary<string, IRandomAlgorithm>();
    private static readonly Dictionary<string, IDistribution> _distributions = new Dictionary<string, IDistribution>();
    private static readonly string[] _preferredAlgorithms = { "AES-256", "ChaCha20" };
    private static readonly string[] _preferredDistributions = { "SHA-256", "SHA-384", "SHA-512" };
    private static readonly object _syncRoot = new object();

    public static void Initialize(string configFilePath)
    {
        lock (_syncRoot)
        {
            if (_algorithms.Count > 0 || _distributions.Count > 0)
            {
                throw new InvalidOperationException("The library has already been initialized.");
            }

            try
            {
                var config = File.ReadAllText(configFilePath);
                var settings = JsonConvert.DeserializeObject<CryptoSettings>(config);

                foreach (var algorithm in _preferredAlgorithms)
                {
                    if (settings.Algorithms.ContainsKey(algorithm))
                    {
                        var algo = settings.Algorithms[algorithm];
                        _algorithms.Add(algorithm, new OpenSSLRandomAlgorithm(algo));
                    }
                }

                foreach (var distribution in _preferredDistributions)
                {
                    if (settings.Distributions.ContainsKey(distribution))
                    {
                        var dist = settings.Distributions[distribution];
                        _distributions.Add(distribution, new OpenSSLDistribution(dist));
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to initialize the library: {ex.Message}");
            }
        }
    }

