    public static string GenerateHash(string input, HashAlgorithm algorithm)
    {
        lock (_syncRoot)
        {
            if (!IsInitialized())
            {
                throw new InvalidOperationException("The library has not been initialized.");
            }

            var dist = GetDistribution(algorithm);
            return dist.GenerateHash(input);
        }
    }

    private static bool IsInitialized() => _randomAlgorithms != null;

    private static RandomAlgorithm GetRandomAlgorithm()
    {
        if (!IsInitialized())
        {
            throw new InvalidOperationException("The library has not been initialized.");
        }

        var algo = _randomAlgorithms[_currentAlgo];
        _currentAlgo++;
        if (_currentAlgo >= _randomAlgorithms.Length)
        {
            _currentAlgo = 0;
        }

        return algo;
    }

    private static Distribution GetDistribution(HashAlgorithm algorithm)
    {
        if (!IsInitialized())
        {
            throw new InvalidOperationException("The library has not been initialized.");
