const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const mongoose = require('mongoose');
const passport = require('passport');
const jwtStrategy = require('passport-jwt').Strategy;
const ExtractJwt = require('passport-jwt').ExtractJwt;
const User = require('../models/User');
const Message = require('../models/Message');
const PushNotificationService = require('../services/PushNotificationService');
const AuthService = require('../services/AuthService');

const app = express();
app.use(bodyParser.json());
app.use(cors());

// Connect to MongoDB
mongoose.connect(process.env.MONGODB_URI, { useNewUrlParser: true });

// Initialize Passport
passport.use(new jwtStrategy({
    secretOrKey: process.env.JWT_SECRET,
    jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
}, async (jwtPayload, done) => {
    try {
        const user = await User.findById(jwtPayload.id);
        if (!user) {
            return done(null, false);
        }
        return done(null, user);
    } catch (err) {
        return done(err, false);
    }
}));

// Routes
app.post('/login', async (req, res) => {
    const { username, password } = req.body;
    try {
        const user = await AuthService.authenticateUser({ username, password });
        if (!user) {
            return res.status(401).json({ message: 'Invalid credentials' });
        }
        const token = AuthService.generateToken(user);
        res.json({ status: 'success', token, userId: user._id });
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error logging in' });
    }
});

app.post('/messages', async (req, res) => {
    const { username, password, message, recipient } = req.body;
    try {
        if (!req.user) {
            return res.status(401).json({ message: 'Unauthorized' });
        }
        const user = await User.findById(req.user._id);
        if (!user) {
            return res.status(404).json({ message: 'User not found' });
        }
        if (message.length > 500) {
            return res.status(422).json({ message: 'Message too long' });
        }
        const recipientUser = await User.findById(recipient);
        if (!recipientUser) {
            return res.status(404).json({ message: 'Recipient not found' });
        }
        const newMessage = await Message.create({ userId: req.user._id, recipientId: recipientUser._id, text: message });
        PushNotificationService.sendMessageNotification(recipientUser, newMessage);
        res.json({ status: 'success', message: newMessage });
    } catch (err) {
        console.error(err);
        res.status(500).json({ message: 'Error sending message' });
    }
});
