import asyncio
import time
from concurrent.futures import ThreadPoolExecutor

class DataProcessor:
    def __init__(self, storage_service, config_path):
        self.storage_service = storage_service
        self.config_path = config_path
        self.executor = ThreadPoolExecutor(max_workers=50)
        self.sensor_ids = set()
        self.sensor_configs = {}
        self.last_processed_timestamp = None
        self.data_streaming_tasks = []

    async def process_configuration_files(self):
        try:
            config_files = await self.storage_service.get_latest_version(self.config_path)
            for config_file in config_files:
                sensor_id, timestamp, params = self._parse_configuration_file(config_file)
                if not self.sensor_ids or sensor_id not in self.sensor_ids:
                    self.sensor_ids.add(sensor_id)
                    self.sensor_configs[sensor_id] = {
                        'timestamp': timestamp,
                        'params': params
                    }
            await asyncio.gather(*self.data_streaming_tasks)
        except Exception as e:
            print(f'Error processing configuration files: {e}')

    def _parse_configuration_file(self, config_file):
        try:
            with open(config_file, 'r') as f:
                content = f.read()
                sensor_id = int(content[0])
                timestamp = datetime.strptime(content[1], '%Y-%m-%d %H:%M:%S')
                params = {key: value for key, value in [item.split('=') for item in content[2:].split(', ')]}
            return sensor_id, timestamp, params
        except Exception as e:
            print(f'Error parsing configuration file: {e}')

    async def stream_data(self):
        try:
            while True:
                data = await self.storage_service.get_latest_data()
                for sensor_id in self.sensor_ids:
                    if sensor_id in data:
                        params = self.sensor_configs[sensor_id]['params']
                        transformed_data = self._transform_data(data, params)
                        await self.storage_service.save_data(sensor_id, transformed_data)
                time.sleep(10)
        except Exception as e:
            print(f'Error streaming data: {e}')

    def _transform_data(self, data, params):
        # Add transformation logic here
        return data

    def start(self):
        self.loop = asyncio.get_event_loop()
        self.loop.run_until_complete(self.process_configuration_files())
        self.streaming_task = self.loop.create_task(self.stream_data())
