// DAO class for updating user passwords in the database
public class UserPasswordDAO {
  private final String dbUrl;
  private final String dbUsername;
  private final String dbPassword;

  public UserPasswordDAO(String dbUrl, String dbUsername, String dbPassword) {
    this.dbUrl = dbUrl;
    this.dbUsername = dbUsername;
    this.dbPassword = dbPassword;
  }

  public void updateUserPassword(int userId, String newPassword) throws SQLException {
    // Connect to the database and prepare a statement for updating the password
    Connection conn = DriverManager.getConnection(dbUrl, dbUsername, dbPassword);
    PreparedStatement stmt = conn.prepareStatement("UPDATE users SET password=? WHERE id=?");

    // Set the new password and execute the statement
    stmt.setString(1, newPassword);
    stmt.setInt(2, userId);
    int rowsAffected = stmt.executeUpdate();

    // Log the result of the update and close the connection
    if (rowsAffected > 0) {
      System.out.println("Updated password for user " + userId);
    } else {
      System.err.println("Failed to update password for user " + userId);
    }
    conn.close();
  }
}
