```
import datetime
import json
import logging
import os
import requests
import time
from typing import List, Dict

class EnvironmentalMonitoringSystem:
    def __init__(self, sensors: List[Dict], notification_services: List[str]):
        self.sensors = sensors
        self.notification_services = notification_services

    def read_sensor(self, sensor_id: str) -> float:
        """Read the current value of a specified sensor"""
        if not os.path.exists(f"/var/sensors/{sensor_id}"):
            return None
        with open(f"/var/sensors/{sensor_id}", "r") as f:
            data = json.load(f)
            return float(data["value"])

    def aggregate_data(self, data: List[Dict]) -> Dict:
        """Aggregate the data from multiple sensors and calculate summary statistics"""
        aggregated_data = {}
        for sensor in self.sensors:
            value = self.read_sensor(sensor["id"])
            if value is not None:
                aggregated_data[sensor["name"]] = value
        return aggregated_data

    def send_alert(self, data: Dict) -> bool:
        """Send an alert to the configured notification services"""
        for service in self.notification_services:
            try:
                requests.post(service["url"], json=data)
                return True
            except Exception as e:
                logging.error(f"Failed to send alert to {service['name']}: {e}")
                return False

    def monitor_environment(self):
        """Main loop for monitoring the environment and sending alerts"""
        while True:
            data = self.aggregate_data(self.sensors)
            if self.send_alert(data):
                logging.info(f"Alert sent successfully with data {data}")
            time.sleep(60)
