#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <opencv2/opencv.hpp>
#include <opencv2/imgproc/imgproc.hpp>
#include <opencv2/highgui/highgui.hpp>
#include <opencv2/core/core.hpp>
#include "ImageProcessor.h"

using namespace cv;
using namespace std;

class ImageProcessor {
public:
    ImageProcessor() {}

    ~ImageProcessor() {}

    void process(const Mat& input, const string& output) {
        // Load the input image
        Mat img = imread(input);

        // Resize the image if necessary
        if (img.rows > 1024 || img.cols > 1024) {
            resize(img, img, Size(1024, 1024));
        }

        // Convert to grayscale if necessary
        if (img.channels() == 3) {
            cvtColor(img, img, CV_BGR2GRAY);
        }

        // Crop the image if necessary
        if (img.rows > 1024 && img.cols > 1024) {
            Rect roi = getRoi(img);
            Mat croppedImg = img(roi);
            img = croppedImg;
        }

        // Convert to float data type if necessary
        if (img.depth() != CV_32F) {
            img.convertTo(img, CV_32F);
        }

        // Save the output image
        imwrite(output, img);
    }

private:
    Rect getRoi(const Mat& img) {
        // Calculate the aspect ratio of the input image
        double aspectRatio = (double)img.rows / (double)img.cols;

        // Calculate the new width and height for the cropped image
        int newWidth, newHeight;
        if (aspectRatio >= 1.0) {
            newWidth = 1024;
            newHeight = (int)(newWidth / aspectRatio);
        } else {
            newHeight = 1024;
            newWidth = (int)(newHeight * aspectRatio);
        }

        // Calculate the x and y offsets for the cropped image
        int xOffset, yOffset;
        if (img.rows > img.cols) {
            xOffset = 0;
            yOffset = (img.rows - newHeight) / 2;
        } else {
            xOffset = (img.cols - newWidth) / 2;
            yOffset = 0;
        }

        // Return the cropped image region of interest
        return Rect(xOffset, yOffset, newWidth, newHeight);
    }
};
