  private final List<PaymentGateway> gateways;
  private final int workerCount;
  private final ExecutorService executor;

  public PaymentProcessor(List<PaymentGateway> gateways, int workerCount) {
    this.gateways = gateways;
    this.workerCount = workerCount;
    this.executor = Executors.newFixedThreadPool(workerCount);
  }

  public void processPayments(List<String> paymentIds) throws InterruptedException, ExecutionException {
    List<Future<?>> futures = new ArrayList<>();

    for (int i = 0; i < paymentIds.size(); i++) {
      String paymentId = paymentIds.get(i);
      PaymentGateway gateway = getGatewayForPaymentId(paymentId);
      Future<?> future = executor.submit(() -> processPayment(gateway, paymentId));
      futures.add(future);
    }

    for (Future<?> future : futures) {
      try {
        future.get();
      } catch (ExecutionException | InterruptedException e) {
        throw new RuntimeException("Error processing payments", e);
      }
    }
  }

  private PaymentGateway getGatewayForPaymentId(String paymentId) {
    for (PaymentGateway gateway : gateways) {
      if (gateway.supportsPaymentId(paymentId)) {
        return gateway;
      }
    }
    throw new RuntimeException("No gateway found for payment ID: " + paymentId);
  }

  private void processPayment(PaymentGateway gateway, String paymentId) throws IOException {
    // Fetch payment details from the gateway
