def process_order_and_calculate_md5(file_path: str, chunk_size: int = 8192, progress_callback: Optional[Callable[[int], None]] = None, storage_backend: StorageBackend = None, order_id: int = None, status: OrderStatus = None, product_ids: List[int] = None, order_date: datetime = None, customer_ip: str = None, email_sender: EmailSender = None, rate_limiter: RateLimiter = None):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File does not exist: {file_path}")

    with open(file_path, "rb") as f:
        hasher = hashlib.md5()
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            hasher.update(chunk)

        file_hash = hasher.hexdigest()

    if storage_backend is None:
