    except Exception as e:
        # Log error and return failed response
        print(f"Failed to save hash for order {order_id}: {e}")
        return {
            "success": False,
            "error": f"Failed to save hash for order {order_id}",
        }

    if rate_limiter is None:
        raise ValueError("Rate limiter must be provided")

    if rate_limiter.is_rate_limited(customer_ip):
        # Log error and return failed response
        print(f"Rate limit exceeded for customer {customer_ip}")
        return {
            "success": False,
            "error": f"Rate limit exceeded for customer {customer_ip}",
        }

    if email_sender is None:
        raise ValueError("Email sender must be provided")

