namespace ClimateSimulation {
    class WeatherRandomGenerator {
    public:
        WeatherRandomGenerator(unsigned int seed = std::random_device()()) : mt19937(seed) {}
        ~WeatherRandomGenerator() = default;

        void configureTemperatureRange(double min, double max) {
            if (min >= max || min < 0 || max > 100) {
                throw std::invalid_argument("Invalid temperature range");
            }
            m_temperature_range = {min, max};
        }

        void configurePrecipitationRange(double min, double max) {
            if (min >= max || min < 0 || max > 100) {
                throw std::invalid_argument("Invalid precipitation range");
            }
            m_precipitation_range = {min, max};
        }

        void configureWindSpeedRange(double min, double max) {
            if (min >= max || min < 0 || max > 100) {
                throw std::invalid_argument("Invalid wind speed range");
            }
            m_wind_speed_range = {min, max};
        }

        double generateTemperature() {
            return std::uniform_real_distribution<double>(m_temperature_range.first, m_temperature_range.second)(mt19937);
        }

        double generatePrecipitation() {
            return std::uniform_real_distribution<double>(m_precipitation_range.first, m_precipitation_range.second)(mt19937);
        }

        double generateWindSpeed() {
            return std::uniform_real_distribution<double>(m_wind_speed_range.first, m_wind_speed_range.second)(mt19937);
        }

    private:
        std::mt19937 mt19937;
        std::pair<double, double> m_temperature_range = {0.0, 50.0};
        std::pair<double, double> m_precipitation_range = {0.0, 50.0};
        std::pair<double, double> m_wind_speed_range = {0.0, 50.0};
    };
}

