// Define cryptographic resources for managing memory leaks and proper cleanup
class CryptoResourceManager {
private:
    // Map of encryption algorithms to their associated resources
    map<EncryptionAlgorithm, unique_ptr<CryptoPP::AutoSeededRandomPool>> encryptionResources;

    // Map of hashing algorithms to their associated resources
    map<HashingAlgorithm, unique_ptr<CryptoPP::AutoSeededRandomPool>> hashingResources;

public:
    // Constructor for initializing the resource manager
    CryptoResourceManager() {
        // Initialize encryption resources
        encryptionResources[EncryptionAlgorithm::AES_256] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::ChaCha20] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::RSA] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::ECC] = make_unique<CryptoPP::AutoSeededRandomPool>();

        // Initialize hashing resources
        hashingResources[HashingAlgorithm::SHA_256] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::SHA_384] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::SHA_512] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::BLAKE2b] = make_unique<CryptoPP::AutoSeededRandomPool>();
    }

    // Get encryption resource for a given algorithm
    CryptoPP::AutoSeededRandomPool* getEncryptionResource(EncryptionAlgorithm algorithm) {
        return encryptionResources[algorithm].get();
    }

    // Get hashing resource for a given algorithm
    CryptoPP::AutoSeededRandomPool* getHashingResource(HashingAlgorithm algorithm) {
        return hashingResources[algorithm].get();
    }
};

// Define secure messaging library with support for multiple encryption and hashing algorithms
class SecureMessagingLibrary {
private:
    // Map of encryption and hashing algorithms to their associated resources
    map<EncryptionAlgorithm, unique_ptr<CryptoPP::AutoSeededRandomPool>> encryptionResources;
    map<HashingAlgorithm, unique_ptr<CryptoPP::AutoSeededRandomPool>> hashingResources;

    // Map of key pairs for encrypting and decrypting messages
    map<string, pair<unique_ptr<CryptoPP::RSA::PublicKey>, unique_ptr<CryptoPP::RSA::PrivateKey>>> keyPairs;

    // Rotation thread pool for rotating keys
    ThreadPool rotationThreadPool;

public:
    // Constructor for initializing the secure messaging library
    SecureMessagingLibrary() {
        // Initialize encryption and hashing resources
        encryptionResources[EncryptionAlgorithm::AES_256] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::ChaCha0] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::RSA] = make_unique<CryptoPP::AutoSeededRandomPool>();
        encryptionResources[EncryptionAlgorithm::ECC] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::SHA_256] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::SHA_384] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::SHA_512] = make_unique<CryptoPP::AutoSeededRandomPool>();
        hashingResources[HashingAlgorithm::BLAKE2b] = make_unique<CryptoPP::AutoSeededRandomPool>();
    }

    // Generate a new key pair for encrypting and decrypting messages
    pair<string, string> generateKeyPair(EncryptionAlgorithm encryptionAlgorithm) {
        // Generate public and private keys using the specified algorithm
        auto publicKey = make_unique<CryptoPP::RSA::PublicKey>();
        auto privateKey = make_unique<CryptoPP::RSA::PrivateKey>();
        CryptoPP::AutoSeededRandomPool prng;
        if (encryptionAlgorithm == EncryptionAlgorithm::RSA) {
            publicKey->Initialize(prng, 1024);
            privateKey->Initialize(prng, 1024);
        } else if (encryptionAlgorithm == EncryptionAlgorithm::ECC) {
            CryptoPP::DL_GroupParameters_EC<CryptoPP::ECP> params;
            params.AccessGroupParameters().SetGroupParameters("secp192r1");
            publicKey->Initialize(prng, params);
            privateKey->Initialize(prng, params);
        }

        // Serialize the public and private keys as strings
        string publicKeyString = CryptoPP::OStrStreamToString(publicKey.get());
        string privateKeyString = CryptoPP::OStrStreamToString(privateKey.get());

        // Add the key pair to the map of key pairs
        keyPairs[publicKeyString] = make_pair(move(publicKey), move(privateKey));

        return { publicKeyString, privateKeyString };
    }

    // Encrypt a message using the specified algorithm and key
    string encryptMessage(string message, EncryptionAlgorithm encryptionAlgorithm, string key) {
        // Get the encryption resource for the specified algorithm
        auto encryptionResource = encryptionResources[encryptionAlgorithm].get();

        // Encrypt the message using the specified algorithm and key
        CryptoPP::RSAES_OAEP_SHA_Decryptor decryptor(key.c_str());
        string ciphertext;
        CryptoPP::StringSource(message, true, new CryptoPP::AuthenticatedEncryptionFilter(encryptionResource, new CryptoPP::RedirectChannel<CryptoPP::StringSink>(ciphertext)));

        return ciphertext;
    }

    // Decrypt a message using the specified algorithm and key
    string decryptMessage(string ciphertext, EncryptionAlgorithm encryptionAlgorithm, string key) {
        // Get the decryption resource for the specified algorithm
        auto decryptionResource = encryptionResources[encryptionAlgorithm].get();

        // Decrypt the message using the specified algorithm and key
        CryptoPP::RSAES_OAEP_SHA_Encryptor encryptor(key.c_str());
        string plaintext;
        CryptoPP::StringSource(ciphertext, true, new CryptoPP::AuthenticatedDecryptionFilter(decryptionResource, new CryptoPP::RedirectChannel<CryptoPP::StringSink>(plaintext)));

        return plaintext;
    }

    // Hash a message using the specified algorithm
    string hashMessage(string message, HashAlgorithm hashAlgorithm) {
        // Get the hash resource for the specified algorithm
        auto hashResource = hashingResources[hashAlgorithm].get();

        // Hash the message using the specified algorithm
        string hash;
        CryptoPP::StringSource(message, true, new CryptoPP::HashFilter(hashResource, new CryptoPP::HexEncoder(new CryptoPP::StringSink(hash))));

        return hash;
    }
};

int main() {
    // Create an instance of the SecureMessaging class
    SecureMessaging secureMessaging;

    // Generate a new key pair for encrypting and decrypting messages
    auto keyPair = secureMessaging.generateKeyPair(EncryptionAlgorithm::RSA);
    string publicKeyString = keyPair.first;
    string privateKeyString = keyPair.second;

    // Encrypt a message using the specified algorithm and key
    string encryptedMessage = secureMessaging.encryptMessage("Hello, world!", EncryptionAlgorithm::RSA, publicKeyString);

    // Decrypt a message using the specified algorithm and key
    string decryptedMessage = secureMessaging.decryptMessage(encryptedMessage, EncryptionAlgorithm::RSA, privateKeyString);

    // Hash a message using the specified algorithm
    string hash = secureMessaging.hashMessage("Hello, world!", HashAlgorithm::SHA256);
}

