import java.io.File;
import java.io.IOException;
import java.util.List;
import java.util.function.Function;
import java.util.logging.Level;
import java.util.logging.Logger;

public class CSVFilter {
  private static final Logger logger = Logger.getLogger(CSVFilter.class.getName());

  public static void filterCSVFile(String filePath, Function<List<String>, Boolean> filterCondition, String outputPath) throws IOException {
    File inputFile = new File(filePath);
    if (!inputFile.exists()) {
      throw new FileNotFoundException("Input file does not exist: " + filePath);
    }

    List<List<String>> data = readCSVFile(inputFile, filterCondition);

    try (OutputStream outputStream = new FileOutputStream(outputPath)) {
      for (List<String> row : data) {
        if (filterCondition.apply(row)) {
          writeRowToOutput(outputStream, row);
        }
      }
    } catch (IOException e) {
      logger.log(Level.SEVERE, "Error writing to output file", e);
    }
  }

  private static List<List<String>> readCSVFile(File inputFile, Function<List<String>, Boolean> filterCondition) throws IOException {
    CSVReader reader = new CSVReader(new FileReader(inputFile));
    List<List<String>> data = new ArrayList<>();
    String[] headers = reader.readNext();
    while ((headers = reader.readNext()) != null) {
      List<String> row = Arrays.asList(headers);
      if (filterCondition.apply(row)) {
        data.add(row);
      }
    }
    return data;
  }

  private static void writeRowToOutput(OutputStream outputStream, List<String> row) throws IOException {
    CSVWriter writer = new CSVWriter(new OutputStreamWriter(outputStream));
    for (int i = 0; i < row.size(); i++) {
      if (i > 0) {
        writer.write(",");
      }
      writer.write(row.get(i));
    }
    writer.write("\n");
  }
}
