import csv
import logging
from typing import List, Callable

logger = logging.getLogger(__name__)

def filter_csv_file(file_path: str, filter_condition: Callable[[List[str]], bool], output_path: str) -> None:
    """Filter a CSV file based on a given condition and write the filtered data to an output file."""
    try:
        with open(file_path, "r") as input_file:
            reader = csv.reader(input_file)
            headers = next(reader)
            filtered_data = [row for row in reader if filter_condition(row)]

        with open(output_path, "w", newline="") as output_file:
            writer = csv.writer(output_file)
            writer.writerow(headers)
            writer.writerows(filtered_data)
    except FileNotFoundError as e:
        logger.error("Input file does not exist: %s", file_path, exc_info=True)
    except csv.Error as e:
        logger.error("Error reading CSV file: %s", file_path, exc_info=True)
    except IOError as e:
        logger.error("Error writing to output file: %s", output_path, exc_info=True)
