    // Cache layer for storing JWT tokens
    private static final Map<String, String> CACHE = new HashMap<>();

    public static void main(String[] args) {
        // Initialize the cache layer with empty maps
        CACHE.put("jwt-tokens", new ConcurrentHashMap<>());
        CACHE.put("token-refreshes", new ConcurrentHashMap<>());

        // Start the HTTP server for JWT generation and validation requests
        HttpServer httpServer = startHttpServer();

        // Handle incoming JWT generation and validation requests
        httpServer.createContext("/", exchange -> {
            String requestMethod = exchange.getRequestMethod();
            String path = exchange.getRequestURI().getPath();

            if (requestMethod.equalsIgnoreCase("POST") && path.equals("/generate-jwt")) {
                generateJwt(exchange);
            } else if (requestMethod.equalsIgnoreCase("GET") && path.equals("/validate-jwt")) {
                validateJwt(exchange);
            } else {
                exchange.sendResponseHeaders(404, 0);
                exchange.close();
            }
        });

        // Start the HTTP server for real-time sensor data streams
        HttpServer sensorDataHttpServer = startSensorDataHttpServer();

        // Handle incoming real-time sensor data streams
        sensorDataHttpServer.createContext("/", exchange -> {
            String requestMethod = exchange.getRequestMethod();
            String path = exchange.getRequestURI().getPath();

            if (requestMethod.equalsIgnoreCase("POST") && path.equals("/sensor-data")) {
                processSensorData(exchange);
            } else {
                exchange.sendResponseHeaders(404, 0);
                exchange.close();
            }
        });
    }

    private static HttpServer startHttpServer() throws IOException {
        // Start the HTTP server on port 8080
        InetSocketAddress address = new InetSocketAddress(8080);
        return HttpServer.create(address, 0);
    }

    private static HttpServer startSensorDataHttpServer() throws IOException {
        // Start the HTTP server for real-time sensor data streams on port 8090
        InetSocketAddress address = new InetSocketAddress(8090);
        return HttpServer.create(address, 0);
    }

    private static void generateJwt(HttpExchange exchange) throws IOException {
        // Get the JWT claims from the request body
        String claims = getRequestBodyAsString(exchange);

        // Generate a new JWT token using the claims and the private key
        String jwtToken = generateToken(claims, PRIVATE_KEY);

        // Cache the generated JWT token for 10 minutes
        CACHE.put("jwt-tokens", jwtToken, 600);

        // Return the generated JWT token to the client
        exchange.getResponseHeaders().add("Content-Type", "application/json");
        exchange.sendResponseHeaders(201, 0);
        OutputStream responseBody = exchange.getResponseBody();
        responseBody.write(jwtToken.getBytes());
        responseBody.close();
    }

    private static void validateJwt(HttpExchange exchange) throws IOException {
        // Get the JWT token from the request header
        String jwtToken = exchange.getRequestHeaders().getFirst("Authorization");

        // Check if the JWT token is cached and not expired
        if (jwtToken != null && CACHE.containsKey(jwtToken) && !isJwtExpired(jwtToken)) {
            // Return a success response to the client
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, 0);
            OutputStream responseBody = exchange.getResponseBody();
            responseBody.write("JWT token is valid".getBytes());
            responseBody.close();
        } else {
            // Return an error response to the client if the JWT token is invalid or expired
            exchange.sendResponseHeaders(401, 0);
            OutputStream responseBody = exchange.getResponseBody();
            responseBody.write("JWT token is invalid or expired".getBytes());
            responseBody.close();
        }
    }

    private static void processSensorData(HttpExchange exchange) throws IOException {
        // Get the sensor data from the request body
        String sensorData = getRequestBodyAsString(exchange);

        // Use the JWT token from the request header to authenticate and authorize the client
        String jwtToken = exchange.getRequestHeaders().getFirst("Authorization");

        if (jwtToken != null && CACHE.containsKey(jwtToken) && !isJwtExpired(jwtToken)) {
            // If the JWT token is valid and not expired, process the sensor data and return a success response to the client
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(201, 0);
            OutputStream responseBody = exchange.getResponseBody();
            responseBody.write("Sensor data processed successfully".getBytes());
            responseBody.close();
        } else {
            // If the JWT token is invalid or expired, return an error response to the client
            exchange.sendResponseHeaders(401, 0);
            OutputStream responseBody = exchange.getResponseBody();
            responseBody.write("JWT token is invalid or expired".getBytes());
            responseBody.close();
        }
    }

    private static String getRequestBodyAsString(HttpExchange exchange) throws IOException {
        StringBuilder requestBody = new StringBuilder();
        try (InputStream inputStream = exchange.getRequestBody()) {
            BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(inputStream));
            String line;
            while ((line = bufferedReader.readLine()) != null) {
                requestBody.append(line);
            }
        }
        return requestBody.toString();
    }

    private static boolean isJwtExpired(String jwtToken) throws IOException {
        // Check if the JWT token is expired by verifying its signature with the public key and checking the expiration time claim
        JwtConsumer jwtConsumer = new JwtConsumerBuilder().setVerificationKey(PUBLIC_KEY).setRelaxVerificationKeyValidation().build();
        try {
            JwtClaims claims = jwtConsumer.processToClaims(jwtToken);
            Date expirationTime = claims.getExpirationTime();
            return new Date().after(expirationTime);
        } catch (InvalidJwtException e) {
            // If the signature is invalid, assume that the JWT token is invalid and not expired
            return true;
        }
    }
}
```
This is an example of a server-side API using Java to generate and validate JSON Web Tokens. The API has two endpoints: one for generating tokens and one for validating them. The private key and public key are used for generating and verifying the signatures, respectively. The expiration time claim is checked to determine if the token is expired or not.

