import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import redis.clients.jedis.Jedis;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;

public class InventorySystem {
    private static final JedisPool jedisPool = new JedisPool(new JedisPoolConfig(), "localhost");
    private static final KafkaProducer<String, String> kafkaProducer = new KafkaProducer<>();
    private static final ExecutorService executorService = Executors.newCachedThreadPool();

    public static void main(String[] args) throws Exception {
        // Initialize the inventory system
        initializeInventorySystem();

        // Start processing messages from the message queue
        startProcessingMessages();

        System.out.println("Inventory system started.");
    }

    private static void initializeInventorySystem() throws Exception {
        // Connect to the Redis cache
        Jedis jedis = jedisPool.getResource();

        // Initialize the inventory map
        Map<String, Integer> inventoryMap = new HashMap<>();

        // Load the initial inventory levels from the cache
        Set<String> keys = jedis.keys("*");
        for (String key : keys) {
            int level = Integer.parseInt(jedis.get(key));
            inventoryMap.put(key, level);
        }

        // Load the initial Kafka topics and start processing messages
        Set<String> topics = kafkaProducer.listTopics().names();
        for (String topic : topics) {
            startProcessingMessages(topic);
        }
    }

    private static void startProcessingMessages() throws Exception {
        // Start a new thread to process messages from the message queue
        Thread messageProcessorThread = new Thread(() -> {
            try {
                // Connect to the Kafka consumer group
                Consumer<String, String> consumer = kafkaProducer.createConsumer();

                while (true) {
                    // Poll for messages from the topic partitions
                    ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));

                    // Process each message in the batch
                    for (ConsumerRecord<String, String> record : records) {
                        processMessage(record);
                    }
                }
            } catch (Exception e) {
                System.out.println("Error processing messages: " + e.getMessage());
            }
        });

        // Start the message processor thread
        messageProcessorThread.start();
    }

    private static void startProcessingMessages(String topic) throws Exception {
        // Connect to the Kafka consumer group
        Consumer<String, String> consumer = kafkaProducer.createConsumer();

        // Subscribe to the topic partitions
        Set<TopicPartition> partitions = consumer.assignment();
        for (TopicPartition partition : partitions) {
            if (partition.topic().equals(topic)) {
                consumer.seekToBeginning(partition);
                break;
            }
        }

        // Start a new thread to process messages from the topic
        Thread messageProcessorThread = new Thread(() -> {
            try {
                while (true) {
                    ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                    for (ConsumerRecord<String, String> record : records) {
                        processMessage(record);
                    }
                }
            } catch (Exception e) {
                System.out.println("Error processing messages: " + e.getMessage());
            }
        });

        // Start the message processor thread
        messageProcessorThread.start();
    }

    private static void processMessage(ConsumerRecord<String, String> record) throws Exception {
        // Parse the message payload and extract the relevant information
        String key = record.key();
        String value = record.value();

        if (key == null || value == null) {
            return;
        }

        // Update the inventory levels based on the message type
        switch (record.topic()) {
            case "stock-updates":
                updateInventoryLevels(key, Integer.parseInt(value));
                break;
            case "pre-orders":
                processPreOrder(key, value);
                break;
            default:
                System.out.println("Unknown message type: " + record.topic());
        }
    }

    private static void updateInventoryLevels(String key, int level) throws Exception {
        // Connect to the Redis cache
        Jedis jedis = jedisPool.getResource();

        // Update the inventory levels in the cache
        Integer currentLevel = jedis.hget("inventory", key);
        if (currentLevel == null) {
            currentLevel = 0;
        }

        int newLevel = level + currentLevel;
        jedis.hset("inventory", key, String.valueOf(newLevel));
    }

    private static void processPreOrder(String key, String value) throws Exception {
        // Connect to the Redis cache
        Jedis jedis = jedisPool.getResource();

        // Check if the product is currently in stock
        Integer currentLevel = jedis.hget("inventory", key);
        if (currentLevel == null || currentLevel <= 0) {
            System.out.println("Pre-order for out-of-stock product: " + key);
            return;
        }

        // Update the inventory levels in the cache
        jedis.hset("inventory", key, String.valueOf(currentLevel - 1));

        // Create a new pre-order record and send it to the message queue
        ProducerRecord<String, String> record = new ProducerRecord<>("pre-orders", key, value);
        kafkaProducer.send(record);
    }
}
```

This code creates a Kafka producer that can be used to send messages to the `stock-updates` and `pre-orders` topics. The `updateInventoryLevels` method is responsible for updating the inventory levels in the cache based on the message received from the `stock-updates` topic. The `processPreOrder` method is responsible for processing pre-order requests and checking if the product is currently in stock before creating a new pre-order record and sending it to the message queue.

The code also includes a thread that starts a Kafka consumer group for each topic, which will poll for messages from the corresponding partition and pass them to the `processMessage` method for processing. The `processMessage` method will update the inventory levels in the cache based on the message type and create a new pre-order record if necessary.

The code also includes error handling and logging to ensure that any errors or exceptions are properly handled and reported.

