class UpdateClinicStatus {
    private $db;

    public function __construct(PDO $db) {
        $this->db = $db;
    }

    public function update($clinic_id, $new_status, $last_modified_ip, $is_delete = false) {
        $stmt = $this->db->prepare("UPDATE clinics SET status=:new_status, last_modified_date=NOW(), last_modified_ip=:last_modified_ip WHERE id=:clinic_id");
        $stmt->bindValue(':new_status', $new_status);
        $stmt->bindValue(':last_modified_ip', $last_modified_ip);
        $stmt->bindValue(':clinic_id', $clinic_id);

        if ($is_delete) {
            $stmt->execute();
            $deleted_at = date("Y-m-d H:i:s");
            $this->db->query("UPDATE clinics SET deleted_at=:deleted_at WHERE id=:clinic_id");
        } else {
            $stmt->execute();
        }

        if ($stmt->rowCount() > 0) {
            return "Update successful";
        } else {
            return "Error updating clinic status";
        }
    }
}
