using namespace std;

// Log file format: [timestamp] [client IP] [request method] [URL] [HTTP version] [response status] [response size]
const string LOG_FORMAT = "%s %s %s %s %s %d %d";

// Third-party logging service URL
const string LOGGING_SERVICE_URL = "https://logging.example.com/logs";

// Global variables for parsing and logging
map<string, vector<string>> parsingRules;
mutex logMutex;
condition_variable logCondition;
bool isLoggingEnabled = false;

// Function to load parsing rules from a file
void loadParsingRules(const string& filename) {
  // Read the file and parse the lines into a map of strings
  ifstream rulesFile(filename);
  while (getline(rulesFile, line)) {
    istringstream ss(line);
    string key, value;
    getline(ss, key, ':');
    getline(ss, value);
    parsingRules[key] = value;
  }
}

// Function to update the status of log collection
void toggleLoggingStatus() {
  isLoggingEnabled = !isLoggingEnabled;
}

// Function to process a single log entry
bool processLogEntry(const string& line) {
  // Parse the log entry using the parsing rules
  map<string, vector<string>> parsedValues;
  for (const auto& rule : parsingRules) {
    vector<string> matches;
    regex_search(line, matches, rule.second);
    if (!matches.empty()) {
      parsedValues[rule.first] = matches[0];
    }
  }

  // If the log entry is valid, send it to the logging service
  if (isLoggingEnabled) {
    string jsonPayload = "{\"log\": \"" + line + "\"}";
    try {
      curl_easy_setopt(curl, CURLOPT_URL, LOGGING_SERVICE_URL);
      curl_easy_setopt(curl, CURLOPT_POSTFIELDS, jsonPayload.c_str());
      curl_easy_perform(curl);
    } catch (const exception& e) {
      cerr << "Error sending log to logging service: " << e.what() << endl;
    }
  }

  // Return true if the log entry is valid, false otherwise
  return !parsedValues.empty();
}

// Function to process a batch of log entries from a file
void processLogFile(const string& filename) {
  ifstream logFile(filename);
  vector<string> lines;
  while (getline(logFile, line)) {
    // Process each log entry in the batch
    processLogEntry(line);
    usleep(1000); // 1 ms sleep to avoid overloading the system
  }
}

// Function to start processing log files from multiple servers
void startProcessingLogs() {
  while (true) {
    vector<string> filenames = get_filenames(); // Get list of log file names from a distributed system
    for (const auto& filename : filenames) {
      processLogFile(filename);
    }
  }
}

int main() {
  // Initialize the parsing rules and logging service connection
  loadParsingRules("parsing_rules.txt");

  // Start processing logs in a separate thread to avoid blocking the main thread
  thread logProcessor(startProcessingLogs);
  logProcessor.detach();

  while (true) {
    // Check for updates to the logging service status and update the parser accordingly
    toggleLoggingStatus();

    // Sleep for a short period of time to avoid overloading the system with frequent requests
    usleep(1000); // 1 ms sleep
  }

  return 0;
}
```
