class FileMetadataExtractor:
    def __init__(self):
        self.cache = {}

    async def extract_metadata(self, file_path: str) -> Dict[str, any]:
        try:
            # Check if the file is in the cache
            if file_path in self.cache:
                return self.cache[file_path]

            # Connect to the external storage service and retrieve the metadata
            async with aiohttp.ClientSession() as session:
                resp = await session.get(f"{file_path}")
                if resp.status == 200:
                    metadata = await resp.json()
                    # Cache the metadata for future use
                    self.cache[file_path] = metadata
                    return metadata
                else:
                    logging.error(f"Error retrieving metadata for file {file_path}: {resp.status}")
        except Exception as e:
            logging.exception(e)
            return None
