use std::fs;
use std::io;
use std::process::Command;
use std::thread;

pub fn extract_metadata(file_path: &str) -> io::Result<String> {
    let mut metadata = String::new();
    let cmd = Command::new("llvm-mc")
        .arg("-triple")
        .arg("x86_64-pc-linux")
        .arg("-filetype=obj")
        .arg(file_path)
        .stdout(Stdio::piped())
        .spawn()?;
    let mut child = cmd.stdout.unwrap();
    let mut buffer = [0u8; 1024];
    loop {
        match child.read(&mut buffer) {
            Ok(n) => {
                if n == 0 { break }
                metadata.push_str(&String::from_utf8_lossy(&buffer[..n]));
            }
            Err(e) => return Err(io::Error::new(io::ErrorKind::Other, e)),
        }
    }
    Ok(metadata)
}
```
