    private static final int MIN_CACHE_SIZE = 1000;
    private static final int MAX_CACHE_SIZE = 50000;
    private static final String CACHE_NAME = "paymentGatewayCache";
    private static final String KEY_PREFIX = "pg_";
    private static final String VALUE_PREFIX = "v_";

    // Cache for storing payment gateway data
    private Map<String, PaymentGatewayData> cache;

    // Load balancer for distributing requests across multiple nodes
    private LoadBalancer loadBalancer;

    // Properties file for storing configuration settings
    private Properties properties;

    public PaymentGatewayMicroservice(Properties properties) {
        this.properties = properties;
        initCache();
        initLoadBalancer();
    }

    // Initialize cache with default size and timeout values
    private void initCache() {
        cache = new ConcurrentHashMap<>(MIN_CACHE_SIZE, 0.75f, MAX_CACHE_SIZE);
    }

    // Initialize load balancer with default settings
    private void initLoadBalancer() {
        loadBalancer = new LoadBalancer(properties.getInt("loadBalancer.maxConcurrentRequests"));
    }

    // Insert payment gateway data into cache
    public void insertPaymentGatewayData(String key, PaymentGatewayData data) {
        cache.put(keyPrefix + key, data);
    }

    // Update payment gateway data in cache
    public void updatePaymentGatewayData(String key, PaymentGatewayData data) {
        cache.put(keyPrefix + key, data);
    }

    // Retrieve payment gateway data from cache
    public PaymentGatewayData getPaymentGatewayData(String key) {
        return cache.get(keyPrefix + key);
    }

    // Serialize cache to disk for persistence across application restarts
    public void serializeCache() {
        Map<String, byte[]> serializedCache = new HashMap<>();
        cache.forEach((k, v) -> serializedCache.put(keyPrefix + k, valuePrefix + v));
        // Serialize the map to disk using a file writer
    }

    // Deserialize cache from disk for persistence across application restarts
