  return {};
};

const handleInvalidInput = (response, callback) => {
  if (response.statusCode === 400 || response.statusCode === 500) {
    return handleError(response.data);
  } else {
    return callback(null, response.data);
  }
};

const handleUnavailableAPI = (apiName, fallbackApis) => {
  const fallbackApi = fallbackApis[apiName];
  if (fallbackApi !== undefined) {
    return fallbackApi;
  } else {
    throw new Error(`Fallback API ${apiName} is unavailable`);
  }
};

const handleInvalidAPIResponse = (response, callback) => {
  const statusCode = response.statusCode;
  if (statusCode === 400 || statusCode === 500) {
    return handleError(response.data);
  } else {
    return callback(null, response.data);
  }
};

// Define fetching and caching of API data
const fetchData = (apiName, params, callback) => {
  const apiEndpoint = apiEndpoints[apiName];
  if (apiEndpoint !== undefined) {
    axios({
      method: apiEndpoint.method,
      url: `${apiEndpoint.url}?${params}`,
      responseType: apiEndpoint.responseType
    }).then((response) => {
      const data = handleInvalidAPIResponse(response);
      cache[apiName] = data;
      return callback(null, data);
    }).catch((error) => {
      return handleError(error);
    });
  } else {
    throw new Error(`API endpoint ${apiName} is not defined`);
  }
};

const getCachedData = (apiName) => {
  const cachedData = cache[apiName];
  if (cachedData !== undefined) {
    return cachedData;
  } else {
    throw new Error(`No data found for API ${apiName}`);
  }
};

