// Define the structure for storing database connection information
typedef struct {
  char *address;
  int port;
  char *username;
  char *password;
  int timeout;
} db_conn_t;

// Define the structure for storing data retrieval options
typedef struct {
  bool synchronous;
  int num_workers;
} retrieval_options_t;

// Global variables
int max_dbs = 10; // maximum number of databases that can be connected to
int current_dbs = 0; // current number of databases that are connected to
pthread_mutex_t db_lock; // mutex for synchronizing access to the database connections
pthread_cond_t db_cond; // condition variable for waiting for available database slots
retrieval_options_t *retrieval_opts = NULL; // options for data retrieval
db_conn_t *dbs = NULL; // array of database connections

// Function to connect to a database and store its connection information in the dbs array
void connect_to_db(char *address, int port, char *username, char *password, int timeout) {
  int conn_fd = -1;
  struct sockaddr_in server_addr;
  socklen_t server_len = sizeof(server_addr);
  char msg[256];

  // Create a socket for connecting to the database
  if ((conn_fd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
    perror("socket");
    exit(1);
  }

  // Connect to the database using the provided address and port
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(port);
  if (inet_pton(AF_INET, address, &server_addr.sin_addr) <= 0) {
    fprintf(stderr, "Invalid IP address: %s\n", address);
    exit(1);
  }
  if (connect(conn_fd, (struct sockaddr *)&server_addr, server_len) < 0) {
    perror("connect");
    close(conn_fd);
    exit(1);
  }

  // Store the connection information in the dbs array
  if (current_dbs >= max_dbs) {
    fprintf(stderr, "Maximum number of databases reached\n");
    exit(1);
  }
  dbs[current_dbs].address = strdup(address);
  dbs[current_dbs].port = port;
  dbs[current_dbs].username = strdup(username);
  dbs[current_dbs].password = strdup(password);
  dbs[current_dbs].timeout = timeout;
  current_dbs++;
}

// Function to disconnect from a database and remove its connection information from the dbs array
void disconnect_from_db(int idx) {
  // Remove the connection information from the dbs array
  free(dbs[idx].address);
  free(dbs[idx].username);
  free(dbs[idx].password);
  current_dbs--;
}

