#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateNfarCrcIndications(NFAPI_CRC_INDICATION_PDU_T **crcList, size_t *listSize, int maxStructures, const char *logFilePath) {
    // Validate input parameters
    if (crcList == NULL || listSize == NULL || maxStructures < 1 || logFilePath == NULL) {
        return -1;
    }

    // Initialize variables
    size_t i = 0, j = 0;
    int ret = 0;
    NFAPI_CRC_INDICATION_PDU_T *crc = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    clock_t startTime, endTime;

    // Allocate memory for the list of structures
    crcList[0] = malloc(maxStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crcList[0] == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    // Initialize the list of structures
    for (i = 0; i < maxStructures; i++) {
        crcList[0][i].RX_UE_INFORMATION_TAG = 0;
        crcList[0][i].RNTI = 0;
        crcList[0][i].CRCFLAG = 0;
    }

    // Populate the list of structures with valid values
    startTime = clock();
    for (i = 0, j = 1; i < maxStructures && ret == 0; i++, j++) {
        crc = &crcList[0][i];
        pthread_mutex_lock(&lock);
        do {
            crc->RX_UE_INFORMATION_TAG = rand() % MAX_STRUCTURES + 1;
            crc->RNTI = rand() % MAX_STRUCTURES + 1;
            crc->CRCFLAG = (uint8_t)rand();
        } while (!isUnique(crcList[0], i, j));
        pthread_mutex_unlock(&lock);
    }
    endTime = clock();
    *listSize = j;
    fprintf(stderr, "Populated %zu structures in %ld seconds\n", j, endTime - startTime);

    // Handle memory allocation failures
    if (ret < 0) {
        free(crcList[0]);
        crcList[0] = NULL;
    }

    return ret;
}

// Check if a structure is unique within the list
bool isUnique(NFAPI_CRC_INDICATION_PDU_T *crcList, size_t i, size_t j) {
    bool unique = true;
    for (size_t k = 0; k < j && unique; k++) {
        if (crcList[i].RX_UE_INFORMATION_TAG == crcList[k].RX_UE_INFORMATION_TAG &&
            crcList[i].RNTI == crcList[k].RNTI) {
            unique = false;
        }
    }
    return unique;
}
