<?php

// Dynamic Salt Generation
class SaltGenerator {
    private $prefix;
    private $suffix;

    public function __construct($prefix = null, $suffix = null) {
        if ($prefix !== null) {
            $this->prefix = $prefix;
        } else {
            $this->prefix = '';
        }
        if ($suffix !== null) {
            $this->suffix = $suffix;
        } else {
            $this->suffix = '';
        }
    }

    public function generate($length = 16) {
        $salt = bin2hex(openssl_random_pseudo_bytes($length));
        return $this->prefix . $salt . $this->suffix;
    }
}

// Algorithm Flexibility and Security
function hashPassword($password, $algorithm = 'PASSWORD_DEFAULT', $options = []) {
    $hashedPassword = null;
    switch ($algorithm) {
        case 'PASSWORD_DEFAULT':
            $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
            break;
        case 'PASSWORD_BCRYPT':
            $hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);
            break;
        case 'PASSWORD_ARGON2ID':
            $hashedPassword = password_hash($password, PASSWORD_ARGON2ID, $options);
            break;
    }
    return $hashedPassword;
}

// Error Handling and Rate Limiting
class PasswordErrorHandler {
    private $errorLog;

    public function __construct() {
        $this->errorLog = new FileLogger('passwords.log');
