        $this->errorLog->log($e);
        return $e->getMessage();
    }
}

class RateLimiter {
    private $rateLimit;
    private $tokenBucket;

    public function __construct($rateLimit = 50) {
        $this->rateLimit = $rateLimit;
        $this->tokenBucket = new TokenBucket();
    }

    public function isRateLimited() {
        return $this->tokenBucket->isEmpty();
    }

    public function limitToken() {
        $this->tokenBucket->consume(1);
    }
}

