namespace AdvancedRandomGenerator
{
    public class RandomNumberGenerator : IDisposable
    {
        private int _seed;
        private double _mean;
        private double _lambda;
        private RangeType _rangeType = RangeType.Inclusive;
        private bool _dynamicallySetRange;
        private double[] _exponentialDistributionParameters;
        private float[] _normalDistributionParameters;
        private int[] _uniformDistributionParameters;

        public RandomNumberGenerator(int seed = 0, RangeType rangeType = RangeType.Inclusive)
        {
            Seed = seed;
            RangeType = rangeType;
        }

        public int Seed
        {
            get => _seed;
            set
            {
                if (value < 0)
                    throw new ArgumentOutOfRangeException(nameof(Seed), "Seed must be a non-negative integer.");
                _seed = value;
            }
        }

        public RangeType RangeType
        {
            get => _rangeType;
            set
            {
                if (value == RangeType.Unknown)
                    throw new ArgumentOutOfRangeException(nameof(RangeType), "Invalid range type.");
                _rangeType = value;
            }
        }

        public void SetExponentialDistributionParameters(double lambda)
        {
            if (lambda <= 0)
                throw new ArgumentOutOfRangeException(nameof(lambda), "Lambda must be a positive number.");
            _lambda = lambda;
        }

        public void SetNormalDistributionParameters(double mean, double standardDeviation)
        {
            if (standardDeviation <= 0)
                throw new ArgumentOutOfRangeException(nameof(standardDeviation), "Standard deviation must be a positive number.");
            _mean = mean;
        }

        public void SetUniformDistributionParameters(int min, int max)
        {
            if (min > max)
                throw new ArgumentOutOfRangeException(nameof(max), "Maximum value must be greater than the minimum value.");
            _uniformDistributionParameters[0] = min;
            _uniformDistributionParameters[1] = max;
        }

        public int GetNextRandomInteger()
        {
            return GenerateRandomInteger();
        }

        private int GenerateRandomInteger(int min = 0, int max = 0)
        {
            if (_dynamicallySetRange)
            {
                min = _uniformDistributionParameters[0];
                max = _uniformDistributionParameters[1];
            }
            return GenerateRandomNumber(min, max);
        }

        public float GetNextRandomFloat()
        {
            return GenerateRandomFloat();
        }

        private float GenerateRandomFloat(float min = 0, float max = 0)
        {
            if (_dynamicallySetRange)
            {
                min = _uniformDistributionParameters[0];
                max = _uniformDistributionParameters[1];
            }
            return GenerateRandomNumber(min, max);
        }

        private int GenerateRandomNumber(int min, int max)
        {
            // Use a random number generator to generate a random integer within the specified range.
            Random rng = new Random(_seed);
            int randomNumber = rng.Next(min, max + 1);
            return randomNumber;
        }

        private float GenerateRandomFloat(float min, float max)
        {
            // Use a random number generator to generate a random floating-point number within the specified range.
            Random rng = new Random(_seed);
            float randomNumber = rng.NextFloat(min, max + 1f);
            return randomNumber;
        }

        public void Reset()
        {
            _seed = 0;
            _rangeType = RangeType.Inclusive;
            _dynamicallySetRange = false;
        }

        public override string ToString()
        {
            return $"Seed: {_seed}, RangeType: {_rangeType}, DynamicallySetRange: {_dynamicallySetRange}";
        }

        #region IDisposable Support
        private bool disposedValue = false; // To detect redundant calls

        protected virtual void Dispose(bool disposing)
        {
            if (!disposedValue)
            {
                if (disposing)
                {
                    // dispose managed state (managed objects).
                }

                // free unmanaged resources (unmanaged objects) and override a finalizer below.
                // set large fields to null.

                disposedValue = true;
            }
        }

        // This code added to correctly implement the disposable pattern.
        public void Dispose()
        {
            // Do not change this code. Put cleanup code in Dispose(bool disposing) above.
            Dispose(true);
            GC.SuppressFinalize(this);
        }
        #endregion
    }
}
