// Define a function to insert a string into a forward list after the first occurrence of a search string, up to N times.
// The function also ensures that no element in the list exceeds 100 characters and handles overflow by truncating the string.
void insertStringInForwardList(forward_list<string>& flist, const string& searchStr, const string& insertStr, size_t N) {
    // Check if the search string is present in the list within the first N elements.
    bool found = false;
    for (auto it = flist.begin(); it != flist.end() && !found && N > 0; ++it, --N) {
        if (*it == searchStr) {
            found = true;
            // Insert the insertion string after the current position.
            it = flist.insert_after(it, insertStr);
        }
    }

    // If the search string is not found within the first N elements, insert the insertion string at the end of the list.
    if (!found) {
        flist.push_back(insertStr);
    }

    // Ensure that no element in the list exceeds 100 characters and handle overflow by truncating the string.
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (it->length() > 100) {
            *it = it->substr(0, 100);
        }
    }
}

