import java.util.*;
import java.io.*;

public class ConfigurationManager {
    private static Map<String, FactoryFunction> factories;

    public ConfigurationManager() {
        factories = new HashMap<>();
    }

    public void addFactory(String id, FactoryFunction factory) {
        if (factories.containsKey(id)) {
            throw new IllegalArgumentException("Factory with ID " + id + " already exists");
        }
        factories.put(id, factory);
    }

    public void removeFactory(String id) {
        factories.remove(id);
    }

    public <T> T createInstance(String id, String data) throws IOException {
        FactoryFunction factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory found for ID " + id);
        }
        return factory.createInstance(data);
    }

    public <T> T createInstance(String id, InputStream data) throws IOException {
        FactoryFunction factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory found for ID " + id);
        }
        return factory.createInstance(data);
    }

    public <T> T mergeConfigs(String id, String... configs) throws IOException {
        FactoryFunction factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory found for ID " + id);
        }
        return factory.mergeConfigs(configs);
    }

    public <T> T mergeConfigs(String id, InputStream... configs) throws IOException {
        FactoryFunction factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory found for ID " + id);
        }
        return factory.mergeConfigs(configs);
    }

    public void close() throws IOException {
        for (FactoryFunction factory : factories.values()) {
            factory.close();
        }
        factories.clear();
    }

    @Override
    protected void finalize() throws Throwable {
        close();
    }
}

interface FactoryFunction<T> {
    T createInstance(String data) throws IOException;
    T createInstance(InputStream data) throws IOException;
    T mergeConfigs(String... configs) throws IOException;
    T mergeConfigs(InputStream... configs) throws IOException;
    void close() throws IOException;
}
