```
package com.example.config;

import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;

public class ConfigurationManager {
    private final ConcurrentHashMap<String, Object> configs = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Function<Object, ?>> factories = new ConcurrentHashMap<>();

    public void addConfig(String id, Object config) {
        configs.put(id, config);
    }

    public void addFactory(String id, Function<Object, ?> factory) {
        factories.put(id, factory);
    }

    public <T> T getConfig(String id, Class<T> clazz) {
        Object config = configs.get(id);
        if (config == null) {
            throw new IllegalArgumentException("No configuration with ID " + id);
        }
        return clazz.cast(config);
    }

    public <T> T createInstance(String id, Class<T> clazz) {
        Function<Object, ?> factory = factories.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No factory with ID " + id);
        }
        return clazz.cast(factory.apply(getConfig(id)));
    }

    public void removeConfig(String id) {
        configs.remove(id);
    }

    public void removeFactory(String id) {
        factories.remove(id);
    }
}
