int encrypt(char *plaintext, char *ciphertext) {
    // Check if the input strings are valid
    // ...

    // Select the appropriate cipher mode based on user input
    int mode = select_mode("ECB");
    if (mode == 0) {
        printf("Error: unable to select cipher mode\n");
        return 1;
    }

    // Generate a random session key for each encryption operation
    unsigned char *key = generate_random_bytes(32);
    if (key == NULL) {
        printf("Error: unable to generate session key\n");
        return 1;
    }

    // Initialize the cipher context using the selected mode and generated key
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: unable to initialize cipher context\n");
        return 1;
    }
    EVP_EncryptInit(ctx, EVP_aes_256_ecb(), key, NULL);

    // Encrypt the plaintext using the generated key and selected mode
    int len = strlen(plaintext);
    char *ciphertext_buffer = malloc(len + 1);
    if (ciphertext_buffer == NULL) {
        printf("Error: unable to allocate memory for ciphertext buffer\n");
        return 1;
    }
    int encrypted_len = EVP_EncryptUpdate(ctx, ciphertext_buffer, len, plaintext, len);
    if (encrypted_len <= 0) {
        printf("Error: unable to encrypt plaintext\n");
        return 1;
    }

    // Copy the encrypted plaintext into the output string
    strcpy(ciphertext, ciphertext_buffer);

    // Clean up and free resources
    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(ciphertext_buffer);

    // Return success
    return 0;
}

// Decryption function
int decrypt(char *ciphertext, char *plaintext) {
    // Check if the input strings are valid
    // ...

    // Select the appropriate cipher mode based on user input
    int mode = select_mode("ECB");
    if (mode == 0) {
        printf("Error: unable to select cipher mode\n");
        return 1;
    }

    // Generate a random session key for each decryption operation
    unsigned char *key = generate_random_bytes(32);
    if (key == NULL) {
        printf("Error: unable to generate session key\n");
        return 1;
    }

    // Initialize the cipher context using the selected mode and generated key
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: unable to initialize cipher context\n");
        return 1;
    }
    EVP_DecryptInit(ctx, EVP_aes_256_ecb(), key, NULL);

    // Decrypt the ciphertext using the generated key and selected mode
    int len = strlen(ciphertext);
    char *plaintext_buffer = malloc(len + 1);
    if (plaintext_buffer == NULL) {
        printf("Error: unable to allocate memory for plaintext buffer\n");
        return 1;
    }
    int decrypted_len = EVP_DecryptUpdate(ctx, plaintext_buffer, len, ciphertext, len);
    if (decrypted_len <= 0) {
        printf("Error: unable to decrypt ciphertext\n");
        return 1;
    }

    // Copy the decrypted ciphertext into the output string
    strcpy(plaintext, plaintext_buffer);

    // Clean up and free resources
    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(plaintext_buffer);

    // Return success
    return 0;
}
