#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>
#include <boost/gil/extension/io/jpeg.hpp>
#include <boost/gil/extension/io/png.hpp>
#include <boost/gil/extension/io/gif.hpp>
#include <boost/gil/extension/io/pdf.hpp>

int convertImagesToPDF(const std::string& inputDir, const std::vector<std::string>& images, const std::string& outputDir) {
    int numConverted = 0;
    for (const auto& image : images) {
        // Get the extension of the image file
        size_t extPos = image.rfind('.');
        if (extPos == std::string::npos) {
            continue;
        }
        std::string ext = image.substr(extPos + 1);

        // Resize the image to a specified width before converting it to PDF
        int resizeWidth = 800;
        boost::gil::image_view<boost::gil::rgb8_pixel_t> resizedImage;
        if (ext == "jpg" || ext == "jpeg") {
            resizedImage = boost::gil::resize(
                boost::gil::image_read_info<boost::gil::jpeg_tag>(inputDir + "/" + image),
                resizeWidth, 0
            );
        } else if (ext == "png") {
            resizedImage = boost::gil::resize(
                boost::gil::image_read_info<boost::gil::png_tag>(inputDir + "/" + image),
                resizeWidth, 0
            );
        } else if (ext == "gif") {
            resizedImage = boost::gil::resize(
                boost::gil::image_read_info<boost::gil::gif_tag>(inputDir + "/" + image),
                resizeWidth, 0
            );
        } else {
            continue;
        }

        // Convert the resized image to a PDF and save it in the output directory
        try {
            boost::gil::image_write_info<boost::gil::pdf_tag> writeInfo =
                boost::gil::image_write_info<boost::gil::pdf_tag>(outputDir + "/" + image.substr(0, extPos) + ".pdf");
            writeInfo.m_parameters.set("image_resolution", 72);
            boost::gil::image_view<boost::gil::rgb8_pixel_t> pdfImage = resizedImage;
            boost::gil::write_view(outputDir + "/" + image.substr(0, extPos) + ".pdf", pdfImage, writeInfo);
            numConverted++;
        } catch (const std::exception& e) {
            std::cerr << "Error converting image " << image << ": " << e.what() << std::endl;
        }
    }
    return numConverted;
}
```

