from fastapi import FastAPI, Request, Response
from pydantic import BaseModel
from sqlalchemy.orm import Session

app = FastAPI()

class UserProfile(BaseModel):
    id: str
    name: str
    email: str
    address: Optional[Dict] = None
    phone_numbers: List[str] = []

class Address(BaseModel):
    street: str
    city: str
    state: str
    zipcode: int

@app.post("/users/{user_id}/profile")
def update_user_profile(request: Request, user_id: str, body: Dict[str, Any]) -> Response:
    session = request.session
    profile = UserProfile.parse_obj(body)

    # Check if the requested user exists in the database
    try:
        user = session.query(User).get(user_id)
    except NoResultFound as e:
        return Response(status_code=404, content="Invalid user ID")

    # Update the user's profile
    for field in profile:
        setattr(user, field, getattr(profile, field))
    session.commit()

    # Synchronize the updated profile with the external social media platform
    try:
        response = requests.post("https://api.socialmediaplatform.com/users/{user_id}/profile", json=body)
        if response.status_code == 200:
            return Response(status_code=200, content="Profile updated successfully")
        else:
            return Response(status_code=503, content="Error updating profile on social media platform")
    except RequestException as e:
        return Response(status_code=503, content="Network error when communicating with the external social media platform")
