        private static readonly string[] SupportedPaddingSchemes = new string[] { "PKCS7", "ANSI X9.23", "NoPadding" };
        private static readonly Dictionary<string, int> PaddingSchemeLengths = new Dictionary<string, int>() {
            { "PKCS7", 16 },
            { "ANSI X9.23", 8 },
            { "NoPadding", 0 }
        };
