        const auto transactionId = parseTransactionId(line);
        analyzer.addTransaction(transactionId);

        // Fetch transaction metadata for the transaction ID using the Payment Gateway API
        api.fetchTransactionMetadata(transactionId);
    }
    file.close();

    // Print suspicious activities detected by the Transaction Analyzer
    std::cout << "Suspicious activities detected:" << std::endl;
    for (const auto& transaction : analyzer.getTransactions()) {
        if (analyzer.isDuplicate(transaction)) {
            std::cout << transaction << " is a duplicate" << std::endl;
        } else {
            std::cout << transaction << " is not a duplicate" << std::endl;
