using System;
using System.Security.Cryptography;
using System.Threading;
using System.Collections.Concurrent;
using Microsoft.Extensions.Logging;

namespace SecureMessageProcessor
{
    public class SecureMessageProcessor
    {
        private static readonly ConcurrentDictionary<string, byte[]> _cache = new ConcurrentDictionary<string, byte[]>();
        private readonly ILogger<SecureMessageProcessor> _logger;
        private readonly RijndaelManaged _rijndael;

        public SecureMessageProcessor(ILogger<SecureMessageProcessor> logger)
        {
            _logger = logger;
            _rijndael = new RijndaelManaged();
        }

        public string DecryptMessage(string message, string key, string iv)
        {
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Input message is empty.", nameof(message));

            if (string.IsNullOrEmpty(key))
                throw new ArgumentException("Key is not specified.", nameof(key));

            if (string.IsNullOrEmpty(iv))
                throw new ArgumentException("IV is not specified.", nameof(iv));

            string decryptedMessage = null;
            try
            {
                byte[] encryptedBytes = Convert.FromBase64String(message);
                _rijndael.Key = Encoding.UTF8.GetBytes(key);
                _rijndael.IV = Encoding.UTF8.GetBytes(iv);

                using (MemoryStream memoryStream = new MemoryStream(encryptedBytes))
                {
                    using (CryptoStream cryptoStream = new CryptoStream(memoryStream, _rijndael.CreateDecryptor(), CryptoStreamMode.Read))
                    {
                        using (StreamReader streamReader = new StreamReader(cryptoStream))
                        {
                            decryptedMessage = streamReader.ReadToEnd();
                        }
                    }
                }
            }
            catch (Exception e)
            {
                _logger.LogError(e, "Failed to decrypt message.");
            }

            return decryptedMessage;
        }

        public string EncryptMessage(string message, string key, string iv)
        {
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Input message is empty.", nameof(message));

            if (string.IsNullOrEmpty(key))
                throw new ArgumentException("Key is not specified.", nameof(key));

            if (string.IsNullOrEmpty(iv))
                throw new ArgumentException("IV is not specified.", nameof(iv));

            string encryptedMessage = null;
            try
            {
                using (_rijndael)
                {
                    _rijndael.Key = Encoding.UTF8.GetBytes(key);
                    _rijndael.IV = Encoding.UTF8.GetBytes(iv);

                    byte[] messageBytes = Encoding.UTF8.GetBytes(message);
                    using (MemoryStream memoryStream = new MemoryStream())
                    {
                        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, _rijndael.CreateEncryptor(), CryptoStreamMode.Write))
                        {
                            cryptoStream.Write(messageBytes, 0, messageBytes.Length);
                            cryptoStream.FlushFinalBlock();

                            byte[] encryptedBytes = memoryStream.ToArray();
                            encryptedMessage = Convert.ToBase64String(encryptedBytes);
                        }
                    }
                }
            }
            catch (Exception e)
            {
                _logger.LogError(e, "Failed to encrypt message.");
            }

            return encryptedMessage;
        }

        private static void AddCacheEntry(string key, byte[] value)
        {
            if (!_cache.TryAdd(key, value))
            {
                _logger.LogWarning("Failed to add cache entry for key {Key}.", key);
            }
        }

        private static bool TryGetCacheEntry(string key, out byte[] value)
        {
            return _cache.TryGetValue(key, out value);
        }

        private static void RemoveCacheEntry(string key)
        {
            if (!_cache.TryRemove(key))
            {
                _logger.LogWarning("Failed to remove cache entry for key {Key}.", key);
            }
        }
    }
}
