public class CryptographicConfiguration {
    private static final Map<String, String> CONFIG_MAP = new HashMap<>();
    private static final Map<String, FactoryFunction> FACTORY_FUNCTIONS = new HashMap<>();
    private static final List<ValidationSchema> VALIDATION_SCHEMAS = new ArrayList<>();

    public CryptographicConfiguration() {
        // Load configuration from external service
        loadConfig();

        // Register default factory functions
        registerFactoryFunction("des-ecb", new DESCipherFactory(DESMode.ECB));
        registerFactoryFunction("des-ede", new DESCipherFactory(DESMode.EDE));
        registerFactoryFunction("des-ede3", new DESCipherFactory(DESMode.EDE3));
        registerFactoryFunction("des-cfb", new DESCipherFactory(DESMode.CFB));
        registerFactoryFunction("aes-gcm", new AESCipherFactory(AESMode.GCM));
        registerFactoryFunction("chacha20-poly1305", new ChaCha20Poly1305CipherFactory());
        registerFactoryFunction("rsa-oaep", new RSAOAEPEncryptionFactory());

        // Register default validation schemas
        registerValidationSchema(new ValidationSchema("des-ecb", "{\"type\": \"string\", \"enum\": [\"ECB\"]}"));
        registerValidationSchema(new ValidationSchema("des-ede", "{\"type\": \"string\", \"enum\": [\"EDE\"]}"));
        registerValidationSchema(new ValidationSchema("des-ede3", "{\"type\": \"string\", \"enum\": [\"EDE3\"]}"));
        registerValidationSchema(new ValidationSchema("des-cfb", "{\"type\": \"string\", \"enum\": [\"CFB\"]}"));
        registerValidationSchema(new ValidationSchema("aes-gcm", "{\"type\": \"string\", \"enum\": [\"GCM\"]}"));
        registerValidationSchema(new ValidationSchema("chacha20-poly1305", "{\"type\": \"string\", \"enum\": [\"ChaCha20Poly1305\"]}"));
        registerValidationSchema(new ValidationSchema("rsa-oaep", "{\"type\": \"string\", \"enum\": [\"RSAOAEP\"]}"));
    }

    public void loadConfig() {
        // Load configuration from external service
    }

    public void registerFactoryFunction(String id, FactoryFunction factoryFunction) {
        FACTORY_FUNCTIONS.put(id, factoryFunction);
    }

    public void registerValidationSchema(ValidationSchema validationSchema) {
        VALIDATION_SCHEMAS.add(validationSchema);
    }

    public Object getConfigValue(String key) {
        return CONFIG_MAP.get(key);
    }

    public void setConfigValue(String key, Object value) {
        CONFIG_MAP.put(key, value);
    }

    public FactoryFunction getFactoryFunction(String id) {
        return FACTORY_FUNCTIONS.get(id);
    }

    public ValidationSchema getValidationSchema(String id) {
        return VALIDATION_SCHEMAS.stream().filter(schema -> schema.getId().equals(id)).findFirst().orElse(null);
    }

    public void validateConfig() {
        // Validate configuration against all validation schemas
    }
}
