  // Define a function to download the input file from S3 and call readFileAndProcessRecords() on it
  auto downloadInputFile = [&](const std::string& key) {
    HeadObjectRequest request;
    request.WithBucket(BUCKET_NAME).WithKey(key);
    HeadObjectResult response = s3Client.HeadObject(request);

    if (!response.IsSuccess()) {
      std::cout << "Error: unable to download input file" << std::endl;
      return;
    }

    GetObjectRequest request;
    request.WithBucket(BUCKET_NAME).WithKey(key);
    GetObjectResult response = s3Client.GetObject(request);

    if (!response.IsSuccess()) {
      std::cout << "Error: unable to download input file" << std::endl;
      return;
    }

    readFileAndProcessRecords(response.GetBody());
  };

  // Define a function to handle S3 download errors
  auto s3DownloadError = [&](const std::string& errorMessage) {
    std::cout << "Error: " << errorMessage << std::endl;
    return;
  };

  // Download the input file from S3 and call readFileAndProcessRecords() on it
  downloadInputFile("input_file");
}
