const WebSocketStreamReducer = require('websocket-stream-reducer');
const crypto = require('crypto');
const { FinancialApiService } = require('./financial-api-service');

class ReductionWorker {
  constructor(config) {
    this.config = config;
    this.transactionAmounts = {};
    this.fetchTransactionAmount = this.fetchTransactionAmount.bind(this);
  }

  async processStream(stream, callback) {
    const workerPool = [];
    for (let i = 0; i < this.config.workersCount; i++) {
      workerPool.push(new Worker('./worker.js'));
    }

    stream.on('message', async message => {
      try {
        const transactionAmount = parseInt(message);
        if (isNaN(transactionAmount)) {
          throw new Error(`Invalid transaction amount: ${transactionAmount}`);
        }

        this.transactionAmounts[message] = true;
        await this.fetchTransactionAmount(transactionAmount);
      } catch (error) {
        console.log(`Error processing transaction amount: ${error.message}`);
      } finally {
        callback();
      }
    });
  }

  async fetchTransactionAmount(transactionAmount) {
    try {
      const response = await FinancialApiService.getTransactionDetails(transactionAmount);
      if (!response.ok) {
        throw new Error(`Error fetching transaction amount: ${transactionAmount}`);
      }
      const transactionDetails = await response.json();
      return transactionDetails;
    } catch (error) {
      console.log(`Error fetching transaction amount: ${error.message}`);
    }
  }
}

class FinancialApiService {
  constructor(config) {
    this.config = config;
  }

  async getTransactionDetails(transactionAmount) {
    const url = `${this.config.apiUrl}/transactions/${transactionAmount}`;
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Error fetching transaction details: ${transactionAmount}`);
      }
      const transactionDetails = await response.json();
      return transactionDetails;
    } catch (error) {
      console.log(`Error fetching transaction details: ${error.message}`);
    }
  }
}
```
The `WebSocketStreamReducer` class is responsible for processing a WebSocket stream and reducing the total value of financial transaction amounts. It uses a worker pool to process transactions in parallel, with the number of workers configurable based on system load and transaction volume. The `fetchTransactionAmount` method interacts with a simulated financial API to retrieve transaction details, handling potential latency issues, rate limiting, and retries for failed fetches with exponential backoff.

The reduction logic is encapsulated in the `ReductionWorker` class, which uses the `FinancialApiService` class to interact with the external financial API. The `FinancialApiService` class is responsible for managing the external service interaction and handling potential errors during encryption processes.

