                if is_outdated(self.avatars[user_id]):
                    del self.avatars[user_id]

    def get_cache_size(self):
        with self.lock:
            return len(self.avatars)

    def evict_least_recently_used(self, max_size=1000):
        with self.lock:
            # Evict least recently used avatar to make room for new ones
            if len(self.avatars) > max_size:
                oldest_user_id = None
                oldest_access_time = None
                for user_id, access_time in self.avatars.items():
                    if oldest_access_time is None or access_time < oldest_access_time:
                        oldest_user_id = user_id
                        oldest_access_time = access_time
                del self.avatars[oldest_user_id]
```
