import os
from flask import Flask, jsonify, request
from dotenv import load_dotenv
from rust.module import dbCommandExecutor

app = Flask(__name__)

# Load environment variables from .env file
load_dotenv()

# Set up authentication with third-party API
auth_api = os.getenv("AUTH_API")
auth_token = os.getenv("AUTH_TOKEN")

@app.route("/", methods=["GET"])
def index():
    return "Hello, world!"

@app.route("/login", methods=["POST"])
def login():
    username = request.json["username"]
    password = request.json["password"]
    auth_token = dbCommandExecutor(auth_api, f"SELECT * FROM users WHERE username='{username}' AND password='{password}';")
    return jsonify({"auth_token": auth_token})

@app.route("/logout", methods=["POST"])
def logout():
    auth_token = request.json["auth_token"]
    dbCommandExecutor(auth_api, f"DELETE FROM users WHERE token='{auth_token}';")
    return jsonify({"message": "Logged out successfully."})

@app.route("/users", methods=["GET"])
def users():
    auth_token = request.json["auth_token"]
    results = dbCommandExecutor(auth_api, f"SELECT * FROM users WHERE token='{auth_token}';")
    return jsonify({"results": results})

@app.route("/users/<int:user_id>", methods=["GET"])
def user(user_id):
    auth_token = request.json["auth_token"]
    result = dbCommandExecutor(auth_api, f"SELECT * FROM users WHERE token='{auth_token}' AND id={user_id};")
    return jsonify({"result": result})

if __name__ == "__main__":
    app.run()
