import java.util.*;
import com.google.common.cache.CacheBuilder;
import redis.clients.jedis.JedisPool;

public class JWTService {
  private static final JedisPool REDIS_POOL = new JedisPool("localhost");

  public void generateToken(List<String> forwardList, String firstArg, String secondArg) {
    if (forwardList == null || firstArg == null || secondArg == null) {
      throw new IllegalArgumentException("Invalid input parameters");
    }

    int index = forwardList.indexOf(firstArg);
    if (index != -1) {
      // Insert the second argument after the first argument in the list
      forwardList.add(index + 1, secondArg);
    } else {
      // Insert the second argument at the end of the list
      forwardList.add(secondArg);
    }

    // Use a distributed caching layer to enhance performance further
    REDIS_POOL.set("forward-list", forwardList);
  }
}
