#include <openssl/chacha.h>
#include <openssl/gcm.h>
#include <openssl/ssl.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <pthread.h>

// Configuration Parameters
const int AES_128 = 1; // AES-128 block size
const int AES_256 = 2; // AES-256 block size
const int CHACHA20 = 3; // ChaCha20 block size
const int GCM = 4; // GCM mode for AES-128 and AES-256
const char *CIPHER_NAMES[] = {"AES-128", "AES-256", "ChaCha20", "GCM"}; // Cipher names for command line interface

// Key Generation and Management
unsigned char *generateKey(int cipher) {
  switch (cipher) {
    case AES_128: return generateAES128Key();
    case AES_256: return generateAES256Key();
    case CHACHA20: return generateChaCha20Key();
  }
}

void freeKey(unsigned char *key) {
  OPENSSL_cleanse(key, strlen(key));
  free(key);
}

// Cryptographic Functions
int encrypt(int cipher, unsigned char *plaintext, int plaintext_length, unsigned char *key, unsigned char *iv, unsigned char **ciphertext) {
  switch (cipher) {
    case AES_128: return aes128Encrypt(plaintext, plaintext_length, key, iv, ciphertext);
    case AES_256: return aes256Encrypt(plaintext, plaintext_length, key, iv, ciphertext);
    case CHACHA20: return chacha20Encrypt(plaintext, plaintext_length, key, iv, ciphertext);
  }
}

int decrypt(int cipher, unsigned char *ciphertext, int ciphertext_length, unsigned char *key, unsigned char *iv, unsigned char **plaintext) {
  switch (cipher) {
    case AES_128: return aes128Decrypt(ciphertext, ciphertext_length, key, iv, plaintext);
    case AES_256: return aes256Decrypt(ciphertext, ciphertext_length, key, iv, plaintext);
    case CHACHA20: return chacha20Decrypt(ciphertext, ciphertext_length, key, iv, plaintext);
  }
}

// Command Line Interface
void printUsage() {
  printf("Usage: cryptography <command> [options]\n");
  printf("\t<command> can be one of the following:\n");
  printf("\t\tgenerate-key - Generate a key for a specific cipher.\n");
  printf("\t\tencrypt - Encrypt a plaintext using a specific cipher.\n");
  printf("\t\tdecrypt - Decrypt a ciphertext using a specific cipher.\n");
  printf("Options:\n");
  printf("\t-h, --help - Print usage information and exit.\n");
  printf("\t-c <cipher> - Specify the cipher to use (default: AES-128).\n");
}

int main(int argc, char **argv) {
  if (argc == 1) {
    printUsage();
    return 0;
  }

  int option_index = 1;
  while (option_index < argc) {
    if (strcmp(argv[option_index], "-h") == 0 || strcmp(argv[option_index], "--help") == 0) {
      printUsage();
      return 0;
    } else if (strcmp(argv[option_index], "generate-key") == 0) {
      int cipher = AES_128; // Default cipher
      option_index++;
      if (option_index < argc && strcmp(argv[option_index], "-c") == 0) {
        option_index++;
        if (strcmp(argv[option_index], "AES-128") == 0) cipher = AES_128;
        else if (strcmp(argv[option_index], "AES-256") == 0) cipher = AES_256;
        else if (strcmp(argv[option_index], "ChaCha20") == 0) cipher = CHACHA20;
        else {
          printf("Invalid cipher specified. Using default.\n");
          cipher = AES_128;
        }
      }
      unsigned char *key = generateKey(cipher);
      if (key != NULL) {
        printf("Generated key for %s:\n", CIPHER_NAMES[cipher]);
        printHexString(key, strlen(key));
        freeKey(key);
      } else {
        printf("Error generating key.\n");
      }
    } else if (strcmp(argv[option_index], "encrypt") == 0) {
      int cipher = AES_128; // Default cipher
      option_index++;
      if (option_index < argc && strcmp(argv[option_index], "-c") == 0) {
        option_index++;
        if (strcmp(argv[option_index], "AES-128") == 0) cipher = AES_128;
        else if (strcmp(argv[option_index], "AES-256") == 0) cipher = AES_256;
        else if (strcmp(argv[option_index], "ChaCha20") == 0) cipher = CHACHA20;
        else {
          printf("Invalid cipher specified. Using default.\n");
          cipher = AES_128;
        }
      }
      unsigned char *plaintext = NULL;
      int plaintext_length = 0;
      option_index++;
      if (option_index < argc && strcmp(argv[option_index], "-p") == 0) {
        option_index++;
        plaintext = (unsigned char *) malloc(sizeof(char) * strlen(argv[option_index]));
        memset(plaintext, 0, strlen(argv[option_index]));
        strncpy((char *) plaintext, argv[option_index], strlen(argv[option_index]) - 1);
        plaintext_length = strlen(argv[option_index]);
      } else {
        printf("Invalid plaintext specified. Using default.\n");
      }
      unsigned char *key = generateKey(cipher);
      if (key != NULL) {
        unsigned char *iv = generateRandomIV();
        if (iv != NULL) {
          unsigned char *ciphertext = NULL;
          int ciphertext_length = encrypt(cipher, plaintext, plaintext_length, key, iv, &ciphertext);
          if (ciphertext_length > 0) {
            printf("Encrypted %d bytes of plaintext:\n", ciphertext_length);
            printHexString(ciphertext, ciphertext_length);
          } else {
            printf("Error encrypting data.\n");
          }
          free(iv);
        } else {
          printf("Error generating IV.\n");
        }
      } else {
        printf("Error generating key.\n");
      }
    } else if (strcmp(argv[option_index], "decrypt") == 0) {
      int cipher = AES_128; // Default cipher
      option_index++;
      if (option_index < argc && strcmp(argv[option_index], "-c") == 0) {
        option_index++;
        if (strcmp(argv[option_index], "AES-128") == 0) cipher = AES_128;
        else if (strcmp(argv[option_index], "AES-256") == 0) cipher = AES_256;
        else if (strcmp(argv[option_index], "ChaCha20") == 0) cipher = CHACHA20;
        else {
          printf("Invalid cipher specified. Using default.\n");
          cipher = AES_128;
        }
      }
      unsigned char *ciphertext = NULL;
      int ciphertext_length = 0;
      option_index++;
      if (option_index < argc && strcmp(argv[option_index], "-p") == 0) {
        option_index++;
        ciphertext = (unsigned char *) malloc(sizeof(char) * strlen(argv[option_index]));
        memset(ciphertext, 0, strlen(argv[option_index]));
        strncpy((char *) ciphertext, argv[option_index], strlen(argv[option_index]) - 1);
        ciphertext_length = strlen(argv[option_index]);
      } else {
        printf("Invalid ciphertext specified. Using default.\n");
      }
      unsigned char *key = generateKey(cipher);
      if (key != NULL) {
        unsigned char *iv = generateRandomIV();
        if (iv != NULL) {
          unsigned char *plaintext = NULL;
          int plaintext_length = decrypt(cipher, ciphertext, ciphertext_length, key, iv, &plaintext);
          if (plaintext_length > 0) {
            printf("Decrypted %d bytes of ciphertext:\n", plaintext_length);
            printHexString(plaintext, plaintext_length);
          } else {
            printf("Error decrypting data.\n");
          }
          free(iv);
        } else {
          printf("Error generating IV.\n");
        }
      } else {
        printf("Error generating key.\n");
      }
    } else if (strcmp(argv[option_index], "-h") == 0 || strcmp(argv[option_index], "--help") == 0) {
      printUsage();
    } else {
      printf("Invalid option specified. Using default.\n");
    }
    option_index++;
  }
}

// Function to generate a random initialization vector (IV).
unsigned char *generateRandomIV() {
  unsigned char iv[16]; // 128-bit IV
  FILE *fp = fopen("/dev/urandom", "rb");
  if (!fp) {
    return NULL;
  }
  fread(iv, sizeof(unsigned char), 16, fp);
  fclose(fp);
  return iv;
}

// Function to print a hexadecimal string.
void printHexString(unsigned char *string, int length) {
  for (int i = 0; i < length; i++) {
    printf("%02x", string[i]);
  }
  printf("\n");
}

// Function to generate a key for a specific cipher.
unsigned char *generateKey(int cipher) {
  switch (cipher) {
    case AES_128: return generateRandomKey(16);
    case AES_192: return generateRandomKey(24);
    case AES_256: return generateRandomKey(32);
    default: return NULL;
  }
}

// Function to generate a random key.
unsigned char *generateRandomKey(int length) {
  unsigned char key[length]; // Key buffer
  FILE *fp = fopen("/dev/urandom", "rb");
  if (!fp) {
    return NULL;
  }
  fread(key, sizeof(unsigned char), length, fp);
  fclose(fp);
  return key;
}

