#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/kdf.h>

// Function to integrate custom AES encryption library into larger application framework
EVP_CIPHER_CTX* aesEncrypt(const unsigned char *key, const unsigned char *iv, int mode, int padding, int kdf) {
    // Allocate memory for the EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Could not allocate memory for EVP_CIPHER_CTX\n");
        return NULL;
    }

    // Set the AES key and IV
    if (!EVP_CipherInit(ctx, EVP_aes_128_ecb(), key, iv, 1)) {
        printf("Error: Could not set AES key and IV\n");
        return NULL;
    }

    // Set the padding scheme
    if (!EVP_CIPHER_CTX_set_padding(ctx, padding)) {
        printf("Error: Could not set padding scheme\n");
        return NULL;
    }

    // Set the cipher mode
    switch (mode) {
        case ECB:
            if (!EVP_CipherInit(ctx, EVP_aes_128_ecb(), key, iv, 1)) {
                printf("Error: Could not set AES ECB mode\n");
                return NULL;
            }
            break;
        case CBC:
            if (!EVP_CipherInit(ctx, EVP_aes_128_cbc(), key, iv, 1)) {
                printf("Error: Could not set AES CBC mode\n");
                return NULL;
            }
            break;
        case GCM:
            if (!EVP_CipherInit(ctx, EVP_aes_128_gcm(), key, iv, 1)) {
                printf("Error: Could not set AES GCM mode\n");
                return NULL;
            }
            break;
        default:
            printf("Error: Unsupported cipher mode\n");
            return NULL;
    }

    // Set the key derivation function
    switch (kdf) {
        case PBKDF2:
            if (!EVP_PBE_CipherInit(ctx, EVP_aes_128_cbc(), key, iv, 1)) {
                printf("Error: Could not set PBKDF2 KDF\n");
                return NULL;
            }
            break;
        case HKDF:
            if (!EVP_HKDF_CipherInit(ctx, EVP_aes_128_cbc(), key, iv, 1)) {
                printf("Error: Could not set HKDF KDF\n");
                return NULL;
            }
            break;
        default:
            printf("Error: Unsupported KDF\n");
            return NULL;
    }

    // Return the pointer to the EVP_CIPHER_CTX structure
    return ctx;
}

// Example usage of the aesEncrypt function
int main() {
    unsigned char key[] = "0123456789abcdef";  // AES key
    unsigned char iv[] = "0123456789abcdef";   // Initialization vector
    int mode = ECB;                            // Cipher mode (ECB, CBC, GCM)
    int padding = PKCS7;                       // Padding scheme (PKCS7, ANSI X923, ISO 10126)
    int kdf = PBKDF2;                          // Key derivation function (PBKDF2, HKDF)

    EVP_CIPHER_CTX *ctx = aesEncrypt(key, iv, mode, padding, kdf);
    if (ctx == NULL) {
        printf("Error: Could not initialize AES encryption\n");
        return 1;
    }

    // Encrypt the message using the EVP_CIPHER_CTX structure
    unsigned char plaintext[] = "Hello, World!";
    size_t plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[16];
    size_t ciphertext_len;
    if (!EVP_CipherUpdate(ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) {
        printf("Error: Could not encrypt message\n");
        return 1;
    }

    // Print the encrypted message
    printf("Encrypted message: ");
    for (size_t i = 0; i < ciphertext_len; i++) {
        printf("%02x", ciphertext[i]);
    }
    printf("\n");

    // Clean up the EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX_free(ctx);

    return 0;
}
