    const char* input_file_path = "/path/to/input.jpg";
    const char* output_dir = "/path/to/output";
    const char* metadata_file_name = NULL; // or "/path/to/metadata.json"

    int status = convert_jpeg_to_pdf(input_file_path, output_dir, metadata_file_name);
    if (status != 0) {
        fprintf(stderr, "Error converting JPEG to PDF: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}
