#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Configuration options
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_INFO  1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

// Logging mechanism
static void logCondition(int level, const char *format, ...) {
    // Check if the logging level is above or equal to the configured level
    if (level >= getLogLevel()) {
        // Format the message with variable arguments
        va_list args;
        va_start(args, format);
        char* formattedMessage = malloc(strlen(format) + 1);
        vsprintf(formattedMessage, format, args);
        va_end(args);

        // Prevent buffer overflow issues by limiting the length of the message
        int maxLength = getMaxLogLength();
        if (strlen(formattedMessage) > maxLength) {
            formattedMessage[maxLength - 1] = '\0';
        }

        // Handle concurrent access to the log mechanism safely
        pthread_mutex_lock(&logMutex);
        fprintf(stderr, "%s\n", formattedMessage);
        pthread_mutex_unlock(&logMutex);
    }
}
```
This code block defines a function `logCondition` that takes three arguments: the logging level (an integer), a format string, and variable number of arguments. The function checks if the given logging level is above or equal to the configured logging level using `getLogLevel()` and if it is, formats the message with `vsprintf()`. It then allocates memory for the formatted message using `malloc()`, checks if the length of the message exceeds a maximum length using `strlen()`, and if so truncates the message to prevent buffer overflow issues. Finally, it uses `pthread_mutex_lock()` and `pthread_mutex_unlock()` to handle concurrent access to the log mechanism safely, ensuring that logs from multiple threads do not interfere with each other.

