using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Linq;
using Microsoft.Extensions.Logging;

namespace WebsiteManager
{
    class Program
    {
        static void Main(string[] args)
        {
            var logger = LoggerFactory.Create(builder =>
                builder.AddConsole()
                       .SetMinimumLevel(LogLevel.Information));

            var config = new ConfigurationBuilder()
                .AddJsonFile("config.json")
                .Build();

            var sites = config["sites"];
            foreach (var site in sites)
            {
                var cloudPlatform = site["cloud_platform"];
                var operations = site["operations"];

                // Verify the existence of necessary files for each site
                if (!File.Exists("web.config"))
                {
                    logger.LogError($"Failed to find 'web.config' file in {site}");
                    continue;
                }

                if (!File.Exists("appsettings.json"))
                {
                    logger.LogError($"Failed to find 'appsettings.json' file in {site}");
                    continue;
                }

                // Execute operations for each site concurrently
                foreach (var operation in operations)
                {
                    var task = Task.Run(async () =>
                    {
                        switch (operation)
                        {
                            case "add":
                                await AddSiteAsync(site, cloudPlatform);
                                break;
                            case "remove":
                                await RemoveSiteAsync(site, cloudPlatform);
                                break;
                            case "start":
                                await StartSiteAsync(site, cloudPlatform);
                                break;
                            case "stop":
                                await StopSiteAsync(site, cloudPlatform);
                                break;
                            case "restart":
                                await RestartSiteAsync(site, cloudPlatform);
                                break;
                        }
                    });
                }
            }
        }

        private static async Task AddSiteAsync(string site, string cloudPlatform)
        {
            // Perform add operation for the given site on the specified cloud platform
            var result = await CloudPlatform.AddSiteAsync(site);

            if (result == null)
            {
                Console.WriteLine($"Failed to add {site} on {cloudPlatform}");
            }
            else
            {
                Console.WriteLine($"Successfully added {site} on {cloudPlatform} with id {result}");
            }
        }

        private static async Task RemoveSiteAsync(string site, string cloudPlatform)
        {
            // Perform remove operation for the given site on the specified cloud platform
            var result = await CloudPlatform.RemoveSiteAsync(site);

            if (result == null)
            {
                Console.WriteLine($"Failed to remove {site} from {cloudPlatform}");
            }
            else
            {
                Console.WriteLine($"Successfully removed {site} from {cloudPlatform} with id {result}");
            }
        }

        private static async Task StartSiteAsync(string site, string cloudPlatform)
        {
            // Perform start operation for the given site on the specified cloud platform
            var result = await CloudPlatform.StartSiteAsync(site);

            if (result == null)
            {
                Console.WriteLine($"Failed to start {site} on {cloudPlatform}");
            }
            else
            {
                Console.WriteLine($"Successfully started {site} on {cloudPlatform} with id {result}");
            }
        }

        private static async Task StopSiteAsync(string site, string cloudPlatform)
        {
            // Perform stop operation for the given site on the specified cloud platform
            var result = await CloudPlatform.StopSiteAsync(site);

            if (result == null)
            {
                Console.WriteLine($"Failed to stop {site} on {cloudPlatform}");
            }
            else
            {
                Console.WriteLine($"Successfully stopped {site} on {cloudPlatform} with id {result}");
            }
        }

        private static async Task RestartSiteAsync(string site, string cloudPlatform)
        {
            // Perform restart operation for the given site on the specified cloud platform
            var result = await CloudPlatform.RestartSiteAsync(site);

            if (result == null)
            {
                Console.WriteLine($"Failed to restart {site} on {cloudPlatform}");
            }
            else
            {
                Console.WriteLine($"Successfully restarted {site} on {cloudPlatform} with id {result}");
            }
        }
    }
