import java.util.HashMap;
import java.util.Map;
import javax.ws.rs.core.Response;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.json.JSONObject;
import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.Claims;
import com.auth0.jwt.exceptions.JWTCreationException;
import com.auth0.jwt.exceptions.JWTVerificationException;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class JWTService {
    private static final Logger LOGGER = LoggerFactory.getLogger(JWTService.class);

    private static final String KEY_SERVICE = "key-service";
    private static final String CACHE_SERVICE = "cache-service";
    private static final String KAFKA_TOPIC = "kafka-topic";
    private static final String ALGORITHM = "algorithm";

    private KeyService keyService;
    private CacheService cacheService;
    private ProducerRecord<String, String> kafkaProducer;
    private Algorithm algorithm;

    public JWTService() {
        this.keyService = new KeyService(KEY_SERVICE);
        this.cacheService = new CacheService(CACHE_SERVICE);
        this.kafkaProducer = new ProducerRecord<>(KAFKA_TOPIC, "JWT");
        this.algorithm = Algorithm.HMAC512(ALGORITHM);
    }

    public Response generateToken(String userId) {
        try {
            Map<String, Object> claims = new HashMap<>();
            claims.put("userId", userId);
            String token = JWT.create()
                    .withClaims(claims)
                    .sign(algorithm);
            cacheService.setToken(token);
            return Response.ok().entity(token).build();
        } catch (JWTCreationException e) {
            LOGGER.error("Error creating JWT", e);
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).build();
        }
    }

    public void validateToken(String token) throws JWTVerificationException {
        DecodedJWT decodedJWT = JWT.decode(token);
        Claims claims = decodedJWT.getClaims();
        String userId = (String) claims.get("userId");
        if (!cacheService.isTokenValid(token)) {
            throw new JWTVerificationException("Invalid token");
        }
        LOGGER.info("Token is valid for user {}", userId);
    }

    public void rotateToken() {
        String oldToken = cacheService.getToken();
        String newToken = generateToken(oldToken).readEntity(String.class);
        cacheService.setToken(newToken);
        kafkaProducer.value(newToken);
        LOGGER.info("Rotating token for user {}", oldToken);
    }

    public void handleMessage(ConsumerRecord<String, String> record) {
        try {
            validateToken(record.value());
            cacheService.invalidateToken(record.value());
            LOGGER.info("Successfully verified JWT token");
        } catch (JWTVerificationException e) {
            LOGGER.error("Error verifying JWT token", e);
            cacheService.setToken(record.value());
            kafkaProducer.value(record.value());
            LOGGER.info("Rotating token for user {}", record.value());
        }
    }
}

class KeyService {
    private static final String KEY_CACHE = "key-cache";
    private CacheService cacheService;

    public KeyService(String cacheName) {
        this.cacheService = new CacheService(cacheName);
    }

    public void setKey(String key) {
        cacheService.setKey(key);
    }

    public String getKey() {
        return cacheService.getKey();
    }
}

class CacheService {
    private static final String CACHE_NAME = "cache-name";
    private Cache<String, String> cache;

    public CacheService(String cacheName) {
        this.cache = new Cache<>(cacheName);
    }

    public void setToken(String token) {
        cache.put(token, "valid");
    }

    public boolean isTokenValid(String token) {
        return cache.containsKey(token);
    }

    public void invalidateToken(String token) {
        cache.remove(token);
    }
}

class ProducerRecord<K, V> {
    private K key;
    private V value;

    public ProducerRecord(K key, V value) {
        this.key = key;
        this.value = value;
    }

    public void setKey(K key) {
        this.key = key;
    }

    public K getKey() {
        return key;
    }

    public void setValue(V value) {
        this.value = value;
    }

    public V getValue() {
        return value;
    }
}
