class OAuthSessionHandler {
    private $provider;
    private $parameters;
    private $tokenStorageService;

    public function __construct(string $providerName, array $parameters = [], TokenStorageService $tokenStorageService) {
        // Validate the provider name and parameters
        if (!in_array($providerName, ['google', 'facebook', 'github'])) {
            throw new InvalidArgumentException('Unsupported provider');
        }

        $this->provider = $providerName;
        $this->parameters = $parameters;
        $this->tokenStorageService = $tokenStorageService;
    }

    public function authenticate(string $username, string $password): array {
        // Authenticate the user using the selected provider
        switch ($this->provider) {
            case 'google':
                // Google OAuth authentication flow
                break;
            case 'facebook':
                // Facebook OAuth authentication flow
                break;
            case 'github':
                // GitHub OAuth authentication flow
                break;
        }

        // Check for rate limit exceeded or temporary network failures
        if ($response->getStatusCode() == 429 || $response->getStatusCode() == 500) {
            throw new \Exception('Rate limit exceeded or temporary network failure');
        }

        // Validate the response and extract the access token
        $body = json_decode($response->getBody());
        if (!isset($body->access_token)) {
            throw new \Exception('Invalid credentials');
        }

        // Store the access token securely in the session using the external token storage service
        $this->tokenStorageService->storeToken($username, $body->access_token);

        return ['provider' => $this->provider, 'access_token' => $body->access_token];
    }

    public function __toString(): string {
        // Display the current provider and its parameters
        return "OAuthSessionHandler: {$this->provider} ({$this->parameters})";
    }

    public function getToken(string $username): ?string {
        // Retrieve the access token from the session using the external token storage service
        return $this->tokenStorageService->getToken($username);
    }

    public function setProvider(string $providerName, array $parameters = []): void {
        // Set the current provider and parameters
        if (!in_array($providerName, ['google', 'facebook', 'github'])) {
            throw new InvalidArgumentException('Unsupported provider');
        }

        $this->provider = $providerName;
        $this->parameters = $parameters;
    }
}
