// Bulk Update Function
async function bulkUpdateUsers(userIds: string[], updates: any): Promise<any> {
  // Lock the cache to prevent race conditions during bulk updates
  const cacheLock = await acquireCacheLock();

  try {
    // Check if the user profiles are cached, and fetch them from the database if necessary
    const users = await getUsers(userIds);

    // Apply the updates to each user's profile
    for (const user of users) {
      updateUserProfile(user, updates);
    }

    // Save the updated profiles to the database
    await saveUsers(users);
  } finally {
    // Release the cache lock
    releaseCacheLock(cacheLock);
  }
}

// Individual Update Function
async function updateUserProfile(userId: string, updates: any): Promise<any> {
  // Lock the cache to prevent race conditions during individual updates
  const cacheLock = await acquireCacheLock();

  try {
    // Check if the user profile is cached, and fetch it from the database if necessary
    const user = await getUser(userId);

    // Apply the updates to the user's profile
    updateUserProfile(user, updates);

    // Save the updated profile to the database
    await saveUser(user);
  } finally {
    // Release the cache lock
    releaseCacheLock(cacheLock);
  }
}

