  unsigned char *key; // The key for the currently selected cipher
} cryptContext;

// Define the global context
cryptContext context;

int main() {
  printf("Cipher Library Version: %s\n", LIBRARY_VERSION);

  // Initialize the context
  context.cipher = CIPHER_AES_128;
  context.mode = MODE_ENCRYPTION;
  context.keySize = 16;
  context.key = NULL;

  // Load the key from an external certificate management system
  if (loadKey()) {
    printf("Error loading key\n");
    return -1;
  }

  // Set the current cipher and mode
  cipherInit(context.cipher, context.mode);

  // Perform encryption or decryption
  unsigned char plaintext[16] = {0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88};
  unsigned char ciphertext[16];
  size_t len = sizeof(plaintext);
  if (context.mode == MODE_ENCRYPTION) {
    cipherEncrypt(plaintext, ciphertext, len);
  } else {
    cipherDecrypt(ciphertext, plaintext, len);
  }

  // Output the result
  printf("Result: ");
  for (int i = 0; i < len; i++) {
    printf("%02x", ciphertext[i]);
  }
  printf("\n");

  // Clean up
  destroyCipher();

  return 0;
}

void cipherInit(int cipher, int mode) {
  if (cipher < CIPHER_AES_128 || cipher > CIPHER_GCM) {
    printf("Error: Invalid cipher\n");
    exit(-1);
  }
  if (mode != MODE_ENCRYPTION && mode != MODE_DECRYPTION) {
    printf("Error: Invalid mode\n");
    exit(-2);
  }
  context.cipher = cipher;
  context.mode = mode;
}

void cipherEncrypt(unsigned char *plaintext, unsigned char *ciphertext, size_t len) {
  // Perform the encryption using the selected cipher and key
  switch (context.cipher) {
    case CIPHER_AES_128:
      AES_encrypt(plaintext, ciphertext, context.key);
      break;
    case CIPHER_AES_256:
      AES_encrypt(plaintext, ciphertext, context.key);
      break;
    case CIPHER_ChaCha20:
      ChaCha20_encrypt(plaintext, ciphertext, context.key);
      break;
    case CIPHER_GCM:
      GCM_encrypt(plaintext, ciphertext, context.key);
      break;
  }
}

void cipherDecrypt(unsigned char *ciphertext, unsigned char *plaintext, size_t len) {
  // Perform the decryption using the selected cipher and key
  switch (context.cipher) {
    case CIPHER_AES_128:
      AES_decrypt(ciphertext, plaintext, context.key);
      break;
    case CIPHER_AES_256:
      AES_decrypt(ciphertext, plaintext, context.key);
      break;
    case CIPHER_ChaCha20:
      ChaCha20_decrypt(ciphertext, plaintext, context.key);
      break;
    case CIPHER_GCM:
      GCM_decrypt(ciphertext, plaintext, context.key);
      break;
  }
}

void setCipherKey(int cipher, int keySize, unsigned char *key) {
  // Set the key for the specified cipher
  switch (cipher) {
    case CIPHER_AES_128:
      AES_set_encrypt_key(key, keySize, &context.key);
      break;
    case CIPHER_AES_256:
      AES_set_decrypt_key(key, keySize, &context.key);
      break;
    case CIPHER_ChaCha20:
      ChaCha20_set_key(key, keySize, &context.key);
      break;
    case CIPHER_GCM:
      GCM_set_key(key, keySize, &context.key);
      break;
  }
}

void getCipherKey(int cipher, unsigned char *key) {
  // Get the key for the specified cipher
  switch (cipher) {
    case CIPHER_AES_128:
      AES_get_encrypt_key(context.key, key);
      break;
    case CIPHER_AES_256:
      AES_get_decrypt_key(context.key, key);
      break;
    case CIPHER_ChaCha20:
      ChaCha20_get_key(context.key, key);
      break;
    case CIPHER_GCM:
      GCM_get_key(context.key, key);
      break;
  }
}

void destroyCipher() {
  // Clean up the cipher and key
  switch (context.cipher) {
    case CIPHER_AES_128:
      AES_destroy_encrypt_key(context.key);
      break;
    case CIPHER_AES_256:
      AES_destroy_decrypt_key(context.key);
      break;
    case CIPHER_ChaCha20:
      ChaCha20_destroy_key(context.key);
      break;
    case CIPHER_GCM:
      GCM_destroy_key(context.key);
      break;
  }
}
