#include <openssl/err.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <stdbool.h>
#include <string.h>

// Structure to hold the encryption context
struct EncryptionContext {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32]; // 256-bit AES key
    bool initialized;
};

// Function to initialize the encryption context
int initEncryption(const char *password, const char *salt) {
    int ret = 0;
    struct EncryptionContext *ctx;

    // Check if the password and salt are valid
    if (!password || !salt) {
        ERR_clear_error();
        return -1;
    }

    // Allocate memory for the encryption context
    ctx = (struct EncryptionContext *)malloc(sizeof(struct EncryptionContext));
    if (!ctx) {
        ERR_clear_error();
        return -2;
    }
    memset(ctx, 0, sizeof(struct EncryptionContext));

    // Generate a random initialization vector (IV)
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Set the IV length to 96 bits (as required by GCM)
    int iv_len = EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, 96, NULL);
    if (iv_len <= 0) {
        ERR_clear_error();
        return -3;
    }

    // Derive the encryption key from the password and salt using PBKDF2
    int pbkdf2 = EVP_PBE_CipherInit(ctx->ctx, "AES-256-GCM", "id-aes256-GCM", NULL, NULL, 0);
    if (pbkdf2 <= 0) {
        ERR_clear_error();
        return -4;
    }

    // Set the salt and iteration count for PBKDF2
    int salt_len = EVP_PBE_CipherInit(ctx->ctx, "salt", (unsigned char *)salt, strlen(salt), 0);
    if (salt_len <= 0) {
        ERR_clear_error();
        return -5;
    }

    // Set the password and iteration count for PBKDF2
    int pwd_len = EVP_PBE_CipherInit(ctx->ctx, "password", (unsigned char *)password, strlen(password), 0);
    if (pwd_len <= 0) {
        ERR_clear_error();
        return -6;
    }

    // Set the key length for PBKDF2
