    if (key_len <= 0) {
        ERR_clear_error();
        return -7;
    }

    // Set the IV for GCM
    int iv_set = EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, 96, (void *)iv);
    if (iv_set <= 0) {
        ERR_clear_error();
        return -8;
    }

    // Set the key for GCM
    int key_set = EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_IVLEN, 32, (void *)ctx->key);
    if (key_set <= 0) {
        ERR_clear_error();
        return -9;
