    public function registerUser($tenant, $username, $password) {
        // Validate the username and password against tenant-specific policies
        if (!$this->validateUsername($tenant, $username)) {
            throw new Exception('Invalid username');
        }
        if (!$this->validatePassword($tenant, $password)) {
            throw new Exception('Invalid password');
        }

        // Hash the password using the tenant's preferred algorithm and parameters
        $hashedPassword = $this->hashPassword($tenant, $password);

        // Save the hashed password in the user database
        $userDatabase = $this->getUserDatabase($tenant);
        $userDatabase->save('users', [$username => $hashedPassword]);
    }

    public function loginUser($tenant, $username, $password) {
        // Validate the username and password against tenant-specific policies
        if (!$this->validateUsername($tenant, $username)) {
            throw new Exception('Invalid username');
        }
        if (!$this->validatePassword($tenant, $password)) {
            throw new Exception('Invalid password');
        }

        // Retrieve the hashed password from the user database
        $userDatabase = $this->getUserDatabase($tenant);
        $hashedPassword = $userDatabase->findOne('users', [$username]);
        if (!$hashedPassword) {
            throw new Exception('User not found');
        }

        // Compare the provided password with the hashed one in the database
        if ($this->verifyPassword($tenant, $password, $hashedPassword)) {
            return true;
        } else {
            throw new Exception('Invalid credentials');
        }
    }

    public function resetPassword($tenant, $username, $newPassword) {
        // Validate the username and password against tenant-specific policies
        if (!$this->validateUsername($tenant, $username)) {
            throw new Exception('Invalid username');
        }
        if (!$this->validatePassword($tenant, $newPassword)) {
            throw new Exception('Invalid password');
        }

        // Retrieve the hashed password from the user database
        $userDatabase = $this->getUserDatabase($tenant);
        $hashedPassword = $userDatabase->findOne('users', [$username]);
        if (!$hashedPassword) {
            throw new Exception('User not found');
        }

        // Update the hashed password in the user database with the new one
        $userDatabase->updateOne('users', ['$set' => [$username => $this->hashPassword($tenant, $newPassword)]]);
