import java.util.HashMap;
import java.util.Map;
import javax.cache.Cache;
import javax.cache.CacheManager;
import javax.cache.Caching;
import org.apache.http.HttpStatus;

public class SessionManager {
    private static final String CACHE_NAME = "userSessions";
    private static final int SESSION_TIMEOUT = 30 * 60; // 30 minutes

    private Cache<String, UserSession> userSessions;
    private SessionManagementService sessionManagementService;

    public SessionManager() {
        this.userSessions = createUserSessionCache();
        this.sessionManagementService = new SessionManagementService();
    }

    private static Cache<String, UserSession> createUserSessionCache() {
        CacheManager cacheManager = Caching.getCacheManager();
        if (cacheManager == null) {
            throw new IllegalStateException("Unable to obtain cache manager");
        }

        Cache<String, UserSession> userSessions = cacheManager.createCache(CACHE_NAME, HashMap.class, String.class);
        if (userSessions == null) {
            throw new IllegalStateException("Unable to create user session cache");
        }

        return userSessions;
    }

    public UserSession getUserSession(String sessionId) {
        UserSession userSession = userSessions.get(sessionId);

        if (userSession == null || userSession.isExpired()) {
            try {
                userSession = sessionManagementService.retrieveUserSession(sessionId);
                if (userSession != null) {
                    userSessions.put(sessionId, userSession);
                }
            } catch (SessionNotFoundException e) {
                // handle error
            }
        }

        return userSession;
    }

    public void updateUserSession(String sessionId, UserSession userSession) {
        try {
            sessionManagementService.updateUserSession(sessionId, userSession);
            userSessions.put(sessionId, userSession);
        } catch (SessionNotFoundException e) {
            // handle error
        }
    }

    public void deleteUserSession(String sessionId) {
        try {
            sessionManagementService.deleteUserSession(sessionId);
            userSessions.remove(sessionId);
        } catch (SessionNotFoundException e) {
            // handle error
        }
    }

    private class UserSession {
        private String sessionId;
        private int expirationTime;
        private Map<String, Object> data = new HashMap<>();

        public UserSession(String sessionId, int expirationTime) {
            this.sessionId = sessionId;
            this.expirationTime = expirationTime;
        }

        public String getSessionId() {
            return sessionId;
        }

        public void setExpirationTime(int expirationTime) {
            this.expirationTime = expirationTime;
        }

        public Map<String, Object> getData() {
            return data;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expirationTime;
        }
    }
}
```
