<?php
class AuthenticationService {
  private $userManagementApi;
  private $hashingAlgorithm;
  private $saltLength;

  public function __construct($userManagementApi, $hashingAlgorithm, $saltLength) {
    $this->userManagementApi = $userManagementApi;
    $this->hashingAlgorithm = $hashingAlgorithm;
    $this->saltLength = $saltLength;
  }

  public function generateSalt() {
    return password_hash($this->generateRandomString(), PASSWORD_BCRYPT);
  }

  private function generateRandomString($length = 16) {
    return substr(str_shuffle(str_repeat('0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', ceil($length / 62))), 0, $length);
  }

  public function hashPassword($password) {
    return password_hash($password, $this->hashingAlgorithm, ['salt' => $this->generateSalt()]);
  }

  public function verifyPassword($password, $hashedPassword) {
    return password_verify($password, $hashedPassword);
  }

  public function regenerateSaltsForExistingUsers() {
    // Update the salts for existing users in the user management system.
    $this->userManagementApi->updateUserSalts();
  }
}
```
