            _logger = logger;
        }

        public async Task<List<string>> GetWeaknessesAsync(int pokemonId)
        {
            try
            {
                var client = _httpClientFactory.CreateClient();
                var response = await client.GetAsync($"https://pokeapi.co/api/v2/pokemon/{pokemonId}/weaknesses");
                if (response.IsSuccessStatusCode)
                {
