            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to retrieve weaknesses for Pokemon ID {pokemonId}");
                return null;
            }
        }

        public async Task<List<string>> GetWeatherEffectsAsync(int pokemonId)
        {
            try
            {
                var client = _httpClientFactory.CreateClient();
                var response = await client.GetAsync($"https://pokeapi.co/api/v2/pokemon/{pokemonId}/weather-effects");
                if (response.IsSuccessStatusCode)
                {
