                    return weatherEffects;
                }
                else
                {
                    _logger.LogError($"Failed to retrieve weather effects for Pokemon ID {pokemonId}");
                    return null;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to retrieve weather effects for Pokemon ID {pokemonId}");
                return null;
            }
