                var client = _httpClientFactory.CreateClient();
                var response = await client.GetAsync($"https://pokeapi.co/api/v2/pokemon/{pokemonId}/terrain-effects");
                if (response.IsSuccessStatusCode)
                {
                    var content = await response.Content.ReadAsStringAsync();
                    var terrainEffects = JsonSerializer.Deserialize<List<string>>(content);
                    return terrainEffects;
                }
                else
                {
                    _logger.LogError($"Failed to retrieve terrain effects for Pokemon ID {pokemonId}");
                    return null;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to retrieve terrain effects for Pokemon ID {pokemonId}");
                return null;
            }
