        public async Task<string> ConstructHtmlStringAsync(int pokemonId)
        {
            var weaknesses = await GetWeaknessesAsync(pokemonId);
            var weatherEffects = await GetWeatherEffectsAsync(pokemonId);
            var terrainEffects = await GetTerrainEffectsAsync(pokemonId);

            if (weaknesses == null || weatherEffects == null || terrainEffects == null)
            {
                return null;
            }

            var document = new HtmlDocument();
            document.LoadHtml("<html><body>");
            var bodyNode = document.DocumentNode.SelectSingleNode("//body");

            var h1Node = document.CreateElement("h1");
            h1Node.InnerText = $"Weaknesses of Pokemon {pokemonId}";
            bodyNode.AppendChild(h1Node);

            foreach (var weakness in weaknesses)
            {
                var pNode = document.CreateElement("p");
                pNode.InnerText = $"- {weakness}";
                bodyNode.AppendChild(pNode);
            }

            h1Node = document.CreateElement("h1");
            h1Node.InnerText = $"Weather Effects of Pokemon {pokemonId}";
            bodyNode.AppendChild(h1Node);

            foreach (var weatherEffect in weatherEffects)
            {
                var pNode = document.CreateElement("p");
                pNode.InnerText = $"- {weatherEffect}";
                bodyNode.AppendChild(pNode);
            }

            h1Node = document.CreateElement("h1");
            h1Node.InnerText = $"Terrain Effects of Pokemon {pokemonId}";
            bodyNode.AppendChild(h1Node);

            foreach (var terrainEffect in terrainEffects)
            {
                var pNode = document.CreateElement("p");
                pNode.InnerText = $"- {terrainEffect}";
                bodyNode.AppendChild(pNode);
            }

            var htmlString = document.DocumentNode.OuterHtml;

            return htmlString;
        }
    }
}
```

### Explanation

* The `PokemonApi` class contains three methods: `GetWeaknesses`, `GetWeatherEffects`, and `GetTerrainEffects`. These methods use the `HttpClient` to make GET requests to the PokeAPI.
