        start_time = datetime.now()
        log_file = "database_management.log"
        with open(log_file, "a") as f:
            f.write("Started monitoring and managing databases at {}\n".format(start_time))

        for db_name in db_names:
            if not self._verify_schema_exists(db_name):
                return "Schema missing for {}".format(db_name)
            for operation in operations:
                self._perform_operation(db_name, operation)

        end_time = datetime.now()
        with open(log_file, "a") as f:
            f.write("Finished monitoring and managing databases at {}\n".format(end_time))

    def _verify_schema_exists(self, db_name: str):
        if self._get_database_schema(db_name) is None:
            return False
        return True

    def _perform_operation(self, db_name: str, operation: str):
        start_time = datetime.now()
        with open(log_file, "a") as f:
            f.write("Started {} for {} at {}\n".format(operation, db_name, start_time))

        if operation == "create":
            self._create_database(db_name)
        elif operation == "drop":
            self._drop_database(db_name)
        elif operation == "backup":
            self._backup_database(db_name)
        elif operation == "restore":
            self._restore_database(db_name)
        elif operation == "optimize":
            self._optimize_database(db_name)

        end_time = datetime.now()
