// define a struct to represent a transaction configuration
struct TransactionConfig {
    int id; // unique ID for the transaction
    int age; // age of the transaction (in seconds)
    int count; // number of transactions in the past 3 seconds
    double weightedSum; // weighted sum of all transactions
};

// define a struct to represent a factory function for creating transaction configurations
struct FactoryFunction {
    int id; // unique ID for the factory function
    void* (*func)(void); // pointer to the factory function
};

// define a struct to represent a registry of factory functions keyed by ID
struct FactoryFunctionRegistry {
    int num_factories; // number of factory functions in the registry
    struct FactoryFunction factories[10]; // array of factory functions
};

// define a struct to represent a thread-safe configuration registry
struct ConfigurationRegistry {
    pthread_mutex_t mutex; // mutex for synchronizing access to the registry
    int num_configs; // number of transaction configurations in the registry
    struct TransactionConfig configs[10]; // array of transaction configurations
};

// define a function to load and validate a configuration from an external service
void* load_and_validate_configuration(char* config_file) {
    // open the configuration file
    FILE* fp = fopen(config_file, "r");
    if (!fp) {
        printf("Error: unable to open configuration file\n");
        return NULL;
    }

    // parse the configuration from the file
    YAML::Node config = YAML::LoadFile(config_file);

    // validate the configuration against a schema
    if (!validate_configuration(config)) {
        printf("Error: invalid configuration\n");
        return NULL;
    }

    // allocate memory for the transaction configuration and populate it with data from the config
    struct TransactionConfig* conf = (struct TransactionConfig*) malloc(sizeof(struct TransactionConfig));
    conf->id = config["id"].as<int>();
    conf->age = config["age"].as<int>();
    conf->count = config["count"].as<int>();
    conf->weightedSum = config["weightedSum"].as<double>();

    // return the pointer to the configuration
    return (void*) conf;
}

// define a function to validate a configuration against a schema
bool validate_configuration(YAML::Node config) {
    // check that the configuration has the required fields
    if (!config.IsMap()) {
        printf("Error: invalid configuration\n");
        return false;
    }

    if (!config["id"].as<int>()) {
        printf("Error: invalid transaction ID\n");
        return false;
    }

    if (!config["age"].as<int>()) {
        printf("Error: invalid age\n");
        return false;
    }

    if (!config["count"].as<int>()) {
        printf("Error: invalid count\n");
        return false;
    }

    if (!config["weightedSum"].as<double>()) {
        printf("Error: invalid weighted sum\n");
        return false;
    }

    // check that the configuration is valid according to the schema
    // this would typically involve more complex validation rules

    // if all checks pass, return true
    return true;
}

// define a function to add a factory function to the registry
void add_factory_function(struct FactoryFunctionRegistry* registry, struct FactoryFunction func) {
    pthread_mutex_lock(&registry->mutex);

    // check that there is space in the registry for another factory function
    if (registry->num_factories == 10) {
        printf("Error: registry full\n");
        return;
    }

    // add the new factory function to the registry
    registry->factories[registry->num_factories] = func;
    registry->num_factories++;

    pthread_mutex_unlock(&registry->mutex);
}

// define a function to remove a factory function from the registry
void remove_factory_function(struct FactoryFunctionRegistry* registry, int id) {
    pthread_mutex_lock(&registry->mutex);

    // find the index of the factory function with the given ID in the registry
    int i = 0;
    for (; i < registry->num_factories; i++) {
        if (registry->factories[i].id == id) break;
    }

    // check that a matching factory function was found
    if (i == registry->num_factories) {
        printf("Error: no such factory function\n");
        return;
    }

    // remove the matching factory function from the registry
    for (int j = i; j < registry->num_factories - 1; j++) {
        registry->factories[j] = registry->factories[j + 1];
    }
    registry->num_factories--;

    pthread_mutex_unlock(&registry->mutex);
}

// define a function to retrieve a factory function from the registry by ID
struct FactoryFunction* get_factory_function(struct FactoryFunctionRegistry* registry, int id) {
    pthread_mutex_lock(&registry->mutex);

    // find the index of the factory function with the given ID in the registry
    int i = 0;
    for (; i < registry->num_factories; i++) {
        if (registry->factories[i].id == id) break;
    }

    // check that a matching factory function was found
    if (i == registry->num_factories) {
        printf("Error: no such factory function\n");
        return NULL;
    }

    // retrieve the matching factory function from the registry
    struct FactoryFunction* func = &registry->factories[i];

    pthread_mutex_unlock(&registry->mutex);

    return func;
}

// define a function to add a transaction configuration to the registry
void add_transaction_configuration(struct ConfigurationRegistry* registry, struct TransactionConfig conf) {
    pthread_mutex_lock(&registry->mutex);

    // check that there is space in the registry for another transaction configuration
    if (registry->num_configs == 10) {
        printf("Error: registry full\n");
        return;
    }

    // add the new transaction configuration to the registry
    registry->configurations[registry->num_configs] = conf;
    registry->num_configs++;

    pthread_mutex_unlock(&registry->mutex);
}

// define a function to remove a transaction configuration from the registry by ID
void remove_transaction_configuration(struct ConfigurationRegistry* registry, int id) {
    pthread_mutex_lock(&registry->mutex);

    // find the index of the transaction configuration with the given ID in the registry
    int i = 0;
    for (; i < registry->num_configs; i++) {
