    // remove the matching transaction configuration from the registry
    for (int j = i; j < registry->num_configs - 1; j++) {
        registry->configurations[j] = registry->configurations[j + 1];
    }
    registry->num_configs--;

    pthread_mutex_unlock(&registry->mutex);
}

// define a function to retrieve a transaction configuration from the registry by ID
struct TransactionConfig* get_transaction_configuration(struct ConfigurationRegistry* registry, int id) {
    pthread_mutex_lock(&registry->mutex);

    // find the index of the transaction configuration with the given ID in the registry
    int i = 0;
