    struct FactoryFunction* func = get_factory_function(registry, id);

    if (!func) return NULL;

    // create a new transaction configuration using the factory function
    struct TransactionConfig conf = *func.config;

    // randomize the configuration fields according to the factory function
    for (int i = 0; i < func.num_fields; i++) {
        if (func.field[i].type == "integer") {
            conf.field[i] = generate(func.field[i].min, func.field[i].max);
        } else if (func.field[i].type == "double") {
            conf.field[i] = generate(func.field[i].min, func.field[i].max);
        } else if (func.field[i].type == "string") {
            conf.field[i] = generate_string(func.field[i].length);
        }
    }

    // add the new transaction configuration to the registry
    add_transaction_configuration(registry, conf);

    return &conf;
}

// define a function to check if a transaction configuration is valid according to a factory function in the registry
bool is_valid(struct ConfigurationRegistry* registry, struct TransactionConfig* config) {
    // retrieve the factory function from the registry by ID
    struct FactoryFunction* func = get_factory_function(registry, config->id);

    if (!func) return false;

    // check that the configuration is valid according to the factory function
    for (int i = 0; i < func.num_fields; i++) {
        if (!in_range(config->field[i], func.field[i].min, func.field[i].max)) return false;
    }

    return true;
}
