// Cache layer for optimizing profile retrieval and updates
class CacheLayer {
    private $cache;

    public function __construct(CacheInterface $cache) {
        $this->cache = $cache;
    }

    // Check if user profile is cached, serve the cached version if available
    public function getCachedUserProfile($userID) {
        return $this->cache->get('user_profile_' . $userID);
    }

    // Fetch latest user profile from database and cache it
    public function fetchAndCacheLatestUserProfile($userID) {
        $userProfile = $this->database->fetchUserProfile($userID);
        $this->cache->set('user_profile_' . $userID, $userProfile);
        return $userProfile;
    }

    // Invalidate cache upon certain events, such as profile updates or account deletions
    public function invalidateCache($userID) {
        $this->cache->delete('user_profile_' . $userID);
    }
}

// Random string generation with customizable character set and secure hashing of passwords
class RandomStringGen {
    private $charset;

    public function __construct($charset) {
        $this->charset = $charset;
    }

    // Generate a random string with the specified length
    public function generateRandomString($length) {
        return substr(str_shuffle(str_repeat($this->charset, 10)), 0, $length);
    }

    // Securely hash a given password with a configurable number of rounds for enhanced security
    public function hashPassword($password, $rounds = 5000) {
        return password_hash($password, PASSWORD_DEFAULT, ['cost' => $rounds]);
    }
}

// User-friendly web interface for generating and validating random strings and hashed passwords
class WebInterface {
    private $randomStringGen;

    public function __construct(RandomStringGen $randomStringGen) {
        $this->randomStringGen = $randomStringGen;
    }

    // Generate a random string with the specified length
    public function generateRandomString($length, $charset) {
        return $this->randomStringGen->generateRandomString($length, $charset);
    }

    // Validate whether a given password meets the configured security requirements
    public function validatePassword($password, $rounds = 5000) {
        if (strlen($password) < 8) {
            return 'Password must be at least 8 characters long';
        }

        if (!preg_match('/[a-z]/', $password)) {
            return 'Password must contain at least one lowercase letter';
        }

        if (!preg_match('/[A-Z]/', $password)) {
            return 'Password must contain at least one uppercase letter';
        }

        if (!preg_match('/\d/', $password)) {
            return 'Password must contain at least one digit';
        }

        return true;
    }
}
