  int status;
  json_object *data;
};

// Function to fetch data from the API and parse the JSON response
struct api_response* fetch_api_data(const char *endpoint, const char *headers[], const char *parameters[]) {
  // Initialize a CURL handle for the API request
  CURL *curl = curl_easy_init();
  if (!curl) {
    return NULL;
  }

  // Set the URL and HTTP headers for the API request
  curl_easy_setopt(curl, CURLOPT_URL, endpoint);
  curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

  // Set the query parameters for the API request
  char *query = curl_easy_escape(curl, parameters[0], strlen(parameters[0]));
  curl_easy_setopt(curl, CURLOPT_URL, query);

  // Perform the API request and check for errors
  CURLcode res;
  struct api_response *response = malloc(sizeof(struct api_response));
  response->data = json_object_new();
  if ((res = curl_easy_perform(curl)) != CURLE_OK) {
    fprintf(stderr, "Failed to fetch API data: %s\n", curl_easy_strerror(res));
    free(response);
    return NULL;
  }

  // Check the HTTP status code for the response
  long http_code;
  curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
  if (http_code != 200) {
    fprintf(stderr, "API request failed with status code %ld\n", http_code);
    free(response->data);
    free(response);
    return NULL;
  }

  // Parse the JSON response data and check for errors
  json_object *json = json_tokener_parse(response->data);
  if (json == NULL) {
    fprintf(stderr, "Failed to parse API response\n");
    free(response->data);
    free(response);
    return NULL;
  }

  // Clean up and return the API response data
  curl_easy_cleanup(curl);
  json_object_put(json);
  return response;
}

