import java.util.Random;

public class NetworkLatencySimulator {
    private DistributionType distributionType = DistributionType.NORMAL;
    private double mean = 100.0;
    private double stddev = 50.0;
    private int rangeStart = 0;
    private int rangeEnd = 1000;
    private Cache cache = new Cache();

    public NetworkLatencySimulator(int rangeStart, int rangeEnd) {
        this.rangeStart = rangeStart;
        this.rangeEnd = rangeEnd;
    }

    public NetworkLatencySimulator(DistributionType distributionType, double mean, double stddev, int rangeStart, int rangeEnd) {
        this.distributionType = distributionType;
        this.mean = mean;
        this.stddev = stddev;
        this.rangeStart = rangeStart;
        this.rangeEnd = rangeEnd;
    }

    public int getRandomLatency() {
        switch (this.distributionType) {
            case NORMAL:
                return getNormalDistribution();
            case UNIFORM:
                return getUniformDistribution();
            case EXPONENTIAL:
                return getExponentialDistribution();
            default:
                throw new IllegalArgumentException("Invalid distribution type");
        }
    }

    private int getNormalDistribution() {
        Random random = new Random();
        double latency = random.nextGaussian() * stddev + mean;
        return (int) Math.round(latency);
    }

    private int getUniformDistribution() {
        Random random = new Random();
        double latency = random.nextDouble() * (rangeEnd - rangeStart) + rangeStart;
        return (int) Math.round(latency);
    }

    private int getExponentialDistribution() {
        Random random = new Random();
        double lambda = 1 / mean;
        double latency = -Math.log(random.nextDouble()) / lambda;
        return (int) Math.round(latency);
    }

    public void setDistributionType(DistributionType distributionType) {
        this.distributionType = distributionType;
    }

    public void setMean(double mean) {
        this.mean = mean;
    }

    public void setStddev(double stddev) {
        this.stddev = stddev;
    }

    @Override
    public String toString() {
        return "NetworkLatencySimulator [distributionType=" + distributionType + ", mean=" + mean + ", stddev=" + stddev + ", rangeStart=" + rangeStart + ", rangeEnd=" + rangeEnd + "]";
    }
}
