// Function to convert a JPEG file to a PDF file using a third-party tool
int convert_jpeg_to_pdf(const char* input_file, const char* output_dir, const char* metadata) {
    // Check if the input file exists and is a valid JPEG image
    if (access(input_file, F_OK) == -1) {
        printf("Error: Input file %s does not exist or is not a valid JPEG image.\n", input_file);
        return 1;
    }

    // Check if the output directory exists and is writable
    if (access(output_dir, F_OK) == -1 || access(output_dir, W_OK) == -1) {
        printf("Error: Output directory %s does not exist or is not writable.\n", output_dir);
        return 1;
    }

    // Parse the metadata and generate a PDF file with the provided information
    char* pdf_file = generate_pdf(input_file, output_dir, metadata);
    if (pdf_file == NULL) {
        printf("Error: Could not generate PDF file.\n");
        return 1;
    }

    // Clean up temporary files and resources used by the third-party tool
    cleanup(input_file, output_dir);

    return 0;
}

// Generate a PDF file with the provided metadata
char* generate_pdf(const char* input_file, const char* output_dir, const char* metadata) {
    // Create a temporary directory to store the JPEG image and generated PDF file
    char* tmp_dir = get_tmp_dir();
    if (tmp_dir == NULL) {
        printf("Error: Could not create temporary directory.\n");
        return NULL;
    }

    // Create a temporary file to store the JPEG image
    char* tmp_file = generate_filename(input_file, ".jpg", tmp_dir);
    if (tmp_file == NULL) {
        printf("Error: Could not create temporary file.\n");
        return NULL;
    }

    // Copy the JPEG image to the temporary file
    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open input file.\n");
        return NULL;
    }
    int rc = write(tmp_file, fd, 0, SEEK_SET);
    close(fd);
    if (rc < 0) {
        printf("Error: Could not copy JPEG image to temporary file.\n");
        return NULL;
    }

    // Generate the PDF file using a third-party tool
    char* pdf_file = generate_filename(input_file, ".pdf", output_dir);
    if (pdf_file == NULL) {
        printf("Error: Could not create PDF file.\n");
        return NULL;
    }
    rc = execute_command("third-party-tool", tmp_file, pdf_file, metadata);
    if (rc < 0) {
        printf("Error: Could not generate PDF file using third-party tool.\n");
        return NULL;
    }

    // Clean up temporary files and resources used by the third-party tool
    cleanup(tmp_file, tmp_dir);

    return pdf_file;
}

// Generate a filename with the provided extension in the specified directory
char* generate_filename(const char* file, const char* ext, const char* dir) {
    // Get the current time and date in a suitable format for the filename
    struct tm* timeinfo = localtime(&time);
    char* datetime = asctime(timeinfo);
    datetime[strlen(datetime) - 1] = '\0';

    // Generate the filename
    int len = strlen(file) + strlen(ext) + strlen(dir) + strlen(datetime) + 2;
    char* filename = (char*) malloc(len);
    sprintf(filename, "%s/%s_%s.%s", dir, file, datetime, ext);

    return filename;
}

// Execute the specified command and redirect its output to a file
int execute_command(const char* cmd, const char* input, const char* output, const char* metadata) {
    // Create a temporary file to store the third-party tool's output
    char* tmp_file = generate_filename(input, ".out", "");
    if (tmp_file == NULL) {
        printf("Error: Could not create temporary file for third-party tool output.\n");
        return -1;
    }

    // Execute the command and redirect its output to the temporary file
    int rc = system(cmd, input, tmp_file);
    if (rc < 0) {
        printf("Error: Could not execute third-party tool.\n");
        return -1;
    }

    // Read the contents of the temporary file and embed the metadata into the PDF file
    int fd = open(tmp_file, O_RDONLY);
    if (fd == -1) {
        printf("Error: Could not open third-party tool output file.\n");
        return -1;
    }
    char buffer[BUFSIZ];
    ssize_t bytes = read(fd, buffer, BUFSIZ);
    close(fd);
    if (bytes < 0) {
        printf("Error: Could not read third-party tool output file.\n");
        return -1;
    }
    buffer[bytes] = '\0';
    rc = embed_metadata(output, metadata, buffer);
    if (rc < 0) {
        printf("Error: Could not embed metadata into PDF file.\n");
        return -1;
    }

    // Clean up temporary files and resources used by the third-party tool
    cleanup(tmp_file);

    return rc;
}

// Embed the provided metadata into the specified PDF file
int embed_metadata(const char* pdf, const char* metadata, const char* buffer) {
    // Open the PDF file in append mode to embed the metadata
    int fd = open(pdf, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        printf("Error: Could not open PDF file.\n");
        return -1;
    }

    // Write the metadata to the end of the PDF file
    ssize_t bytes = write(fd, buffer, strlen(buffer));
    if (bytes < 0) {
        printf("Error: Could not write metadata to PDF file.\n");
        return -1;
    }

    // Close the PDF file and return successfully
    close(fd);
    return 0;
}

// Clean up temporary files and resources used by the third-party tool
void cleanup(const char* tmp_file, const char* tmp_dir) {
    // Remove the temporary directory and its contents
    remove(tmp_dir);

    // Remove the temporary file generated by the third-party tool
    remove(tmp_file);
}
