using namespace std;

int resizeImages(const string& inputDir, const string& jsonConfig, const string& outputDir) {
    Json::Value config = Json::parse(jsonConfig);
    int width = config["width"].asInt();
    vector<string> imageFiles = getImageFileNames(inputDir);
    int numSuccessfulConversions = 0;

    for (const string& file : imageFiles) {
        try {
            cv::Mat image = cv::imread(file, CV_LOAD_IMAGE_UNCHANGED);
            cv::resize(image, image, cv::Size(width, width), 0, 0, CV_INTER_CUBIC);
            string outputFile = outputDir + "/" + file.substr(file.find_last_of(".") + 1) + ".pdf";
            cv::imwrite(outputFile, image);
            numSuccessfulConversions++;
        } catch (const std::exception& e) {
            cerr << "Error resizing image: " << file << endl;
        }
    }

    return numSuccessfulConversions;
}
