Here is an example of how you could write a C# function that parses an XML document using XPath and returns the first element that matches a given name:
```
using System.Xml;
using System.Xml.XPath;

public static string GetFirstElement(string xml, string xpath)
{
    XmlDocument doc = new XmlDocument();
    doc.LoadXml(xml);

    XPathNavigator navigator = doc.CreateNavigator();
    XPathExpression expression = navigator.Compile(xpath);
    XPathNodeIterator iterator = navigator.Select(expression);

    if (iterator.Count == 0)
    {
        throw new Exception("No elements found matching the given XPath");
    }
    else if (iterator.Count > 1)
    {
        throw new Exception("Multiple elements found matching the given XPath");
    }
    else
    {
        return iterator.Current.Value;
    }
}
