Here is an example of how you could write a C function that takes a string and a size limit as input, and returns a new string with a slash appended to the end if the input string does not exceed the size limit, or returns `null` if it does:
```
#include <string.h>

char* addSlashIfNotExceedingLimit(const char* str, size_t limit)
{
    if (strlen(str) <= limit)
    {
        return NULL;
    }
    else
    {
        char* newStr = (char*) malloc(limit + 1);
        memcpy(newStr, str, limit - 1);
        newStr[limit - 1] = '/';
        newStr[limit] = '\0';
        return newStr;
    }
}
