    aes_encrypt = &aes_encrypt_ecb;
    aes_decrypt = &aes_decrypt_ecb;

    // Read input file, generate salt and IV, compute key, and perform PBKDF2 with user password and generated salt
    fp = fopen(argv[15], "r");
    if (fp == NULL) {
        printf("Error reading input file.\n");
        return EXIT_FAILURE;
    }

    while (!feof(fp)) {
        for (i = 0; i < BLOCKSIZE && !feof(fp); i++) {
            plaintext[i] = fgetc(fp);
        }

        // Generate random salt and IV
        generate_salt(salt, SALT_LENGTH);
        generate_iv(iv, IV_LENGTH);

        // Compute key using PBKDF2 with user password and generated salt
        compute_key(password, MAX_PASSWORD_LENGTH, salt, iter_count, output, PBKDF2_HASH_SIZE);

        // Perform AES encryption using computed key
        for (i = 0; i < BLOCKSIZE / 16; i++) {
            aes_encrypt(&plaintext[16 * i], &ciphertext[16 * i], output);
        }

        // Perform AES decryption using computed key
        for (i = 0; i < BLOCKSIZE / 16; i++) {
            aes_decrypt(&ciphertext[16 * i], &temp[16 * i], output);
        }
    }

    // Write decrypted plaintext to output file
    fp = fopen(argv[17], "w");
    if (fp == NULL) {
        printf("Error writing output file.\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < BLOCKSIZE && !feof(fp); i++) {
        fputc(temp[i], fp);
    }
