use std::time::Instant;
use std::sync::Arc;
use serde_json::Value;
use std::thread::{self, JoinHandle};
use std::error::Error;

struct CompressedImage {
    image: Vec<u8>,
    compression_algorithm: String,
}

impl CompressedImage {
    fn new(image: Vec<u8>, compression_algorithm: &str) -> Self {
        Self {
            image,
            compression_algorithm: compression_algorithm.to_string(),
        }
    }
}

struct QueryResult {
    results: Vec<serde_json::Value>,
    error: Option<String>,
}

impl QueryResult {
    fn new() -> Self {
        Self {
            results: vec![],
            error: None,
        }
    }
}

struct Service {
    connections: Vec<Arc<dyn Connection>>,
}

impl Service {
    fn new(connections: &[Arc<dyn Connection>]) -> Self {
        Self {
            connections: connections.to_vec(),
        }
    }

    fn process_image(&self, image: Vec<u8>, compression_algorithm: &str) -> QueryResult {
        let start = Instant::now();
        let compressed_image = CompressedImage::new(image, compression_algorithm);
        let mut results = vec![];
        for connection in &self.connections {
            match connection.execute_query(&compressed_image) {
                Ok(result) => {
                    results.push(result);
                }
                Err(err) => {
                    return QueryResult::new().with_error(format!("{}", err));
                }
            }
        }
        let end = Instant::now();
        println!(
            "Conversion and query execution took {} ms",
            (end - start).as_millis()
        );
        QueryResult { results, error: None }
    }
}

struct Connection {
    connection: Arc<dyn DatabaseConnection>,
}

impl Connection {
    fn new(connection: Arc<dyn DatabaseConnection>) -> Self {
        Self { connection }
    }

    fn execute_query(&self, compressed_image: &CompressedImage) -> Result<serde_json::Value, Box<dyn Error>> {
        let start = Instant::now();
        let query = self.connection.build_query(compressed_image)?;
        let results = self.connection.execute(query)?;
        let end = Instant::now();
        println!(
            "Query execution took {} ms",
            (end - start).as_millis()
        );
        Ok(results)
    }
}

struct DatabaseConnection {
    connection: Arc<dyn Database>,
}

impl DatabaseConnection {
    fn new(connection: Arc<dyn Database>) -> Self {
        Self { connection }
    }

    fn build_query(&self, compressed_image: &CompressedImage) -> Result<String, Box<dyn Error>> {
        let mut query = String::new();
        query += "SELECT * FROM images WHERE ";
        match compressed_image.compression_algorithm {
            "jpeg" => query += "compression = 'jpeg' AND ",
            "png" => query += "compression = 'png' AND ",
            "gif" => query += "compression = 'gif' AND ",
            _ => return Err(format!("Unsupported compression algorithm: {}", compressed_image.compression_algorithm).into()),
        };
        query += format!("width <= {} AND height <= {}", compressed_image.image.len());
        Ok(query)
    }

    fn execute(&self, query: String) -> Result<serde_json::Value, Box<dyn Error>> {
        let start = Instant::now();
        let results = self.connection.execute(query)?;
        let end = Instant::now();
        println!(
            "Query execution took {} ms",
            (end - start).as_millis()
        );
        Ok(results)
    }
}

struct Database {
    connection: Arc<dyn DatabaseConnection>,
}

impl Database {
    fn new(connection: Arc<dyn DatabaseConnection>) -> Self {
        Self { connection }
    }

    fn execute(&self, query: String) -> Result<serde_json::Value, Box<dyn Error>> {
        let start = Instant::now();
        let results = self.connection.execute(query)?;
        let end = Instant::now();
        println!(
            "Query execution took {} ms",
            (end - start).as_millis()
        );
        Ok(results)
    }
}

