// ClinicStatusUpdater.java
package com.example;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.apache.http.HttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ClinicStatusUpdater {
    private static final Logger LOGGER = LoggerFactory.getLogger(ClinicStatusUpdater.class);
    private static final int THROTTLE_LIMIT = 100;
    private static final int THROTTLE_WINDOW = 60; // minutes

    private CloseableHttpClient httpClient;
    private Connection dbConnection;
    private Map<String, String> clinicStatuses;
    private ScheduledExecutorService throttleExecutor;

    public ClinicStatusUpdater(CloseableHttpClient httpClient, Connection dbConnection) {
        this.httpClient = httpClient;
        this.dbConnection = dbConnection;
        this.clinicStatuses = new HashMap<>();
        this.throttleExecutor = Executors.newScheduledThreadPool(1);
    }

    public void updateClinicStatus(String clinicId, String newStatus, String lastModifiedIp, List<String> externalDataSources) {
        // Check if the clinic status has changed and if so, update it in the database
        if (!clinicStatuses.containsKey(clinicId) || !clinicStatuses.get(clinicId).equals(newStatus)) {
            try (PreparedStatement statement = dbConnection.prepareStatement("UPDATE clinics SET status = ? WHERE id = ?")) {
                statement.setString(1, newStatus);
                statement.setString(2, clinicId);
                statement.executeUpdate();
            } catch (SQLException e) {
                LOGGER.error("Failed to update clinic status", e);
            }
        }

        // Fetch and merge clinic statuses from external data sources
        for (String dataSource : externalDataSources) {
            HttpResponse response = null;
            try {
                response = httpClient.execute(new HttpGet("https://" + dataSource + "/clinics/" + clinicId));
                if (response.getStatusLine().getStatusCode() == 200) {
                    String status = new JSONObject(EntityUtils.toString(response.getEntity())).getString("status");
                    clinicStatuses.put(clinicId, status);
                } else {
                    LOGGER.warn("Failed to fetch clinic status from " + dataSource + ", response code: " + response.getStatusLine().getStatusCode());
                }
            } catch (IOException | JSONException e) {
                LOGGER.error("Failed to fetch clinic status from " + dataSource, e);
            } finally {
                if (response != null) {
                    try {
                        response.close();
                    } catch (IOException e) {
                        LOGGER.warn("Failed to close HTTP response", e);
                    }
                }
            }
        }

        // Implement distributed rate limiter
        throttleExecutor.schedule(() -> {
            int updatedClinics = 0;
            for (String clinicId : clinicStatuses.keySet()) {
                try (PreparedStatement statement = dbConnection.prepareStatement("UPDATE clinics SET status = ? WHERE id = ?")) {
                    String status = clinicStatuses.get(clinicId);
                    statement.setString(1, status);
                    statement.setString(2, clinicId);
                    updatedClinics += statement.executeUpdate();
                } catch (SQLException e) {
                    LOGGER.error("Failed to update clinic status", e);
                }
            }
            LOGGER.info("Updated " + updatedClinics + " clinic(s) in the distributed rate limiter");
        }, 1, TimeUnit.MINUTES);
    }
}
```
Note: This is just an example and may need to be modified based on specific requirements. Also, this code uses external libraries (e.g., `org.apache.httpcomponents`) which are not included in the snippet above.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>
#include <math.h>
#include "image_conversion_library.h"

// define the structure for storing image information
struct image_info {
    char *file_path;
    int width;
    int height;
};

// define the structure for storing conversion result
struct conversion_result {
    int status;
    char *message;
};

// define the structure for storing worker thread information
struct worker_thread_info {
    pthread_t thread;
    struct image_info *image_info;
    struct conversion_result *conversion_result;
};

// define the structure for storing conversion context
struct conversion_context {
    char *input_dir;
    char *output_dir;
    int max_images_per_pdf;
    int num_threads;
    int total_files;
    int processed_files;
    pthread_mutex_t lock;
};

// define the function prototype for worker thread entry point
void *worker_thread(void *arg);

int main(int argc, char **argv) {
    // validate command-line arguments
    if (argc < 4) {
        printf("Usage: %s [input directory] [output directory] [max images per PDF]\n", argv[0]);
        return -1;
    }

    // initialize conversion context
    struct conversion_context *conversion_context = malloc(sizeof(struct conversion_context));
    conversion_context->input_dir = argv[1];
    conversion_context->output_dir = argv[2];
    conversion_context->max_images_per_pdf = atoi(argv[3]);
    conversion_context->num_threads = 0;
    conversion_context->total_files = 0;
    conversion_context->processed_files = 0;
    pthread_mutex_init(&conversion_context->lock, NULL);

    // get the total number of files in the input directory
    struct dirent *entry;
    DIR *dir = opendir(conversion_context->input_dir);
    if (dir == NULL) {
        printf("Error: Failed to open input directory %s\n", conversion_context->input_dir);
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        struct stat st;
        if (stat(entry->d_name, &st) == 0 && S_ISREG(st.st_mode)) {
            conversion_context->total_files++;
        }
    }
    closedir(dir);

    // initialize worker thread information
    struct worker_thread_info *worker_threads = malloc(sizeof(struct worker_thread_info) * conversion_context->num_threads);
    for (int i = 0; i < conversion_context->num_threads; i++) {
        worker_threads[i].image_info = NULL;
        worker_threads[i].conversion_result = malloc(sizeof(struct conversion_result));
        pthread_create(&worker_threads[i].thread, NULL, &worker_thread, (void *)&worker_threads[i]);
    }

    // wait for all worker threads to finish
    for (int i = 0; i < conversion_context->num_threads; i++) {
        pthread_join(worker_threads[i].thread, NULL);
    }

    // free memory
    free(conversion_context);
    for (int i = 0; i < conversion_context->num_threads; i++) {
        free(worker_threads[i].conversion_result);
    }
    free(worker_threads);

    return 0;
}

void *worker_thread(void *arg) {
    struct worker_thread_info *worker_thread = (struct worker_thread_info *)arg;
    while (1) {
        pthread_mutex_lock(&conversion_context->lock);
        if (conversion_context->processed_files >= conversion_context->total_files) {
            break;
        }
        int index = conversion_context->processed_files % conversion_context->num_threads;
        worker_thread[index].image_info = malloc(sizeof(struct image_info));
        strcpy(worker_thread[index].image_info->file_path, conversion_context->input_dir);
        conversion_context->processed_files++;
        pthread_mutex_unlock(&conversion_context->lock);

        // perform image conversion
        int status = image_convert(worker_thread[index].image_info->file_path, worker_thread[index].conversion_result);

        if (status == 0) {
            printf("Image %s converted successfully\n", worker_thread[index].image_info->file_path);
        } else {
            printf("Error: Failed to convert image %s\n", worker_thread[index].image_info->file_path);
        }
    }
}

// define the function for converting an image file to a PDF file
int image_convert(char *file_path, struct conversion_result *conversion_result) {
    // validate input parameters
    if (file_path == NULL || conversion_result == NULL) {
        return -1;
    }

    // open the input file
    FILE *input_file = fopen(file_path, "rb");
    if (input_file == NULL) {
        printf("Error: Failed to open input file %s\n", file_path);
        return -1;
    }

    // read the image data from the input file
    char *image_data = malloc(sizeof(char) * 1024 * 1024);
    size_t num_read = fread(image_data, sizeof(char), 1024 * 1024, input_file);
    if (num_read == 0) {
        printf("Error: Failed to read image data from file %s\n", file_path);
        return -1;
    }

    // close the input file
    fclose(input_file);

    // convert the image data to PDF format
    struct pdf *pdf = pdf_create();
    if (pdf == NULL) {
        printf("Error: Failed to create PDF document\n");
        return -1;
    }

    int status = pdf_add_image(pdf, image_data, num_read);
    if (status != 0) {
        printf("Error: Failed to add image data to PDF document\n");
        return -1;
    }

    // write the PDF file to disk
    char *output_file_path = malloc(strlen(conversion_context->output_dir) + strlen(file_path) + 2);
    sprintf(output_file_path, "%s/%s.pdf", conversion_context->output_dir, file_path);
    FILE *output_file = fopen(output_file_path, "wb");
    if (output_file == NULL) {
        printf("Error: Failed to open output file %s\n", output_file_path);
        return -1;
    }

    size_t num_written = fwrite(pdf->data, sizeof(char), pdf->size, output_file);
    if (num_written != pdf->size) {
        printf("Error: Failed to write PDF data to file %s\n", output_file_path);
        return -1;
    }

    // close the output file
    fclose(output_file);

    // free memory
    free(image_data);
    free(output_file_path);

    pdf_destroy(pdf);

    return 0;
}

