// Custom min-max algorithm for finding the smallest and largest values in a dataset
struct MinMax {
  double min, max;
};

MinMax find_min_max(const std::vector<double>& data) {
  MinMax result;
  result.min = data[0];
  result.max = data[0];
  for (size_t i = 1; i < data.size(); ++i) {
    if (data[i] < result.min) {
      result.min = data[i];
    } else if (data[i] > result.max) {
      result.max = data[i];
    }
  }
  return result;
}

// Function to read real-time sensor data from a custom file format
std::vector<double> read_sensor_data(const std::string& filename) {
  // Open the file and check for errors
  std::ifstream file(filename);
  if (!file.is_open()) {
    throw std::runtime_error("File not found: " + filename);
  }

  // Read the data from the file and store it in a vector
  std::vector<double> data;
  double value;
  while (file >> value) {
    data.push_back(value);
  }

  // Check for errors in the data format
  if (data.empty()) {
    throw std::runtime_error("Invalid data format: " + filename);
  }

  return data;
}

// Function to process the sensor data and find the smallest and largest values
std::vector<double> process_sensor_data(const std::string& filename) {
  // Read the sensor data from the file
  std::vector<double> data = read_sensor_data(filename);

  // Find the smallest and largest values in the dataset
  MinMax min_max = find_min_max(data);

  return { min_max.min, min_max.max };
}

// Function to write the processed data to another file
void write_processed_data(const std::vector<double>& data, const std::string& filename) {
  // Open the output file and check for errors
  std::ofstream file(filename);
  if (!file.is_open()) {
    throw std::runtime_error("File not found: " + filename);
  }

  // Write the data to the output file
  for (const auto& value : data) {
    file << value << "\n";
  }
}

// Function to log the processing steps and any errors encountered
void log_processing(const std::string& filename, const std::vector<double>& data) {
  // Open the log file and check for errors
  std::ofstream log_file("log.txt", std::ios_base::app);
  if (!log_file.is_open()) {
    throw std::runtime_error("Failed to open log file");
  }

  // Log the processing steps and any errors encountered
  log_file << "Processing started: " << filename << "\n";
  for (const auto& value : data) {
    if (!(std::isfinite(value))) {
      log_file << "Error: Non-finite value detected: " << value << "\n";
    }
  }
  log_file << "Processing completed: " << filename << "\n\n";
}

// Function to monitor the program's health and data ingestion rates
void monitor_health() {
  // Check for errors in the sensor data files
  std::vector<std::string> error_files;
  for (const auto& filename : filenames) {
    try {
      read_sensor_data(filename);
    } catch (const std::runtime_error& e) {
      error_files.push_back(filename);
    }
  }

  // Log the errors encountered and display a warning message
  if (!error_files.empty()) {
    log_processing("Error: Failed to read sensor data from files: " + error_files[0]);
    std::cout << "Warning: Some sensor data files could not be read due to errors." << std::endl;
  }
}

// Function to validate the program's performance and scalability under varying network conditions
void test_performance() {
  // Test the program's performance on different datasets with varying sizes
  for (const auto& filename : filenames) {
    std::vector<double> data = read_sensor_data(filename);
    MinMax min_max = find_min_max(data);
    write_processed_data({ min_max.min, min_max.max }, "output.txt");
  }
}

int main() {
  // Read the sensor data files from a directory and store them in a vector
  std::vector<std::string> filenames = { "sensor1.txt", "sensor2.txt", "sensor3.txt" };
  std::vector<double> data;
  for (const auto& filename : filenames) {
    data.push_back(read_sensor_data(filename));
  }

  // Process the sensor data and find the smallest and largest values
  MinMax min_max = find_min_max(data);

  // Write the processed data to another file
  write_processed_data({ min_max.min, min_max.max }, "output.txt");

  // Log the processing steps and any errors encountered
  log_processing("sensor1.txt", data);
  log_processing("sensor2.txt", data);
  log_processing("sensor3.txt", data);

  // Monitor the program's health and data ingestion rates
  monitor_health();

  // Validate the program's performance and scalability under varying network conditions
  test_performance();

  return 0;
}
