nfapi_cr_indication_pdu_t* create_crc_indication_list(int listSize, db_connection_t* dbConnections, logging_options_t* loggingOptions) {
    // Check for valid input parameters
    if (listSize <= 0 || listSize > MAX_LIST_SIZE) {
        fprintf(stderr, "Invalid list size provided: %d\n", listSize);
        return NULL;
    }
    if (dbConnections == NULL || dbConnections->hostname == NULL) {
        fprintf(stderr, "Invalid database connection details provided\n");
        return NULL;
    }

    // Initialize list of NFAPI_CRC_INDICATION_PDU_T structures
    nfapi_cr_indication_pdu_t* crcIndList = malloc(sizeof(nfapi_cr_indication_pdu_t) * listSize);
    if (crcIndList == NULL) {
        fprintf(stderr, "Failed to allocate memory for CR indication list\n");
        return NULL;
    }

    // Initialize thread-safe queues for managing database operations
    pthread_mutex_t dbQueueMutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t dbQueueCond = PTHREAD_COND_INITIALIZER;
    pthread_t* dbQueues = malloc(sizeof(pthread_t) * MAX_DB_CONNECTIONS);
    if (dbQueues == NULL) {
        fprintf(stderr, "Failed to allocate memory for database queues\n");
        free(crcIndList);
        return NULL;
    }

    // Initialize logging mechanism
    FILE* logFile = NULL;
    if (loggingOptions->enableLogging) {
        logFile = fopen("cr_indication_list.log", "w");
        if (logFile == NULL) {
            fprintf(stderr, "Failed to open log file for writing\n");
        } else {
            setvbuf(logFile, NULL, _IONBF, 0); // Disable buffering for log file
        }
    }

    // Initialize error handling variables
    bool hasError = false;
    int dbConnectionIndex = 0;
    int retryAttempts = 0;

    // Iterate over the list of NFAPI_CRC_INDICATION_PDU_T structures, fetching RX_UE_INFORMATION_TAG and RNTI values from external databases
    for (int i = 0; i < listSize; i++) {
        nfapi_cr_indication_pdu_t* crcInd = &crcIndList[i];

        // Fetch RX_UE_INFORMATION_TAG and RNTI values from database
        db_connection_t* dbConnection = &dbConnections[dbConnectionIndex];
        if (retryAttempts >= MAX_RETRY_ATTEMPTS) {
            // If we have reached the maximum retry attempts, set an error flag and break out of the loop
            hasError = true;
            break;
        } else {
            // Attempt to fetch RX_UE_INFORMATION_TAG and RNTI values from database
            int result = fetch_rx_ue_information_tag(dbConnection, &crcInd->rxUeInformationTag);
            if (result != 0) {
                retryAttempts++;
                continue;
            } else {
                // If successful, attempt to fetch RNTI value from database
                result = fetch_rnti(dbConnection, &crcInd->rnti);
                if (result != 0) {
                    retryAttempts++;
                    continue;
                } else {
                    // If successful, validate CRCFLAG value and handle invalid RX_UE_INFORMATION_TAG or RNTI values
                    if (crcInd->rxUeInformationTag < 0 || crcInd->rnti < 0) {
                        hasError = true;
                        break;
                    } else {
                        // If all checks pass, set CRCFLAG value and continue to next iteration
                        crcInd->crcFlag = 1;
                    }
                }
            }
        }
    }

    if (hasError) {
        // If an error has occurred, free memory and return NULL
        free(crcIndList);
        free(dbQueues);
        if (logFile != NULL) fclose(logFile);
        return NULL;
    } else {
        // If no errors have occurred, compress the list of populated structures before returning to caller
        nfapi_cr_indication_pdu_t* compressedCrcIndList = malloc(sizeof(nfapi_cr_indication_pdu_t) * (listSize - i));
        if (compressedCrcIndList == NULL) {
            fprintf(stderr, "Failed to allocate memory for compressed CR indication list\n");
            free(crcIndList);
            free(dbQueues);
            if (logFile != NULL) fclose(logFile);
            return NULL;
        }
        memcpy(compressedCrcIndList, &crcIndList[i], sizeof(nfapi_cr_indication_pdu_t) * (listSize - i));
        free(crcIndList);
        crcIndList = compressedCrcIndList;
    }

    // Logging mechanism
    if (logFile != NULL) {
        fprintf(logFile, "CR Indication List Created: %d entries\n", listSize);
        for (int i = 0; i < listSize; i++) {
            nfapi_cr_indication_pdu_t* crcInd = &crcIndList[i];
            fprintf(logFile, "Entry %d: RX UE Information Tag = %d, RNTI = %d\n", i + 1, crcInd->rxUeInformationTag, crcInd->rnti);
        }
    }

    return crcIndList;
}

