import java.util.concurrent.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.client.RestTemplate;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.cache.annotation.EnableCaching;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.model.FindOneAndReplaceOptions;
import com.mongodb.client.model.ReturnDocument;
import java.util.*;
import org.springframework.http.HttpStatus;

@Service
@EnableCaching
public class PokemonService {
    @Autowired
    private RestTemplate restTemplate;

    @Autowired
    private MongoClient mongoClient;

    @GetMapping("/pokemon")
    public ResponseEntity<String> getPokemon(@RequestParam(value = "id") Long id) {
        try {
            // Check if the Pokemon ID exists in the database
            FindOneAndReplaceOptions options = new FindOneAndReplaceOptions().returnDocument(ReturnDocument.AFTER);
            Document pokemonDoc = mongoClient.getDatabase("pokemondb").getCollection("pokemon").findOneAndUpdate(new Document("id", id), new Document(), options);
            if (pokemonDoc == null) {
                // If the Pokemon ID does not exist in the database, retrieve it from the external API and cache it
                Document pokemon = restTemplate.getForObject("https://pokeapi.co/api/v2/pokemon/" + id, Document.class);
                pokemonDoc = new Document("id", pokemon.getInteger("id")).append("name", pokemon.getString("name")).append("types", pokemon.getArray("types"));
                mongoClient.getDatabase("pokemondb").getCollection("pokemon").insertOne(pokemonDoc);
            }

            // Retrieve the Pokemon's habitat information from an external API (if available)
            Document habitat = null;
            try {
                habitat = restTemplate.getForObject("https://habitatapi.com/api/v1/pokemons/" + id, Document.class);
            } catch (Exception e) {} // Ignore errors from the external API

            // Build the JSON response with the Pokemon's details and habitat information (if available)
            String json = new ObjectMapper().writeValueAsString(new Document("id", pokemonDoc.getInteger("id")).append("name", pokemonDoc.getString("name")).append("types", pokemonDoc.getArray("types")));
            if (habitat != null) {
                json = json + new ObjectMapper().writeValueAsString(new Document("habitat", habitat));
            }

            return ResponseEntity.ok(json);
        } catch (Exception e) {
            // Handle errors and provide meaningful error messages to the user
            if (e instanceof HttpClientErrorException) {
                return ResponseEntity.status(((HttpClientErrorException) e).getStatusCode()).body("{\"error\": \"Invalid Pokemon ID\"}");
            } else {
                return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("{\"error\": \"Internal server error\"}");
            }
        }
    }
}
```
