using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public static class Hasher
{
    public static async Task<bool> ComputeAndVerifyHashAsync(string filePathOrUrl, int minFileSize = 0, int maxFileSize = int.MaxValue, DateTime? minLastModifiedDate = null, DateTime? maxLastModifiedDate = null)
    {
        try
        {
            using var httpClient = new HttpClient();
            using var stream = await GetStreamFromUrlAsync(filePathOrUrl);
            if (stream == null) return false;

            // Read the file in chunks to handle large files efficiently
            const int bufferSize = 4096;
            byte[] buffer = new byte[bufferSize];
            using var sha256Hasher = SHA256.Create();
            long totalBytesRead = 0;
            while (true)
            {
                // Check if the file size is within the specified range
                if (totalBytesRead < minFileSize || totalBytesRead > maxFileSize) break;

                // Check if the last modified date is within the specified range
                DateTime? lastModifiedDate = null;
                if (minLastModifiedDate.HasValue && stream.CanSeek)
                {
                    lastModifiedDate = new DateTime(stream.Position, DateTimeKind.Utc);
                }
                if (lastModifiedDate.HasValue && lastModifiedDate < minLastModifiedDate || lastModifiedDate > maxLastModifiedDate) break;

                // Hash the chunk
                int bytesRead = await stream.ReadAsync(buffer, 0, bufferSize);
                sha256Hasher.TransformBlock(buffer, 0, bytesRead, null, 0);

                // Update the progress
                totalBytesRead += bytesRead;
            }

            // Verify the hash against an external API
            string hash = BitConverter.ToString(sha256Hasher.Hash).Replace("-", "");
            bool isVerified = await VerifyHashAsync(hash);
            if (!isVerified) return false;

            // Cache the verified hash for future use
            await CacheHashAsync(hash);
            return true;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error occurred while computing and verifying hash: {ex.Message}");
            return false;
        }
    }

    private static async Task<Stream> GetStreamFromUrlAsync(string url)
    {
        // Handle SFTP/FTP URLs by creating an SSH client to connect to the server
        if (url.StartsWith("ftp://") || url.StartsWith("ftps://"))
        {
            using var sshClient = new SshClient(new Uri(url));
            await sshClient.ConnectAsync();
            return sshClient.CreateShellStream("bash", 0, 0, 0, 0);
        }

        // Handle HTTP/HTTPS URLs by making an HTTP request to download the file
        else if (url.StartsWith("http://") || url.StartsWith("https://"))
        {
            using var httpClient = new HttpClient();
            return await httpClient.GetStreamAsync(new Uri(url));
        }

        // Handle local file paths by reading the file directly
        else if (File.Exists(url))
        {
            return File.OpenRead(url);
        }

        // Return null for any other URL type
        return null;
    }

    private static async Task<bool> VerifyHashAsync(string hash)
    {
