use tokio::runtime::Runtime;
use std::collections::HashMap;
use std::error::Error;

struct MergeSortedStreams {
    streams: Vec<(Box<dyn Iterator>, Box<dyn Fn(&T) -> bool>)>,
}

impl MergeSortedStreams {
    fn new() -> Self {
        MergeSortedStreams {
            streams: Vec::new(),
        }
    }

    fn add_stream(&mut self, stream: Box<dyn Iterator>, sorting_key: Box<dyn Fn(&T) -> bool>) {
        self.streams.push((stream, sorting_key));
    }

    fn merge(&self) -> Result<Vec<T>, Box<dyn Error>> {
        let mut merged_stream = Vec::new();

        for (stream, sorting_key) in &self.streams {
            for item in stream {
                if !merged_stream.contains(item) && sorting_key(item) {
                    merged_stream.push(item);
                }
            }
        }

        Ok(merged_stream)
    }
}

struct ApiClient {
    api_url: String,
    client: reqwest::blocking::Client,
    cache: HashMap<String, Vec<T>>,
}

impl ApiClient {
    fn new() -> Self {
        ApiClient {
            api_url: "https://example.com/api".to_string(),
            client: reqwest::blocking::Client::new(),
            cache: HashMap::new(),
        }
    }

    fn get(&mut self, endpoint: &str) -> Result<Vec<T>, Box<dyn Error>> {
        if let Some(cache) = self.cache.get(endpoint) {
            return Ok(cache.clone());
        }

        let response = self.client.get(self.api_url.clone() + endpoint).send()?;
        let data: Vec<T> = response.json()?;

        self.cache.insert(endpoint.to_string(), data.clone());
        Ok(data)
    }
}

struct System {
