        let data = self.api_client.get(endpoint)?;
        self.merge_sorted_streams.add_stream(Box::new(data.into_iter()), Box::new(|item| item.id == 0));
        Ok(())
    }

    fn process_data(&mut self) -> Result<Vec<T>, Box<dyn Error>> {
        let data = self.merge_sorted_streams.merge()?;
        // TODO: Process the data and return the result.
        Ok(data)
    }
}

fn main() {
    let mut system = System::new();
    let endpoints = vec!["/api/endpoint1", "/api/endpoint2"];

    for endpoint in endpoints {
        system.fetch_data(endpoint)?;
    }

    let data = system.process_data()?;
    println!("{:?}", data);
}
