class DepartmentResource(Resource):
    @cache.memoize(timeout=3600)
    def get(self, department_id):
        session = Session()
        department = session.query(Department).filter_by(id=department_id).one_or_none()
        if not department:
            return make_response('Department not found', 404)
        response = jsonify({'department': department})
        response.headers['Content-Type'] = 'application/json'
        return response

    @cache.memoize(timeout=3600)
    def put(self, department_id):
        session = Session()
        department = session.query(Department).filter_by(id=department_id).one_or_none()
        if not department:
            return make_response('Department not found', 404)
        data = request.get_json()
        if 'name' in data and 'description' in data:
            department.name = data['name']
            department.description = data['description']
            try:
                session.commit()
                return make_response('Department updated', 200)
            except IntegrityError as e:
                return make_response(f'Failed to update department: {e}', 400)
        else:
            return make_response('Invalid data provided', 400)

    @cache.memoize(timeout=3600)
    def delete(self, department_id):
        session = Session()
        department = session.query(Department).filter_by(id=department_id).one_or_none()
        if not department:
            return make_response('Department not found', 404)
        try:
            session.delete(department)
            session.commit()
            return make_response('Department deleted', 200)
        except IntegrityError as e:
            return make_response(f'Failed to delete department: {e}', 400)

