import java.util.*;
import javax.ws.rs.core.Response;

public class AuthAPI {
    private static final int MAX_ATTEMPTS = 3;
    private static final long MINUTES_PER_ATTEMPT = 1L; // in minutes

    private UserService userService;
    private RoleService roleService;
    private PermissionService permissionService;
    private NotificationService notificationService;
    private RateLimiter rateLimiter;

    public AuthAPI(UserService userService, RoleService roleService, PermissionService permissionService, NotificationService notificationService) {
        this.userService = userService;
        this.roleService = roleService;
        this.permissionService = permissionService;
        this.notificationService = notificationService;
    }

    public Response registerUser(String username, String password, String email) {
        if (username == null || password == null || email == null) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = new User(username, password, email);
            boolean success = userService.registerUser(user);
            if (success) {
                return Response.ok().entity("User registered successfully").build();
            } else {
                return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Failed to register user").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while registering user: " + e.getMessage()).build();
        }
    }

    public Response loginUser(String username, String password) {
        if (username == null || password == null) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = userService.getUserByUsername(username);
            if (user != null && user.verifyPassword(password)) {
                String token = generateTokenForUser(user);
                return Response.ok().entity("User logged in successfully").build();
            } else {
                return Response.status(Response.Status.UNAUTHORIZED).entity("Invalid username or password").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while logging in user: " + e.getMessage()).build();
        }
    }

    public Response getUserRolesAndPermissions(String token) {
        if (token == null || token.isEmpty()) {
            return Response.status(Response.Status.UNAUTHORIZED).entity("Invalid token").build();
        }
        try {
            User user = userService.getUserByToken(token);
            if (user != null) {
                List<Role> roles = roleService.getRolesForUser(user);
                List<Permission> permissions = permissionService.getPermissionsForUser(user);
                return Response.ok().entity("User roles and permissions retrieved successfully").build();
            } else {
                return Response.status(Response.Status.UNAUTHORIZED).entity("Invalid token").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while retrieving user roles and permissions: " + e.getMessage()).build();
        }
    }

    public Response getUserInfo(String token) {
        if (token == null || token.isEmpty()) {
            return Response.status(Response.Status.UNAUTHORIZED).entity("Invalid token").build();
        }
        try {
            User user = userService.getUserByToken(token);
            if (user != null) {
                Map<String, Object> userInfo = new HashMap<>();
                userInfo.put("username", user.getUsername());
                userInfo.put("email", user.getEmail());
                return Response.ok().entity(userInfo).build();
            } else {
                return Response.status(Response.Status.UNAUTHORIZED).entity("Invalid token").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while retrieving user info: " + e.getMessage()).build();
        }
    }

    public Response sendVerificationCode(String username, String email) {
        if (username == null || username.isEmpty() || email == null || email.isEmpty()) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = userService.getUserByUsername(username);
            if (user != null) {
                notificationService.sendVerificationCode(user, email);
                return Response.ok().entity("Verification code sent successfully").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("User not found").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while sending verification code: " + e.getMessage()).build();
        }
    }

    public Response verifyUser(String username, String email, String code) {
        if (username == null || username.isEmpty() || email == null || email.isEmpty() || code == null || code.isEmpty()) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = userService.getUserByUsername(username);
            if (user != null && user.getEmail().equalsIgnoreCase(email)) {
                notificationService.verifyCode(user, code);
                return Response.ok().entity("User verified successfully").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("User not found").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while verifying user: " + e.getMessage()).build();
        }
    }

    public Response recoverPassword(String username, String email) {
        if (username == null || username.isEmpty() || email == null || email.isEmpty()) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = userService.getUserByUsername(username);
            if (user != null && user.getEmail().equalsIgnoreCase(email)) {
                String passwordResetToken = generatePasswordResetToken(user);
                notificationService.sendPasswordResetCode(user, email, passwordResetToken);
                return Response.ok().entity("Password reset code sent successfully").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("User not found").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while recovering password: " + e.getMessage()).build();
        }
    }

    public Response resetPassword(String username, String email, String code, String newPassword) {
        if (username == null || username.isEmpty() || email == null || email.isEmpty() || code == null || code.isEmpty() || newPassword == null || newPassword.isEmpty()) {
            return Response.status(Response.Status.BAD_REQUEST).entity("Invalid input parameters").build();
        }
        try {
            User user = userService.getUserByUsername(username);
            if (user != null && user.getEmail().equalsIgnoreCase(email)) {
                notificationService.verifyPasswordResetCode(user, code);
                userService.updatePassword(user, newPassword);
                return Response.ok().entity("Password reset successfully").build();
            } else {
                return Response.status(Response.Status.NOT_FOUND).entity("User not found").build();
            }
        } catch (Exception e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error while resetting password: " + e.getMessage()).build();
        }
    }

    private String generatePasswordResetToken(User user) {
        // generate a random token and send it to the user's email address
        return "";
    }
