        InputStream inputStream = s3Client.getObjectContent(s3Object);
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8));

        // Initialize regex pattern for keywords and list of matching lines
        Pattern pattern = Pattern.compile("error|warning");
        List<String> matchedLines = new ArrayList<>();

        // Iterate over file lines and match against keyword patterns
        String line;
        while ((line = reader.readLine()) != null) {
            Matcher matcher = pattern.matcher(line);
            if (matcher.find()) {
                matchedLines.add(line);
            }
        }

        // Generate summary report based on file content and reporting API integration
        String report;
        if (!matchedLines.isEmpty()) {
            List<String> csvRows = new ArrayList<>();
            for (String line : matchedLines) {
                csvRows.add(line);
            }
            report = String.format(CSV_TEMPLATE, String.join("\n", csvRows));
        } else {
            report = "{\"files\": []}";
        }

        // Upload summary report to reporting API
        try {
            uploadReport(report);
        } catch (IOException e) {
            logger.warn("Failed to upload report", e);
        }
