<?php

class AuthenticationService {
    private $apiClient;
    private $config;

    public function __construct(ApiClient $apiClient, array $config = []) {
        $this->apiClient = $apiClient;
        $this->config = $config;
    }

    public function generateSalt(): string {
        return password_hash($this->generateRandomString(), PASSWORD_BCRYPT);
    }

    private function generateRandomString(int $length = 16): string {
        $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characters[rand(0, strlen($characters) - 1)];
        }

        return $randomString;
    }

    public function hashPassword(string $password): string {
        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function authenticateUser(string $username, string $password): bool {
        // Check if the user exists in the external user management system
        $user = $this->apiClient->getUserByUsername($username);

        if (!$user) {
            return false;
        }

        // Check if the password is correct
        return password_verify($password, $user['password']);
    }

    public function registerNewUser(string $username, string $password): bool {
        // Generate a salt for the user's password
        $salt = $this->generateSalt();

        // Hash the password with the salt and BCRYPT algorithm
        $hashedPassword = $this->hashPassword($password);

        // Create a new user in the external user management system
        $user = [
            'username' => $username,
            'password' => $salt . '$' . $hashedPassword,
        ];

        return $this->apiClient->createUser($user);
    }

    public function regenerateSalt(string $username): bool {
        // Get the user from the external user management system
        $user = $this->apiClient->getUserByUsername($username);

        if (!$user) {
            return false;
        }

        // Generate a new salt for the user's password
        $newSalt = $this->generateSalt();

        // Update the user's password in the external user management system with the new salt
        $updatedUser = [
            'username' => $user['username'],
            'password' => $newSalt . '$' . $user['password'],
        ];

        return $this->apiClient->updateUser($updatedUser);
    }

    public function logAuthenticationAttempt(string $username, string $ipAddress): void {
        // Log the authentication attempt in a database or file
        $log = [
            'username' => $username,
            'ip_address' => $ipAddress,
            'timestamp' => time(),
        ];

        $this->apiClient->createAuthenticationAttempt($log);
    }

    public function notifySuspiciousActivity(string $username, string $ipAddress): void {
        // Notify the user or administrator of suspicious activity, such as failed login attempts from multiple locations within a short period
        $message = "User '$username' has had multiple failed login attempts from IP address '$ipAddress' within a short period.";

        $this->apiClient->notify($message);
    }

    public function getCurrentTimeZoneOffset(string $username): int {
        // Get the user's time zone offset from the external user management system
        $user = $this->apiClient->getUserByUsername($username);

        if (!$user) {
            return 0;
        }

        // Convert the user's time zone to an offset in minutes
        $timeZoneOffset = (new DateTime())->setTimezone(new DateTimeZone($user['time_zone']))->getOffset();

        return intval($timeZoneOffset / 60);
    }

    public function handleAuthenticationAttempt(string $username, string $password, string $ipAddress): bool {
        // Handle the authentication attempt by verifying the password and updating the user's last login timestamp
        if ($this->authenticateUser($username, $password)) {
            $user = $this->apiClient->getUserByUsername($username);

            if ($user) {
                $updatedUser = [
                    'username' => $user['username'],
                    'last_login' => date('Y-m-d H:i:s'),
                ];

                return $this->apiClient->updateUser($updatedUser);
            }
        }

        // Log the authentication attempt in a database or file
        $log = [
            'username' => $username,
            'ip_address' => $ipAddress,
            'timestamp' => time(),
        ];

        $this->apiClient->createAuthenticationAttempt($log);

        // Notify the user or administrator of suspicious activity, such as failed login attempts from multiple locations within a short period
        $this->notifySuspiciousActivity($username, $ipAddress);

        return false;
    }
}
