#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/stat.h>
#include <pthread.h>
#include <unistd.h>

// Third-party tool for converting images to PDFs
#define THIRD_PARTY_TOOL "convert"

// Maximum number of threads to use for conversion
#define MAX_THREADS 8

// Progress bar settings
#define PROGRESS_BAR_WIDTH 50
#define PROGRESS_BAR_CHARACTER '#'
#define PROGRESS_BAR_SEPARATOR ' '

// Output resolution for the converted PDFs (in DPI)
#define OUTPUT_RESOLUTION 300

// List of file extensions to convert
#define FILE_EXTENSIONS "jpg,jpeg,png"

// Timeout in seconds for the conversion process
#define TIMEOUT 60

// Logging settings
#define LOGGING_FILE "batchConvertJpegToPdf.log"
#define LOGGING_LEVEL LOG_DEBUG

// Structure to store thread information
typedef struct {
    pthread_t thread;
    int fileIndex;
} ThreadInfo;

// Function to check if a given file is an image
bool isImageFile(const char *filePath) {
    // Check the file extension
    const char *ext = strrchr(filePath, '.');
    if (ext == NULL) {
        return false;
    }

    // Compare with supported extensions
    if (strcasecmp(ext, ".jpg") == 0 || strcasecmp(ext, ".jpeg") == 0 || strcasecmp(ext, ".png") == 0) {
        return true;
    } else {
        return false;
    }
}

// Function to convert a single image file to PDF
int convertImageToPdf(const char *inputFile, const char *outputFile, size_t maxPagesPerPdf, int outputResolution) {
    // Build the command-line arguments for the third-party tool
    char *args[] = {"convert", inputFile, "-limit", "memory", "-density", "300", outputFile};

    // Execute the command and capture its output
    FILE *fp = popen(THIRD_PARTY_TOOL, "w");
    if (fp == NULL) {
        return errno;
    }
    for (int i = 0; i < sizeof(args)/sizeof(char*); i++) {
        fprintf(fp, "%s\n", args[i]);
    }
    pclose(fp);

    // Return 0 if successful, else return the error code
    if (ferror(fp)) {
        return errno;
    } else {
        return 0;
    }
}

// Function to convert multiple image files in a directory to PDFs
int batchConvertJpegToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int numThreads) {
    // Check if the input directory exists and contains only valid image files
    struct stat st;
    if (stat(inputDir, &st) == 0 && S_ISDIR(st.st_mode)) {
        DIR *dir = opendir(inputDir);
        if (dir == NULL) {
            return errno;
        }
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            const char *filePath = entry->d_name;
            if (!isImageFile(filePath)) {
                continue;
            }
        }
    } else {
        return ENOENT;
    }

    // Initialize a progress bar and logging framework
    ProgressBar *progressBar = newProgressBar(PROGRESS_BAR_WIDTH);
    Logging *logging = newLogging(LOGGING_FILE, LOGGING_LEVEL);

    // Create a thread pool to manage the conversion process
    ThreadPool *threadPool = newThreadPool(numThreads);

    // Iterate over all image files in the input directory and convert them to PDFs
    int errorCode = 0;
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        const char *filePath = entry->d_name;
        if (!isImageFile(filePath)) {
            continue;
        }

        // Get the file index for the progress bar
        int fileIndex = getFileIndex(inputDir, filePath);

        // Create a thread to convert the image file
        ThreadInfo *threadInfo = newThreadInfo();
        threadInfo->fileIndex = fileIndex;
        pthread_create(&threadInfo->thread, NULL, (void* (*)(void*))convertImageToPdf, inputFile);

        // Add the thread to the thread pool
        addThread(threadPool, threadInfo);
    }

    // Wait for all threads to complete and update the progress bar
    while (getNumCompletedThreads(threadPool) < getNumThreads(threadPool)) {
        // Update the progress bar
        updateProgressBar(progressBar, 100 * getNumCompletedThreads(threadPool) / getNumThreads(threadPool));

        // Sleep for a short time to avoid overwhelming the CPU
        usleep(1000);
    }

    // Get the first error code encountered during conversion
    errorCode = getFirstErrorCode(threadPool);

    // Clean up the thread pool and progress bar
    deleteThreadPool(threadPool);
    deleteProgressBar(progressBar);

    return errorCode;
}
