import asyncio
import logging
from typing import List

import aiohttp

class StockTradingApplication:
    def __init__(self):
        self.strategies = []
        self.payment_validation_rules = []
        self.api_connections = {}
        self.payment_providers = {}
        self.trade_executions = {}
        self.payment_validations = {}
        self.log = logging.getLogger(__name__)

    def add_strategy(self, strategy):
        self.strategies.append(strategy)

    def add_payment_validation_rule(self, rule):
        self.payment_validation_rules.append(rule)

    def connect_api(self, api_name, url):
        self.api_connections[api_name] = aiohttp.ClientSession()

    def connect_payment_provider(self, provider_name, url):
        self.payment_providers[provider_name] = aiohttp.ClientSession()

    async def fetch_market_data(self, api_name: str, symbol: str) -> dict:
        try:
            async with self.api_connections[api_name].get(url=f"{url}/{symbol}") as response:
                return await response.json()
        except Exception as e:
            self.log.error("Failed to fetch market data from API %s for symbol %s", api_name, symbol)
            raise e

    async def execute_trade(self, trade: dict):
        try:
            strategy = self.strategies[trade["strategy"]]
            trade_result = await strategy(trade)
            return trade_result
        except Exception as e:
            self.log.error("Failed to execute trade %s", trade)
            raise e

    async def validate_payment(self, payment: dict):
        try:
            rule = self.payment_validation_rules[payment["rule"]]
            payment_result = await rule(payment)
            return payment_result
        except Exception as e:
            self.log.error("Failed to validate payment %s", payment)
            raise e

    async def handle_trade_execution_request(self, trade_execution):
        try:
            symbol = trade_execution["symbol"]
            trade = await self.fetch_market_data(trade_execution["api"], symbol)
            if trade is None:
                raise ValueError("Failed to fetch market data for symbol {}".format(symbol))
            trade_result = await self.execute_trade(trade)
            return trade_result
        except Exception as e:
            self.log.error("Failed to handle trade execution request %s", trade_execution)
            raise e

    async def handle_payment_validation_request(self, payment_validation):
        try:
            payment = payment_validation["payment"]
            payment_result = await self.validate_payment(payment)
            return payment_result
        except Exception as e:
            self.log.error("Failed to handle payment validation request %s", payment_validation)
            raise e

    async def run(self):
        while True:
            try:
                trade_execution = await self.trade_executions.get()
                if trade_execution is None:
                    continue
                trade_result = await self.handle_trade_execution_request(trade_execution)
                if trade_result is not None:
                    self.log.info("Trade executed with result %s", trade_result)
            except Exception as e:
                self.log.error("Failed to execute trade")
                raise e

            try:
                payment_validation = await self.payment_validations.get()
                if payment_validation is None:
                    continue
                payment_result = await self.handle_payment_validation_request(payment_validation)
                if payment_result is not None:
                    self.log.info("Payment validated with result %s", payment_result)
            except Exception as e:
                self.log.error("Failed to validate payment")
                raise e
