// Header file: drone_management.h
#ifndef DRONE_MANAGEMENT_H
#define DRONE_MANAGEMENT_H

#include <vector>
#include <map>
#include <string>
#include <memory>
#include <chrono>

// Define a structure to represent a drone
struct Drone {
  int id; // unique identifier for the drone
  std::string name; // name of the drone
  std::vector<int> sensors; // list of sensor types supported by the drone
  std::map<std::string, std::string> payload_configs; // map of payload configurations
  bool is_connected; // flag indicating whether the drone is connected to ground control
  int battery_level; // current battery level of the drone
  double flight_time; // total flight time of the drone
};

// Define a structure to represent a survey request
struct SurveyRequest {
  std::string id; // unique identifier for the survey request
  std::string drone_id; // ID of the drone to be used for the survey
  std::vector<std::string> sensor_types; // list of sensor types required for the survey
  std::map<std::string, int> payload_configs; // map of payload configurations required for the survey
  double latitude; // latitude of the survey location
  double longitude; // longitude of the survey location
  double altitude; // altitude of the survey location
};

// Define a structure to represent a survey task
struct SurveyTask {
  std::string id; // unique identifier for the survey task
  std::string drone_id; // ID of the drone assigned to the survey task
  std::vector<std::string> sensor_types; // list of sensor types required for the survey task
  std::map<std::string, int> payload_configs; // map of payload configurations required for the survey task
  double latitude; // latitude of the survey location
  double longitude; // longitude of the survey location
  double altitude; // altitude of the survey location
  bool is_completed; // flag indicating whether the survey task has been completed
};

// Define a class to manage drones and survey tasks
class DroneManager {
 public:
  DroneManager();
  ~DroneManager();

  // Methods for managing drones
  void add_drone(const std::string& name, const std::vector<int>& sensors, const std::map<std::string, std::string>& payload_configs);
  void remove_drone(const std::string& drone_id);
  bool is_drone_connected(const std::string& drone_id) const;
  int get_battery_level(const std::string& drone_id) const;
  double get_flight_time(const std::string& drone_id) const;
  void update_drone_status(const std::string& drone_id, bool is_connected, int battery_level, double flight_time);

  // Methods for managing survey requests and tasks
  void add_survey_request(const SurveyRequest& request);
  void remove_survey_request(const std::string& request_id);
  bool is_survey_task_completed(const std::string& task_id) const;
  void update_survey_task_status(const std::string& task_id, bool is_completed);
  SurveyTask get_survey_task(const std::string& task_id) const;
  std::vector<SurveyTask> get_all_survey_tasks() const;

 private:
  // Map of drone IDs to Drone objects
  std::map<std::string, Drone> drones_;

  // Map of survey request IDs to SurveyRequest objects
  std::map<std::string, SurveyRequest> survey_requests_;

  // Map of survey task IDs to SurveyTask objects
  std::map<std::string, SurveyTask> survey_tasks_;
};

#endif // DRONE_MANAGEMENT_H
