// Source file: drone_management.cpp
#include "drone_management.h"
#include <iostream>
#include <sstream>
#include <fstream>

DroneManager::DroneManager() {}

DroneManager::~DroneManager() {}

void DroneManager::add_drone(const std::string& name, const std::vector<int>& sensors, const std::map<std::string, std::string>& payload_configs) {
  drones_.emplace(name, Drone{name, sensors, payload_configs});
}

void DroneManager::remove_drone(const std::string& drone_id) {
  drones_.erase(drone_id);
}

bool DroneManager::is_drone_connected(const std::string& drone_id) const {
  return drones_.at(drone_id).is_connected;
}

int DroneManager::get_battery_level(const std::string& drone_id) const {
  return drones_.at(drone_id).battery_level;
}

double DroneManager::get_flight_time(const std::string& drone_id) const {
  return drones_.at(drone_id).flight_time;
}

void DroneManager::update_drone_status(const std::string& drone_id, bool is_connected, int battery_level, double flight_time) {
  auto& drone = drones_.at(drone_id);
  drone.is_connected = is_connected;
  drone.battery_level = battery_level;
  drone.flight_time += flight_time;
}

void DroneManager::add_survey_request(const SurveyRequest& request) {
  survey_requests_.emplace(request.id, request);
}

void DroneManager::remove_survey_request(const std::string& request_id) {
  survey_requests_.erase(request_id);
}

bool DroneManager::is_survey_task_completed(const std::string& task_id) const {
  return survey_tasks_.at(task_id).is_completed;
}

void DroneManager::update_survey_task_status(const std::string& task_id, bool is_completed) {
  auto& task = survey_tasks_.at(task_id);
  task.is_completed = is_completed;
}

SurveyTask DroneManager::get_survey_task(const std::string& task_id) const {
  return survey_tasks_.at(task_id);
}

std::vector<SurveyTask> DroneManager::get_all_survey_tasks() const {
  std::vector<SurveyTask> tasks;
  for (const auto& task : survey_tasks_) {
    tasks.push_back(task.second);
  }
  return tasks;
}
