import os
from flask import Flask, request, jsonify
from sqlalchemy import create_engine, MetaData, Table
from sqlalchemy.orm import sessionmaker

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = os.environ.get("DATABASE_URL") or "sqlite:///drones.db"
engine = create_engine(app.config["SQLALCHEMY_DATABASE_URI"])
metadata = MetaData()
drone_table = Table("drone", metadata,
    Column("id", Integer, primary_key=True),
    Column("name", String),
    Column("model", String),
    Column("mission_id", Integer, ForeignKey("mission.id")),
)
mission_table = Table("mission", metadata,
    Column("id", Integer, primary_key=True),
    Column("drone_id", Integer, ForeignKey("drone.id")),
    Column("start_time", DateTime),
    Column("end_time", DateTime),
)
metadata.create_all(engine)
Session = sessionmaker(bind=engine)
session = Session()

@app.route("/drones", methods=["GET"])
def get_drones():
    drones = session.query(Drone).all()
    return jsonify([{
        "id": drone.id,
        "name": drone.name,
        "model": drone.model,
        "mission_id": drone.mission_id,
    } for drone in drones])

@app.route("/drones", methods=["POST"])
def create_drone():
    try:
        drone = Drone(name=request.json["name"], model=request.json["model"])
        session.add(drone)
        session.commit()
        return jsonify({"id": drone.id})
    except Exception as e:
        session.rollback()
        raise e

@app.route("/drones/<int:drone_id>", methods=["PUT"])
def update_drone(drone_id):
    try:
        drone = session.query(Drone).get(drone_id)
        if not drone:
            return jsonify({"error": f"Drone with ID {drone_id} not found."}), 404
        drone.name = request.json["name"]
        drone.model = request.json["model"]
        session.commit()
        return jsonify({"id": drone.id})
    except Exception as e:
        session.rollback()
        raise e

@app.route("/drones/<int:drone_id>", methods=["DELETE"])
def delete_drone(drone_id):
    try:
        drone = session.query(Drone).get(drone_id)
        if not drone:
            return jsonify({"error": f"Drone with ID {drone_id} not found."}), 404
        mission = session.query(Mission).filter(Mission.drone_id == drone_id).first()
        if mission:
            raise Exception(f"Cannot delete drone with ongoing mission.")
        session.delete(drone)
        session.commit()
        return jsonify({"message": f"Drone with ID {drone_id} deleted."})
    except Exception as e:
        session.rollback()
        raise e

@app.route("/drones/<int:drone_id>/missions", methods=["GET"])
