    try:
        drone = session.query(Drone).get(drone_id)
        if not drone:
            return jsonify({"error": f"Drone with ID {drone_id} not found."}), 404
        mission = session.query(Mission).get(mission_id)
        if not mission:
            return jsonify({"error": f"Mission with ID {mission_id} not found."}), 404
        session.delete(mission)
        drone.missions.remove(mission)
        session.commit()
        return jsonify({"message": f"Mission with ID {mission_id} deleted."})
    except Exception as e:
        session.rollback()
        raise e
```

