    id = Column(Integer, primary_key=True)
    name = Column(String)
    missions = relationship("Mission", backref="drone")

class Mission(Base):
    __tablename__ = "missions"

    id = Column(Integer, primary_key=True)
    drone_id = Column(Integer, ForeignKey("drones.id"))
    start_time = Column(DateTime)
    end_time = Column(DateTime)
