        drone.name = name
        self.session.commit()
        return drone

    def delete(self, id):
        drone = self.session.query(Drone).get(id)
        if not drone:
            raise Exception(f"Drone with ID {id} not found.")
        self.session.delete(drone)
        self.session.commit()
        return f"Drone with ID {id} deleted."

