// Define a struct to represent the cached paths
struct path_cache {
  char *path;
  bool is_absolute;
};

// Define a function to cache the resolved path
void cache_resolved_path(char *path, bool is_absolute) {
  // Add the path to the cache if it's not already there
  struct path_cache *cache = malloc(sizeof(struct path_cache));
  cache->path = path;
  cache->is_absolute = is_absolute;
  // If the cache is full, remove the least recently used entry
  if (num_cached_paths >= max_cache_size) {
    free(lru_cache);
    lru_cache = NULL;
  }
}

// Define a function to get the resolved path from the cache
char *get_resolved_path(char *path) {
  // Check if the path is already cached
  for (struct path_cache *cache = lru_cache; cache != NULL; cache = cache->next) {
    if (strcmp(path, cache->path) == 0) {
      return cache->path;
    }
  }
  // If the path is not cached, resolve it and add it to the cache
  struct stat sb;
  if (stat(path, &sb) == -1) {
    printf("Error: %s\n", strerror(errno));
    return NULL;
  }
  char *resolved_path = malloc(sizeof(char) * (sb.st_size + 1));
  if (resolved_path == NULL) {
    printf("Error: unable to allocate memory\n");
    return NULL;
  }
  sprintf(resolved_path, "%s", path);
  cache_resolved_path(resolved_path, is_absolute);
  return resolved_path;
}

