char *expand_environment_variables(char *path) {
  // Check if the path contains any environment variables
  char *env_var = strstr(path, "$");
  while (env_var != NULL) {
    // Get the name of the environment variable
    char *env_name = env_var + 1;
    size_t env_len = strcspn(env_name, "/");
    if (env_len == 0) {
      break;
    }
    // Check if the environment variable is defined
    char *env_value = getenv(env_name);
    if (env_value == NULL) {
      printf("Error: environment variable '%s' is not defined\n", env_name);
      return NULL;
    }
    // Replace the environment variable with its value in the path
    size_t new_len = strlen(env_value) + strlen(path) - (env_len + 1);
    char *new_path = malloc(sizeof(char) * new_len);
    if (new_path == NULL) {
      printf("Error: unable to allocate memory\n");
      return NULL;
    }
    sprintf(new_path, "%s%s", env_value, path + (env_len + 1));
    free(path);
    path = new_path;
