// SecureMessagingLibrary.java
package com.example;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.context.ApplicationListener;
import org.springframework.context.event.ContextRefreshedEvent;

public class SecureMessagingLibrary implements ApplicationListener<ContextRefreshedEvent> {
    private static final Log LOGGER = LogFactory.getLog(SecureMessagingLibrary.class);

    private SSLContext mContext;

    public SecureMessagingLibrary(SSLContext context) {
        mContext = context;
    }

    @Override
    public void onApplicationEvent(ContextRefreshedEvent event) {
        LOGGER.info("Initializing OpenSSL context...");
        try {
            // Initialize the SSLContext with the provided configuration
            mContext = SSLContext.getInstance("TLSv1.2");
            mContext.init(null, null, null);
        } catch (Exception e) {
            LOGGER.error("Error initializing OpenSSL context: " + e.getMessage());
        }
    }

    public void enableEncryptionAlgorithm(String algorithm) {
        // Enable a specific encryption algorithm in the SSLContext
        try {
            mContext.createSSLEngine().setEnabledCipherSuites(new String[] {algorithm});
        } catch (Exception e) {
            LOGGER.error("Error enabling encryption algorithm: " + e.getMessage());
        }
    }

    public void enableHashingAlgorithm(String algorithm) {
        // Enable a specific hashing algorithm in the SSLContext
        try {
            mContext.createSSLEngine().setEnabledProtocols(new String[] {algorithm});
        } catch (Exception e) {
            LOGGER.error("Error enabling hashing algorithm: " + e.getMessage());
        }
    }
}
