import os
from PIL import Image
import exifread
import datetime
import time
import requests
import json
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_image(filepath, metadata):
    """Process a single image file and extract its metadata"""
    try:
        with Image.open(filepath) as image:
            # Extract EXIF data from the image
            exif = {exifread.process_file(filepath).get(tag, 'No Value') for tag in ['DateTimeOriginal', 'ResolutionUnit']}
            # Add image dimensions to metadata dictionary
            exif['Width'] = image.size[0]
            exif['Height'] = image.size[1]
            # Return the processed metadata
            return {**metadata, **exif}
    except Exception as e:
        logger.error(f"Error processing image {filepath}: {e}")
        raise e

def analyze_images(directory, criteria):
    """Analyze all images in a directory and extract metadata based on given criteria"""
    start = time.time()
    logger.info(f"Analyzing images in {directory}...")

    # Collect all image files in the directory
    files = [os.path.join(directory, f) for f in os.listdir(directory)]

    # Initialize metadata dictionary to store extracted data
    metadata = {}

    # Process each image file and extract metadata
    for file in files:
        if not os.path.isfile(file):
            logger.info(f"Skipping {file}, as it is not a valid file")
            continue
        try:
            with open(file, 'rb') as fh:
                content = fh.read()
                # Check image format support and skip if unsupported
                if Image.open(content).format in ('JPEG', 'PNG', 'WebP'):
                    metadata[os.path.basename(file)] = process_image(file, {})
                else:
                    logger.info(f"Skipping {file}, as it has an unsupported image format")
        except Exception as e:
            logger.error(f"Error processing {file}: {e}")

    # Filter metadata based on criteria
    filtered_metadata = {}
    for key, value in metadata.items():
        if criteria['date'][0] <= value['DateTimeOriginal'] < criteria['date'][1]:
            if value['ResolutionUnit'] == criteria['resolution']:
                filtered_metadata[key] = value

    # Save analysis report to an external cloud storage service (e.g., AWS S3)
    logger.info(f"Saving analysis report to external cloud storage...")
    try:
        response = requests.post('https://s3-external-storage.com/', data=json.dumps(filtered_metadata))
        if response.status_code == 201:
            logger.info(f"Analysis report saved successfully to {response.url}")
        else:
            logger.error(f"Error saving analysis report: {response.text}")
    except Exception as e:
        logger.error(f"Error saving analysis report: {e}")

    # Send a notification via an external service (e.g., Slack, email) about the completion of image analysis and report availability
    logger.info(f"Sending notification to users...")
    try:
        requests.post('https://external-notification-service.com/', data={'subject': 'Image analysis complete', 'message': f'The image analysis has been completed, and the report is available at {response.url}.'})
    except Exception as e:
        logger.error(f"Error sending notification: {e}")

    end = time.time()
    logger.info(f"Analysis complete in {end-start} seconds")
