import sys
from typing import List, Iterable

class MergeSortedLists:
    def __init__(self, lists: List[Iterable], buffer_size=10000):
        self.lists = lists
        self.buffer_size = buffer_size
        self.current_list = 0
        self.current_element = None
        self.last_known_state = None

    def _get_next_element(self) -> Any:
        while True:
            try:
                return next(self.lists[self.current_list])
            except StopIteration:
                if self.current_list == len(self.lists) - 1:
                    break
                else:
                    self.current_list += 1
        return None

    def _merge_lists(self, lists: List[Iterable]) -> Iterator[Any]:
        while True:
            if not all(list_ is None for list_ in lists):
                min_element = min([next(list_, None) for list_ in lists if list_], key=lambda x: x.key)
                yield min_element
            else:
                break

    def _external_sort(self, lists: List[Iterable]) -> Iterator[Any]:
        # Implement external sorting mechanism here
        pass

    def merge(self, lists: List[Iterable]) -> Iterator[Any]:
        buffer = []
        while True:
            try:
                element = self._get_next_element()
                if element is None:
                    break
                buffer.append(element)
                if len(buffer) >= self.buffer_size:
                    yield from self._merge_lists(buffer)
                    buffer = []
            except StopIteration:
                yield from self._external_sort(lists)
                break
        if buffer:
            yield from self._merge_lists(buffer)

def merge_sorted_lists(lists: List[Iterable], buffer_size=10000):
    return MergeSortedLists(lists, buffer_size).merge(lists)
```
