  private boolean success; // flag indicating whether the upload was successful
  private String message; // message describing the result of the upload

  public UploadResult(boolean success, String message) {
    this.success = success;
    this.message = message;
  }

  public boolean isSuccess() {
    return success;
  }

  public String getMessage() {
    return message;
  }
}

