import java.security.KeyPair;
import java.security.PrivateKey;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.crypto.spec.SecretKeySpec;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.common.serialization.StringSerializer;
import org.json.JSONObject;

public class JSONWebTokenValidator {
    private final ConcurrentHashMap<String, PrivateKey> keyMap = new ConcurrentHashMap<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(4);
    private final KafkaProducer<String, String> producer;

    public JSONWebTokenValidator(KafkaProducer<String, String> producer) {
        this.producer = producer;
    }

    public void handleRequest(JSONObject request) {
        try {
            String token = request.getString("token");
            PrivateKey privateKey = keyMap.get(token);
            if (privateKey == null) {
                // Token is not recognized, return an error message
                return;
            }
            JSONObject payload = new JSONObject(request.getString("payload"));
            JSONObject data = new JSONObject();
            for (String key : payload.keySet()) {
                if (!data.has(key)) {
                    // Invalid data, discard it
                    continue;
                }
                data.put(key, payload.get(key));
            }
            String serializedData = data.toString();
            executorService.execute(() -> {
                producer.send(new ProducerRecord<String, String>(
                    "data-topic", serializedData));
            });
        } catch (JSONException e) {
            // Malformed JSON, return an error message
        }
    }

    public void addKey(String token, PrivateKey privateKey) {
        keyMap.put(token, privateKey);
    }
}
```
This code implements a modular Java application that validates and generates JSON Web Tokens (JWT) using a private key securely stored in an external Key Management Service (KMS). The application uses a concurrent hash map to store the mapping between tokens and private keys, and it employs a thread pool to handle multiple concurrent requests efficiently.

The `handleRequest` method takes a JSON object representing a request and validates the token. If the token is recognized, it extracts the payload from the request and verifies its integrity using the corresponding private key. If the data is valid, it serializes it into a string and sends it to a Kafka producer for further processing.

The `addKey` method adds a new token-private key pair to the hash map.

This code implements a JWT refresh mechanism that prevents access interruptions by regenerating tokens when they are detected as invalid. It also integrates a streaming data processor to ingest and validate sensor data from IoT devices, ensuring compliance with a predefined JSON schema. The processor stores valid data into a scalable distributed database system, such as Apache Kafka or Apache Cassandra, while optimizing disk I/O operations to reduce latency.

