        {
            try
            {
                var cmsProvider = GetCmsProvider(contentType);
                if (cmsProvider == null)
                {
                    throw new Exception($"Unsupported content type: {contentType}");
                }

                // Compress the content using the best available compression algorithm
                var compressedContent = await CompressContentAsync(content, cmsProvider.SupportedCompressionAlgorithms);

                // Update the content on the CMS provider
                var updateResponse = await cmsProvider.UpdateContentAsync(compressedContent);

                // Log the compression algorithm and transmission time
                _logger.LogInformation($"Compression algorithm: {updateResponse.CompressionAlgorithm}, transmission time: {updateResponse.TransmissionTime}");
            }
            catch (Exception e)
            {
                _logger.LogError(e, "Failed to update content");
            }
        }

        private async Task<byte[]> CompressContentAsync(string content, IList<CompressionAlgorithm> supportedAlgorithms)
        {
            foreach (var algorithm in supportedAlgorithms)
            {
                try
                {
                    var compressedContent = await algorithm.CompressAsync(content);
                    return compressedContent;
                }
                catch (Exception e)
                {
                    _logger.LogError(e, $"Failed to compress content using compression algorithm: {algorithm.Name}");
                }
            }
            throw new Exception("No suitable compression algorithm found");
        }

        private CmsProvider GetCmsProvider(string contentType)
        {
            foreach (var cmsProvider in _cmsProviders)
            {
                if (cmsProvider.SupportsContentType(contentType))
                {
                    return cmsProvider;
                }
            }
            return null;
        }

        private class CmsProvider
        {
            public string Name { get; set; }
            public IList<CompressionAlgorithm> SupportedCompressionAlgorithms { get; set; }

            public bool SupportsContentType(string contentType)
