import java.util.*;
import java.io.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class InventoryManager {
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    public static void main(String[] args) throws IOException {
        // Parse configuration settings from JSON file
        Map<String, Object> configSettings = parseConfigFile(args[0]);

        // Initialize inventory system and API client
        InventorySystem inventorySystem = new InventorySystem();
        CloseableHttpClient httpClient = HttpClients.createDefault();

        // Start processing inventory updates in a separate thread
        Thread inventoryUpdateThread = new Thread(() -> {
            while (true) {
                try {
                    // Fetch latest inventory data from external API
                    HttpGet request = new HttpGet("https://external-api.com/inventory");
                    request.addHeader("Authorization", "Bearer " + configSettings.get("apiToken"));
                    CloseableHttpResponse response = httpClient.execute(request);
                    String responseBody = EntityUtils.toString(response.getEntity());

                    // Parse inventory data and update system
                    List<InventoryItem> items = OBJECT_MAPPER.readValue(responseBody, new TypeReference<List<InventoryItem>>() {});
                    inventorySystem.updateInventory(items);
                } catch (Exception e) {
                    // Handle error and continue processing
                    System.err.println("Error updating inventory: " + e.getMessage());
                }
            }
        });
        inventoryUpdateThread.start();

        // Start API server to handle requests from clients
        InventoryAPI api = new InventoryAPI(inventorySystem);
        api.startServer();
    }

    private static Map<String, Object> parseConfigFile(String fileName) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName))) {
            return OBJECT_MAPPER.readValue(reader, new TypeReference<Map<String, Object>>() {});
        } catch (Exception e) {
            throw new IOException("Error parsing configuration file", e);
        }
    }
}
```
