function getLocationInfo(latitude, longitude) {
  return new Promise((resolve, reject) => {
    request({
      url: 'https://geolocation-service.com/api/locations',
      method: 'GET',
      qs: {
        latitude,
        longitude,
        format: 'json'
      }
    }, (error, response, body) => {
      if (error) {
        console.log(`Error getting location information for ${latitude},${longitude}`, error);
        reject(error);
      } else {
        const parsedBody = JSON.parse(body);
        resolve({
          city: parsedBody.city,
          zipCode: parsedBody.zipCode
        });
      }
    });
  });
}

