// Get current weather conditions and forecast for a given location
router.get('/weather/:location', async (req, res) => {
  const location = req.params.location;
  let cacheKey = `${location}-currentWeather`;

  // Check if cache exists
  if (cache.get(cacheKey)) {
    console.log(`Cache hit for ${cacheKey}`);
    res.send(cache.get(cacheKey));
  } else {
    try {
      const locationInfo = await getLocationInfo(location);
      const weatherInfo = await getWeatherInfo(locationInfo.city);
      const climateHistory = await getClimateHistory(locationInfo.zipCode);
      const machineLearningModel = await getMachineLearningModel();

      // Generate JSON response
      const response = {
        currentWeather: weatherInfo.currentWeather,
        forecast: weatherInfo.forecast,
        temperatureStats: climateHistory.climateEvents,
        machineLearningModel: machineLearningModel.machineLearningModel,
        location: locationInfo.city
      };

      // Cache response for 30 minutes
      cache.put(cacheKey, response, cacheDuration);
      res.send(response);
    } catch (error) {
      console.log(`Error getting weather information for ${location}`, error);
      res.status(500).send({ message: 'Error fetching data' });
    }
  }
});

// Handle real-time updates via WebSocket connections
router.ws('/updates', (socket, request) => {
  const location = request.params.location;

  // Set up WebSocket connection and subscribe to updates
  const webSocket = new WebSocket('wss://weather-api.com/api/updates');
  webSocket.on('message', (message) => {
    const parsedMessage = JSON.parse(message);
    if (parsedMessage.location === location) {
      // Send message to client
      socket.send(parsedMessage.data);
    }
  });
});

