```rust
use std::env;
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread::sleep;
use std::time::Duration;
use std::path::Path;

use rustc_driver::catch_with_exit_code;
use rustc_driver::logger::Logger;
use rustc_driver::sync_lazy::SyncLazy;

fn compile(src: &str) -> i32 {
    // Setup logger and ice hook
    let log = Logger::new("compile");
    let log_hook = SyncLazy::new(|| log.clone());

    // Get maximum resident set size (RSS) threshold from environment variable
    let rss_threshold: u64 = env::var("RSS_THRESHOLD")
        .unwrap()
        .parse()
        .expect("Invalid RSS threshold");

    // Check if source file exists and is readable
    if !Path::new(src).exists() || !Path::new(src).is_file() {
        log.error(format!("Source file {} does not exist or is not a file", src));
        return 1;
    }

    // Setup command to run the Rust compiler with logging hook and ice hook
    let mut cmd = Command::new("rustc");
    cmd.arg(src).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let log_hook = log_hook.clone();
    let rss_threshold = rss_threshold.clone();
    cmd.before_exec(|_| {
        // Install logging hook and ice hook
        log_hook.install(|| {});
        SyncLazy::new(move || {
            // Check RSS after compilation
            let mut rss = 0;
            while rss < rss_threshold {
                sleep(Duration::from_millis(100));
                rss = get_rss();
            }
            log.warn("RSS threshold exceeded, terminating process");
            return 1;
        });
        Ok(())
    });

    // Run command and catch any errors with the `catch_with_exit_code` function
    let exit_code = catch_with_exit_code(|| {
        cmd.exec();
        log.error("Failed to execute Rust compiler");
        return 1;
    });

    // Log compilation duration and exit code
    let start = Instant::now();
    let mut rss = get_rss();
    log.info(format!("Compilation finished with exit code {}", exit_code));
    while rss < rss_threshold {
        sleep(Duration::from_millis(100));
        rss = get_rss();
    }
    let duration = start.elapsed().as_secs_f64();
    log.info(format!("Compilation took {:.2} seconds", duration));

    // Return exit code
    return exit_code;
}

fn get_rss() -> u64 {
    // Get resident set size (RSS) in bytes
    let mut rss = 0;
    for line in read_lines("/proc/self/statm")? {
        if let Ok(line) = line {
            let parts: Vec<&str> = line.split(" ").collect();
            if parts[0].parse::<u64>().unwrap() > 0 {
                rss += parts[0].parse::<u64>().unwrap();
            }
        }
    }
    return rss;
}
