    printf("\tSamples per Pixel: %d\n", info.samples_per_pixel);

    // Free memory allocated for the image data
    delete[] info.data;

    return 0;
}

Here is an example of a `resolveHostname` function that uses standard library functions to perform DNS resolution:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int resolveHostname(const char *hostname, u_char **ip) {
    struct hostent *host;
    struct in_addr addr;
    int error = 0;

    // Perform DNS resolution
    host = gethostbyname(hostname);
    if (!host) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
        return -1;
    }

    // Get IP address from the first result
    addr = *((struct in_addr *)host->h_addr_list[0]);
    *ip = malloc(sizeof(u_char) * 4);
    memcpy(*ip, &addr.s_addr, sizeof(u_char) * 4);

    return error;
}
```
This function takes a `hostname` as an input and returns the corresponding IP address in a `u_char` array. It uses standard library functions to perform DNS resolution using the `gethostbyname` function, which returns a `struct hostent *` pointer that contains information about the host. The function then extracts the first result from the list of addresses and copies it into an allocated buffer.

Here is an example of how to use this function:
