```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <semaphore.h>

#define MAX_CONCURRENT_RESOLUTIONS 10

int resolveHostname(const char *hostname, u_char **ip) {
    struct hostent *host;
    struct in_addr addr;
    int error = 0;

    // Perform DNS resolution
    host = gethostbyname(hostname);
    if (!host) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", hostname);
        return -1;
    }

    // Get IP address from the first result
    addr = *((struct in_addr *)host->h_addr_list[0]);
    *ip = malloc(sizeof(u_char) * 4);
    memcpy(*ip, &addr.s_addr, sizeof(u_char) * 4);

    return error;
}

int acquireSemaphore() {
    // Acquire semaphore to limit the number of concurrent resolutions
    int error = sem_wait(&semaphore);
    if (error) {
        fprintf(stderr, "Failed to acquire semaphore: %s\n", strerror(error));
        return -1;
    }
    return 0;
}

int releaseSemaphore() {
    // Release semaphore when done with resolution
    int error = sem_post(&semaphore);
    if (error) {
        fprintf(stderr, "Failed to release semaphore: %s\n", strerror(error));
        return -1;
    }
    return 0;
}
```
This code demonstrates how to add a semaphore to the `resolveHostname` function to limit the number of concurrent resolutions. It uses the `sem_wait` and `sem_post` functions from `<semaphore.h>` to acquire and release the semaphore, respectively. These functions are used to block the thread until the semaphore is available, and then to signal that the thread is ready to proceed.

