```csharp
using System;
using System.Threading.Tasks;
using System.Net.Http;
using Newtonsoft.Json;

public class DynamicWeatherMiddleware
{
    private HttpClient _httpClient;
    private string _apiUrl;

    public DynamicWeatherMiddleware(HttpClient httpClient, string apiUrl)
    {
        _httpClient = httpClient;
        _apiUrl = apiUrl;
    }

    public async Task<string> FetchTemperatureAsync()
    {
        // Send a GET request to the API endpoint for temperature data
        var response = await _httpClient.GetAsync(_apiUrl + "/temperature");

        // Deserialize the JSON response and extract the temperature value
        var jsonResponse = JsonConvert.DeserializeObject<dynamic>(response);
        var temperature = jsonResponse["temperature"];

        return temperature;
    }

    public async Task<string> FetchHumidityAsync()
    {
        // Send a GET request to the API endpoint for humidity data
        var response = await _httpClient.GetAsync(_apiUrl + "/humidity");

        // Deserialize the JSON response and extract the humidity value
        var jsonResponse = JsonConvert.DeserializeObject<dynamic>(response);
        var humidity = jsonResponse["humidity"];

        return humidity;
    }

    public async Task<string> FetchWindSpeedAsync()
    {
        // Send a GET request to the API endpoint for wind speed data
        var response = await _httpClient.GetAsync(_apiUrl + "/wind-speed");

        // Deserialize the JSON response and extract the wind speed value
        var jsonResponse = JsonConvert.DeserializeObject<dynamic>(response);
        var windSpeed = jsonResponse["windSpeed"];

        return windSpeed;
    }

    public async Task<string> FetchPrecipitationAsync()
    {
        // Send a GET request to the API endpoint for precipitation data
        var response = await _httpClient.GetAsync(_apiUrl + "/precipitation");

        // Deserialize the JSON response and extract the precipitation value
        var jsonResponse = JsonConvert.DeserializeObject<dynamic>(response);
        var precipitation = jsonResponse["precipitation"];

        return precipitation;
    }

    public override string ToString()
    {
        // Return a formatted string representing the current weather conditions
        return $"Current weather conditions: {FetchTemperatureAsync()}, {FetchHumidityAsync()}, {FetchWindSpeedAsync()}, {FetchPrecipitationAsync()}";
    }
}
