using System;
using Microsoft.AspNetCore.Identity;

public class ClinicStatusUpdater {
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly SignInManager<ApplicationUser> _signInManager;

    public ClinicStatusUpdater(UserManager<ApplicationUser> userManager, SignInManager<ApplicationUser> signInManager) {
        _userManager = userManager;
        _signInManager = signInManager;
    }

    public async Task UpdateClinicStatusAsync(int clinicId, string status) {
        // Validate input clinic ID
        if (!clinicId.HasValue) {
            throw new ArgumentException("Invalid clinic ID");
        }

        // Handle edge cases such as non-existent clinic IDs and invalid IP addresses
        var ipAddress = _signInManager.GetCurrentIPAddress();
        if (!ipAddress.IsValid()) {
            throw new InvalidOperationException("Invalid IP address");
        }

        // Validate input status
        if (string.IsNullOrEmpty(status)) {
            throw new ArgumentException("Invalid status");
        }

        // Connect to the database and update the clinic status
        using var context = new ApplicationDbContext();
        var clinic = await context.Clinics.FindAsync(clinicId);
        if (clinic == null) {
            throw new InvalidOperationException("Invalid clinic ID");
        }

        clinic.Status = status;
        await context.SaveChangesAsync();
    }
}
