// Utility class for managing sets of integers using a Union-Find data structure
class Set {
public:
    void add(int element) {
        // Add the element to the set if it is not already present
        if (!contains(element)) {
            elements.push_back(element);
        }
    }

    bool contains(int element) const {
        // Check if the element is in the set
        return std::find(elements.begin(), elements.end(), element) != elements.end();
    }

    void union_(Set& other) {
        // Union this set with another set
        for (int element : other.getElements()) {
            add(element);
        }
    }

    std::vector<int> getElements() const {
        // Return the elements in the set as a vector
        return elements;
    }

private:
    std::vector<int> elements;
};

// Utility class for managing threads and synchronization
class ThreadManager {
public:
    void startThreads(const std::function<void()>& function) {
        // Start a new thread to execute the given function
        std::thread thread(function);
        threads.push_back(std::move(thread));
    }

    void waitForThreads() {
        // Wait for all started threads to complete
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    std::vector<std::thread> threads;
};

