#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

// External dependencies
#include "third_party/logging.h"
#include "third_party/decompression.h"
#include "third_party/parsing.h"

// Constants
#define MAX_FILES 500
#define MIN_COMPRESSION_LEVEL 1
#define MAX_COMPRESSION_LEVEL 9
#define FILE_FORMAT_GZIP 1
#define FILE_FORMAT_BZIP2 2
#define PARSING_RULES_CONFIG "parsing_rules.conf"
#define ERROR_THRESHOLD 10

// Structures
typedef struct {
    char* filepath;
    int compression_level;
    int file_format;
} file_t;

typedef struct {
    char* field_name;
    int field_type;
    int field_length;
} field_t;

// Function declarations
void* process_file(void* args);
int parse_file(const char* filepath, const char* parsing_rules);
int decompress_file(const char* filepath, const char* output_filepath);
int handle_error(const char* error_message);
void log_diagnostic(const char* diagnostic_message);

// Main function
int main(int argc, char** argv) {
    // Check command-line arguments
    if (argc < 2) {
        printf("Usage: %s [input file paths]\n", argv[0]);
        return 1;
    }

    // Initialize variables
    int num_files = argc - 1;
    file_t* files = malloc(sizeof(file_t) * num_files);
    for (int i = 0; i < num_files; i++) {
        char* input_filepath = argv[i + 1];
        int compression_level = MIN_COMPRESSION_LEVEL;
        int file_format = FILE_FORMAT_GZIP;
        if (strlen(input_filepath) > 3 && strcmp(input_filepath + strlen(input_filepath) - 3, ".gz") == 0) {
            compression_level = MAX_COMPRESSION_LEVEL;
            file_format = FILE_FORMAT_GZIP;
        } else if (strlen(input_filepath) > 4 && strcmp(input_filepath + strlen(input_filepath) - 4, ".bz2") == 0) {
            compression_level = MAX_COMPRESSION_LEVEL;
            file_format = FILE_FORMAT_BZIP2;
        }
        files[i].filepath = input_filepath;
        files[i].compression_level = compression_level;
        files[i].file_format = file_format;
    }

    // Load parsing rules from configuration file
    char* parsing_rules = read_parsing_rules(PARSING_RULES_CONFIG);
    if (parsing_rules == NULL) {
        printf("Error: Unable to load parsing rules\n");
        return 1;
    }

    // Create threads for processing files
    pthread_t* thread_ids = malloc(sizeof(pthread_t) * num_files);
    for (int i = 0; i < num_files; i++) {
        file_t* file = &files[i];
        void* args = file;
        if (pthread_create(&thread_ids[i], NULL, process_file, args) != 0) {
            printf("Error: Unable to create thread for file %s\n", file->filepath);
            return 1;
        }
    }

    // Wait for threads to complete
    for (int i = 0; i < num_files; i++) {
        if (pthread_join(thread_ids[i], NULL) != 0) {
            printf("Error: Unable to join thread for file %s\n", files[i].filepath);
            return 1;
        }
    }

    // Clean up resources
    free(files);
    free(thread_ids);
    free(parsing_rules);

    return 0;
}

// Processes a single file by decompressing and parsing it
void* process_file(void* args) {
    file_t* file = (file_t*)args;
    char* input_filepath = file->filepath;
    int compression_level = file->compression_level;
    int file_format = file->file_format;

    // Decompress the file
    char* output_filepath = malloc(strlen(input_filepath) + 1);
    strcpy(output_filepath, input_filepath);
    if (decompress_file(input_filepath, output_filepath) != 0) {
        log_diagnostic("Error: Unable to decompress file %s\n", input_filepath);
        return NULL;
    }

    // Parse the file
    int parse_result = parse_file(output_filepath, parsing_rules);
    if (parse_result != 0) {
        log_diagnostic("Error: Unable to parse file %s\n", output_filepath);
        return NULL;
    }

    // Clean up resources
    free(output_filepath);

    return NULL;
}

// Parses a single file using the specified parsing rules
int parse_file(const char* filepath, const char* parsing_rules) {
    // Load parsing rules from configuration file
    if (parsing_rules == NULL) {
        printf("Error: Unable to load parsing rules\n");
        return 1;
    }

    // Open input and output files
    FILE* input_file = fopen(filepath, "rb");
    if (input_file == NULL) {
        printf("Error: Unable to open file %s\n", filepath);
        return 1;
    }
    FILE* output_file = fopen("output.csv", "wb");
    if (output_file == NULL) {
        printf("Error: Unable to create output file\n");
        return 1;
    }

    // Parse the input file and write the results to the output file
    int parse_result = 0;
    while (!feof(input_file)) {
        field* fields = NULL;
        parse_result = parse_record(input_file, &fields);
        if (parse_result != 0) {
            break;
        }
        write_record(output_file, fields);
        free_fields(fields);
    }

    // Clean up resources
    fclose(input_file);
    fclose(output_file);

    return parse_result;
}

// Parses a single record from the input file and returns a pointer to an array of fields
int parse_record(FILE* input_file, field** fields) {
    // Read each field from the input file
    while (!feof(input_file)) {
        char* field_value = read_field(input_file);
        if (field_value == NULL) {
            break;
        }
        add_field(fields, field_value);
        free(field_value);
    }

    return 0;
}

