package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	_ "github.com/go-sql-driver/mysql"
)

type Config struct {
	Servers []string `json:"servers"`
}

type Database struct {
	sync.Mutex
	DB         *sql.DB
	ConfigPath string
	Config     *Config
}

func NewDatabase(configPath string) (*Database, error) {
	db := &Database{
		ConfigPath: configPath,
	}

	// Load configuration from file
	data, err := ioutil.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read configuration file: %w", err)
	}

	config := &Config{}
	err = json.Unmarshal(data, config)
	if err != nil {
		return nil, fmt.Errorf("failed to unmarshal configuration: %w", err)
	}

	db.Config = config

	// Connect to SQL server
	dsn := fmt.Sprintf("%s:%s@tcp(%s)/%s?parseTime=true", db.Config.Servers[0], "root", "localhost:3306", "mydatabase")
	db.DB, err = sql.Open("mysql", dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to SQL server: %w", err)
	}

	// Set connection pooling and timeouts
	db.DB.SetMaxIdleConns(10)
	db.DB.SetMaxOpenConns(100)
	db.DB.SetConnMaxLifetime(time.Hour)

	return db, nil
}

func (db *Database) ReadRecords(key string) ([]byte, error) {
	// Acquire lock on database connection
	db.Lock()
	defer db.Unlock()

	// Setup query statement and arguments
	query := `SELECT id, key, timestamp, metadata FROM records WHERE key = ?`
	args := []interface{}{key}

	// Execute query and scan results into slice of byte slices
	var records [][]byte
	rows, err := db.DB.Query(query, args...)
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var id int
		var record []byte

		err := rows.Scan(&id, &record)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		records = append(records, record)
	}

	// Return records as byte slice
	return json.Marshal(records)
}

func (db *Database) WriteRecord(key string, record []byte) error {
	// Acquire lock on database connection
	db.Lock()
	defer db.Unlock()

	// Setup query statement and arguments
	query := `INSERT INTO records (id, key, timestamp, metadata) VALUES (?, ?, ?, ?)`
	args := []interface{}{key, record}

	// Execute query
	result, err := db.DB.Exec(query, args...)
	if err != nil {
		return fmt.Errorf("failed to execute query: %w", err)
	}

	// Get number of affected rows and check for errors
	affected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get affected rows: %w", err)
	} else if affected == 0 {
		return fmt.Errorf("no records were affected")
	}

	return nil
}

func (db *Database) Close() error {
	// Acquire lock on database connection
	db.Lock()
	defer db.Unlock()

	// Close database connection
	if err := db.DB.Close(); err != nil {
		return fmt.Errorf("failed to close database connection: %w", err)
	}

	return nil
}

func main() {
	configPath := "./config.json"
	db, err := NewDatabase(configPath)
	if err != nil {
		log.Fatalf("failed to create database: %v", err)
	}
	defer db.Close()

	http.HandleFunc("/read", func(w http.ResponseWriter, r *http.Request) {
		key := r.URL.Query().Get("key")

		// Check if key is set in query parameters
		if key == "" {
			w.WriteHeader(http.StatusBadRequest)
			fmt.Fprint(w, "Key not set")
			return
		}

		// Read records from database
		records, err := db.ReadRecords(key)
		if err != nil {
			log.Printf("failed to read records: %v", err)
			w.WriteHeader(http.StatusInternalServerError)
			fmt.Fprint(w, "Failed to read records")
			return
		}

		// Write records to response writer
		_, err = w.Write(records)
		if err != nil {
			log.Printf("failed to write records: %v", err)
		}
	})

	http.HandleFunc("/write", func(w http.ResponseWriter, r *http.Request) {
		key := r.URL.Query().Get("key")
		record := r.Body

		// Check if key and record are set in query parameters
		if key == "" || record == nil {
			w.WriteHeader(http.StatusBadRequest)
			fmt.Fprint(w, "Key or record not set")
			return
		}

		// Write record to database
		err := db.WriteRecord(key, record)
		if err != nil {
			log.Printf("failed to write record: %v", err)
			w.WriteHeader(http.StatusInternalServerError)
			fmt.Fprint(w, "Failed to write record")
			return
		}

		// Write success message to response writer
		_, err = w.Write([]byte("Record written"))
		if err != nil {
			log.Printf("failed to write response: %v", err)
		}
	})

	http.ListenAndServe(":8080", nil)
}
```
This code creates a new database connection using the `NewDatabase` function, which takes in a configuration file path as an argument. It then sets up two HTTP handlers for reading and writing records to the database. The `/read` handler queries the database for records based on the `key` query parameter and returns them as JSON. The `/write` handler writes a new record to the database using the `WriteRecord` function.

The `ReadRecords` function uses a prepared statement to read records from the database based on the `key` value. It then scans the results into a slice of byte slices and returns them as JSON. The `WriteRecord` function uses a prepared statement to write a new record to the database.

The `Close` function closes the database connection when it is called. This function is only called once, during program termination.

