import logging
import json

def process_log_file(filename):
    try:
        with open(filename, 'r') as file:
            for line in file:
                data = json.loads(line)
                if data['status'] == 'ERROR':
                    logging.error('Error processing log file: %s', filename)
                elif data['status'] == 'WARNING':
                    logging.warning('Warning processing log file: %s', filename)
                else:
                    logging.info('Processed log file: %s', filename)
            return True
    except Exception as e:
        logging.error('Error reading log file: %s', filename)
        logging.error(e)
        return False
