const double backoffFactor = 2;

// Logging level
enum class LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR
};

// Custom logging system
class Logger {
public:
    // Log message with specified log level and context
    void log(LogLevel level, const std::string& msg) {
        switch (level) {
            case LogLevel::DEBUG:
                std::cout << "[Debug] " << msg << std::endl;
                break;
            case LogLevel::INFO:
                std::cout << "[Info] " << msg << std::endl;
                break;
            case LogLevel::WARNING:
                std::cout << "[Warning] " << msg << std::endl;
                break;
            case LogLevel::ERROR:
                std::cout << "[Error] " << msg << std::endl;
                break;
        }
    }
};

// Payment transaction data structure
struct Transaction {
    std::string id;
    double amount;
    std::string cardNumber;
    std::string cardExpiryDate;
    bool processed = false;
};

// Cache for storing previously processed transactions
class TransactionCache {
private:
    // Map of transaction IDs to their processed status
    std::map<std::string, bool> processedTransactions_;

public:
    // Check if a transaction has been processed before
    bool isProcessed(const std::string& id) {
        return processedTransactions_.find(id) != processedTransactions_.end();
    }

    // Mark a transaction as processed
    void markAsProcessed(const std::string& id) {
        processedTransactions_[id] = true;
    }
};

// Thread-safe transaction cache for storing previously processed transactions
class TransactionCacheThreadSafe : public TransactionCache {
private:
    // Mutex for synchronizing access to the cache map
    std::mutex mutex_;

public:
    // Check if a transaction has been processed before (thread-safe)
    bool isProcessed(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        return TransactionCache::isProcessed(id);
    }

    // Mark a transaction as processed (thread-safe)
    void markAsProcessed(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        TransactionCache::markAsProcessed(id);
    }
};

// Function to process a payment transaction using the payment gateway API
void processPaymentTransaction(const Transaction& transaction) {
    // Check if the transaction has already been processed
    if (transaction.processed) {
        Logger::log(LogLevel::INFO, "Transaction " + transaction.id + " has already been processed");
        return;
    }

    // Validate the payment metadata
    validatePaymentMetadata(transaction);

    // Check for rate limiting
    checkRateLimiting();

    // Process the transaction using the payment gateway API
    processTransactionUsingGateway(transaction);
}

// Function to validate the payment metadata
void validatePaymentMetadata(const Transaction& transaction) {
    // Validate the transaction amount
    if (transaction.amount <= 0) {
        Logger::log(LogLevel::ERROR, "Invalid transaction amount: " + std::to_string(transaction.amount));
        return;
    }

    // Validate the card details
    if (!validateCardDetails(transaction.cardNumber)) {
        Logger::log(LogLevel::WARNING, "Invalid card number: " + transaction.cardNumber);
        return;
    }

    // Validate the card expiry date
    if (transaction.cardExpiryDate <= 0) {
        Logger::log(LogLevel::ERROR, "Invalid card expiry date: " + transaction.cardExpiryDate);
        return;
    }
}

// Function to check for rate limiting
void checkRateLimiting() {
    // Check if the current request count exceeds the rate limit
    if (requestCount > rateLimit) {
        Logger::log(LogLevel::WARNING, "Current request count exceeds rate limit: " + std::to_string(rateLimit));
        return;
    }
}

// Function to process a transaction using the payment gateway API
void processTransactionUsingGateway(const Transaction& transaction) {
    // Set up the HTTP client for making requests to the payment gateway API
    CURL* curl = curl_easy_init();
    if (curl) {
        // Set the URL and request method for the API call
        std::string url = paymentGatewayUrl + "/process";
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_POST, 1);

        // Set up the JSON data for the API call
        std::string jsonData = "{\"id\": \"" + transaction.id + "\", \"amount\": " + std::to_string(transaction.amount) + ", \"cardNumber\": \"" + transaction.cardNumber + "\", \"cardExpiryDate\": \"" + transaction.cardExpiryDate + "\"}";
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, jsonData.c_str());

        // Make the API call and handle any errors that occur
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            Logger::log(LogLevel::ERROR, "API call failed: " + std::string(curl_easy_strerror(res)));
            return;
        }
    }
}

// Function to validate a card number using the Luhn algorithm
