    Transaction transaction;
    transaction.id = "1234567890";
    transaction.amount = 10.00;
    transaction.cardNumber = "1234-1234-1234-1234";
    transaction.cardExpiryDate = "12/25";
    processPaymentTransaction(transaction);
    return 0;
}
