#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/conf.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/rand.h>
#include <openssl/x509.h>
#include <openssl/hmac.h>
#include <openssl/safestack.h>
#include <openssl/engine.h>
#include <openssl/crypto.h>

// Global variables
static EVP_CIPHER_CTX *encrypt_ctx;
static EVP_CIPHER_CTX *decrypt_ctx;
static int block_size = 16; // AES-256 block size
static int key_len = 32; // AES-256 key length
static int auth_tag_len = 16; // SHA-256 authentication tag length
static char *key; // Stores the session key
static bool init = false; // Flag to check if the service has been initialized

// Initialize the secure messaging service with a given configuration file.
// The function loads the OpenSSL library and initializes the EVP_CIPHER and EVP_MD contexts.
int initialize(const char *config_file) {
    // Load the OpenSSL library
    SSL_load_error_strings();
    SSL_library_init();

    // Initialize the EVP_CIPHER and EVP_MD contexts
    encrypt_ctx = EVP_CIPHER_CTX_new();
    decrypt_ctx = EVP_CIPHER_CTX_new();

    // Read the configuration file and get the enabled algorithms
    FILE *config = fopen(config_file, "r");
    if (!config) {
        printf("Error opening config file: %s\n", strerror(errno));
        return 1;
    }
    char line[256];
    while (fgets(line, sizeof(line), config)) {
        // Check if the line contains a enabled algorithm
        if (strncmp(line, "ENABLED_ALGORITHMS", strlen("ENABLED_ALGORITHMS")) == 0) {
            char *enabled = strtok(line, ":");
            char *algorithm = strtok(NULL, " ");
            if (strcmp(algorithm, "AES-256") == 0) {
                EVP_CIPHER_CTX_init(encrypt_ctx);
                EVP_EncryptInit_ex(encrypt_ctx, EVP_aes_256_cbc(), NULL, NULL, NULL);
                EVP_CIPHER_CTX_set_padding(encrypt_ctx, 0);
            } else if (strcmp(algorithm, "ChaCha20") == 0) {
                EVP_CIPHER_CTX_init(encrypt_ctx);
                EVP_EncryptInit_ex(encrypt_ctx, EVP_chacha20(), NULL, NULL, NULL);
                EVP_CIPHER_CTX_set_padding(encrypt_ctx, 0);
            } else if (strcmp(algorithm, "SHA-256") == 0) {
                EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
                EVP_DigestInit_ex(md_ctx, EVP_sha256(), NULL);
            } else if (strcmp(algorithm, "SHA-384") == 0) {
                EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
                EVP_DigestInit_ex(md_ctx, EVP_sha384(), NULL);
            } else if (strcmp(algorithm, "SHA-512") == 0) {
                EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
                EVP_DigestInit_ex(md_ctx, EVP_sha512(), NULL);
            }
        }
    }
    fclose(config);

    // Initialize the session key with a random value
    unsigned char random[32];
    RAND_bytes(random, sizeof(random));
    key = malloc(sizeof(char) * 64);
    for (int i = 0; i < 32; i++) {
        key[i] = random[i];
    }

    // Initialize the logging framework
    Log_Init();

    init = true;
    return 0;
}

// Encrypt a message using the specified algorithm.
int encrypt(const char *msg, const char *algorithm) {
    if (!init) {
        printf("Error: Service has not been initialized yet\n");
        return -1;
    }

    // Check if the algorithm is supported
    EVP_CIPHER_CTX *ctx = NULL;
    if (strcmp(algorithm, "AES-256") == 0) {
        ctx = encrypt_ctx;
    } else if (strcmp(algorithm, "ChaCha20") == 0) {
        ctx = encrypt_ctx;
    } else {
        printf("Error: Algorithm not supported\n");
        return -1;
    }

    // Generate a random initialization vector
    unsigned char iv[block_size];
    RAND_bytes(iv, sizeof(iv));

    // Encrypt the message using the specified algorithm and IV
    int len = strlen(msg);
    char ciphertext[len + 1];
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, (unsigned char *)ciphertext, &len, (unsigned char *)msg, len);
    EVP_EncryptFinal_ex(ctx, (unsigned char *)ciphertext + len, &len);

    // Generate an authentication tag using the specified hash algorithm
    unsigned char auth_tag[auth_tag_len];
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
    EVP_DigestInit_ex(md_ctx, EVP_get_digestbyname(algorithm), NULL);
    EVP_DigestUpdate(md_ctx, (unsigned char *)msg, len);
    EVP_DigestFinal_ex(md_ctx, auth_tag, &auth_tag_len);

    // Concatenate the ciphertext and authentication tag
    int total_len = len + auth_tag_len;
    char *encrypted_msg = malloc(sizeof(char) * (total_len + 1));
    memcpy(encrypted_msg, ciphertext, len);
    memcpy(encrypted_msg + len, auth_tag, auth_tag_len);
    encrypted_msg[total_len] = '\0';

    return 0;
}

// Decrypt a message using the specified algorithm.
int decrypt(const char *msg, const char *algorithm) {
    if (!init) {
        printf("Error: Service has not been initialized yet\n");
        return -1;
    }

    // Check if the algorithm is supported
    EVP_CIPHER_CTX *ctx = NULL;
    if (strcmp(algorithm, "AES-256") == 0) {
        ctx = encrypt_ctx;
    } else if (strcmp(algorithm, "ChaCha20") == 0) {
        ctx = encrypt_ctx;
    } else {
        printf("Error: Algorithm not supported\n");
        return -1;
    }

    // Extract the ciphertext and authentication tag from the message
    int len = strlen(msg);
    char *ciphertext = malloc(sizeof(char) * (len + 1));
    memcpy(ciphertext, msg, len);
    ciphertext[len] = '\0';
    unsigned char auth_tag[auth_tag_len];
    memcpy(auth_tag, ciphertext + len - auth_tag_len, auth_tag_len);

    // Decrypt the message using the specified algorithm and IV
    int plaintext_len = len - auth_tag_len;
    char *plaintext = malloc(sizeof(char) * (plaintext_len + 1));
    EVP_DecryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_DecryptUpdate(ctx, (unsigned char *)plaintext, &plaintext_len, (unsigned char *)ciphertext, len - auth_tag_len);
    EVP_DecryptFinal_ex(ctx, (unsigned char *)plaintext + plaintext_len, &plaintext_len);

    // Verify the authentication tag using the specified hash algorithm
    EVP_MD_CTX *md_ctx = EVP_MD_CTX_create();
    EVP_DigestInit_ex(md_ctx, EVP_get_digestbyname(algorithm), NULL);
    EVP_DigestUpdate(md_ctx, (unsigned char *)msg, len - auth_tag_len);
    unsigned char expected_auth_tag[auth_tag_len];
    EVP_DigestFinal_ex(md_ctx, expected_auth_tag, &auth_tag_len);

    if (memcmp(expected_auth_tag, auth_tag, auth_tag_len) != 0) {
        printf("Error: Authentication tag verification failed\n");
        return -1;
    }

    return 0;
}

// Main function for testing the encryption and decryption functions
int main() {
    initialize_openssl();

    char *msg = "Hello, world!";
    encrypt(msg, "AES-256");
    decrypt(msg, "AES-256");

    return 0;
}

