#include <iostream>
#include <vector>
#include <unordered_map>

// Define a struct for an octree node
struct OctreeNode {
    // Data members for the node
    std::vector<double> data;
    std::unordered_map<int, OctreeNode*> children;
};

// Function to initialize an octree with a given feature size, number of initial leaf nodes, and data capacity
void initializeOctree(std::vector<OctreeNode>& octree, int featureSize, int numInitialLeafNodes, int dataCapacity) {
    // Check for invalid input
    if (featureSize < 0 || numInitialLeafNodes < 0 || dataCapacity <= 0) {
        std::cout << "Invalid input: feature size, number of initial leaf nodes, and data capacity must be positive integers." << std::endl;
        return;
    }

    // Allocate memory for the octree and its associated arrays
    octree.resize(featureSize);
    for (int i = 0; i < featureSize; ++i) {
        octree[i].data.reserve(dataCapacity);
        octree[i].children.reserve(numInitialLeafNodes);
    }
}

// Function to insert a new node into the octree
void insertNode(std::vector<OctreeNode>& octree, int featureSize, std::vector<double> data) {
    // Check for invalid input
    if (featureSize < 0 || data.size() <= 0) {
        std::cout << "Invalid input: feature size and data must be positive integers." << std::endl;
        return;
    }

    // Find the appropriate leaf node to insert the new data
    int currentLevel = 0;
    while (currentLevel < featureSize && octree[currentLevel].children.size() == 0) {
        ++currentLevel;
    }

    // Insert the new data into the leaf node
    OctreeNode* node = &octree[currentLevel];
    node->data.push_back(data);

    // If the leaf node is full, split it into child nodes and recursively insert the data
    if (node->data.size() >= octree[currentLevel].data.capacity()) {
        int newChildLevel = currentLevel + 1;
        while (newChildLevel < featureSize && octree[newChildLevel].children.size() > 0) {
            ++newChildLevel;
        }
        if (newChildLevel < featureSize) {
            // Split the leaf node into child nodes
            int numChildren = std::pow(2, newChildLevel - currentLevel);
            for (int i = 0; i < numChildren; ++i) {
                OctreeNode* newChild = new OctreeNode();
                newChild->data.reserve(octree[currentLevel].data.capacity() / numChildren);
                node->children.emplace(std::make_pair(i, newChild));
            }
            // Recursively insert the data into the child nodes
            for (int i = 0; i < node->data.size(); ++i) {
                int childIndex = i % numChildren;
                OctreeNode* child = node->children[childIndex];
                child->data.push_back(node->data[i]);
            }
        }
    }
}

// Function to remove a node from the octree
void removeNode(std::vector<OctreeNode>& octree, int featureSize, std::vector<double> data) {
    // Check for invalid input
    if (featureSize < 0 || data.size() <= 0) {
        std::cout << "Invalid input: feature size and data must be positive integers." << std::endl;
        return;
    }

    // Find the appropriate leaf node to remove the data from
    int currentLevel = 0;
    while (currentLevel < featureSize && octree[currentLevel].children.size() == 0) {
        ++currentLevel;
    }

    // Remove the data from the leaf node
    OctreeNode* node = &octree[currentLevel];
    for (int i = 0; i < node->data.size(); ++i) {
        if (node->data[i] == data) {
            node->data.erase(node->data.begin() + i);
            break;
        }
    }

    // If the leaf node is empty, merge it with its sibling nodes and recursively remove the data
    if (node->data.size() == 0) {
        int parentLevel = currentLevel - 1;
        while (parentLevel >= 0 && octree[parentLevel].children.size() == 0) {
            --parentLevel;
        }
        if (parentLevel >= 0) {
            // Merge the leaf node with its sibling nodes
            OctreeNode* parent = &octree[parentLevel];
            int childIndex = currentLevel - parentLevel;
            for (int i = childIndex + 1; i < octree[parentLevel].children.size(); ++i) {
                OctreeNode* child = octree[parentLevel].children[i];
                node->data.insert(node->data.end(), child->data.begin(), child->data.end());
            }
            // Recursively remove the data from the parent node
            removeNode(octree, featureSize, data);
        }
    }
}

// Function to serialize and deserialize an octree for persistence and integration with external systems
void serializeOctree(const std::vector<OctreeNode>& octree, std::string& serializedData) {
    // Serialize the octree into a string
    serializedData = "";
    for (int i = 0; i < featureSize; ++i) {
        OctreeNode* node = &octree[i];
        for (const auto& data : node->data) {
            serializedData += std::to_string(data) + " ";
        }
        for (const auto& child : node->children) {
            serializeOctree(child.second, serializedData);
        }
    }
}

void deserializeOctree(std::vector<OctreeNode>& octree, const std::string& serializedData) {
    // Deserialize the serialized data into an octree
    int currentLevel = 0;
    while (currentLevel < featureSize && octree[currentLevel].children.size() == 0) {
        ++currentLevel;
    }

    // Split the serialized data into individual nodes and insert them into the octree
    std::vector<std::string> nodes = split(serializedData, " ");
    for (int i = 0; i < nodes.size(); ++i) {
        OctreeNode* node = &octree[currentLevel];
        node->data.push_back(std::stod(nodes[i]));
        while (node->data.size() >= octree[currentLevel].data.capacity()) {
            int newChildLevel = currentLevel + 1;
            while (newChildLevel < featureSize && octree[newChildLevel].children.size() > 0) {
                ++newChildLevel;
            }
            if (newChildLevel < featureSize) {
                // Split the leaf node into child nodes
                int numChildren = std::pow(2, newChildLevel - currentLevel);
                for (int i = 0; i < octree[parentLevel].children.size(); ++i) {
                    OctreeNode* child = octree[parentLevel].children[i];
                    node->data.insert(node->data.end(), child->data.begin(), child->data.end());
                }
            }
        }
    }
}

// Split a string into an array of substrings based on a delimiter
std::vector<std::string> split(const std::string& s, char delimiter) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream stream(s);
    while (std::getline(stream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

