#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdbool.h>

// Define the maximum number of semaphore instances that can be created
#define MAX_SEMAPHORES 10

// Define the initial value for each semaphore instance
static int default_value = 0;

// Define the maximum value for each semaphore instance
static int max_value = 10;

// Define the minimum value for each semaphore instance
static int min_value = 0;

// Define the name of the semaphore instances
static char* semaphore_names[MAX_SEMAPHORES] = {NULL};

// Define the semaphore handles for each instance
static sem_t* semaphores[MAX_SEMAPHORES];

// Define the number of times each semaphore was acquired and released
static int acquire_counts[MAX_SEMAPHORES] = {0};
static int release_counts[MAX_SEMAPHORES] = {0};

/**
 * Create a new semaphore with the specified name, initial value, and maximum value.
 * If the name is already in use, return NULL and log an error message.
 */
sem_t* create_semaphore(const char* name, int initial_value, int max_value) {
    // Check if the name is already in use
    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        if (semaphores[i] && strcmp(name, semaphore_names[i]) == 0) {
            fprintf(stderr, "Semaphore name '%s' already in use\n", name);
            return NULL;
        }
    }

    // Create a new semaphore with the specified initial value and maximum value
    sem_t* semaphore = malloc(sizeof(sem_t));
    if (semaphore == NULL) {
        fprintf(stderr, "Failed to allocate memory for semaphore\n");
        return NULL;
    }
    if (sem_init(semaphore, 0, initial_value) < 0) {
        fprintf(stderr, "Failed to initialize semaphore: %s\n", strerror(errno));
        free(semaphore);
        return NULL;
    }

    // Set the maximum value for the semaphore
    if (max_value > 0) {
        if (sem_set_value(semaphore, max_value) < 0) {
            fprintf(stderr, "Failed to set maximum value for semaphore: %s\n", strerror(errno));
            free(semaphore);
            return NULL;
        }
    }

    // Add the new semaphore to the list of created semaphores
    int i = 0;
    while (i < MAX_SEMAPHORES && semaphores[i] != NULL) {
        i++;
    }
    if (i >= MAX_SEMAPHORES) {
        fprintf(stderr, "Too many semaphores created\n");
        free(semaphore);
        return NULL;
    }
    semaphores[i] = semaphore;
    strncpy(semaphore_names[i], name, MAX_SEMAPHORES - 1);

    // Return the new semaphore handle
    return semaphore;
}

/**
 * Delete a semaphore with the specified name. If the name is not in use, log an error message.
 */
bool delete_semaphore(const char* name) {
    for (int i = 0; i < MAX_SEMAPHORES; i++) {
        if (semaphores[i] && strcmp(name, semaphore_names[i]) == 0) {
            // Destroy the semaphore and free its resources
            sem_destroy(semaphores[i]);
            free(semaphores[i]);

            // Remove the semaphore from the list of created semaphores
            for (int j = i; j < MAX_SEMAPHORES - 1; j++) {
                semaphores[j] = semaphores[j + 1];
                strncpy(semaphore_names[j], semaphore_names[j + 1], MAX_SEMAPHORES - 1);
            }

            // Return success
            return true;
        }
    }

    // Log an error message if the name is not in use
    fprintf(stderr, "Semaphore name '%s' not found\n", name);
    return false;
}

/**
 * Acquire a semaphore with the specified name. If the semaphore cannot be acquired within the specified timeout, log an error message and return failure.
 */
bool acquire_semaphore(const char* name, int timeout) {
    // Find the semaphore handle for the specified name
    int i = 0;
    while (i < MAX_SEMAPHORES && strcmp(name, semaphore_names[i]) != 0) {
        i++;
    }
    if (i >= MAX_SEMAPHORES) {
        fprintf(stderr, "Semaphore name '%s' not found\n", name);
        return false;
    }

    // Acquire the semaphore with the specified timeout
    int ret = 0;
    if (timeout > 0) {
        ret = sem_trywait(semaphores[i]);
    } else {
        ret = sem_wait(semaphores[i]);
    }
    if (ret < 0 && errno != EAGAIN) {
        fprintf(stderr, "Failed to acquire semaphore: %s\n", strerror(errno));
        return false;
    } else if (ret == 0) {
        // Log the successful acquisition of the semaphore
        fprintf(stdout, "Acquired semaphore '%s'\n", name);

        // Increment the number of acquired semaphores for the thread
        pthread_mutex_lock(&mutex);
        num_acquired[i]++;
        pthread_mutex_unlock(&mutex);
    }

    // Return success or failure based on the outcome of the acquisition attempt
    return ret == 0;
}

/**
 * Release a semaphore with the specified name. If the semaphore is not currently acquired, log an error message and return failure.
 */
bool release_semaphore(const char* name) {
    // Find the semaphore handle for the specified name
    int i = 0;
    while (i < MAX_SEMAPHORES && strcmp(name, semaphore_names[i]) != 0) {
        i++;
    }
    if (i >= MAX_SEMAPHORES) {
        fprintf(stderr, "Semaphore name '%s' not found\n", name);
        return false;
    }

    // Release the semaphore
    int ret = sem_post(semaphores[i]);
    if (ret < 0) {
        fprintf(stderr, "Failed to release semaphore: %s\n", strerror(errno));
        return false;
    } else if (ret == 0) {
        // Log the successful release of the semaphore
        fprintf(stdout, "Released semaphore '%s'\n", name);

        // Decrement the number of acquired semaphores for the thread
        pthread_mutex_lock(&mutex);
        num_acquired[i]--;
        pthread_mutex_unlock(&mutex);
    }

    // Return success or failure based on the outcome of the release attempt
    return ret == 0;
}

/**
 * Test whether a semaphore with the specified name is currently acquired. If the semaphore is not in use, log an error message and return false.
 */
bool is_semaphore_acquired(const char* name) {
    // Find the semaphore handle for the specified name
    int i = 0;
    while (i < MAX_SEMAPHORES && strcmp(name, semaphore_names[i]) != 0) {
        i++;
    }
    if (i >= MAX_SEMAPHORES) {
        fprintf(stderr, "Semaphore name '%s' not found\n", name);
        return false;
    }

    // Return whether the semaphore is currently acquired or not
    return num_acquired[i] > 0;
}

