import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.yaml.snakeyaml.*;

public class HybridAutomationTool {
  private static final String CONFIG_FILE = "config.yml";
  private static final int LOG_LEVEL_DEBUG = 0;
  private static final int LOG_LEVEL_INFO = 1;
  private static final int LOG_LEVEL_WARN = 2;
  private static final int LOG_LEVEL_ERROR = 3;

  private Map<String, String> envConfig; // Environment-specific settings
  private List<Command> commands; // List of commands to execute
  private Logger logger; // Logger instance for logging messages

  public HybridAutomationTool(Map<String, String> config) {
    this.envConfig = config;
    this.commands = new ArrayList<>();
    this.logger = new Logger();
  }

  public void addCommand(String command) {
    this.commands.add(new Command(command));
  }

  public void executeCommands() throws Exception {
    for (Command cmd : commands) {
      ProcessBuilder pb = new ProcessBuilder(cmd.getCommand());
      Map<String, String> env = pb.environment();
      env.putAll(envConfig);

      // Check and conditionally delete files before executing the command
      checkAndDeleteFiles(cmd.getFilesToCheck());

      // Execute the command and read its output and error streams
      Process process = pb.start();
      BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
      String line;
      while ((line = reader.readLine()) != null) {
        logger.log(LOG_LEVEL_INFO, "Command output: " + line);
      }

      BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
      String error;
      while ((error = errorReader.readLine()) != null) {
        logger.log(LOG_LEVEL_ERROR, "Command error: " + error);
      }
    }
  }

  private void checkAndDeleteFiles(List<String> filesToCheck) throws IOException {
    for (String file : filesToCheck) {
      Path path = Paths.get(file);
      if (Files.exists(path)) {
        Files.delete(path);
        logger.log(LOG_LEVEL_WARN, "Deleted file: " + file);
      }
    }
  }

  private void logMessage(int level, String message) {
    switch (level) {
      case LOG_LEVEL_DEBUG:
        System.out.println("[DEBUG] " + message);
        break;
      case LOG_LEVEL_INFO:
        System.out.println("[INFO] " + message);
        break;
      case LOG_LEVEL_WARN:
        System.out.println("[WARN] " + message);
        break;
      case LOG_LEVEL_ERROR:
        System.err.println("[ERROR] " + message);
        break;
    }
  }
}

class Command {
  private String command; // The command to execute
  private List<String> filesToCheck; // Files to check and delete before executing the command

  public Command(String command) {
    this.command = command;
    this.filesToCheck = new ArrayList<>();
  }

  public String getCommand() {
    return command;
  }

  public List<String> getFilesToCheck() {
    return filesToCheck;
  }
}

class Logger {
  private Map<String, Integer> logLevels = new HashMap<>();

  public void log(int level, String message) {
    if (logLevels.get(level) != null && logLevels.get(level) >= level) {
      System.out.println("[" + LocalDateTime.now() + "] " + message);
    }
  }
}
