#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <limits.h>
#include <assert.h>
#include "database.h"

// Structure to hold record data
struct Record {
    long id;
    double timestamp;
    char* tags[]; // array of strings
    char* metadata[]; // array of strings
    char* server_specific_data[]; // array of strings
    int status_flag;
};

// Structure to hold the database state
struct Database {
    struct Record** records; // pointer to an array of pointers to records
    pthread_mutex_t lock; // mutex for synchronizing access to the database
    sem_t sem; // semaphore for waiting on available servers
};

// Function to initialize the database with the given number of records
void db_init(struct Database* db, int num_records) {
    db->records = (struct Record**)malloc(sizeof(struct Record*) * num_records);
    for (int i = 0; i < num_records; i++) {
        db->records[i] = NULL;
    }
    pthread_mutex_init(&db->lock, NULL);
    sem_init(&db->sem, 0, 1); // 1 available server
}

// Function to allocate memory for a new record and add it to the database
int db_add_record(struct Database* db, struct Record* record) {
    pthread_mutex_lock(&db->lock);
    int i;
    for (i = 0; i < MAX_NUM_RECORDS; i++) {
        if (db->records[i] == NULL) {
            db->records[i] = record;
            break;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return i < MAX_NUM_RECORDS ? 0 : -1; // return error if no space left in database
}

// Function to update the status flag of a record in the database
void db_update_status(struct Database* db, long id, int new_status) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < MAX_NUM_RECORDS; i++) {
        if (db->records[i] != NULL && db->records[i]->id == id) {
            db->records[i]->status_flag = new_status;
            break;
        }
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to retrieve a record from the database by its ID
struct Record* db_get_record(struct Database* db, long id) {
    struct Record* result = NULL;
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < MAX_NUM_RECORDS; i++) {
        if (db->records[i] != NULL && db->records[i]->id == id) {
            result = db->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&db->lock);
    return result;
}

// Function to remove a record from the database by its ID
void db_remove_record(struct Database* db, long id) {
    pthread_mutex_lock(&db->lock);
    for (int i = 0; i < MAX_NUM_RECORDS; i++) {
        if (db->records[i] != NULL && db->records[i]->id == id) {
            free(db->records[i]);
            db->records[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to wait for an available server and acquire it
void db_acquire_server(struct Database* db) {
    sem_wait(&db->sem); // wait on available server
}

// Function to release a previously acquired server
void db_release_server(struct Database* db) {
    sem_post(&db->sem); // release available server
}

// Custom load balancing algorithm that selects the server with the lowest load average
int db_select_server(struct Database* db, int num_servers) {
    int min_load = INT_MAX;
    int selected_server = -1;
    for (int i = 0; i < num_servers; i++) {
        if (db->servers[i].load_average < min_load) {
            min_load = db->servers[i].load_average;
            selected_server = i;
        }
    }
    return selected_server;
}

// Function to handle a read operation on the database
void* db_read(struct Database* db, long id) {
    struct Record* record = db_get_record(db, id);
    if (record == NULL) {
        printf("Error: No record with ID %ld found in database\n", id);
        return NULL;
    }
    // Handle read operation on record
    return record;
}

// Function to handle a write operation on the database
void db_write(struct Database* db, struct Record* record) {
    // Acquire available server
    db_acquire_server(db);
    // Add record to database if it does not already exist
    if (db_add_record(db, record) != 0) {
        printf("Error: Could not add new record to database\n");
    }
    // Release acquired server
    db_release_server(db);
}

// Function to handle a delete operation on the database
void db_delete(struct Database* db, long id) {
    struct Record* record = db_get_record(db, id);
    if (record == NULL) {
        printf("Error: No record with ID %ld found in database\n", id);
    } else {
        // Remove record from database
        db_remove_record(db, id);
    }
}

// Function to handle a update operation on the database
void db_update(struct Database* db, long id, int new_status) {
    struct Record* record = db_get_record(db, id);
    if (record == NULL) {
        printf("Error: No record with ID %ld found in database\n", id);
    } else {
        // Update status of record
        db_update_record(db, id, new_status);
    }
}
