    public static List<Pokemon> Deserialize(string filePath) {
        try {
            using (var fileStream = new FileStream(filePath, FileMode.Open)) {
                var formatter = new BinaryFormatter();
                var pokemonList = (List<Pokemon>)formatter.Deserialize(fileStream);

                // Perform versioning by checking the serialization header of the binary file
                if (pokemonList.SerializationHeader != "POKEMON_V2") {
                    throw new Exception("Unsupported serialization version");
                }

                return pokemonList;
            }
