    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        // DNS resolution failed, return error code
        return -errno;
    }

    for (int i = 0; host->h_addr_list[i] != NULL; i++) {
        u_char *ipv4_addr = host->h_addr_list[i];
        callback(ipv4_addr);
    }

    return 0;
}

