const loadAndRunTests = (testConfig) => {
  const db = require('./database');
  const blueslip = require('blueslip');
  const tests = testConfig.tests;
  const moduleName = testConfig.moduleName;

  // Load the module
  let module;
  try {
    module = require(`./${moduleName}`);
  } catch (err) {
    console.error(`Error loading module ${moduleName}: ${err}`);
    return;
  }

  // Initialize the forward list and mocking library
  const forwardList = [];
  blueslip.reset();

  // Run the tests
  for (const test of tests) {
    try {
      const result = module[test]();
      console.log(`Test ${test} passed!`);
      forwardList.push({ test, result });
    } catch (err) {
      console.error(`Error running test ${test}: ${err}`);
      blueslip.reset();
    }
  }

  // Save the results to the database and log them
  const timestamp = new Date().getTime();
  db.saveTestResults(moduleName, forwardList, timestamp);
  console.log(`Saved test results for ${moduleName} at ${timestamp}`);

  // Reset the mocking library after each test
  blueslip.reset();
};
```
