import os
import subprocess
import threading
import time
from typing import List, Optional

class CommandExecutor:
    def __init__(self, max_concurrent_processes: int = 5) -> None:
        self._max_concurrent_processes = max_concurrent_processes
        self._active_processes = {}

    def execute(self, command: str, timeout: float = 0.0, cwd: Optional[str] = None) -> str:
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        if timeout > 0:
            process.wait(timeout)
        output = process.stdout.read().decode()
        return output.strip()

    def execute_async(self, command: str, timeout: float = 0.0, cwd: Optional[str] = None) -> threading.Thread:
        if len(self._active_processes) >= self._max_concurrent_processes:
            raise RuntimeError("Maximum number of concurrent processes reached")
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        thread = threading.Thread(target=self._monitor_process, args=(process,))
        self._active_processes[thread] = process
        return thread

    def _monitor_process(self, process: subprocess.Popen):
        try:
            output = process.stdout.read().decode()
            if output:
                print(output)
        except Exception as e:
            print(f"Error occurred while monitoring process: {e}")
        finally:
            self._active_processes.pop(threading.current_thread())

    def cancel(self, thread: threading.Thread):
        try:
            process = self._active_processes[thread]
            process.terminate()
        except Exception as e:
            print(f"Error occurred while cancelling process: {e}")
        finally:
            del self._active_processes[thread]

class CommandChain:
    def __init__(self, commands: List[str], timeout: float = 0.0, cwd: Optional[str] = None) -> None:
        self._commands = commands
        self._timeout = timeout
        self._cwd = cwd

    def execute(self):
        output = ""
        for command in self._commands:
            try:
                output += self.execute_async(command).get() + "\n"
            except Exception as e:
                print(f"Error occurred while executing command chain: {e}")
                break
        return output

    def execute_async(self, command: str) -> threading.Thread:
        if len(self._active_processes) >= self._max_concurrent_processes:
            raise RuntimeError("Maximum number of concurrent processes reached")
        process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        thread = threading.Thread(target=self._monitor_process, args=(process,))
        self._active_processes[thread] = process
        return thread

    def _monitor_process(self, process: subprocess.Popen):
        try:
            output = process.stdout.read().decode()
            if output:
                print(output)
        except Exception as e:
            print(f"Error occurred while monitoring process: {e}")
        finally:
            self._active_processes.pop(threading.current_thread())

    def cancel(self, thread: threading.Thread):
        try:
            process = self._active_processes[thread]
            process.terminate()
        except Exception as e:
            print(f"Error occurred while cancelling process: {e}")
        finally:
            del self._active_processes[thread]

class CommandRateLimiter:
    def __init__(self, limit: int = 10) -> None:
        self._limit = limit
        self._current_requests = 0

    def request(self):
        if self._current_requests < self._limit:
            self._current_requests += 1
            return True
        else:
            return False

    def release(self):
        if self._current_requests > 0:
            self._current_requests -= 1

class CommandTimeout:
    def __init__(self, timeout: float = 60.0) -> None:
        self._timeout = timeout
        self._start_time = time.time()

    def is_expired(self):
        if time.time() - self._start_time >= self._timeout:
            return True
        else:
            return False

class CommandResourceUsageMonitor:
