import hashlib
import json
from typing import Dict, List, Optional

import mysql.connector as mysql
import pymongo
import psycopg2

class DatabaseConnector:
    def __init__(self, db_config: Dict[str, str], cache_size: int = 100):
        self.db_config = db_config
        self.cache = {}
        self.cache_size = cache_size
        self.connections = {
            "mysql": mysql.connect(**self.db_config),
            "postgres": psycopg2.connect(**self.db_config),
            "mongo": pymongo.MongoClient(**self.db_config)
        }

    def close(self):
        for conn in self.connections.values():
            conn.close()

    def execute(self, operation: str, data: Dict[str, Any], batch_size: int = 1000):
        # Validate data integrity using checksums
        data["checksum"] = hashlib.md5(json.dumps(data).encode("utf-8")).hexdigest()

        # Check if the operation is idempotent and the cache contains the result
        if self.is_idempotent(operation) and data["checksum"] in self.cache:
            return self.cache[data["checksum"]]

        # Connect to the appropriate database system based on the configuration settings
        db = self.connections[self.db_config["system"]]

        # Execute the operation and handle errors
        try:
            if operation == "insert":
                result = db.insert(data)
            elif operation == "update":
                result = db.update(data)
            elif operation == "delete":
                result = db.delete(data)
            else:
                raise ValueError("Invalid operation")
        except Exception as e:
            # Retry failed operations and handle transient errors gracefully
            if self.is_transient(e):
                return self.execute(operation, data, batch_size)
            else:
                raise e from None

        # Store the result in the cache
        self.cache[data["checksum"]] = result

        # Return the result of the operation
        return result

    def is_idempotent(self, operation):
        return operation in ["insert", "update"]

    def is_transient(self, error):
        return type(error) == ConnectionError or type(error) == TimeoutError

    def clear_cache(self):
        self.cache = {}
