import time
from datetime import datetime
from collections import defaultdict
from threading import Lock
from concurrent.futures import ThreadPoolExecutor

class UserSession:
    def __init__(self, user_id):
        self.user_id = user_id
        self.start_time = None
        self.end_time = None
        self.device_info = defaultdict(int)
        self.activity_logs = []

    def add_log(self, log):
        if not self.start_time:
            self.start_time = log["timestamp"]
        self.end_time = log["timestamp"]
        self.device_info[log["device_info"]] += 1
        self.activity_logs.append(log)

    def get_average_time_spent(self):
        total_time = 0
        for device, time_spent in self.device_info.items():
            total_time += time_spent * device["avg_usage"]
        return total_time / len(self.device_info)

    def get_most_active_devices(self):
        most_active_devices = []
        for device, time_spent in self.device_info.items():
            if time_spent > 0:
                most_active_devices.append((device["name"], time_spent))
        return most_active_devices

    def get_top_devices(self):
        top_devices = []
        for device, time_spent in self.device_info.items():
            if time_spent > 0:
                top_devices.append((device["name"], time_spent))
        return top_devices

    def get_user_id(self):
        return self.user_id

class UserSessionManager:
    def __init__(self, user_sessions=None):
        if not user_sessions:
            user_sessions = {}
        self.user_sessions = user_sessions
        self.lock = Lock()

    def get_session(self, user_id):
        with self.lock:
            session = self.user_sessions.get(user_id)
            if not session:
                session = UserSession(user_id)
                self.user_sessions[user_id] = session
            return session

    def add_log(self, log):
        with self.lock:
            user_id = log["user_id"]
            session = self.get_session(user_id)
            session.add_log(log)

    def get_sessions(self):
        return list(self.user_sessions.values())

def process_user_activity_logs(logs, settings=None):
    if not settings:
        settings = {}
    activity_age_threshold = settings.get("activity_age_threshold", 30)
    max_activity_logs_per_second = settings.get("max_activity_logs_per_second", 50)
    average_time_spent_threshold = settings.get("average_time_spent_threshold", 300)
    user_session_manager = UserSessionManager()
    for log in logs:
        timestamp = log["timestamp"]
        if datetime.now() - timestamp < timedelta(seconds=activity_age_threshold):
            user_id = log["user_id"]
            session = user_session_manager.get_session(user_id)
            session.add_log(log)
            if len(session.activity_logs) > max_activity_logs_per_second:
                session.activity_logs = session.activity_logs[-max_activity_logs_per_second:]
            average_time_spent = session.get_average_time_spent()
            if average_time_spent > average_time_spent_threshold:
                device_info = log["device_info"]
                external_api.send_alert(user_id, device_info, "High usage detected")
    user_sessions = user_session_manager.get_sessions()
    for session in user_sessions:
        average_time_spent = session.get_average_time_spent()
        if average_time_spent > average_time_spent_threshold:
            device_info = session.get_most_active_devices()
            external_api.send_alert(session.get_user_id(), device_info, "High usage detected")
    for session in user_sessions:
        average_time_spent = session.get_average_time_spent()
        if average_time_spent > average_time_spent_threshold:
            device_info = session.get_top_devices()
            database.persist(session.get_user_id(), device_info)
