import os
import json
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from urllib.request import urlopen

class FileHasher:
    def __init__(self, api_url, concurrency=8):
        self.api_url = api_url
        self.concurrency = concurrency

    def get_hash(self, filepath):
        with open(filepath, "rb") as f:
            hash_value = hashlib.md5(f.read()).hexdigest()
        return hash_value

    def store_hash(self, hash_value, filepath):
        try:
            response = urlopen(self.api_url + "?file=" + filepath + "&hash=" + hash_value)
            if response.getcode() != 201:
                raise Exception("Failed to store hash value")
        except Exception as e:
            print("Error storing hash value:", e)

    def retrieve_hash(self, filepath):
        try:
            response = urlopen(self.api_url + "?file=" + filepath)
            if response.getcode() != 200:
                raise Exception("Failed to retrieve hash value")
            json_data = json.loads(response.read())
            return json_data["hash"]
        except Exception as e:
            print("Error retrieving hash value:", e)

    def verify_hash(self, filepath):
        calculated_hash = self.get_hash(filepath)
        stored_hash = self.retrieve_hash(filepath)
        if calculated_hash != stored_hash:
            print("Hash mismatch for", filepath)

    def hash_files(self, files):
        with ThreadPoolExecutor(max_workers=self.concurrency) as executor:
            futures = []
            for file in files:
                future = executor.submit(self.verify_hash, file)
                futures.append(future)
            for future in futures:
                try:
                    future.result()
                except Exception as e:
                    print("Error hashing file:", e)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--api-url", type=str, required=True, help="API URL for storing and retrieving hash values")
    parser.add_argument("--concurrency", type=int, default=8, help="Concurrency level for hashing files (default: 8)")
    args = parser.parse_args()

    file_hasher = FileHasher(api_url=args.api_url, concurrency=args.concurrency)
    files = [os.path.join("files", f) for f in os.listdir("files")]
    file_hasher.hash_files(files)
