import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutionException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ConfigureAndDeployService {
    private static final Logger LOGGER = Logger.getLogger(ConfigureAndDeployService.class.getName());

    public static String deployService(String serviceName, String region, Map<String, String> configParams) throws IOException, ExecutionException, InterruptedException {
        // Check if the service.yaml file exists in the specified directory
        File serviceYamlFile = new File("service.yaml");
        if (!serviceYamlFile.exists()) {
            LOGGER.log(Level.SEVERE, "Missing service configuration file: service.yaml");
            return "Error: Missing service configuration file";
        }

        // Validate the service name and region
        if (serviceName == null || serviceName.isEmpty()) {
            LOGGER.log(Level.SEVERE, "Invalid service name: null or empty");
            return "Error: Invalid service name";
        }
        if (region == null || region.isEmpty()) {
            LOGGER.log(Level.SEVERE, "Invalid region: null or empty");
            return "Error: Invalid region";
        }

        // Calculate the SHA-256 hash of the service configuration file
        String configFileHash = calculateFileSha256(serviceYamlFile);
        if (configFileHash == null) {
            LOGGER.log(Level.SEVERE, "Failed to calculate SHA-256 hash for service configuration file");
            return "Error: Failed to calculate SHA-256 hash";
        }

        // Deploy the new service instance using the external API
        try {
            String deploymentResponse = deployServiceInstance(serviceName, region, configParams, configFileHash);
            if (deploymentResponse == null) {
                LOGGER.log(Level.SEVERE, "Failed to deploy service instance");
                return "Error: Failed to deploy service instance";
            }
            return deploymentResponse;
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "API interaction error", e);
            return "Error: API interaction error";
        }
    }

    private static String calculateFileSha256(File file) throws IOException {
        // Read the file in chunks to optimize memory usage
        FileInputStream inputStream = new FileInputStream(file);
        byte[] buffer = new byte[1024];
        MessageDigest digester = null;
        try {
            digester = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Failed to calculate SHA-256 hash", e);
            return null;
        }
        int read = 0;
        while ((read = inputStream.read(buffer)) > 0) {
            digester.update(buffer, 0, read);
        }
        byte[] shaHash = digester.digest();
        return bytesToHex(shaHash);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexBuilder = new StringBuilder();
        for (byte b : bytes) {
            hexBuilder.append(String.format("%02x", b));
        }
        return hexBuilder.toString();
    }
}
