// Define a struct to hold the summary statistics for each file
typedef struct {
  int num_logs;
  long total_bytes;
} file_stats_t;

// Define a function to validate a log file against a JSON schema
int validate_json(const char *filepath, json_object *schema) {
  // Open the file and create a new JSON parser object
  FILE *fp = fopen(filepath, "r");
  json_parser *parser = json_parser_new();

  // Set the JSON schema for validation
  json_parser_set_schema(parser, schema);

  // Read the file line by line and validate each line against the schema
  char buf[1024];
  while (fgets(buf, sizeof(buf), fp)) {
    if (!json_parser_load_string(parser, buf)) {
      json_parser_error_t error = json_parser_get_error(parser);
      printf("Error parsing JSON: %s\n", error.text);
      return 1;
    }
  }

  // Clean up the parser and file
  json_parser_free(parser);
  fclose(fp);

  // Return success
  return 0;
}

// Define a function to aggregate summary statistics from a log file
void aggregate_stats(const char *filepath, file_stats_t *stats) {
  // Open the file and create a new JSON parser object
  FILE *fp = fopen(filepath, "r");
  json_parser *parser = json_parser_new();

  // Set the JSON schema for validation
  json_parser_set_schema(parser, stats->schema);

  // Read the file line by line and validate each line against the schema
  char buf[1024];
  while (fgets(buf, sizeof(buf), fp)) {
    if (!json_parser_load_string(parser, buf)) {
      json_parser_error_t error = json_parser_get_error(parser);
      printf("Error parsing JSON: %s\n", error.text);
      return;
    }

    // Increment the number of logs and total bytes read
    stats->num_logs++;
    stats->total_bytes += strlen(buf);
  }

  // Clean up the parser and file
  json_parser_free(parser);
  fclose(fp);
}

// Define a function to process a log file
void process_log(const char *filepath) {
  // Check if the file exists
  struct stat st;
  if (stat(filepath, &st) == -1) {
    perror("Error checking file:");
    return;
  }

  // Open the file and create a new JSON parser object
  FILE *fp = fopen(filepath, "r");
  json_parser *parser = json_parser_new();

  // Set the JSON schema for validation
  json_parser_set_schema(parser, stats->schema);

  // Read the file line by line and validate each line against the schema
  char buf[1024];
  while (fgets(buf, sizeof(buf), fp)) {
    if (!json_parser_load_string(parser, buf)) {
      json_parser_error_t error = json_parser_get_error(parser);
      printf("Error parsing JSON: %s\n", error.text);
      return;
    }

    // Increment the number of logs and total bytes read
    stats->num_logs++;
    stats->total_bytes += strlen(buf);
  }

  // Clean up the parser and file
  json_parser_free(parser);
  fclose(fp);
}

// Define a function to read log files from a directory
void read_logs(const char *directory) {
  // Open the directory
  DIR *dp = opendir(directory);
  if (dp == NULL) {
    perror("Error opening directory:");
    return;
  }

  // Loop through each file in the directory and process it
  struct dirent *ep;
  while ((ep = readdir(dp)) != NULL) {
    char *filename = ep->d_name;
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", directory, filename);

    // Check if the file is a log file
    if (strncmp(filename, "log", 3) == 0 || strncmp(filename, "json", 4) == 0 || strncmp(filename, "csv", 3) == 0) {
      process_log(path);
    } else {
      printf("Error: file %s is not a log file\n", filename);
      return;
    }
  }

  // Clean up the directory stream
  closedir(dp);
}

// Define a function to read multiple log files from a directory and validate their content against a JSON schema
void aggregate_stats_async(const char *directory, json_object *schema) {
  // Create a new thread for asynchronous processing
  pthread_t thread;
  int err = pthread_create(&thread, NULL, read_logs, directory);
  if (err != 0) {
    perror("Error creating thread:");
    return;
  }

  // Create a new JSON parser object for the schema
  json_parser *schema_parser = json_parser_new();

  // Set the JSON schema for validation
  json_parser_set_schema(schema_parser, schema);

  // Loop through each file in the directory and validate its content against the schema
  struct dirent *ep;
  while ((ep = readdir(dp)) != NULL) {
    char *filename = ep->d_name;
    char path[1024];
    snprintf(path, sizeof(path), "%s/%s", directory, filename);

    // Check if the file is a log file
    if (strncmp(filename, "log", 3) == 0 || strncmp(filename, "json", 4) == 0 || strncmp(filename, "csv", 3) == 0) {
      validate_json(path, schema);
    } else {
      printf("Error: file %s is not a log file\n", filename);
      return;
    }
  }

  // Clean up the parser and directory stream
  json_parser_free(schema_parser);
  closedir(dp);
}
