#include <string.h>
#include <stdlib.h>

char* appendSlash(const char* input, size_t limit)
{
    if (input == nullptr || limit == 0) return NULL;

    size_t len = strlen(input);
    if (len >= limit) return NULL;

    char* output = malloc(limit + 1);
    memcpy(output, input, len);
    output[len] = '/';
    output[len+1] = '\0';

    return output;
}
