```java
import java.util.Arrays;

public class DisjointPairs {
    private static int[] unionFind; // Union-Find structure for efficient disjointness checks
    private static int count; // Number of disjoint pairs found
    private static long totalTime; // Total time taken to perform the check for each pair

    public static void main(String[] args) {
        // Read input array from user
        int[] input = readInput();

        // Initialize Union-Find structure with default values
        unionFind = new int[input.length];
        Arrays.fill(unionFind, -1);

        // Perform Union-Find operations concurrently with other tasks in the application
        for (int i = 0; i < input.length; i++) {
            for (int j = i + 1; j < input.length; j++) {
                if (!isDisjoint(i, j)) {
                    continue; // Skip pairs that are not disjoint
                }

                // Perform Union-Find operations
                int root1 = findRoot(i);
                int root2 = findRoot(j);
                if (root1 == root2) {
                    continue; // Skip pairs that are already connected
                }

                // Merge the two roots and update the count
                unionFind[root2] = root1;
                count++;
            }
        }

        System.out.println("Number of disjoint pairs: " + count);
        System.out.println("Total time taken: " + totalTime + " milliseconds");
    }

    // Helper method to read input array from user
    private static int[] readInput() {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the length of the integer array: ");
        int len = scanner.nextInt();
        int[] input = new int[len];
        for (int i = 0; i < len; i++) {
            System.out.printf("Enter element %d: ", i + 1);
            input[i] = scanner.nextInt();
        }
        return input;
    }

    // Helper method to find the root of an element in Union-Find structure
    private static int findRoot(int x) {
        while (unionFind[x] >= 0) {
            x = unionFind[x];
        }
        return x;
    }

    // Helper method to check if two elements are disjoint in Union-Find structure
    private static boolean isDisjoint(int x, int y) {
        return findRoot(x) != findRoot(y);
    }
}
