#include <unordered_map>
#include <variant>
#include <nlohmann/json.hpp>
#include <fstream>
#include <sstream>
#include <string>

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> readConfiguration(const std::string& path, const std::string& environment) {
    // Load the JSON file into a string stream
    std::ifstream file(path);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open configuration file: " + path);
    }
    std::stringstream json_data;
    json_data << file.rdbuf();
    file.close();

    // Parse the JSON data and create a map of settings
    nlohmann::json j = nlohmann::json::parse(json_data);
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> settings;
    for (auto& setting : j.items()) {
        // Extract the setting name and value from the JSON object
        std::string name = setting.key();
        nlohmann::json value = setting.value();

        // Check if the setting is a nested JSON object or array
        if (value.is_object() || value.is_array()) {
            // Convert the nested JSON structure into a flat map
            auto flat_map = flattenJSON(value);
            settings[name] = flat_map;
        } else {
            // Extract the setting value from the JSON object
            if (value.is_string()) {
                std::string string_value = value.get<std::string>();
                settings[name] = string_value;
            } else if (value.is_number_integer()) {
                int int_value = value.get<int>();
                settings[name] = int_value;
            } else if (value.is_number_float()) {
                double float_value = value.get<double>();
                settings[name] = float_value;
            } else if (value.is_boolean()) {
                bool bool_value = value.get<bool>();
                settings[name] = bool_value;
            } else {
                throw std::runtime_error("Unsupported JSON type: " + value.type_name());
            }
        }
    }

    // Merge the settings from multiple files if necessary
    auto env_setting = j["environments"][environment];
    if (!env_setting.is_null()) {
        for (auto& [key, value] : env_setting.items()) {
            settings[key] = value;
        }
    }

    return settings;
}

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> flattenJSON(const nlohmann::json& json) {
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> flat_map;
    for (auto& [key, value] : json.items()) {
        if (value.is_object() || value.is_array()) {
            auto nested_flat_map = flattenJSON(value);
            for (auto& [nested_key, nested_value] : nested_flat_map) {
                flat_map[key + "." + nested_key] = nested_value;
            }
        } else {
            if (value.is_string()) {
                std::string string_value = value.get<std::string>();
                flat_map[key] = string_value;
            } else if (value.is_number_integer()) {
                int int_value = value.get<int>();
                flat_map[key] = int_value;
            } else if (value.is_number_float()) {
                double float_value = value.get<double>();
                flat_map[key] = float_value;
            } else if (value.is_boolean()) {
                bool bool_value = value.get<bool>();
                flat_map[key] = bool_value;
            } else {
                throw std::runtime_error("Unsupported JSON type: " + value.type_name());
            }
        }
    }
    return flat_map;
}
```
This implementation uses the `nlohmann/json` library for parsing and managing the JSON data structure. It extracts each setting from the JSON object and checks if it is a nested JSON object or array, converting it into a flat map using the `flattenJSON()` function if necessary. The function then merges the settings from multiple files, if necessary, and returns the final map of settings.

The `readConfiguration()` function takes two inputs: the path to the JSON file and an environment identifier (e.g., "DEV", "TEST", "PROD"). It first loads the JSON file into a string stream and then parses the data using the `nlohmann::json` library. The function then extracts each setting from the parsed JSON object, checking if it is a nested JSON structure or an atomic type, and converts it into a flat map using the `flattenJSON()` function if necessary.

