import asyncio
from datetime import datetime, timedelta
from typing import Dict, List

from cached_property import cached_property
from concurrent.futures import ThreadPoolExecutor

class TransactionProcessor:
    def __init__(self, api_url: str, time_window: int = 30):
        self.api_url = api_url
        self.time_window = timedelta(days=time_window)

    async def process_transactions(self, transactions: List[Transaction]) -> Dict[str, float]:
        # Split the dataset into smaller batches and process them concurrently
        with ThreadPoolExecutor() as executor:
            future_to_user = {executor.submit(self._process_transaction_batch, transaction_batch): user for transaction_batch, user in self.split_transactions(transactions)}
            results = [future.result() for future in future_to_user]

        # Combine the results and return the total transaction amount for each user
        return {user: sum(results[user]) for user in set(results)}

    def split_transactions(self, transactions: List[Transaction]) -> Dict[List[Transaction], str]:
        # Split the dataset into smaller batches based on the number of concurrent API requests allowed
        transaction_batches = []
        user_to_batch = {}
        for transaction in transactions:
            if transaction.user not in user_to_batch:
                transaction_batches.append([])
                user_to_batch[transaction.user] = len(transaction_batches) - 1
            transaction_batches[user_to_batch[transaction.user]].append(transaction)
        return {transaction_batch: user for transaction_batch, user in user_to_batch.items()}

    async def _process_transaction_batch(self, transactions: List[Transaction]) -> Dict[str, float]:
        # Fetch the latest transaction details from the external API using cached properties
        with cached_property(expire=timedelta(seconds=60)) as self.api_cache:
            api_responses = await self._fetch_transaction_details(transactions)

        # Handle potential latency issues and manage API call rate
        retries = 3
        backoff_factor = 2
        for i in range(retries):
            try:
                return {user: sum(transaction.amount for transaction in transactions if transaction.timestamp >= datetime.now() - self.time_window) for user in set(transactions)}
            except (NetworkError, TooManyRequestsError) as e:
                await asyncio.sleep(backoff_factor * (2 ** i))

        # Handle invalid input formats and provide informative error messages
        raise ValueError("Invalid transaction data format")

    async def _fetch_transaction_details(self, transactions: List[Transaction]) -> Dict[str, dict]:
        # Fetch the latest transaction details from the external API using the payment processing API
        api_responses = {}
        for transaction in transactions:
            try:
                response = await self.api_cache.get(f"{transaction.user}_{transaction.id}")
            except (NetworkError, TooManyRequestsError) as e:
                await asyncio.sleep(backoff_factor * (2 ** i))
            else:
                if response is None:
                    api_response = requests.get(f"{self.api_url}/transactions/{transaction.id}")
                    api_responses[transaction] = api_response.json()

        # Handle rate limiting and exponential backoff for failed API calls
        retries = 3
        backoff_factor = 2
        for i in range(retries):
            try:
                return {transaction: response["data"] for transaction, response in api_responses.items()}
            except (NetworkError, TooManyRequestsError) as e:
                await asyncio.sleep(backoff_factor * (2 ** i))

        # Handle invalid API responses and provide informative error messages
        raise ValueError("Invalid API response format")
