#!/usr/bin/env python

import os
import sys
import logging
import json

from datetime import datetime
from collections import OrderedDict

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class CIDC:
    def __init__(self):
        self.config = {}
        self.environments = {}
        self.build_steps = {}
        self.test_steps = {}
        self.deployment_steps = {}
        self.dependency_manager = DependencyManager()
        self.notification_system = NotificationSystem()

    def configure(self, config):
        self.config = config
        self.environments = OrderedDict([
            ("development", {"build": "build-dev", "test": "test-dev"}),
            ("staging", {"build": "build-stage", "test": "test-stage"}),
            ("production", {"build": "build-prod", "test": "test-prod"})
        ])
        self.build_steps = OrderedDict([
            ("build-dev", {"command": "python setup.py develop --user"}),
            ("build-stage", {"command": "python setup.py sdist"}),
            ("build-prod", {"command": "python setup.py bdist_wheel"}),
        ])
        self.test_steps = OrderedDict([
            ("test-dev", {"command": "python -m unittest discover -s tests/ -p '*_test.py'"}),
            ("test-stage", {"command": "python -m unittest discover -s tests/ -p '*_test.py'}"),
            ("test-prod", {"command": "python -m pytest --cov=src"}),
        ])
        self.deployment_steps = OrderedDict([
            ("deploy-dev", {"command": "python setup.py install --user"}),
            ("deploy-stage", {"command": "python setup.py sdist upload -r pypi"}),
            ("deploy-prod", {"command": "python setup.py bdist_wheel upload -r pypi"})
        ])
        self.dependency_manager.update(self.config)

    def run(self):
        for environment, build in self.environments.items():
            logger.info("Building and testing {}...".format(environment))
            try:
                self.build_and_test(environment, build)
            except Exception as e:
                logger.error("Failed to build and test {}: {}".format(environment, str(e)))
                return False
        logger.info("All builds and tests succeeded!")
        return True

    def build_and_test(self, environment, build):
        self.dependency_manager.install(environment)
        build = self.build_steps[build["build"]]
        test = self.test_steps[build["test"]]
        result = self.execute_step("Build", environment, build["command"])
        if result:
            result = self.execute_step("Test", environment, test["command"])
            if not result:
                logger.error("Tests failed for {}".format(environment))
        else:
            logger.error("Build failed for {}".format(environment))
        return result

    def execute_step(self, step, environment, command):
        start = datetime.now()
        self.dependency_manager.update(self.config)
        logger.info("Executing {} step for {}...".format(step, environment))
        try:
            result = os.system(command)
            if result != 0:
                logger.error("{} step failed for {}: Non-zero exit code ({})".format(step, environment, result))
                return False
            else:
                end = datetime.now()
                duration = (end - start).total_seconds() * 1000
                self.notification_system.notify("{} step succeeded for {} in {:.2f} ms".format(step, environment, duration))
                return True
        except Exception as e:
            logger.error("{} step failed for {}: {}".format(step, environment, str(e)))
            self.notification_system.notify("{} step failed for {} due to error: {}".format(step, environment, str(e)))
            return False
