Microservice for JSON Web Token Generation and Validation:
```java
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;

public class JwtService {
    private static final String ALGORITHM = "AES";
    private static final int KEY_LENGTH = 128;

    private SecretKeySpec secretKey;

    public JwtService() {
        // Initialize the secret key from the secure Key Management Service (KMS)
        secretKey = new SecretKeySpec(getSecretKey(), ALGORITHM);
    }

    public String generateJwtToken(String userId, int expirationTime) throws Exception {
        // Generate a JSON Web Token using the secret key and user ID
        String token = Base64.getEncoder().encodeToString(userId.getBytes()) + "." + expirationTime;
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, secretKey);
        return new String(cipher.doFinal(token.getBytes()));
    }

    public boolean validateJwtToken(String jwtToken) throws Exception {
        // Validate the JSON Web Token using the secret key
        Cipher cipher = Cipher.getInstance(ALGORITHM);
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        String token = new String(cipher.doFinal(Base64.getDecoder().decode(jwtToken)));
        int expirationTime = Integer.parseInt(token.split("\\.")[1]);
        return System.currentTimeMillis() < expirationTime;
    }
}
