import org.apache.ignite.Ignite;
import org.apache.ignite.IgniteCache;

public class CacheService {
    private static final String CACHE_NAME = "sensor-data";
    private Ignite ignite;

    public CacheService() {
        // Initialize the Ignite instance with appropriate configuration and cache settings
        ignite = Ignite.start();
    }

    public void put(String key, SensorData data) {
        // Store the sensor data in a distributed cache for efficient retrieval and processing
        IgniteCache<String, SensorData> cache = ignite.cache(CACHE_NAME);
        cache.put(key, data);
    }

    public SensorData get(String key) {
        // Retrieve the sensor data from the distributed cache for efficient processing
        IgniteCache<String, SensorData> cache = ignite.cache(CACHE_NAME);
        return cache.get(key);
    }
}
