#define MAX_CRC_LIST_SIZE 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crc;
} CRC_ENTRY_T;

int handleRanCrcIndications(NFAPI_CRC_INDICATION_PDU_T ***crcList, size_t *listSize, int maxStructures, FILE *logFile, RAN_SYS_API_T *ranSysApi, int concurrencyLevel) {
    // Allocate memory for the list of CRC indication PDUs
    *crcList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * maxStructures);
    if (*crcList == NULL) {
        fprintf(logFile, "handleRanCrcIndications: Memory allocation failed\n");
        return -1;
    }

    // Initialize the list size to 0
    *listSize = 0;

    // Set up a loop to handle incoming CRC indication PDUs from the RAN system
    while (*listSize < maxStructures) {
        // Acquire a new CRC indication PDU from the RAN system using the ranSysApi
        NFAPI_CRC_INDICATION_PDU_T *crc = ranSysApi->getNextCrcIndication();
        if (crc == NULL) {
            // If there are no more CRC indications, break from the loop and return
            break;
        }

        // Validate the CRC indication PDU to ensure it is valid and not corrupted
        int validate = ranSysApi->validateCrcIndication(crc);
        if (validate != 0) {
            fprintf(logFile, "handleRanCrcIndications: Invalid CRC indication received from RAN system\n");
            continue;
        }

        // Allocate memory for the new CRC entry in the list
        (*crcList)[*listSize] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*crcList)[*listSize] == NULL) {
            fprintf(logFile, "handleRanCrcIndications: Memory allocation failed\n");
            return -1;
        }

        // Copy the CRC indication PDU into the list entry
        memcpy((*crcList)[*listSize], crc, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Increment the list size
        (*listSize)++;
    }

    // If there are no more CRC indications to process, return success
    if (*listSize == 0) {
        return 0;
    }

    // Handle each CRC entry in the list concurrently using the concurrency level specified
    for (int i = 0; i < *listSize; i++) {
        // Create a new thread to handle the CRC entry
        pthread_t thread;
        if (pthread_create(&thread, NULL, handleCrcEntry, (*crcList)[i]) != 0) {
            fprintf(logFile, "handleRanCrcIndications: Failed to create new thread for CRC entry\n");
            return -1;
        }

        // Add the thread to a list of active threads for handling CRC entries
        pthread_mutex_lock(&threadMutex);
        activeThreads[i] = thread;
        pthread_mutex_unlock(&threadMutex);
    }

    // Wait for all active threads to finish before returning
    for (int i = 0; i < *listSize; i++) {
        void *status;
        if (pthread_join(activeThreads[i], &status) != 0) {
            fprintf(logFile, "handleRanCrcIndications: Failed to join thread for CRC entry\n");
            return -1;
        }
    }

    // Return success if all active threads have finished
    return 0;
}

void *handleCrcEntry(void *arg) {
    // Cast the argument to a NFAPI_CRC_INDICATION_PDU_T pointer
    NFAPI_CRC_INDICATION_PDU_T *crc = (NFAPI_CRC_INDICATION_PDU_T *)arg;

