fn create_directory(name: &str) -> Result<(), String> {
    // Check if environment variable is already set
    let env_var = env::var("DIR_PATH");
    if !env_var.is_err() && env_var.unwrap().len() > 0 {
        return Ok(());
    }

    // Create new directory with given name
    let dir_path = PathBuf::from(name);
    match create_dir(&dir_path) {
        Ok(_) => {},
        Err(err) => {
            if err.kind() == std::io::ErrorKind::PermissionDenied ||
                err.kind() == std::io::ErrorKind::AlreadyExists {
                    // Handle error by retrying with exponential backoff
                    let mut tries = 0;
