#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/kdf.h>

// Define the maximum IV length in bytes (96 bits)
#define MAX_IV_LEN 12

// Define the salt length in bytes (32 bits)
#define SALT_LEN 4

// Define the password length in bytes (64 bits)
#define PASSWORD_LEN 8

// Define the number of iterations for PBKDF2 key derivation
#define ITERATIONS 10000

// Define the minimum IV length in bytes (128 bits)
#define MIN_IV_LEN 16

// Define the maximum password length in bytes (512 bits)
#define MAX_PASSWORD_LEN 64

// Define the AES-256-GCM cipher context structure
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[MAX_IV_LEN];
} aes_gcm_ctx;

// Initialize an AES-256-GCM cipher context with a given password and salt, ensuring the IV length is set to 96 bits. Use the PBKDF2 algorithm with SHA-256 to derive the encryption key from the password and salt, incorporating key stretching for enhanced security.
int init_aes_gcm(aes_gcm_ctx *ctx, const unsigned char *password, size_t password_len, const unsigned char *salt, size_t salt_len) {
    int ret;

    // Validate input parameters
    if (ctx == NULL || password == NULL || salt == NULL) {
        return 0;
    }

    // Initialize the AES-256-GCM cipher context with the given password and salt
    ctx->ctx = EVP_CIPHER_CTX_new();
    ret = EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, NULL, NULL);
    if (ret != 1) {
        return 0;
    }

    // Generate a secure random IV using the OS random number generator
    ret = RAND_bytes(ctx->iv, MAX_IV_LEN);
    if (ret != 1) {
        return 0;
    }

    // Set the IV length to 96 bits
    EVP_CIPHER_CTX_set_iv_length(ctx->ctx, MIN_IV_LEN);

    // Use PBKDF2 with SHA-256 to derive the encryption key from the password and salt
    unsigned char *key = NULL;
    ret = PKCS5_PBKDF2_HMAC(password, password_len, salt, salt_len, ITERATIONS, EVP_sha256(), MIN_IV_LEN, &key);
    if (ret != 1) {
        return 0;
    }

    // Set the encryption key for the cipher context
    ret = EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, key, ctx->iv);
    if (ret != 1) {
        OPENSSL_free(key);
        return 0;
    }

    // Free the derived encryption key
    OPENSSL_free(key);

    return 1;
}

// Clean up an AES-256-GCM cipher context and free any associated resources.
int cleanup_aes_gcm(aes_gcm_ctx *ctx) {
    // Validate input parameters
    if (ctx == NULL || ctx->ctx == NULL) {
        return 0;
    }

    // Clean up the cipher context
    EVP_CIPHER_CTX_free(ctx->ctx);
    memset(ctx, 0, sizeof(aes_gcm_ctx));

    return 1;
}

// Encrypt a block of plaintext using an AES-256-GCM cipher context.
int encrypt_block(const unsigned char *plaintext, size_t plaintext_len, const aes_gcm_ctx *ctx, unsigned char *ciphertext) {
    int ret;

    // Validate input parameters
    if (plaintext == NULL || ctx == NULL || ciphertext == NULL) {
        return 0;
    }

    // Encrypt the plaintext using the AES-256-GCM cipher context
    EVP_EncryptUpdate(ctx->ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);

    // Set the tag for the encrypted block
    ret = EVP_EncryptFinal_ex(ctx->ctx, NULL, NULL);
    if (ret != 1) {
        return 0;
    }

    return 1;
}

// Decrypt a block of ciphertext using an AES-256-GCM cipher context.
int decrypt_block(const unsigned char *ciphertext, size_t ciphertext_len, const aes_gcm_ctx *ctx, unsigned char *plaintext) {
    int ret;

    // Validate input parameters
    if (ciphertext == NULL || ctx == NULL || plaintext == NULL) {
        return 0;
    }

    // Decrypt the ciphertext using the AES-256-GCM cipher context
    EVP_DecryptUpdate(ctx->ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len);

    // Set the tag for the decrypted block
    ret = EVP_DecryptFinal_ex(ctx->ctx, NULL, NULL);
    if (ret != 1) {
        return 0;
    }

    return 1;
}

// Example usage of the encryption service:
int main() {
    // Define the encryption context
    aes_gcm_ctx ctx;

    // Initialize the encryption context with the given password and salt
    if (init_aes_gcm(&ctx, "password", "salt")) {
        printf("Encryption context initialized successfully.\n");
    } else {
        printf("Failed to initialize encryption context.\n");
    }

    // Define the plaintext and ciphertext buffers
    unsigned char plaintext[16];
    unsigned char ciphertext[32];

    // Encrypt a block of plaintext using the encryption context
    if (encrypt_block(plaintext, 16, &ctx, ciphertext)) {
        printf("Encrypted block successfully.\n");
    } else {
        printf("Failed to encrypt block.\n");
    }

    // Decrypt a block of ciphertext using the encryption context
    if (decrypt_block(ciphertext, 32, &ctx, plaintext)) {
        printf("Decrypted block successfully.\n");
    } else {
        printf("Failed to decrypt block.\n");
    }

    // Clean up the encryption context
    if (cleanup_aes_gcm(&ctx)) {
        printf("Encryption context cleaned up successfully.\n");
    } else {
        printf("Failed to clean up encryption context.\n");
    }

    return 0;
}
