// Imports
const { exec } = require("child_process");
const axios = require("axios").default;
const cache = require("memory-cache");

// Constants
const API_URL = "https://external-api.example.com";
const CACHE_TTL = 60 * 1000; // 1 minute in milliseconds
const RATE_LIMIT_THRESHOLD = 50;

// Function to execute a shell command and retrieve data from an external API
async function executeCommand(command) {
  const cacheKey = `shell-command:${command}`;

  // Check if the command has been executed recently
  const cachedData = cache.get(cacheKey);
  if (cachedData && Date.now() - cachedData.timestamp < CACHE_TTL) {
    return cachedData.data;
  }

  // Execute the shell command and retrieve data from the external API
  try {
    const result = await exec(command);
    if (result.status === 0) {
      const apiResponse = await axios.get(`${API_URL}/${result.stdout}`);
      cache.put(cacheKey, apiResponse.data);
      return apiResponse.data;
    } else {
      console.error("Shell command failed with status code", result.status);
      return null;
    }
  } catch (err) {
    console.error("Error executing shell command:", err);
    return null;
  }
}

// Function to handle errors and log them to a remote server for monitoring purposes
function logError(err, message = "") {
  const errorMessage = `${message}: ${err.message}`;
  console.error(errorMessage);
  axios.post("https://remote-server.example.com/log", {
    timestamp: Date.now(),
    level: "error",
    message: errorMessage,
  });
}

// Function to limit the number of API calls and manage load effectively
async function rateLimit(func) {
  const now = Date.now();
  if (now - lastCall > RATE_LIMIT_THRESHOLD) {
    await func();
    lastCall = now;
  } else {
    console.log("Rate limit exceeded");
  }
}

// Main function that executes the shell command and retrieves data from an external API
async function main(command) {
  try {
    const result = await executeCommand(command);
    if (result) {
      return result;
    } else {
      logError("Failed to retrieve data from API");
      return null;
    }
  } catch (err) {
    logError("Failed to execute shell command", err);
    return null;
  }
}
