using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace DynamicCryptoGenerator
{
    public class CryptoGenerator
    {
        private readonly Dictionary<string, Type> _cryptoAlgorithms = new Dictionary<string, Type>();
        private readonly Dictionary<string, Type> _hashAlgorithms = new Dictionary<string, Type>();

        public CryptoGenerator()
        {
            // Register supported crypto and hash algorithms
            RegisterCryptoAlgorithm("AES-256", typeof(Aes));
            RegisterCryptoAlgorithm("ChaCha20", typeof(ChaCha20));
            RegisterHashAlgorithm("SHA-256", typeof(Sha256));
            RegisterHashAlgorithm("SHA-384", typeof(Sha384));
            RegisterHashAlgorithm("SHA-512", typeof(Sha512));
        }

        public void RegisterCryptoAlgorithm(string name, Type algorithm)
        {
            _cryptoAlgorithms.Add(name, algorithm);
        }

        public void RegisterHashAlgorithm(string name, Type algorithm)
        {
            _hashAlgorithms.Add(name, algorithm);
        }

        public byte[] Encrypt(byte[] data, string algorithmName)
        {
            var algorithm = GetCryptoAlgorithm(algorithmName);
            return algorithm.Encrypt(data);
        }

        public byte[] Decrypt(byte[] data, string algorithmName)
        {
            var algorithm = GetCryptoAlgorithm(algorithmName);
            return algorithm.Decrypt(data);
        }

        public byte[] Hash(byte[] data, string algorithmName)
        {
            var algorithm = GetHashAlgorithm(algorithmName);
            return algorithm.ComputeHash(data);
        }

        private ICryptoTransform GetCryptoAlgorithm(string name)
        {
            if (_cryptoAlgorithms.ContainsKey(name))
            {
                Type type = _cryptoAlgorithms[name];
                var ctor = type.GetConstructor(new[] { typeof(byte[]) });
                return (ICryptoTransform)ctor.Invoke(new object[] { new byte[32] });
            }
            else
            {
                throw new ArgumentException($"Unsupported crypto algorithm: {name}");
            }
        }

        private IHashAlgorithm GetHashAlgorithm(string name)
        {
            if (_hashAlgorithms.ContainsKey(name))
            {
                Type type = _hashAlgorithms[name];
                var ctor = type.GetConstructor(new[] { typeof(byte[]) });
                return (IHashAlgorithm)ctor.Invoke(new object[] { new byte[32] });
            }
            else
            {
                throw new ArgumentException($"Unsupported hash algorithm: {name}");
            }
        }
    }
}
