            logging.error(f"Exception occurred while fetching weather data for device {device} in location {location}: {e}")
            return None

    def detect_anomalies(self, log, weather_data):
        # Detect anomalies in the log using a machine learning model
        try:
            input_data = np.array([log["temperature"], weather_data["main"]["temp"]])
            output = self.model.predict(input_data)
            return output[0]
        except Exception as e:
            logging.error(f"Exception occurred while detecting anomalies in log {log}: {e}")
            return None

class AnomalyDetectionModel:
