import java.io.*;
import java.nio.charset.Charset;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.io.FileUtils;
import org.apache.commons.io.LineIterator;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.util.concurrent.ThreadFactoryBuilder;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.stream.JsonWriter;

public class FileProcessingSystem {
  private static final int MAX_CACHE_SIZE = 1000;
  private static final long CACHE_EXPIRATION = TimeUnit.MINUTES.toMillis(30);
  private static final Gson gson = new Gson();
  private static final JsonParser jsonParser = new JsonParser();
  private static final String LOGGING_SERVICE_URL = "https://logging-service.example.com";

  // Cache for recently processed file summaries
  private static LoadingCache<String, FileSummary> cache;

  public static void main(String[] args) throws Exception {
    // Initialize cache with maximum size and expiration time
    cache = CacheBuilder.newBuilder()
        .maximumSize(MAX_CACHE_SIZE)
        .expireAfterWrite(CACHE_EXPIRATION, TimeUnit.MILLISECONDS)
        .build(new CacheLoader<String, FileSummary>() {
          @Override
          public FileSummary load(String key) throws Exception {
            return null;
          }
        });

    // Initialize thread pool for concurrent file processing
    ExecutorService executor = newFixedThreadPool(Runtime.getRuntime().availableProcessors(),
        new ThreadFactoryBuilder().setNameFormat("file-processing-thread-%d").build());

    // Start file processing loop
    processFiles(executor);
  }

  private static void processFiles(ExecutorService executor) throws Exception {
    Path startingPath = Paths.get("/path/to/starting/directory");

    Files.walkFileTree(startingPath, new SimpleFileVisitor<Path>() {
      @Override
      public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
        if (attrs.isRegularFile() && isTextFile(file)) {
          executor.execute(() -> processFile(file));
        }
        return FileVisitResult.CONTINUE;
      }
    });
  }

  private static boolean isTextFile(Path file) throws IOException {
    // Check if the file has a supported encoding
    Charset charset = Files.probeContentType(file);
    return charset != null && !charset.name().startsWith("application/");
  }

  private static void processFile(Path file) {
    try {
      // Create a new summary object for the file
      FileSummary summary = new FileSummary(file.toString());

      // Read the file line by line and identify lines containing specific keywords
      LineIterator iterator = FileUtils.lineIterator(file.toFile(), "UTF-8");
      try {
        while (iterator.hasNext()) {
          String line = iterator.nextLine();
          if (line.contains("error") || line.contains("warning")) {
            summary.incrementErrorCount();
          }
        }
      } finally {
        iterator.close();
      }

      // Write the summary to the cache
      cache.put(file.toString(), summary);
    } catch (IOException e) {
      System.out.println("Error reading file " + file + ": " + e.getMessage());
    }
  }

  private static class FileSummary {
    private String path;
    private int errorCount = 0;

    public FileSummary(String path) {
      this.path = path;
    }

    public void incrementErrorCount() {
      errorCount++;
    }

    public String getPath() {
      return path;
    }

    public int getErrorCount() {
      return errorCount;
    }
  }
}
```

