#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <curl/curl.h>

typedef struct {
    char *file_path;
    char *bucket_name;
    char *directory_name;
    int file_size;
    char *hash_value;
} file_info;

int upload_file(file_info *file) {
    // Validate file metadata and calculate SHA-256 hash
    if (file->file_size == 0 || strlen(file->bucket_name) == 0 || strlen(file->directory_name) == 0) {
        printf("Invalid file metadata\n");
        return -1;
    }
    char hash[SHA256_DIGEST_LENGTH];
    sha256(file->file_path, &hash);
    if (strcmp(hash, file->hash_value) == 0) {
        printf("File already exists in the specified location\n");
        return -1;
    }

    // Create an EVP_CIPHER structure for the chosen cipher
    const EVP_CIPHER *cipher = NULL;
    switch (file->cipher_mode) {
        case ECB:
            cipher = EVP_get_cipherbyname("aes-128-ecb");
            break;
        case EDE:
            cipher = EVP_get_cipherbyname("aes-192-ede");
            break;
        case EDE3:
            cipher = EVP_get_cipherbyname("aes-256-ede3");
            break;
        case CFB:
            cipher = EVP_get_cipherbyname("aes-128-cfb");
            break;
    }

    // Initialize the encryption and decryption routines
    EVP_CIPHER_CTX *encrypt_ctx, *decrypt_ctx;
    int enc_len, dec_len;
    unsigned char iv[16], key[32];
    if (!EVP_EncryptInit_ex(encrypt_ctx, cipher, NULL, NULL, NULL)) {
        printf("Error initializing encryption context\n");
        return -1;
    }
    if (!EVP_DecryptInit_ex(decrypt_ctx, cipher, NULL, NULL, NULL)) {
        printf("Error initializing decryption context\n");
        return -1;
    }

    // Upload the file using multipart uploads and automatic retries
    int part_number = 1;
    long file_size = file->file_size;
    long chunk_size = 1024 * 1024; // 1MB chunks
    while (file_size > 0) {
        if (file_size < chunk_size) {
            chunk_size = file_size;
        }
        unsigned char *chunk = malloc(chunk_size);
        fread(chunk, 1, chunk_size, file->file_path);
        if (!EVP_EncryptUpdate(encrypt_ctx, chunk, &enc_len, chunk, chunk_size)) {
            printf("Error encrypting chunk\n");
            return -1;
        }
        // Upload the encrypted chunk to the cloud storage service
        if (upload_chunk(encrypted_chunk) == -1) {
            printf("Error uploading encrypted chunk\n");
            return -1;
        }
        free(chunk);
        part_number++;
        file_size -= chunk_size;
    }

    // Log successful upload and return status code
    printf("File uploaded successfully\n");
    return 0;
}

int sha256(const char *file_path, unsigned char *hash) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Error opening file for hashing");
        return -1;
    }
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    int read = 0;
    unsigned char buffer[4096];
    while ((read = fread(buffer, 1, sizeof(buffer), file)) != 0) {
        if (read < 0) {
            perror("Error reading from file for hashing");
            return -1;
        }
        SHA256_Update(&ctx, buffer, read);
    }
    SHA256_Final(hash, &ctx);
    fclose(file);
    return 0;
}
