import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class PokemonService {
    private static final int THREAD_POOL_SIZE = 50;
    private static final int MAX_CONCURRENT_REQUESTS = 50000;
    private static final long TIMEOUT = 1000L; // in milliseconds
    private static final String DATABASE_URL = "http://localhost:8080/pokemon-database";
    private static final String EVOLUTION_CHAIN_API_URL = "http://localhost:8081/evolution-chain-api";
    private static final String HABITAT_INFO_API_URL = "http://localhost:8082/habitat-info-api";
    private static final String SOCIAL_MEDIA_INTEGRATION_URL = "https://pokemon.com";
    private static final int MAX_RETRY_ATTEMPTS = 3;
    private static final long RETRY_DELAY = 100L; // in milliseconds
    private static final String DATABASE_CACHE_NAME = "pokemon-database-cache";
    private static final String EVOLUTION_CHAIN_CACHE_NAME = "evolution-chain-cache";
    private static final String HABITAT_INFO_CACHE_NAME = "habitat-info-cache";
    private static final int CACHE_TTL = 60; // in seconds

    private static ThreadPoolExecutor threadPoolExecutor = null;
    private static CacheManager cacheManager = null;

    public static void main(String[] args) {
        // Initialize the thread pool and cache manager
        threadPoolExecutor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        cacheManager = new CacheManager();

        // Register the cache manager with the database connection pool
        registerCacheManager(cacheManager, DATABASE_CACHE_NAME);

        // Start the service
        startService();
    }

    public static void startService() {
        // Set up the HTTP server and start listening for incoming requests
        HttpServer httpServer = new HttpServer(8080);
        httpServer.start();

        while (true) {
            try {
                // Wait for an incoming request
                HttpRequest request = httpServer.waitForNextRequest();

                // Handle the request asynchronously using a thread from the thread pool
                threadPoolExecutor.execute(new RequestHandler(request));
            } catch (InterruptedException e) {
                // Exit the loop if the service is shutting down
                break;
            }
        }
    }

    private static class RequestHandler implements Runnable {
        private final HttpRequest request;

        public RequestHandler(HttpRequest request) {
            this.request = request;
        }

        @Override
        public void run() {
            try {
                // Parse the incoming request and retrieve the Pokemon ID
                int pokemonId = Integer.parseInt(request.getPathParameter("id"));

                // Retrieve the Pokemon details from the cache if available, otherwise fetch them from the external API
                PokemonDetails pokemonDetails = cacheManager.getCache(DATABASE_CACHE_NAME).getIfPresent(pokemonId);
                if (pokemonDetails == null) {
                    pokemonDetails = retrievePokemonDetails(pokemonId, THREAD_POOL_SIZE);
                }

                // Retrieve the evolution chain details from the cache if available, otherwise fetch them from the external API
                EvolutionChain evolutionChain = cacheManager.getCache(EVOLUTION_CHAIN_CACHE_NAME).getIfPresent(pokemonId);
                if (evolutionChain == null) {
                    evolutionChain = retrieveEvolutionChainDetails(pokemonId, THREAD_POOL_SIZE);
                }

                // Retrieve the habitat information from the cache if available, otherwise fetch it from the external API
                HabitatInfo habitatInfo = cacheManager.getCache(HABITAT_INFO_CACHE_NAME).getIfPresent(pokemonId);
                if (habitatInfo == null) {
                    habitatInfo = retrieveHabitatInformation(pokemonId, THREAD_POOL_SIZE);
                }

                // Prepare the JSON response with the Pokemon details and evolution chain information
                JsonObject jsonResponse = new JsonObject();
                jsonResponse.addProperty("name", pokemonDetails.getName());
                jsonResponse.addProperty("types", pokemonDetails.getTypes());
                jsonResponse.addProperty("weaknesses", pokemonDetails.getWeaknesses());
                jsonResponse.addProperty("evolutionChain", evolutionChain.toString());
                jsonResponse.addProperty("habitatInfo", habitatInfo.toString());

                // Send the response back to the client
                request.respond(jsonResponse.toString(), "application/json");
            } catch (Exception e) {
                // Handle any exceptions gracefully and send a meaningful error message to the client
                System.err.println("Error handling request: " + e.getMessage());
                request.respond("Internal server error", 500);
            }
        }
    }

    private static PokemonDetails retrievePokemonDetails(int pokemonId, int maxAttempts) {
        // Retrieve the Pokemon details from the external API
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return fetchPokemonDetails(pokemonId);
            } catch (Exception e) {
                if (attempt == maxAttempts) {
                    throw new RuntimeException("Failed to retrieve Pokemon details after " + maxAttempts + " attempts", e);
                }
                // Retry after a short delay if the API call failed
                Thread.sleep(5000);
            }
        }
        return null;
    }

    private static EvolutionChain retrieveEvolutionChainDetails(int pokemonId, int maxAttempts) {
        // Retrieve the evolution chain details from the external API
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return fetchEvolutionChainDetails(pokemonId);
            } catch (Exception e) {
                if (attempt == maxAttempts) {
                    throw new RuntimeException("Failed to retrieve evolution chain details after " + maxAttempts + " attempts", e);
                }
                // Retry after a short delay if the API call failed
                Thread.sleep(5000);
            }
        }
        return null;
    }

    private static HabitatInfo retrieveHabitatInformation(int pokemonId, int maxAttempts) {
        // Retrieve the habitat information from the external API
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return fetchHabitatInformation(pokemonId);
            } catch (Exception e) {
                if (attempt == maxAttempts) {
                    throw new RuntimeException("Failed to retrieve habitat information after " + maxAttempts + " attempts", e);
                }
                // Retry after a short delay if the API call failed
                Thread.sleep(5000);
            }
        }
        return null;
    }

    private static PokemonDetails fetchPokemonDetails(int pokemonId) {
        // Fetch the Pokemon details from the external API
        JsonObject jsonResponse = new JsonObject();
        HttpRequest request = new HttpRequest("GET", "https://pokeapi.co/api/v2/pokemon/" + pokemonId);
        jsonResponse = request.send().getJsonBody();
        return parsePokemonDetails(jsonResponse);
    }

    private static EvolutionChain fetchEvolutionChainDetails(int pokemonId) {
        // Fetch the evolution chain details from the external API
        JsonObject jsonResponse = new JsonObject();
        HttpRequest request = new HttpRequest("GET", "https://pokeapi.co/api/v2/evolution-chain/" + pokemonId);
        jsonResponse = request.send().getJsonBody();
        return parseEvolutionChainDetails(jsonResponse);
    }

    private static HabitatInfo fetchHabitatInformation(int pokemonId) {
        // Fetch the habitat information from the external API
        JsonObject jsonResponse = new JsonObject();
        HttpRequest request = new HttpRequest("GET", "https://pokeapi.co/api/v2/pokemon-habitat/" + pokemonId);
        jsonResponse = request.send().getJsonBody();
        return parseHabitatInformation(jsonResponse);
    }

    private static PokemonDetails parsePokemonDetails(JsonObject jsonResponse) {
        // Parse the Pokemon details from the JSON response
        String name = jsonResponse.getString("name");
        List<String> types = new ArrayList<>();
        for (int i = 0; i < jsonResponse.getArray("types").size(); i++) {
            types.add(jsonResponse.getJsonObject("types").getJsonObject(i).getString("type").toLowerCase());
        }
        List<String> weaknesses = new ArrayList<>();
        for (int i = 0; i < jsonResponse.getArray("weaknesses").size(); i++) {
            weaknesses.add(jsonResponse.getJsonObject("weaknesses").getJsonObject(i).getString("type").toLowerCase());
        }
        return new PokemonDetails(name, types, weaknesses);
    }

    private static EvolutionChain parseEvolutionChainDetails(JsonObject jsonResponse) {
        // Parse the evolution chain details from the JSON response
        List<String> evolutions = new ArrayList<>();
        for (int i = 0; i < jsonResponse.getArray("evolves_to").size(); i++) {
            JsonObject evolveTo = jsonResponse.getJsonObject("evolves_to").getJsonObject(i);
            String evolution = evolveTo.getString("species").toLowerCase() + " (" + evolveTo.getInt("evolution_details")[0].getString("gender_rate") + ")";
            evolutions.add(evolution);
        }
        return new EvolutionChain(jsonResponse.getString("species"), evolutions);
    }

    private static HabitatInfo parseHabitatInformation(JsonObject jsonResponse) {
        // Parse the habitat information from the JSON response
        String name = jsonResponse.getString("name");
        List<String> pokemon = new ArrayList<>();
        for (int i = 0; i < jsonResponse.getArray("pokemon_species").size(); i++) {
            JsonObject species = jsonResponse.getJsonObject("pokemon_species").getJsonObject(i);
            String pkmnName = species.getString("name");
            pokemon.add(pkmnName);
        }
        return new HabitatInfo(name, pokemon);
    }
}

class PokemonDetails {
    private String name;
    private List<String> types;
    private List<String> weaknesses;

    public PokemonDetails(String name, List<String> types, List<String> weaknesses) {
        this.name = name;
        this.types = types;
        this.weaknesses = weaknesses;
    }

    public String getName() {
        return name;
    }

    public List<String> getTypes() {
        return types;
    }

    public List<String> getWeaknesses() {
        return weaknesses;
    }
}

class EvolutionChain {
    private String species;
    private List<String> evolutions;

    public EvolutionChain(String species, List<String> evolutions) {
        this.species = species;
        this.evolutions = evolutions;
    }

    public String getSpecies() {
        return species;
    }

    public List<String> getEvolutions() {
        return evolutions;
    }
}

class HabitatInfo {
    private String name;
    private List<String> pokemon;

    public HabitatInfo(String name, List<String> pokemon) {
        this.name = name;
        this.pokemon = pokemon;
    }

    public String getName() {
        return name;
    }

    public List<String> getPokemon() {
        return pokemon;
    }
}

