using System;
using UnityEngine;

public class DynamicValueGenerator
{
    private readonly Random _random = new Random();
    private readonly Dictionary<DistributionType, Distribution> _distributions = new Dictionary<DistributionType, Distribution>();
    private readonly object _lock = new object();

    public float NextFloat(DistributionType distributionType, float minValue, float maxValue)
    {
        lock (_lock)
        {
            if (!_distributions.TryGetValue(distributionType, out Distribution distribution))
            {
                distribution = CreateDistribution(distributionType);
                _distributions[distributionType] = distribution;
            }

            return (float)distribution.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public int NextInt(DistributionType distributionType, int minValue, int maxValue)
    {
        lock (_lock)
        {
            if (!_distributions.TryGetValue(distributionType, out Distribution distribution))
            {
                distribution = CreateDistribution(distributionType);
                _distributions[distributionType] = distribution;
            }

            return (int)(distribution.NextDouble() * (maxValue - minValue) + minValue);
        }
    }

    public Vector3 NextVector3(DistributionType distributionType, float minValue, float maxValue)
    {
        lock (_lock)
        {
            if (!_distributions.TryGetValue(distributionType, out Distribution distribution))
            {
                distribution = CreateDistribution(distributionType);
                _distributions[distributionType] = distribution;
            }

            return new Vector3((float)distribution.NextDouble() * (maxValue - minValue) + minValue,
                              (float)distribution.NextDouble() * (maxValue - minValue) + minValue,
                              (float)distribution.NextDouble() * (maxValue - minValue) + minValue);
        }
    }

    public Matrix4x4 NextMatrix4x4(DistributionType distributionType, float minValue, float maxValue)
    {
        lock (_lock)
        {
            if (!_distributions.TryGetValue(distributionType, out Distribution distribution))
            {
                distribution = CreateDistribution(distributionType);
                _distributions[distributionType] = distribution;
            }

            return new Matrix4x4((float)distribution.NextDouble() * (maxValue - minValue) + minValue,
                                 (float)distribution.NextDouble() * (maxValue - minValue) + minValue,
                                 (float)distribution.NextDouble() * (maxValue - minValue) + minValue,
                                 (float)distribution.NextDouble() * (maxValue - minValue) + minValue);
        }
    }

    private Distribution CreateDistribution(DistributionType distributionType)
    {
        switch (distributionType)
        {
            case DistributionType.Gaussian:
                return new GaussianDistribution(_random);
            case DistributionType.Uniform:
                return new UniformDistribution(_random);
            case DistributionType.Exponential:
                return new ExponentialDistribution(_random);
            default:
                throw new ArgumentException($"Unsupported distribution type: {distributionType}");
        }
    }
}

public enum DistributionType
{
    Gaussian,
    Uniform,
    Exponential
}

public interface Distribution
{
    double NextDouble();
}

public class GaussianDistribution : Distribution
{
    private readonly Random _random;

    public GaussianDistribution(Random random)
    {
        _random = random;
    }

    public override double NextDouble()
    {
        return (float)_random.NextGaussian();
    }
}

public class UniformDistribution : Distribution
{
    private readonly Random _random;

    public UniformDistribution(Random random)
    {
        _random = random;
    }

    public override double NextDouble()
    {
        return (float)_random.NextDouble();
    }
}

public class ExponentialDistribution : Distribution
{
    private readonly Random _random;

    public ExponentialDistribution(Random random)
    {
        _random = random;
    }

    public override double NextDouble()
    {
        return (float)_random.NextExponential();
    }
}
