            # Increment counter for error type
            if error_type in self.logs:
                self.logs[error_type] += 1
            else:
                self.logs[error_type] = 1

            # Check if alert threshold is exceeded
            if error_type in self.thresholds and self.logs[error_type] >= self.thresholds[error_type]:
                self.send_alert(error_type)
