```
import os
import json
from datetime import timedelta
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
from jwt import JWT, claims

class JSONWebToken(object):
    def __init__(self):
        self.private_key = os.environ['PRIVATE_KEY']
        self.public_key = os.environ['PUBLIC_KEY']
        self.kms_url = os.environ['KMS_URL']
        self.token_ttl = timedelta(hours=24)

    def generate_token(self, user):
        claims = {
            'iss': self.kms_url,
            'sub': user,
            'aud': ['https://example.com'],
            'exp': datetime.now() + self.token_ttl,
            'iat': datetime.now(),
            'jti': str(uuid4()),
        }
        return JWT.encode(claims, self.private_key)

    def verify_token(self, token):
        claims = JWT.decode(token, self.public_key)
        if claims['iss'] != self.kms_url:
            raise ValueError('Invalid issuer')
        if claims['aud'][0] != 'https://example.com':
            raise ValueError('Invalid audience')
        if claims['exp'] < datetime.now():
            raise ValueError('Token has expired')
        return claims['sub']
```
This microservice generates and validates JSON Web Tokens (JWT) using a private key stored in a secure Key Management Service (KMS), such as AWS KMS, Azure Key Vault, or Google KMS. The token TTL is set to 24 hours.

