            logging.error("Error retrieving schema", exc_info=True)
            raise CustomRuntimeException("Error retrieving schema") from e

        # Create an instance of the metadata class and populate it with extracted metadata
        metadata = metadata_class()
        for key, value in schema["properties"].items():
            if value["type"] == "string":
                try:
                    setattr(metadata, key, await self.get_string_value(file_path, value["format"]))
                except (TypeError, ValueError) as e:
                    logging.error("Error extracting string value", exc_info=True)
                    raise CustomRuntimeException("Error extracting string value") from e
            elif value["type"] == "integer":
                try:
                    setattr(metadata, key, await self.get_integer_value(file_path))
                except (TypeError, ValueError) as e:
                    logging.error("Error extracting integer value", exc_info=True)
                    raise CustomRuntimeException("Error extracting integer value") from e
            elif value["type"] == "float":
                try:
                    setattr(metadata, key, await self.get_float_value(file_path))
                except (TypeError, ValueError) as e:
                    logging.error("Error extracting float value", exc_info=True)
                    raise CustomRuntimeException("Error extracting float value") from e
            elif value["type"] == "array":
                try:
                    setattr(metadata, key, await self.get_array_value(file_path, value["items"]["type"]))
                except (TypeError, ValueError) as e:
                    logging.error("Error extracting array value", exc_info=True)
                    raise CustomRuntimeException("Error extracting array value") from e

        # Caching strategy for frequently accessed file metadata to reduce load on external storage service
        if self.cache is not None:
            self.cache[file_path] = metadata

        return metadata

    async def retrieve_schema(self, file_path: str, file_type: str) -> Dict[str, Any]:
        # Connect to external storage service and retrieve schema definition for given file type
        url = f"{self.external_storage_url}/schemas/{file_type}"
        try:
            response = await self.http_client.get(url)
            return json.loads(response.content)
        except (TypeError, ValueError, IOError) as e:
            logging.error("Error retrieving schema", exc_info=True)
            raise CustomRuntimeException("Error retrieving schema") from e

    async def get_string_value(self, file_path: str, format: str) -> str:
        # Extract string value from given file using specified format
        try:
            with open(file_path, "rb") as f:
                return await self.format_string(f.read(), format)
        except (TypeError, ValueError, IOError) as e:
            logging.error("Error extracting string value", exc_info=True)
            raise CustomRuntimeException("Error extracting string value") from e

    async def get_integer_value(self, file_path: str) -> int:
        # Extract integer value from given file
        try:
            with open(file_path, "rb") as f:
                return await self.format_integer(f.read())
        except (TypeError, ValueError, IOError) as e:
            logging.error("Error extracting integer value", exc_info=True)
            raise CustomRuntimeException("Error extracting integer value") from e

    async def get_float_value(self, file_path: str) -> float:
        # Extract float value from given file
        try:
            with open(file_path, "rb") as f:
                return await self.format_float(f.read())
        except (TypeError, ValueError, IOError) as e:
            logging.error("Error extracting float value", exc_info=True)
            raise CustomRuntimeException("Error extracting float value") from e

    async def get_array_value(self, file_path: str, item_type: str) -> List[Any]:
        # Extract array value from given file using specified item type
        try:
            with open(file_path, "rb") as f:
                return await self.format_array(f.read(), item_type)
        except (TypeError, ValueError, IOError) as e:
            logging.error("Error extracting array value", exc_info=True)
            raise CustomRuntimeException("Error extracting array value") from e

    def file_exists(self, file_path: str) -> bool:
        # Check if given file exists and is accessible
        return os.path.isfile(file_path) and os.access(file_path, os.R_OK)
