use std::fs::File;
use std::io::Read;
use std::path::PathBuf;

fn generate_llvm_ir(file_path: PathBuf) -> Result<String, String> {
    let mut file = match File::open(&file_path) {
        Ok(file) => file,
        Err(_) => return Err("File not found".to_string()),
    };

    let mut buffer = String::new();
    if let Err(_) = file.read_to_string(&mut buffer) {
        return Err("Failed to read file".to_string());
    }

    Ok(buffer)
}
