import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Function;
import java.util.function.Supplier;
import java.security.KeyPair;
import java.security.PrivateKey;
import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import com.google.gson.JsonObject;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.BasicResponseHandler;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ResourceLoader;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import reactor.core.publisher.Mono;

@RestController
public class CryptographicConfigService {

    private static final Logger logger = LoggerFactory.getLogger(CryptographicConfigService.class);
    private static final ExecutorService executorService = Executors.newSingleThreadExecutor();
    private static final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();
    private static final long expirationTimeMillis = 1000L; // 1 second
    private static final int lruSize = 100;

    @GetMapping("/config")
    public Mono<JsonObject> getConfig() {
        return Mono.fromCallable(() -> {
            JsonObject config = (JsonObject) cache.get("config");
            if (config == null || System.currentTimeMillis() - config.getLong("timestamp") > expirationTimeMillis) {
                // fetch new config from external service
                HttpClient httpClient = new HttpClient();
                String url = "http://example.com/config";
                try {
                    BasicResponseHandler responseHandler = new BasicResponseHandler();
                    String response = httpClient.execute(new HttpGet(url), responseHandler);
                    config = new JsonObject(response);
                    cache.put("config", config);
                } catch (Exception e) {
                    logger.error("Failed to fetch config from external service: {}", e.getMessage());
                }
            }
            return config;
        }).subscribeOn(Schedulers.elastic());
    }

    private static final Function<String, Supplier<Object>> factory = id -> {
        switch (id) {
            case "aes-128":
                return () -> new SecretKeySpec("secret".getBytes(), "AES");
            case "aes-256":
                return () -> new SecretKeySpec("super secret".getBytes(), "AES");
            case "chacha20":
                return () -> new SecretKeySpec("cha cha 20".getBytes(), "ChaCha20");
            default:
                throw new IllegalArgumentException("Unsupported cipher ID: " + id);
        }
    };

    private static final Function<String, String> encryptionAlgorithm = id -> {
        switch (id) {
            case "aes-128":
                return Cipher.ENCRYPT_MODE;
            case "aes-256":
                return Cipher.ENCRYPT_MODE;
            case "chacha20":
                return Cipher.ENCRYPT_MODE;
            default:
                throw new IllegalArgumentException("Unsupported cipher ID: " + id);
        }
    };

    public static Object encrypt(String plaintext, String id) {
        try {
            SecretKeySpec key = (SecretKeySpec) factory.apply(id).get();
            Cipher cipher = Cipher.getInstance(encryptionAlgorithm.apply(id));
            GCMParameterSpec spec = new GCMParameterSpec(128, ThreadLocalRandom.current().nextInt());
            cipher.init(Cipher.ENCRYPT_MODE, key, spec);
            return cipher.doFinal(plaintext.getBytes("UTF-8"));
        } catch (Exception e) {
            logger.error("Failed to encrypt text: {}", e.getMessage());
            return null;
        }
    }

    public static String decrypt(Object ciphertext, String id) {
        try {
            SecretKeySpec key = (SecretKeySpec) factory.apply(id).get();
            Cipher cipher = Cipher.getInstance(encryptionAlgorithm.apply(id));
            cipher.init(Cipher.DECRYPT_MODE, key);
            return new String(cipher.doFinal(ciphertext), "UTF-8");
        } catch (Exception e) {
            logger.error("Failed to decrypt text: {}", e.getMessage());
            return null;
        }
    }

    public static void verifyJwtToken(String token, String keyId) {
        try {
            KeyPair keyPair = (KeyPair) factory.apply(keyId).get();
            Cipher cipher = Cipher.getInstance("RSA/NONE/PKCS1Padding");
            cipher.init(Cipher.ENCRYPT_MODE, keyPair.getPublic());
            byte[] signature = cipher.doFinal(token.getBytes("UTF-8"));
            if (signature == null) {
                logger.error("Failed to verify JWT token: signature is null");
                return;
            }
            String signatureBase64 = new String(Base64.encodeBase64(signature));
            if (!token.contains(signatureBase64)) {
                logger.error("Failed to verify JWT token: invalid signature");
                return;
            }
        } catch (Exception e) {
            logger.error("Failed to verify JWT token: {}", e.getMessage());
        }
    }
}

