package com.example.chat;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ChatApplication {
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);
    private final Map<String, MessageAdapter> adapters = new HashMap<>();

    public void init() {
        // Initialize message adapters for supported messaging services
        adapters.put("sms", new SMSMessageAdapter());
        adapters.put("email", new EmailMessageAdapter());
        adapters.put("social-media", new SocialMediaMessageAdapter());
    }

    public void sendMessage(String recipient, String message) {
        // Get the appropriate message adapter based on the recipient's messaging service
        MessageAdapter adapter = adapters.get(recipient);

        if (adapter == null) {
            throw new RuntimeException("Unsupported messaging service for recipient " + recipient);
        }

        // Create a new message instance and set the recipient and content
        Message messageInstance = new Message();
        messageInstance.setRecipient(recipient);
        messageInstance.setContent(message);

        // Asynchronously send the message using the appropriate adapter
        executorService.execute(() -> {
            try {
                adapter.sendMessage(messageInstance);
            } catch (Exception e) {
                System.out.println("Error sending message: " + e.getMessage());
            }
        });
    }

    public void receiveMessage(String sender, String content) {
        // Get the appropriate message adapter based on the sender's messaging service
        MessageAdapter adapter = adapters.get(sender);

        if (adapter == null) {
            throw new RuntimeException("Unsupported messaging service for sender " + sender);
        }

        // Create a new message instance and set the sender and content
        Message messageInstance = new Message();
        messageInstance.setSender(sender);
        messageInstance.setContent(content);

        // Asynchronously receive the message using the appropriate adapter
        executorService.execute(() -> {
            try {
                adapter.receiveMessage(messageInstance);
            } catch (Exception e) {
                System.out.println("Error receiving message: " + e.getMessage());
            }
        });
    }
}
