#include <random>
#include <thread>

class RandomNumberGenerator {
public:
    // Constructor that accepts a seed value from an external data source
    explicit RandomNumberGenerator(unsigned int seed) : mt19937_(seed) {}

    // Initialize the RNG state with the provided seed
    void initialize(unsigned int seed) {
        mt19937_.seed(seed);
    }

    // Generate a random integer within the given range [min, max]
    int generateRandomInt(int min, int max) {
        return std::uniform_int_distribution<>(min, max)(mt19937_);
    }

    // Generate a random floating-point number within the given range [min, max]
    float generateRandomFloat(float min, float max) {
        return std::uniform_real_distribution<>(min, max)(mt19937_);
    }

    // Ensure thread safety by using a mutex to protect the RNG state
    void lock() {
        std::lock_guard<std::mutex> lock(mux_);
    }

private:
    // Use Mersenne Twister algorithm for random number generation
    std::mt19937 mt19937_;

    // Mutex to ensure thread safety when generating random numbers
    std::mutex mux_;
};

#ifdef UNIT_TESTS

// Test the thread safety of the RNG by generating random numbers concurrently
TEST(RandomNumberGenerator, ThreadSafe) {
    const int NUM_THREADS = 8;
    const int NUM_RANDOM_NUMBERS = 100000;

    std::vector<std::thread> threads;
    for (int i = 0; i < NUM_THREADS; ++i) {
        threads.emplace_back(std::thread([&]() {
            RandomNumberGenerator rng(1); // Use the same seed for all threads

            for (int j = 0; j < NUM_RANDOM_NUMBERS; ++j) {
                int randomInt = rng.generateRandomInt(1, 10);
                float randomFloat = rng.generateRandomFloat(1.0f, 10.0f);
            }
        }));
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

// Test the performance of the RNG by generating random numbers in parallel
TEST(RandomNumberGenerator, Performance) {
    const int NUM_RANDOM_NUMBERS = 100000;

    std::vector<std::thread> threads;
    for (int i = 0; i < 8; ++i) {
        threads.emplace_back(std::thread([&]() {
            RandomNumberGenerator rng(1); // Use the same seed for all threads

            for (int j = 0; j < NUM_RANDOM_NUMBERS / 8; ++j) {
                int randomInt = rng.generateRandomInt(1, 10);
                float randomFloat = rng.generateRandomFloat(1.0f, 10.0f);
            }
        }));
    }

    for (auto& thread : threads) {
        thread.join();
    }
}

#endif // UNIT_TESTS

