// main.rs
use std::fs;
use std::io;
use std::path::PathBuf;
use std::sync::{Arc, RwLock};
use std::thread;
use std::time::Duration;

use log::{error, info, warn};
use reqwest::blocking::Client;
use serde::Deserialize;

mod config;
mod http_client;
mod logging;
mod utils;

#[derive(Deserialize)]
struct Configuration {
    log_level: String,
    log_file: PathBuf,
    timeout: u64,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = config::load_config()?;

    if !config.log_file.exists() {
        fs::create_dir(&config.log_file)?;
    }

    let logger = logging::LoggerBuilder::new(config.log_level)
        .with_file_appender(config.log_file)
        .build();

    let client = Client::builder()
        .timeout(Duration::from_secs(config.timeout))
        .build()?;

    let mut request = http_client::RequestBuilder::new(&client);
    request.with_uri("https://api.example.com/data");

    if let Some(headers) = config.http_headers {
        for (key, value) in headers {
            request.header(key, value);
        }
    }

    let mut response = request.send()?;

    if !response.status().is_success() {
        error!("Request failed with status code: {}", response.status());
        return Ok(());
    }

    let data = response.json::<serde_json::Value>()?;

    logger.info("Received data from API");

    fs::write(&config.data_file, &data)?;

    info!("Data saved to file: {}", config.data_file.display());

    Ok(())
}
```

