// utils.rs
use std::path::PathBuf;
use std::sync::{Arc, RwLock};

use log::{error, info};

pub struct LoggerBuilder {
    level: String,
    file_appender: Option<PathBuf>,
}

impl LoggerBuilder {
    pub fn new(level: String) -> Self {
        Self {
            level,
            file_appender: None,
        }
    }

    pub fn with_file_appender(mut self, path: PathBuf) -> Self {
        self.file_appender = Some(path);
        self
    }

    pub fn build(self) -> Logger {
        let file_appender = match self.file_appender {
            Some(path) => Arc::new(RwLock::new(log4rs::append::rolling_file::RotatingFileAppender::builder()
                .filename(path)
                .build())),
            None => Arc::new(RwLock::new(log4rs::append::console::ConsoleAppender::builder().build())),
        };

        Logger {
            level: self.level,
            file_appender,
        }
    }
}
