// http_client.rs
use std::time::Duration;

use reqwest::blocking::{Client, RequestBuilder};

pub struct RequestBuilder {
    client: Client,
    uri: String,
    headers: Vec<(String, String)>,
}

impl RequestBuilder {
    pub fn new(client: &Client) -> Self {
        Self {
            client: client.clone(),
            uri: String::new(),
            headers: Vec::new(),
        }
    }

    pub fn with_uri(&mut self, uri: &str) -> &mut Self {
        self.uri = uri.to_string();
        self
    }

    pub fn header(&mut self, key: String, value: String) -> &mut Self {
        self.headers.push((key, value));
        self
    }

    pub fn send(&self) -> Result<Response, Box<dyn std::error::Error>> {
        let mut builder = self.client.get(self.uri.as_str());

        for (key, value) in &self.headers {
            builder = builder.header(key.as_str(), value);
        }

        let response = builder.send()?;

        if !response.status().is_success() {
            error!("Request failed with status code: {}", response.status());
            return Err("request failed".into());
        }

        Ok(Response { data: response.json::<serde_json::Value>()? })
    }
}
