// logging.rs
use log::{error, info};
use std::sync::Arc;
use std::time::Duration;

pub struct Logger {
    level: String,
    file_appender: Arc<RwLock<log4rs::Appender>>,
}

impl Logger {
    pub fn new(level: String) -> Self {
        let file_appender = Arc::new(RwLock::new(log4rs::append::rolling_file::RotatingFileAppender::builder()
            .build()));

        Self {
            level,
            file_appender,
        }
    }

    pub fn info(&self, message: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut appender = self.file_appender.write().unwrap();
        appender.log(
            log::LevelFilter::Info,
            Some("info"),
            format!("{}", message),
        );
        Ok(())
    }

    pub fn warn(&self, message: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut appender = self.file_appender.write().unwrap();
        appender.log(
            log::LevelFilter::Warn,
            Some("warn"),
            format!("{}", message),
        );
        Ok(())
    }

    pub fn error(&self, message: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut appender = self.file_appender.write().unwrap();
        appender.log(
            log::LevelFilter::Error,
            Some("error"),
            format!("{}", message),
        );
        Ok(())
    }
}
