using System;
using System.IO;
using System.Xml.Linq;
using System.Text;

namespace GetFirstMatchingElement
{
    public static class XPathQuery
    {
        private static Dictionary<string, string> cachedQueries = new Dictionary<string, string>();

        /// <summary>
        /// Parses an XML document using XPath and returns the first element that matches a given name.
        /// If no element is found, throws an ElementNotFoundException with an appropriate error message.
        /// If multiple elements are found with the given name, throws a MultipleElementsFoundException with an error message indicating the count of matching elements.
        /// </summary>
        /// <param name="xml">The XML document to parse.</param>
        /// <param name="xpathQuery">An XPath query that selects the element to return.</param>
        /// <returns>The first element that matches the given name, or null if no such element is found.</returns>
        public static string GetFirstMatchingElement(string xml, string xpathQuery)
        {
            // Validate the XML document
            try
            {
                XDocument.Parse(xml);
            }
            catch (Exception ex)
            {
                throw new ArgumentException("The provided XML document is not well-formed.", nameof(xml), ex);
            }

            // Check if the XPath query has been cached
            if (cachedQueries.ContainsKey(xpathQuery))
            {
                return cachedQueries[xpathQuery];
            }

            // Parse the XML document using XPath
            try
            {
                var xpathNavigator = new XPathDocument(xml).CreateNavigator();
                var xpathResults = xpathNavigator.Select(xpathQuery);

                if (xpathResults.Count == 0)
                {
                    throw new ElementNotFoundException($"The element with the name '{xpathQuery}' was not found in the XML document.");
                }
                else if (xpathResults.Count > 1)
                {
                    throw new MultipleElementsFoundException($"{xpathResults.Count} elements were found with the name '{xpathQuery}'.");
                }

                var element = xpathResults[0].Value;

                // Cache the XPath query for future use
                cachedQueries[xpathQuery] = element;

                return element;
            }
            catch (Exception ex)
            {
                throw new ArgumentException("The provided XPath query is not valid.", nameof(xpathQuery), ex);
            }
        }
    }
}
```
