```
using System;
using System.Collections.Generic;
using System.Linq;

namespace GetFirstMatchingElement
{
    public class CachedXPathQuery
    {
        private static Dictionary<string, string> cachedQueries = new Dictionary<string, string>();

        /// <summary>
        /// Adds a new XPath query to the cache.
        /// </summary>
        /// <param name="xpathQuery">The XPath query to add.</param>
        public static void AddXPathQuery(string xpathQuery)
        {
            cachedQueries[xpathQuery] = null;
        }

        /// <summary>
        /// Removes an XPath query from the cache.
        /// </summary>
        /// <param name="xpathQuery">The XPath query to remove.</param>
        public static void RemoveXPathQuery(string xpathQuery)
        {
            if (cachedQueries.ContainsKey(xpathQuery))
            {
                cachedQueries[xpathQuery] = null;
            }
        }

        /// <summary>
        /// Clears the cache of all XPath queries.
        /// </summary>
        public static void ClearCache()
        {
            cachedQueries.Clear();
        }

        /// <summary>
        /// Returns whether an XPath query is in the cache.
        /// </summary>
        /// <param name="xpathQuery">The XPath query to check.</param>
        /// <returns>True if the XPath query is in the cache, false otherwise.</returns>
        public static bool IsInCache(string xpathQuery)
        {
            return cachedQueries.ContainsKey(xpathQuery);
        }
    }
}
