namespace RandomGenerator {
    class MT19937Generator {
        private:
            std::mt19937 mt;
            int seed;
            bool cachedSeed = false;

        public:
            MT19937Generator(int seed) : seed(seed) {
                if (cachedSeed) {
                    mt.seed(seed);
                } else {
                    mt.seed(std::chrono::system_clock::now().time_since_epoch().count());
                }
            }

            ~MT19937Generator() {}

            int getRandomNumber(int min, int max) {
                if (cachedSeed) {
                    mt.discard(1);
                } else {
                    cachedSeed = true;
                }
                return std::uniform_int_distribution<int>(min, max)(mt);
            }

