```c
#include <openssl/des.h>

// Define the supported cipher modes
typedef enum {
    ECB, EDE, EDE3, CFB
} CipherMode;

// Define a structure to represent an EVP_CIPHER
struct EVP_CIPHER {
    const char* name;
    unsigned long block_size;
    unsigned long key_len;
    CipherMode mode;
};

// Define a function to initialize the DES encryption engine
void init_des_encrypt(const char* key, unsigned long key_len) {
    // Initialize the DES encryption engine with the specified key and key length
    DES_KEY_schedule schedule;
    DES_set_key(&schedule, key, key_len);
}

// Define a function to encrypt data using the DES algorithm
void des_encrypt(const char* plaintext, unsigned long plaintext_len, char* ciphertext) {
    // Encrypt the plaintext using the DES encryption engine
    DES_ecb_encrypt((DES_cblock*)plaintext, (DES_cblock*)ciphertext, &schedule, DES_ENCRYPT);
}

// Define a function to decrypt data using the DES algorithm
void des_decrypt(const char* ciphertext, unsigned long ciphertext_len, char* plaintext) {
    // Decrypt the ciphertext using the DES encryption engine
    DES_ecb_encrypt((DES_cblock*)ciphertext, (DES_cblock*)plaintext, &schedule, DES_DECRYPT);
}

// Define a function to generate an EVP_CIPHER structure for the specified cipher mode and key length
struct EVP_CIPHER* get_evp_cipher(const char* name, unsigned long block_size, unsigned long key_len, CipherMode mode) {
    // Allocate memory for the EVP_CIPHER structure
    struct EVP_CIPHER* evp = malloc(sizeof(struct EVP_CIPHER));
    if (evp == NULL) {
        return NULL;
    }

    // Initialize the EVP_CIPHER structure with the specified name, block size, key length, and cipher mode
    evp->name = strdup(name);
    evp->block_size = block_size;
    evp->key_len = key_len;
    evp->mode = mode;

    // Return the EVP_CIPHER structure
    return evp;
}

// Define a function to encrypt data using an EVP_CIPHER structure
void encrypt(const char* plaintext, unsigned long plaintext_len, struct EVP_CIPHER* cipher) {
    // Encrypt the plaintext using the specified EVP_CIPHER structure
    switch (cipher->mode) {
        case ECB:
            des_encrypt(plaintext, plaintext_len, cipher->name);
            break;
        case EDE:
            des_ede_encrypt(plaintext, plaintext_len, cipher->name);
            break;
        case EDE3:
            des_ede3_encrypt(plaintext, plaintext_len, cipher->name);
            break;
        case CFB:
            des_cfb_encrypt(plaintext, plaintext_len, cipher->name);
            break;
    }
}

// Define a function to decrypt data using an EVP_CIPHER structure
void decrypt(const char* ciphertext, unsigned long ciphertext_len, struct EVP_CIPHER* cipher) {
    // Decrypt the ciphertext using the specified EVP_CIPHER structure
    switch (cipher->mode) {
        case ECB:
            des_decrypt(ciphertext, ciphertext_len, cipher->name);
            break;
        case EDE:
            des_ede_decrypt(ciphertext, ciphertext_len, cipher->name);
            break;
        case EDE3:
            des_ede3_decrypt(ciphertext, ciphertext_len, cipher->name);
            break;
        case CFB:
            des_cfb_decrypt(ciphertext, ciphertext_len, cipher->name);
            break;
    }
}
