class FinancialSummary:
    def __init__(self, file_path, output_file_path, aggregation_params):
        self.file_path = file_path
        self.output_file_path = output_file_path
        self.aggregation_params = aggregation_params
        self.transactions = []
        self.summaries = {}

    def read_csv(self):
        with open(self.file_path, 'r') as f:
            reader = csv.reader(f)
            for row in reader:
                transaction = {
                    "date": datetime.strptime(row[0], "%Y-%m-%d"),
                    "type": row[1],
                    "amount": float(row[2]),
                    "currency": row[3]
                }
                self.transactions.append(transaction)

    def process_transactions(self):
        for transaction in self.transactions:
            date = transaction["date"]
            type = transaction["type"]
            amount = transaction["amount"]
            currency = transaction["currency"]
            if date in self.summaries:
                summary = self.summaries[date]
                if type == "deposit":
                    summary["deposits"] += amount
                elif type == "withdrawal":
                    summary["withdrawals"] += amount
                else:
                    raise ValueError(f"Invalid transaction type: {type}")
                summary["total_amount"] += amount
                summary["total_count"] += 1
            else:
                self.summaries[date] = {
                    "deposits": 0,
                    "withdrawals": 0,
                    "total_amount": 0,
                    "total_count": 0
                }
                if type == "deposit":
                    self.summaries[date]["deposits"] += amount
                elif type == "withdrawal":
                    self.summaries[date]["withdrawals"] += amount
                else:
                    raise ValueError(f"Invalid transaction type: {type}")
                self.summaries[date]["total_amount"] += amount
                self.summaries[date]["total_count"] += 1

