public class PokemonService {
    private final List<String> apiUrls = Arrays.asList(
            "https://pokeapi.co/api/v2/weaknesses",
            "https://pokeapi.co/api/v2/evolution-chain",
            "https://pokeapi.co/api/v2/habitat",
