    public PokemonService() {
        // Initialize the cache with empty data structures for each API URL
        apiUrls.forEach(url -> apiData.put(url, new ArrayList<>()));
    }

    public void fetchPokemonData(String pokemonId) {
        try {
            // Fetch the Pokemon ID from the primary API
            HttpResponse response = Unirest.get("https://pokeapi.co/api/v2/pokemon/" + pokemonId).asJson();
            JSONObject jsonResponse = new JSONObject(response.getBody().toString());

            // Fetch data from the external APIs using the Pokemon ID
            apiUrls.forEach(url -> {
                HttpResponse apiResponse = Unirest.get(url + "/" + pokemonId).asJson();
                JSONArray jsonData = new JSONArray(apiResponse.getBody().toString());
                if (jsonData.length() > 0) {
                    // Add the API response data to the cache
                    apiData.put(url, jsonData);
                } else {
                    // Fallback to using the cache data if available
                    apiData.put(url, new ArrayList<>());
                }
            });

            // Parse and handle the API responses
            JSONObject pokemonData = parsePokemonData(jsonResponse);
            List<JSONObject> weaknesses = parseWeaknesses(apiData.get("weaknesses"));
            List<JSONObject> evolutionChain = parseEvolutionChain(apiData.get("evolution-chain"));
            List<JSONObject> habitatInfo = parseHabitatInfo(apiData.get("habitat"));
            List<JSONObject> abilities = parseAbilities(apiData.get("abilities"));
            JSONObject heightWeightData = parseHeightWeightData(apiData.get("height-weight"));

            // Combine the API responses and return the Pokemon data in a JSON format
            JSONObject jsonPokemonData = new JSONObject();
            jsonPokemonData.put("name", pokemonData.getString("name"));
            jsonPokemonData.put("type", pokemonData.getString("type"));
            jsonPokemonData.put("weaknesses", weaknesses);
            jsonPokemonData.put("evolutionChain", evolutionChain);
            jsonPokemonData.put("habitat", habitatInfo);
            jsonPokemonData.put("abilities", abilities);
            jsonPokemonData.put("heightWeight", heightWeightData);

            return jsonPokemonData;
        } catch (UnirestException | JSONException e) {
            // Handle any potential exceptions gracefully
            System.out.println("Error: " + e.getMessage());
            return null;
        }
    }

    private JSONObject parsePokemonData(JSONObject jsonResponse) throws JSONException {
        // Parse the Pokemon data from the primary API response
        JSONObject pokemonData = new JSONObject();
        pokemonData.put("name", jsonResponse.getString("name"));
        pokemonData.put("type", jsonResponse.getString("type"));
        return pokemonData;
    }

    private List<JSONObject> parseWeaknesses(JSONArray jsonData) throws JSONException {
        // Parse the weakness data from the external API response
        List<JSONObject> weaknesses = new ArrayList<>();
        for (int i = 0; i < jsonData.length(); i++) {
            JSONObject weakness = new JSONObject();
            weakness.put("name", jsonData.getJSONObject(i).getString("name"));
            weakness.put("type", jsonData.getJSONObject(i).getString("type"));
            weaknesses.add(weakness);
        }
        return weaknesses;
    }

    private List<JSONObject> parseEvolutionChain(JSONArray jsonData) throws JSONException {
        // Parse the evolution chain data from the external API response
        List<JSONObject> evolutionChain = new ArrayList<>();
        for (int i = 0; i < jsonData.length(); i++) {
            JSONObject stage = new JSONObject();
            stage.put("stage", jsonData.getJSONObject(i).getString("stage"));
            stage.put("evolution", jsonData.getJSONObject(i).getString("evolution"));
            evolutionChain.add(stage);
        }
        return evolutionChain;
    }

    private List<JSONObject> parseHabitatInfo(JSONArray jsonData) throws JSONException {
        // Parse the habitat data from the external API response
        List<JSONObject> habitatInfo = new ArrayList<>();
        for (int i = 0; i < jsonData.length(); i++) {
            JSONObject habitat = new JSONObject();
            habitat.put("name", jsonData.getJSONObject(i).getString("name"));
            habitat.put("region", jsonData.getJSONObject(i).getString("region"));
            habitatInfo.add(habitat);
        }
        return habitatInfo;
    }

    private List<JSONObject> parseAbilities(JSONArray jsonData) throws JSONException {
        // Parse the ability data from the external API response
        List<JSONObject> abilities = new ArrayList<>();
        for (int i = 0; i < jsonData.length(); i++) {
            JSONObject ability = new JSONObject();
            ability.put("name", jsonData.getJSONObject(i).getString("name"));
            ability.put("type", jsonData.getJSONObject(i).getString("type"));
            abilities.add(ability);
        }
        return abilities;
    }

    private JSONObject parseHeightWeightData(JSONArray jsonData) throws JSONException {
        // Parse the height and weight data from the external API response
        JSONObject heightWeightData = new JSONObject();
        for (int i = 0; i < jsonData.length(); i++) {
            if (jsonData.getJSONObject(i).getString("name").equalsIgnoreCase("height")) {
                heightWeightData.put("height", jsonData.getJSONObject(i).getString("value"));
            } else if (jsonData.getJSONObject(i).getString("name").equalsIgnoreCase("weight")) {
                heightWeightData.put("weight", jsonData.getJSONObject(i).getString("value"));
            }
        }
        return heightWeightData;
    }
