                        continue

                    # Update processed data dictionary
                    processed_data[full_path] = data

            # Export processed data in various formats
            export_formats = ['Excel', 'SQL database dump']
            for format in export_formats:
                with open(f'processed_data_{format}.{format}', 'w') as f:
                    if format == 'Excel':
                        writer = csv.writer(f)
                        writer.writerow(['header'])
                        for row in processed_data.values():
                            writer.writerow([row])
                    elif format == 'SQL database dump':
                        f.write('INSERT INTO table (column1, column2) VALUES ')
                        for row in processed_data.values():
                            f.write(f'({", ".join(str(value) for value in row)})')

        except Exception as e:
            logger.error(f'Error processing files: {e}')
            continue

# Set up scalable Java service for retrieving Pokemon weaknesses and evolution details
pokemon_weaknesses = {}
pokemon_evolutions = {}

def get_weaknesses(id):
    if id in pokemon_weaknesses:
        return pokemon_weaknesses[id]

    # Retrieve weaknesses from external REST API
    response = requests.get(f'https://pokeapi.co/api/v2/pokemon/{id}/weaknesses')
    if response.status_code != 200:
        logger.error(f'Failed to retrieve weaknesses for Pokemon {id}')
        return []

    # Update cache and return weaknesses
    pokemon_weaknesses[id] = response.json()['results']
    return pokemon_weaknesses[id]

def get_evolution(id):
    if id in pokemon_evolutions:
        return pokemon_evolutions[id]

    # Retrieve evolution details from external REST API
    response = requests.get(f'https://pokeapi.co/api/v2/pokemon/{id}/evolution')
    if response.status_code != 200:
        logger.error(f'Failed to retrieve evolution details for Pokemon {id}')
        return {}

    # Update cache and return evolution details
    pokemon_evolutions[id] = response.json()['results']
    return pokemon_evolutions[id]

# Set up scalable Java service for handling incoming requests
def handle_requests(requests):
    responses = []
    for request in requests:
        if request.endswith('.pokemon'):
            id = request.split('.')[0]
            weaknesses = get_weaknesses(id)
            evolutions = get_evolution(id)
            response = {
                'weaknesses': weaknesses,
                'evolution': evolutions
            }
        else:
            logger.warn(f'Invalid request: {request}')
            response = {}

        responses.append(response)

    return responses
