import json
from typing import Dict, List

class ConfigLoader:
    def __init__(self, config_file: str, encryption_key: bytes):
        self.config_file = config_file
        self.encryption_key = encryption_key

    def load(self) -> Dict[str, List]:
        # Load the configuration file and decrypt it using the provided encryption key
        with open(self.config_file, "r") as f:
            config = json.load(f)

        # Validate the configuration settings against a dynamic schema that changes based on environmental variables or a separate schema file
        validation_schema = {
            "log_level": {"type": "string", "enum": ["debug", "info", "warn", "error"]},
            "output_format": {"type": "string", "enum": ["json", "plain"]},
            "destination": {"type": "string", "enum": ["file", "console", "remote_server"]}
        }

        schema = {
            "loggers": [
                {
                    "name": str,
                    "level": str,
                    "format": str,
                    "destination": {"type": "string", "enum": ["file", "console", "remote_server"]}
                }
            ]
        }

        # Use the validated settings to configure a multi-threaded logging framework dynamically, based on the log level, output format, and destination (file, console, or remote server)
        if not schema.validate(config):
            raise ValidationError("Invalid configuration")

        loggers = {}
        for logger in config["loggers"]:
            name = logger["name"]
            level = logger["level"]
            format = logger["format"]
            destination = logger["destination"]

            if destination == "file":
                # Create a file handler for the logger
                file_handler = logging.FileHandler(f"{name}.log")
                file_handler.setLevel(level)
                file_handler.setFormatter(logging.Formatter(format))

                loggers[name] = {"file": file_handler}
            elif destination == "console":
                # Create a stream handler for the logger
                console_handler = logging.StreamHandler()
                console_handler.setLevel(level)
                console_handler.setFormatter(logging.Formatter(format))

                loggers[name] = {"stream": console_handler}
            elif destination == "remote_server":
                # Create a remote server handler for the logger
                remote_server_handler = logging.RemoteServerHandler(f"{name}.log")
                remote_server_handler.setLevel(level)
                remote_server_handler.setFormatter(logging.Formatter(format))

                loggers[name] = {"remote_server": remote_server_handler}
            else:
                raise ValueError(f"Invalid destination '{destination}'")

        return loggers

    def get_logger(self, name: str) -> logging.Logger:
        """Get a logger instance for the specified name"""
        if name not in self.loggers:
            raise ValueError(f"Unknown logger '{name}'")

        return self.loggers[name]
