import json
import time
from datetime import datetime
from typing import Dict, List
from urllib.parse import urlparse

import requests
import psycopg2

SENSOR_DATA_TABLE = "sensor_data"
SENSOR_METADATA_TABLE = "sensor_metadata"

class DataSync:
    def __init__(self, db_url: str, auth_token: str):
        self.db_url = db_url
        self.auth_token = auth_token
        self.conn = None
        self.cursor = None

    def connect(self):
        if not self.conn or not self.cursor:
            try:
                self.conn = psycopg2.connect(self.db_url, sslmode='require')
                self.cursor = self.conn.cursor()
            except Exception as e:
                print("Failed to connect to PostgreSQL database:", e)
                return False
        return True

    def disconnect(self):
        if self.conn and self.cursor:
            try:
                self.conn.close()
                self.cursor = None
                self.conn = None
            except Exception as e:
                print("Failed to close PostgreSQL connection:", e)

    def get_sensor_data(self, sensor_id: int):
        query = f"SELECT * FROM {SENSOR_DATA_TABLE} WHERE sensor_id = %s"
        self.cursor.execute(query, (sensor_id,))
        return self.cursor.fetchall()

    def get_sensor_metadata(self, sensor_id: int):
        query = f"SELECT * FROM {SENSOR_METADATA_TABLE} WHERE sensor_id = %s"
        self.cursor.execute(query, (sensor_id,))
        return self.cursor.fetchall()

    def insert_sensor_data(self, sensor_data: Dict[str, List]):
        query = f"""INSERT INTO {SENSOR_DATA_TABLE} (sensor_id, reading_time, data)
                   VALUES (%s, %s, %s)"""
        self.cursor.execute(query, (sensor_data['sensor_id'], sensor_data['reading_time'], json.dumps(sensor_data['data'])))

    def insert_sensor_metadata(self, sensor_metadata: Dict[str, str]):
        query = f"""INSERT INTO {SENSOR_METADATA_TABLE} (sensor_id, metadata)
                   VALUES (%s, %s)"""
        self.cursor.execute(query, (sensor_metadata['sensor_id'], json.dumps(sensor_metadata)))

    def validate_data(self, data: Dict[str, List]):
        schema = {
            "type": "object",
            "properties": {
                "sensor_id": {"type": "integer"},
                "reading_time": {"type": "string"},
                "data": {"type": "array"}
            },
            "required": ["sensor_id", "reading_time", "data"]
        }
        try:
            jsonschema.validate(instance=data, schema=schema)
            return True
        except jsonschema.ValidationError as e:
            print("Data validation failed with error:", e)
            return False

    def validate_metadata(self, metadata: Dict[str, str]):
        schema = {
            "type": "object",
            "properties": {
                "sensor_id": {"type": "integer"},
                "metadata": {"type": "string"}
            },
            "required": ["sensor_id", "metadata"]
        }
        try:
            jsonschema.validate(instance=metadata, schema=schema)
            return True
        except jsonschema.ValidationError as e:
            print("Metadata validation failed with error:", e)
            return False

    def get_api_data(self, url: str):
        try:
            response = requests.get(url=url, headers={'Authorization': f"Bearer {self.auth_token}"})
            if response.status_code == 200:
                return response.json()
            else:
                print("API call failed with status code", response.status_code)
        except requests.exceptions.RequestException as e:
            print("Failed to make API request:", e)

    def handle_api_response(self, api_data: Dict[str, List]):
        sensor_id = api_data['sensor_id']
        reading_time = datetime.now().isoformat()
        data = api_data['data']
        metadata = api_data['metadata']
        if not self.validate_data(api_data):
            print("Data validation failed for sensor", sensor_id)
            return False
        if not self.validate_metadata(metadata):
            print("Metadata validation failed for sensor", sensor_id)
            return False
        self.insert_sensor_data({'sensor_id': sensor_id, 'reading_time': reading_time, 'data': data})
        self.insert_sensor_metadata({'sensor_id': sensor_id, 'metadata': metadata})
        return True

    def handle_api_failure(self, api_url: str):
        try:
            response = requests.get(url=api_url, headers={'Authorization': f"Bearer {self.auth_token}"}, timeout=10)
            if response.status_code == 200:
                return True
            else:
                print("API call failed with status code", response.status_code)
        except requests.exceptions.RequestException as e:
            print("Failed to make API request:", e)
        return False

    def sync_data(self, api_urls: List[str]):
        for api_url in api_urls:
            sensor_id = urllib.parse.parse_qs(api_url)['sensor_id'][0]
            if not self.handle_api_failure(api_url):
                print("API call failed for sensor", sensor_id)
                return False
            api_data = self.get_api_data(api_url)
            if not self.handle_api_response(api_data):
                print("Data insertion failed for sensor", sensor_id)
                return False
        return True
