// Main function for generating reports
struct ReportResponse generateReport(struct ReportRequest* request) {
    struct ReportData* data = request->data;
    char* database = data->database;
    char* table = data->table;
    char* columns[] = data->columns;
    bool is_email_report = request->is_email_report;
    char* message_format = request->message_format;
    struct AnalyticsConfig* config = request->config;

    // Fetch the data from the database
    char* fetched_data = fetchData(database, table);
    if (fetched_data == NULL) {
        return createReportResponse(false, "Error fetching data", NULL);
    }

    // Parse the data based on the format
    char* parsed_data = parseData(fetched_data, message_format);
    if (parsed_data == NULL) {
        free(fetched_data);
        return createReportResponse(false, "Error parsing data", NULL);
    }
    free(fetched_data);

    // Aggregate and transform the data based on the report configuration
    char* processed_data = processData(parsed_data, request);
    if (processed_data == NULL) {
        return createReportResponse(false, "Error processing data", NULL);
    }

    // Generate the report in the specified format
    char* generated_report = generateReport(processed_data, message_format);
    if (generated_report == NULL) {
        return createReportResponse(false, "Error generating report", NULL);
    }

    // Send the report via email or SMS depending on the request
    bool is_sent = false;
    if (is_email_report) {
        is_sent = sendEmailReport(generated_report, request);
    } else {
        is_sent = sendSmsReport(generated_report, request);
    }
    if (!is_sent) {
        return createReportResponse(false, "Error sending report", NULL);
    }

    // Track the report generation event and user interaction using the analytics configuration
    trackAnalyticsEvent(request);

    // Cache the processed data based on the report configuration and frequency of access
    cacheData(processed_data, request);

    // Return the generated report response
    return createReportResponse(true, "Success", generated_report);
}

// Create a report response structure with success status and error message if any
struct ReportResponse createReportResponse(bool success, char* error_message, char* data) {
    struct ReportResponse response;
    response.success = success;
    response.error_message = error_message;
    response.report_data = data;
    return response;
}
