import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.common.PDMetadata;
import org.apache.pdfbox.rendering.PDFRenderer;

public class ImageToPdf {
    private static final int DEFAULT_RESOLUTION = 300;
    private static final String DEFAULT_OUTPUT_FILENAME = "output.pdf";
    private static final boolean DEFAULT_WATERMARK = false;

    public static void main(String[] args) throws IOException {
        // Parse command-line arguments
        String inputDirPath = args[0];
        String outputFileName = args[1];
        boolean watermark = Boolean.parseBoolean(args[2]);

        // Initialize PDF document and renderer
        PDDocument doc = new PDDocument();
        PDFRenderer renderer = new PDFRenderer(doc);

        // Get list of image files in the input directory
        List<File> imageFiles = getImageFiles(inputDirPath);

        // Convert images to PDF pages
        for (File imageFile : imageFiles) {
            // Fetch metadata from external service
            ImageMetadata metadata = fetchMetadata(imageFile.getAbsolutePath());

            // Create a new page in the PDF document
            PDPage page = doc.createPage(PDRectangle.A4);

            // Add image to the page
            renderer.drawImage(page, imageFile.getAbsolutePath(), DEFAULT_RESOLUTION, metadata.getResolution());

            // Set watermark on the page (if applicable)
            if (watermark) {
                PDMetadata metadata = new PDMetadata(doc);
                metadata.importXML("http://www.aiim.org/pdfa/ns/id/", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><x:xmpmeta xmlns:x=\"adobe:ns:meta/\"><rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\"><rdf:Description rdf:about=\"\"/></rdf:RDF></x:xmpmeta>");
                page.setThumbnail(metadata);
            }

            // Add the page to the PDF document
            doc.addPage(page);
        }

        // Save the PDF document
        doc.save(outputFileName);

        // Close the PDF document
        doc.close();
    }

    private static List<File> getImageFiles(String inputDirPath) {
        File inputDir = new File(inputDirPath);
        if (!inputDir.exists()) {
            throw new IllegalArgumentException("Invalid input directory path");
        }

        List<File> imageFiles = new ArrayList<>();
        for (File file : inputDir.listFiles()) {
            if (file.isDirectory()) {
                imageFiles.addAll(getImageFiles(file.getAbsolutePath()));
            } else {
                String fileName = file.getName().toLowerCase();
                if (fileName.endsWith(".jpg") || fileName.endsWith(".jpeg") || fileName.endsWith(".png") || fileName.endsWith(".gif")) {
                    imageFiles.add(file);
                }
            }
        }

        return imageFiles;
    }

    private static ImageMetadata fetchMetadata(String filePath) throws IOException {
        // Fetch metadata from external service using HTTP request
        String response = HttpRequest.sendGet("http://metadata-service/getMetadata?file=" + filePath);

        // Parse the response and extract required information
        JsonObject jsonObj = new Gson().fromJson(response, JsonObject.class);
        int resolution = jsonObj.get("resolution").getAsInt();
        int colorDepth = jsonObj.get("colorDepth").getAsInt();
        long fileSize = jsonObj.get("fileSize").getAsLong();

        // Return the metadata object
        return new ImageMetadata(resolution, colorDepth, fileSize);
    }
}

class ImageMetadata {
    private int resolution;
    private int colorDepth;
    private long fileSize;

    public ImageMetadata(int resolution, int colorDepth, long fileSize) {
        this.resolution = resolution;
        this.colorDepth = colorDepth;
        this.fileSize = fileSize;
    }

    public int getResolution() {
        return resolution;
    }

    public int getColorDepth() {
        return colorDepth;
    }

    public long getFileSize() {
        return fileSize;
    }
}
