// Structure to store a record with an int key and a char pointer message
typedef struct {
    int key;
    char *message;
} Record;

// Function to initialize the arrays of offsets, keys, and records
void init_records(long *offsets, int *keys, Record **records, int num_records, int min_value, int max_value, size_t message_size) {
    // Allocate memory for the offsets array
    offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets array\n");
        return;
    }

    // Allocate memory for the keys array
    keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys array\n");
        free(offsets);
        return;
    }

    // Allocate memory for the records array
    records = (Record **)malloc(num_records * sizeof(Record *));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the offsets and keys arrays with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = rand() % max_value + min_value;
    }

    // Initialize the records array with descriptive messages
    for (int i = 0; i < num_records; i++) {
        Record *record = (Record *)malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        // Generate a descriptive message using the random integer value as an index into a lookup table
        char *message = (char *)malloc(message_size * sizeof(char));
        if (!message) {
            fprintf(stderr, "Error: Failed to allocate memory for message %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            return;
        }

        strcpy(message, LOOKUP_TABLE[keys[i]]);
        record->key = keys[i];
        record->message = message;
        records[i] = record;
    }
}

// Function to persist the initialized arrays into a file
void persist_records(long *offsets, int *keys, Record **records, int num_records) {
    // Open the output file for writing
    FILE *file = fopen("output.txt", "w");
    if (!file) {
        fprintf(stderr, "Error: Failed to open output file\n");
        return;
    }

    // Write the offsets array to the file
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%ld ", offsets[i]);
    }
    fprintf(file, "\n");

    // Write the keys array to the file
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d ", keys[i]);
    }
    fprintf(file, "\n");

    // Write the records array to the file
    for (int i = 0; i < num_records; i++) {
        Record *record = records[i];
        fprintf(file, "%d %s\n", record->key, record->message);
    }

    // Close the output file
    fclose(file);
}
```
This code includes a function called `init_records` that dynamically allocates memory for three arrays: an array of long integers (offsets), an array of integers (keys), and an array of pointers to structures containing a single integer key and a character pointer message. The function also initializes the offsets and keys arrays with random values within the specified range, and the records array with descriptive messages generated using the random integer values as indices into a lookup table.

The `persist_records` function takes the same three arrays as input and writes them to a file called "output.txt" in the current directory. The output file includes one line for each record, where each line consists of the offset value, key value, and descriptive message separated by spaces.

The `init_records` and `persist_records` functions include error handling to manage cases where memory allocation fails, and ensure that the function can handle a large number of records efficiently. The `LOOKUP_TABLE` array is used to generate the descriptive messages for each record.

