public class PokemonWeaknesses {
  private static final Map<String, String> WEAKNESSES_CACHE = new ConcurrentHashMap<>();
  private static final int CACHE_EXPIRATION_TIME_MINUTES = 30;

  public static Map<String, String> getWeaknesses(List<Pokemon> pokemons) {
    // Check if the cache has expired and update it if necessary
    updateCacheIfExpired();

    // Retrieve the weaknesses for each Pokemon from the cache or API
    Map<String, String> weaknesses = new HashMap<>();
    for (Pokemon pokemon : pokemons) {
      String type = pokemon.getType();
      if (WEAKNESSES_CACHE.containsKey(type)) {
        weaknesses.put(pokemon, WEAKNESSES_CACHE.get(type));
      } else {
        try {
          // Make an API request to retrieve the weaknesses for this type
          String response = makeRequest(type);

          // Parse the JSON response and extract the weaknesses
          Map<String, Object> jsonResponse = parseJsonResponse(response);
          List<String> weaknessesList = (List<String>) jsonResponse.get("weaknesses");

          // Add the weaknesses to the cache for future use
          WEAKNESSES_CACHE.put(type, weaknessesList);

          // Return the weaknesses for this Pokemon
          weaknesses.put(pokemon, weaknessesList);
        } catch (Exception e) {
          // Log the error and return the last known good weaknesses
          logger.error("Error retrieving weaknesses for type " + type, e);
          weaknesses.put(pokemon, WEAKNESSES_CACHE.get(type));
        }
      }
    }

    return weaknesses;
  }

  private static void updateCacheIfExpired() {
    if (WEAKNESSES_CACHE.isEmpty() || System.currentTimeMillis() - WEAKNESSES_CACHE.get("lastUpdated") > CACHE_EXPIRATION_TIME_MINUTES * 60 * 1000) {
      try {
        // Make an API request to retrieve the latest weaknesses
        String response = makeRequest();

        // Parse the JSON response and update the cache
