```
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <variant>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>
#include <algorithm>
#include <cassert>
#include <openssl/aes.h>
#include <openssl/chacha.h>
#include <openssl/sha.h>

// Define the cryptographic algorithms supported by the utility
enum class Algorithm { AES256, ChaCha20 };

// Define the hashing algorithms supported by the utility
enum class HashAlgorithm { SHA256, SHA384, SHA512 };

// Define the structure to hold configuration settings
struct Configuration {
    // Array size for processing
    int array_size;
    // API endpoint for fetching element metadata
    std::string api_endpoint;
    // Communication protocols
    std::vector<std::string> communication_protocols;
    // Security policies
    std::unordered_map<std::string, std::variant<int, double, std::string, bool, std::vector<std::string>>> security_policies;
};

// Define the structure to hold cryptographic resources
struct CryptographicResource {
    // The algorithm used for encryption/decryption
    Algorithm algorithm;
    // The hashing algorithm used for message authentication
    HashAlgorithm hash_algorithm;
    // The key used for encryption/decryption
    std::string key;
};

// Define the structure to hold thread-safe JSON parsing data
struct JsonData {
    // The configuration settings from the JSON file
    Configuration config;
    // The cryptographic resources required for encryption/decryption
    CryptographicResource resource;
};

// Define the class to handle multi-threaded cryptographic operations
class CryptoUtility {
private:
    // A mutex to protect concurrent access to the JSON data
    std::mutex json_data_mutex_;
    // A condition variable to signal when new JSON data is available
    std::condition_variable json_data_cond_;
    // The JSON data structure
    JsonData json_data_;
    // A flag indicating whether the utility has been initialized
    bool initialized_ = false;

public:
    // Constructor
    CryptoUtility() {
        // Initialize the JSON data structure with default values
        json_data_.config.array_size = 1024;
        json_data_.config.api_endpoint = "https://example.com/api";
        json_data_.config.communication_protocols = { "HTTP", "WebSocket" };
        json_data_.config.security_policies["minimum_password_length"] = 8;
        json_data_.resource.algorithm = Algorithm::AES256;
        json_data_.resource.hash_algorithm = HashAlgorithm::SHA256;
    }

    // Initialize the utility with configuration settings from a JSON file
    void initialize(const std::string& config_file) {
        if (initialized_) {
            return;
        }

        // Lock the mutex to protect concurrent access to the JSON data
        std::lock_guard<std::mutex> lock(json_data_mutex_);

        // Load the configuration settings from the JSON file
        if (!loadConfiguration(config_file, json_data_.config)) {
            std::cerr << "Failed to load configuration settings" << std::endl;
            return;
        }

        // Dynamically load the cryptographic algorithms and initialize them with the configuration settings
        if (!initializeCryptographicResources(json_data_.config, json_data_.resource)) {
            std::cerr << "Failed to initialize cryptographic resources" << std::endl;
            return;
        }

        // Set the flag indicating that the utility has been initialized
        initialized_ = true;
    }

    // Encrypt a message using the specified cryptographic algorithm and key
    std::string encrypt(const std::string& plaintext, const CryptographicResource& resource) {
        if (!initialized_) {
            throw std::runtime_error("Utility has not been initialized");
        }

        // Lock the mutex to protect concurrent access to the JSON data
        std::lock_guard<std::mutex> lock(json_data_mutex_);

        // Validate the input parameters
        if (plaintext.empty()) {
            throw std::invalid_argument("Plaintext is empty");
        }
        if (!resource.algorithm) {
            throw std::invalid_argument("Cryptographic algorithm is not specified");
        }
        if (resource.key.empty()) {
            throw std::invalid_argument("Key is empty");
        }

        // Encrypt the message using the specified cryptographic algorithm and key
        switch (resource.algorithm) {
            case Algorithm::AES256:
                return AES_encrypt(plaintext, resource.key);
            case Algorithm::ChaCha20:
                return ChaCha20_encrypt(plaintext, resource.key);
        }
    }

    // Decrypt a message using the specified cryptographic algorithm and key
    std::string decrypt(const std::string& ciphertext, const CryptographicResource& resource) {
        if (!initialized_) {
            throw std::runtime_error("Utility has not been initialized");
        }

        // Lock the mutex to protect concurrent access to the JSON data
        std::lock_guard<std::mutex> lock(json_data_mutex_);

        // Validate the input parameters
        if (ciphertext.empty()) {
            throw std::invalid_argument("Ciphertext is empty");
        }
        if (!resource.algorithm) {
            throw std::invalid_argument("Cryptographic algorithm is not specified");
        }
        if (resource.key.empty()) {
            throw std::invalid_argument("Key is empty");
        }

        // Decrypt the message using the specified cryptographic algorithm and key
        switch (resource.algorithm) {
            case Algorithm::AES256:
                return AES_decrypt(ciphertext, resource.key);
            case Algorithm::ChaCha20:
                return ChaCha20_decrypt(ciphertext, resource.key);
        }
    }

private:
    // Load the configuration settings from a JSON file
    bool loadConfiguration(const std::string& config_file, JsonData& data) {
        // Open the JSON file for reading
        std::ifstream in(config_file);
        if (!in.is_open()) {
            return false;
        }

        // Parse the JSON file and load the configuration settings
        rapidjson::IStreamWrapper isw(in);
        rapidjson::Document document;
        document.ParseStream(isw);
        if (document.HasParseError() || !document.IsObject()) {
            return false;
        }

        // Load the array size setting
        if (!document["array_size"].IsUint()) {
            return false;
        }
        data.config.array_size = document["array_size"].GetUint();

        // Load the API endpoint setting
        if (!document["api_endpoint"].IsString()) {
            return false;
        }
        std::string api_endpoint = document["api_endpoint"].GetString();
        data.config.api_endpoint = api_endpoint;

        // Load the communication protocols setting
        if (!document["communication_protocols"].IsArray()) {
            return false;
        }
        rapidjson::Value& communication_protocols = document["communication_protocols"];
        for (rapidjson::SizeType i = 0; i < communication_protocols.Size(); ++i) {
            if (!communication_protocols[i].IsString()) {
                return false;
            }
            data.config.communication_protocols.push_back(communication_protocols[i].GetString());
        }

        // Load the security policies setting
        if (!document["security_policies"].IsObject()) {
            return false;
        }
        rapidjson::Value& security_policies = document["security_policies"];
        for (rapidjson::SizeType i = 0; i < security_policies.MemberCount(); ++i) {
            if (!security_policies[i].value.IsString()) {
                return false;
            }
            data.config.security_policies[security_policies[i].name.GetString()] = security_policies[i].value.GetString();
        }
    }

    // Initialize the cryptographic resources required for encryption/decryption using the specified configuration settings
    bool initializeCryptographicResources(const JsonData& data, CryptographicResource& resource) {
        // Validate the input parameters
        if (!data.config.array_size || !data.config.api_endpoint || !data.config.communication_protocols.empty() || !data.config.security_policies.empty()) {
            return false;
        }

        // Dynamically load the cryptographic libraries and initialize them with the configuration settings
        if (!initializeAESCryptography(data.config, resource.aes_resource)) {
            std::cerr << "Failed to initialize AES cryptography" << std::endl;
            return false;
        }
        if (!initializeChaCha20Cryptography(data.config, resource.chacha20_resource)) {
            std::cerr << "Failed to initialize ChaCha20 cryptography" << std::endl;
            return false;
        }
    }
};

// AES encryption and decryption functions
std::string AES_encrypt(const std::string& plaintext, const std::string& key) {
    // Validate the input parameters
    if (plaintext.empty() || key.empty()) {
        throw std::invalid_argument("Plaintext or key is empty");
    }

    // Create a AES cipher object with the specified key
    const std::string& mode = "CBC";
    std::unique_ptr<AESCipher> cipher(new AESCipher(key, mode));
    if (!cipher->isValid()) {
        return "";
    }

    // Encrypt the plaintext using the specified key and mode
    const unsigned char* plaintext_buffer = reinterpret_cast<const unsigned char*>(plaintext.c_str());
    int plaintext_length = plaintext.size();
    std::vector<unsigned char> ciphertext(plaintext_length + AES_BLOCK_SIZE);
    int ciphertext_length = cipher->encrypt(plaintext_buffer, plaintext_length, ciphertext.data());

    // Return the encrypted ciphertext as a string
    return std::string((const char*)ciphertext.data(), ciphertext_length);
}

std::string AES_decrypt(const std::string& ciphertext, const std::string& key) {
    // Validate the input parameters
    if (ciphertext.empty() || key.empty()) {
        throw std::invalid_argument("Ciphertext or key is empty");
    }

    // Create a AES cipher object with the specified key
    const std::string& mode = "CBC";
    std::unique_ptr<AESCipher> cipher(new AESCipher(key, mode));
    if (!cipher->isValid()) {
        return "";
    }

    // Decrypt the ciphertext using the specified key and mode
    const unsigned char* ciphertext_buffer = reinterpret_cast<const unsigned char*>(ciphertext.c_str());
    int ciphertext_length = ciphertext.size();
    std::vector<unsigned char> plaintext(ciphertext_length + AES_BLOCK_SIZE);
    int plaintext_length = cipher->decrypt(ciphertext_buffer, ciphertext_length, plaintext.data());

    // Return the decrypted plaintext as a string
    return std::string((const char*)plaintext.data(), plaintext_length);
}

// ChaCha20 encryption and decryption functions
std::string ChaCha20_encrypt(const std::string& plaintext, const std::string& key) {
    // Validate the input parameters
    if (plaintext.empty() || key.empty()) {
        throw std::invalid_argument("Plaintext or key is empty");
    }

    // Create a ChaCha20 cipher object with the specified key
    const std::string& mode = "chacha20";
    std::unique_ptr<AESCipher> cipher(new AESCipher(key, mode));
    if (!cipher->isValid()) {
        return "";
    }

    // Encrypt the plaintext using the specified key and mode
    const unsigned char* plaintext_buffer = reinterpret_cast<const unsigned char*>(plaintext.c_str());
    int plaintext_length = plaintext.size();
    std::vector<unsigned char> ciphertext(plaintext_length + AES_BLOCK_SIZE);
    int ciphertext_length = cipher->encrypt(plaintext_buffer, plaintext_length, ciphertext.data());

    // Return the encrypted ciphertext as a string
    return std::string((const char*)ciphertext.data(), ciphertext_length);
}

std::string ChaCha20_decrypt(const std::string& ciphertext, const std::string& key) {
    // Validate the input parameters
    if (ciphertext.empty() || key.empty()) {
        throw std::invalid_argument("Ciphertext or key is empty");
    }

    // Create a ChaCha20 cipher object with the specified key
    const std::string& mode = "chacha20";
    std::unique_ptr<AESCipher> cipher(new AESCipher(key, mode));
    if (!cipher->isValid()) {
        return "";
    }

    // Decrypt the ciphertext using the specified key and mode
    const unsigned char* ciphertext_buffer = reinterpret_cast<const unsigned char*>(ciphertext.c_str());
    int ciphertext_length = ciphertext.size();
    std::vector<unsigned char> plaintext(ciphertext_length + AES_BLOCK_SIZE);
    int plaintext_length = cipher->decrypt(ciphertext_buffer, ciphertext_length, plaintext.data());

