const express = require('express');
const router = express.Router();
const db = require('../database/connection');

// Update an existing resource using the HTTP PUT method
router.put('/:id', async (req, res) => {
  const id = req.params.id;
  const requestBody = req.body;

  // Check if the version number in the request body matches the current version of the resource
  const currentVersion = await db.getResourceVersion(id);
  if (currentVersion !== requestBody.version) {
    return res.status(409).json({ message: 'Version mismatch' });
  }

  // Update the resource with the new data
  const updatedResource = await db.updateResource(id, requestBody);

  // If the update was successful, return the updated resource
  if (updatedResource) {
    res.json(updatedResource);
  } else {
    // If the update failed, return an error message
    res.status(500).json({ message: 'Failed to update resource' });
  }
});

// Soft delete a resource by marking it as deleted instead of physically removing it from the database
router.delete('/:id', async (req, res) => {
  const id = req.params.id;

  // Check if the resource exists in the database before trying to delete it
  const resourceExists = await db.checkResourceExistence(id);
  if (!resourceExists) {
    return res.status(404).json({ message: 'Resource not found' });
  }

  // Mark the resource as deleted in the database
  const deletedResource = await db.markResourceAsDeleted(id);

  // If the delete was successful, return a success message
  if (deletedResource) {
    res.json({ message: 'Resource deleted successfully' });
  } else {
    // If the delete failed, return an error message
    res.status(500).json({ message: 'Failed to delete resource' });
  }
});

// Manage database transactions to ensure data consistency during update operations
async function manageTransactions(id, requestBody) {
  try {
    await db.beginTransaction();
    const updatedResource = await updateResource(id, requestBody);
    if (updatedResource) {
      await db.commit();
      return updatedResource;
    } else {
      await db.rollback();
      throw new Error('Failed to update resource');
    }
  } catch (error) {
    await db.rollback();
    throw error;
  }
}

// Implement optimistic concurrency control to prevent stale data issues by including a version number in the request body that must match the current version of the resource to be updated
async function checkVersionMatch(id, requestBody) {
  try {
    const currentVersion = await db.getResourceVersion(id);
    if (currentVersion === requestBody.version) {
      return true;
    } else {
      throw new Error('Version mismatch');
    }
  } catch (error) {
    throw error;
  }
}

// Provide a user-friendly response format for both success and failure scenarios
function generateResponse(success, message, data) {
  return {
    success,
    message,
    data,
  };
}
```
In this code block, we define two routes: one for updating an existing resource using the HTTP PUT method and another for soft deleting a resource. Both routes use asynchronous functions to handle database transactions and error handling, respectively. The `manageTransactions` function is used to manage database transactions to ensure data consistency during update operations. The `checkVersionMatch` function implements optimistic concurrency control by including a version number in the request body that must match the current version of the resource to be updated. Finally, both routes provide a user-friendly response format for both success and failure scenarios using the `generateResponse` function.

