#include <iostream>
#include <forward_list>
#include <string>

bool updateForwardList(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    bool found = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == key) {
            found = true;
            break;
        }
    }

    if (!found && !value.empty()) {
        list.push_back(value);
        return true;
    } else if (found && value.empty()) {
        return false;
    } else if (!found && value.empty()) {
        return false;
    } else {
        *it = value;
        return true;
    }
}
