using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Text;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace ClinicStatusUpdateMiddleware
{
    public class Middleware
    {
        private readonly HttpClient _httpClient;
        private readonly List<string> _allowedStatuses;
        private readonly Dictionary<string, string> _statusTranslations;
        private readonly HashSet<string> _prohibitedWords;
        private readonly IAuditSystem _auditSystem;

        public Middleware(HttpClient httpClient, List<string> allowedStatuses, Dictionary<string, string> statusTranslations, HashSet<string> prohibitedWords, IAuditSystem auditSystem)
        {
            _httpClient = httpClient;
            _allowedStatuses = allowedStatuses;
            _statusTranslations = statusTranslations;
            _prohibitedWords = prohibitedWords;
            _auditSystem = auditSystem;
        }

        public async Task<bool> UpdateClinicStatusAsync(string clinicId, string newStatus, string lastModifiedIpAddress, string lastModifiedByUserId, string language)
        {
            try
            {
                var updatedDetails = await GetUpdatedClinicStatusDetailsAsync(clinicId);

                if (updatedDetails == null)
                {
                    return false;
                }

                var newStatusTranslation = _statusTranslations.GetValueOrDefault(newStatus, newStatus);
                var oldStatusTranslation = updatedDetails.StatusTranslation;

                // Check if the new status is allowed
                if (!_allowedStatuses.Contains(newStatus))
                {
                    throw new Exception($"The new status '{newStatus}' is not allowed.");
                }

                // Check if the new status contains prohibited words
                if (_prohibitedWords.Any(pw => newStatusTranslation.IndexOf(pw, StringComparison.OrdinalIgnoreCase) >= 0))
                {
                    throw new Exception($"The new status '{newStatus}' contains prohibited words.");
                }

                // Check if the new status format is valid
                var regex = new Regex(@"^[A-Z][a-z]*$");
                if (!regex.IsMatch(newStatusTranslation))
                {
                    throw new Exception($"The new status '{newStatus}' does not meet the format requirements.");
                }

                // Check if the new status violates any business rules
                if (/* check business rules */)
                {
                    throw new Exception($"The new status '{newStatus}' violates one or more business rules.");
                }

                // Update the clinic status in the database
                using var dbContext = new DatabaseContext();
                var clinic = dbContext.Clinics.FirstOrDefault(c => c.Id == clinicId);
                if (clinic != null)
                {
                    clinic.Status = newStatus;
                    dbContext.SaveChanges();
                }

                // Send email notifications to clinic administrators
                var notificationDetails = GetEmailNotificationDetails(updatedDetails, newStatusTranslation);
                await SendEmailNotificationsAsync(notificationDetails);

                return true;
            }
            catch (Exception ex)
            {
                _auditSystem.LogError($"Failed to update clinic status for clinic '{clinicId}': {ex.Message}");
                return false;
            }
        }

        private async Task<ClinicStatusDetails> GetUpdatedClinicStatusDetailsAsync(string clinicId)
        {
            try
            {
                using var dbContext = new DatabaseContext();
                var clinic = dbContext.Clinics.FirstOrDefault(c => c.Id == clinicId);

                if (clinic != null)
                {
                    return new ClinicStatusDetails
                    {
                        Status = clinic.Status,
                        StatusTranslation = _statusTranslations.GetValueOrDefault(clinic.Status, clinic.Status),
                        Language = clinic.Language
                    };
                }
            }
            catch (Exception ex)
            {
                _auditSystem.LogError($"Failed to retrieve updated clinic status details for clinic '{clinicId}': {ex.Message}");
            }

            return null;
        }

        private async Task SendEmailNotificationsAsync(IEnumerable<EmailNotificationDetails> notificationDetails)
        {
            try
            {
                using var smtpClient = new SmtpClient();
                foreach (var notification in notificationDetails)
                {
                    await smtpClient.SendMailAsync(notification.Sender, notification.Recipients, notification.Subject, notification.Body);
                }
            }
            catch (Exception ex)
            {
                _auditSystem.LogError($"Failed to send email notifications: {ex.Message}");
            }
        }

        private EmailNotificationDetails GetEmailNotificationDetails(ClinicStatusDetails updatedDetails, string newStatusTranslation)
        {
            var notification = new EmailNotificationDetails
            {
                Sender = "no-reply@example.com",
                Recipients = new List<string> { $"admin@{updatedDetails.Language}.example.com" },
                Subject = $"Clinic Status Update: {updatedDetails.Status} -> {newStatusTranslation}",
                Body = $@"
                    Dear Admin,

                    The clinic status of {updatedDetails.Id} has been updated from '{updatedDetails.Status}' to '{newStatusTranslation}'.

                    Regards,
                    {Environment.UserName}"
            };

            return notification;
        }
    }
}
```
This code creates a middleware component for updating clinic statuses in a database. The middleware is responsible for checking if the new status is allowed, contains prohibited words, and meets the format requirements. If any of these checks fail, an exception is thrown.

The middleware also sends email notifications to clinic administrators when the clinic status is updated. It retrieves the updated clinic status details from the database using a `DatabaseContext` object, and then creates an `EmailNotificationDetails` object with the updated status and recipients. The `SendEmailNotificationsAsync` method uses an `SmtpClient` to send the email notifications.

The middleware is designed to be used in an ASP.NET Core web application, and it includes a dependency on the `Microsoft.EntityFrameworkCore` package for database access.

