            continue;
        } else {
            fprintf(stderr, "Error: File '%s' is not a JPEG or PNG image.\n", entry->d_name);
            return -1;
        }
    }
}

// Function to convert a single image file to PDF
int convertImageToPdf(const char *inputFile, const char *outputFile) {
    // Set the command-line options for the third-party tool
    char *command[] = {"convert", "-quality", "75", inputFile, outputFile, NULL};

    // Execute the third-party tool and capture its output
    FILE *fp = popen("convert -quality 75", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute convert command.\n");
        return -1;
    }

    // Read the output from the tool and handle any errors
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        // Check if there was an error during conversion
        if (strstr(buffer, "Error")) {
            fprintf(stderr, "Error: Failed to convert image '%s' to PDF.\n", inputFile);
            return -1;
        }
    }

    // Close the output stream and return 0 on success
    pclose(fp);
    return 0;
}

// Function to convert multiple images in a directory to PDF files using multi-threading
int batchConvertImagesToPdf(const char *inputDir, const char *outputDir, size_t maxPagesPerPdf, int outputResolution) {
    // Validate the input and output directories
    if (validateInputDirectory(inputDir) == -1 || validateOutputDirectory(outputDir) == -1) {
        return -1;
    }

    // Validate the file types of the input files
    if (validateFileTypes(inputDir) == -1) {
        return -1;
    }

    // Initialize a thread pool with the specified number of threads
    pthread_t threads[numThreads];

    // Create a queue for storing file names and PDF output files
    struct FileQueue *queue = NULL;

    // Populate the queue with the input files and their corresponding PDF output files
    DIR *dir = opendir(inputDir);
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        // Check if the file is a JPEG or PNG image
        if (strcmp(entry->d_name, "jpg") == 0 || strcmp(entry->d_name, "png") == 0) {
            // Allocate memory for the PDF output file name
            char *pdfOutputFile = malloc(sizeof(char) * PATH_MAX);

            // Construct the PDF output file name based on the input file name and the specified output directory
            strcpy(pdfOutputFile, outputDir);
            strcat(pdfOutputFile, "/");
            strcat(pdfOutputFile, entry->d_name);
            strcat(pdfOutputFile, ".pdf");

            // Add the file names to the queue
            enqueue(queue, entry->d_name, pdfOutputFile);
        }
    }

    // Initialize a flag to track if any errors occurred during conversion
    int errorOccurred = 0;

    // Create and execute threads for converting images to PDF files
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, convertImagesToPdf, (void *)queue);
    }

    // Wait for all threads to finish before returning
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Function to handle errors during conversion and free resources
void convertImagesToPdf(struct FileQueue *queue) {
    // Loop until the queue is empty
    while (!isQueueEmpty(queue)) {
        // Dequeue a file name and its corresponding PDF output file name
        char *inputFile = dequeue(queue);
        char *pdfOutputFile = dequeue(queue);

        // Convert the image to PDF using the specified output resolution
        int result = convertImageToPdf(inputFile, pdfOutputFile);

        // Check if any errors occurred during conversion
        if (result == -1) {
            errorOccurred = 1;
        }
    }
}

// Function to check if the queue is empty
int isQueueEmpty(struct FileQueue *queue) {
    return queue->head == NULL;
}

// Function to enqueue a file name and its corresponding PDF output file name
void enqueue(struct FileQueue *queue, char *inputFile, char *pdfOutputFile) {
    // Allocate memory for the new node
    struct Node *newNode = malloc(sizeof(struct Node));

    // Set the input file name and PDF output file name in the new node
    strcpy(newNode->inputFile, inputFile);
    strcpy(newNode->pdfOutputFile, pdfOutputFile);

    // Add the new node to the end of the queue
    if (queue->head == NULL) {
        queue->head = newNode;
    } else {
        queue->tail->next = newNode;
    }
    queue->tail = newNode;
}

// Function to dequeue a file name and its corresponding PDF output file name
void dequeue(struct FileQueue *queue) {
    // Check if the queue is empty
    if (isQueueEmpty(queue)) {
        return NULL;
    }

    // Remove the head node from the queue
    struct Node *head = queue->head;
    queue->head = head->next;
    free(head);
}
```

This code creates a thread pool with the specified number of threads and uses each thread to convert images in a directory to PDF files using the `convertImageToPdf` function. The `batchConvertImagesToPdf` function also validates the input and output directories, validates the file types of the input files, populates a queue with the input files and their corresponding PDF output files, creates threads for converting images to PDF files, waits for all threads to finish before returning, and handles errors during conversion.

This code uses the `pthread_create` function to create each thread, the `pthread_join` function to wait for all threads to finish, and the `pthread_detach` function to detach threads from the main program. It also uses the `strcpy`, `strcat`, and `malloc` functions to allocate memory for the input file name and PDF output file name in each node of the queue.

This code also uses a `struct FileQueue` structure to store the input files and their corresponding PDF output files, and a `struct Node` structure to represent each node in the queue. The `enqueue` function adds a new node with the specified input file name and PDF output file name to the end of the queue, and the `dequeue` function removes the head node from the queue.

This code uses the `isQueueEmpty` function to check if the queue is empty, and the `convertImagesToPdf` function to handle errors during conversion and free resources.

