@routes.post("/webhooks/slack")
async def slack_webhook(request: web.Request) -> web.Response:
    # Handle Slack webhook events and send notifications to configured chat platforms and services
    try:
        payload = await request.json()
        event = payload["event"]
        channel_id = event["channel"]["id"]
        user_id = event["user"]["id"]
        text = event["text"]
        timestamp = datetime.utcfromtimestamp(event["ts"]).strftime("%Y-%m-%d %H:%M:%S")

        # Check if the webhook event is a build success or failure notification
        if "build" in text.lower():
            build_status = "success" if "passed" in text.lower() else "failure"
            notification_type = f"push-{build_status}"

        # Check if the webhook event is a code commit notification
        elif "commit" in text.lower():
            notification_type = "push-code-commit"

        # Check if the webhook event is a deployment success or failure notification
        elif "deployment" in text.lower():
            deployment_status = "success" if "passed" in text.lower() else "failure"
            notification_type = f"push-{deployment_status}"

        # Send notifications to configured chat platforms and services
        for chat_platform, client in chat_platforms.items():
            if client:
                logger.info(f"Sending notification to {chat_platform}...")
                try:
                    response = await client.api_call(
                        method="chat.postMessage",
                        json={
                            "channel": channel_id,
                            "text": f"{notification_type}: {user_id} on {timestamp}"
                        }
                    )
                except SlackApiError as e:
                    logger.error(f"Failed to send notification to {chat_platform}: {e}")
                else:
                    if not response["ok"]:
                        logger.warning(f"Failed to send notification to {chat_platform}: {response['error']}")
            else:
                logger.info(f"{chat_platform} is not configured.")

        # Send notifications to configured push services
        for service, token in notification_services.items():
            if token:
                logger.info(f"Sending notification to {service}...")
                try:
                    response = await send_notification(service, notification_type, channel_id)
                except Exception as e:
                    logger.error(f"Failed to send notification to {service}: {e}")
                else:
                    if not response["success"]:
                        logger.warning(f"Failed to send notification to {service}: {response['message']}")
            else:
                logger.info(f"{service} is not configured.")

        return web.Response(text="Notifications sent successfully!")
    except Exception as e:
        logger.error(f"Error handling Slack webhook event: {e}")
        raise web.HTTPInternalServerError() from e

