import os
import threading
from concurrent.futures import ThreadPoolExecutor

class FileService:
    def __init__(self, storage_service):
        self.storage_service = storage_service
        self.file_cache = {}
        self.file_lock = threading.Lock()

    def upload(self, file_path):
        with self.file_lock:
            if os.path.exists(file_path):
                self.file_cache[file_path] = True
            else:
                self.storage_service.upload(file_path)

    def download(self, file_path):
        with self.file_lock:
            if os.path.exists(file_path):
                return False
            else:
                self.storage_service.download(file_path)
                self.file_cache[file_path] = True

    def get_statistics(self, file_path):
        with self.file_lock:
            if os.path.exists(file_path):
                return self.storage_service.get_statistics(file_path)
            else:
                return None

    def list_files(self):
        with self.file_lock:
            return list(self.file_cache.keys())

    def delete(self, file_path):
        with self.file_lock:
            if os.path.exists(file_path):
                del self.file_cache[file_path]
            else:
                self.storage_service.delete(file_path)

    def cleanup(self):
        with self.file_lock:
            for file_path in list(self.file_cache.keys()):
                if not os.path.exists(file_path):
                    del self.file_cache[file_path]

